async fn api_state() -> Json<AppStateResponse> {
    let started = Instant::now();
    diag!("[API-STATE] start");
    let workspace = active_workspace_path();
    let response = AppStateResponse {
        app_name: "COOLZHU AGENT".to_string(),
        status: "运行".to_string(),
        connection: "本地后端已连".to_string(),
        overview: build_overview_metrics(),
        workspace_id: workspace_identity(&workspace),
        workspace: display_path(&workspace),
        project_branch: git_output(["rev-parse", "--abbrev-ref", "HEAD"])
            .await
            .unwrap_or_else(|| "unknown".to_string()),
        changed_files: git_output(["status", "--short"])
            .await
            .map(|output| {
                output
                    .lines()
                    .filter(|line| !line.trim().is_empty())
                    .count()
            })
            .unwrap_or(0),
        models: ModelState {
            reasoning: config_reasoning_model()
                .filter(|value| !value.trim().is_empty())
                .unwrap_or_else(|| "智谱 / DeepSeek 可配".to_string()),
            vision: config_vision_model()
                .or_else(|| read_config(|c| c.vision.local_model.clone()))
                .filter(|value| !value.trim().is_empty())
                .unwrap_or_else(|| default_local_vision_model().to_string()),
            vision_base_url: config_vision_base_url()
                .or_else(|| read_config(|c| c.vision.local_base_url.clone()))
                .filter(|value| !value.trim().is_empty())
                .unwrap_or_else(|| default_local_vision_base_url().to_string()),
        },
        latest_capture: latest_capture_metadata().await,
        tools: ToolState {
            cli: "在线".to_string(),
            // 动态统计本地 SKILL 数量，避免新增 skill 后计数过期。
            skills: {
                let total = skill_catalog_items().len();
                format!("可用 {total}/{total}")
            },
            plugins: "可用 4/4".to_string(),
        },
        stability: StabilitySummary {
            resolution_cases: standard_resolution_cases().len(),
            scenarios: default_regression_scenarios().len(),
            mode: "dry-run 安全测试".to_string(),
        },
        project_entries: scan_project_entries(&workspace),
    };
    diag!(
        "[API-STATE] response ready: elapsed_ms={}",
        elapsed_millis(started)
    );
    Json(response)
}

async fn api_office_scene() -> Json<OfficeSceneResponse> {
    Json(build_office_scene_response())
}

async fn api_web_cards() -> Json<WebCardApiAuditResponse> {
    Json(build_web_card_api_audit())
}

async fn api_system_info() -> Json<SystemInfoResponse> {
    let workspace = active_workspace_path();
    let port = config_web_bind_addr()
        .parse::<SocketAddr>()
        .map(|addr| addr.port())
        .unwrap_or(8765);
    let active_sessions = session_store()
        .lock()
        .map(|store| store.state.sessions.len())
        .unwrap_or_default();
    Json(SystemInfoResponse {
        workspace: workspace.to_string_lossy().to_string(),
        port,
        build_version: web_console_build_version(),
        active_sessions,
    })
}

fn web_console_build_version() -> String {
    let git_hash = web_console_git_short_hash();
    let build_date = option_env!("COOLZHU_BUILD_DATE")
        .or(option_env!("VERGEN_BUILD_DATE"))
        .or(option_env!("VERGEN_BUILD_TIMESTAMP"))
        .or(option_env!("BUILD_DATE"))
        .unwrap_or("local");
    format!("{git_hash} · {build_date}")
}

fn web_console_git_short_hash() -> String {
    for value in [
        option_env!("COOLZHU_GIT_SHA"),
        option_env!("VERGEN_GIT_SHA"),
        option_env!("GIT_COMMIT"),
        option_env!("GIT_HASH"),
    ]
    .into_iter()
    .flatten()
    {
        let trimmed = value.trim();
        if !trimmed.is_empty() {
            return trimmed.chars().take(12).collect();
        }
    }
    std::process::Command::new("git")
        .arg("-C")
        .arg(env!("CARGO_MANIFEST_DIR"))
        .args(["rev-parse", "--short=12", "HEAD"])
        .output()
        .ok()
        .filter(|output| output.status.success())
        .map(|output| decode_console_output(&output.stdout).trim().to_string())
        .filter(|hash| !hash.is_empty())
        .unwrap_or_else(|| "unknown".to_string())
}

