/// REQ-TOOL-008 Phase C-2：挂起中的审批请求。
///
/// 当 Tool Loop（后续 Phase C-3 接入）或前端 dispatch 收到 RequireApproval /
/// RequireConfirm 时，把对应 `ToolInvoke` 写入 pending 队列；前端轮询
/// `/api/tools/pending` 或监听 SSE 事件来渲染审批面板；用户点击 approve/reject
/// 后通过 `/api/tools/approve|reject` 消费。
#[derive(Debug, Clone, Serialize)]
struct PendingApprovalRecord {
    call_id: String,
    tool_name: String,
    caller: String,
    workspace_id: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    session_id: Option<String>,
    input_summary: String,
    permission: PendingApprovalPermission,
    #[serde(skip)]
    invoke: ToolInvoke,
    #[serde(skip)]
    workspace_root: PathBuf,
    #[serde(skip)]
    created_at: Instant,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct PendingApprovalPermission {
    required: String,
    decision: String,
    reason: String,
    workspace_relative: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    protected_match: Option<String>,
    #[serde(default)]
    affected_paths: Vec<String>,
}

fn pending_approvals() -> &'static Mutex<BTreeMap<String, PendingApprovalRecord>> {
    static PENDING: OnceLock<Mutex<BTreeMap<String, PendingApprovalRecord>>> = OnceLock::new();
    PENDING.get_or_init(|| Mutex::new(BTreeMap::new()))
}

fn build_input_summary(tool_name: &str, input: &JsonValue) -> String {
    let mut parts = Vec::new();
    if let Some(obj) = input.as_object() {
        for (key, value) in obj {
            let desc = match value {
                JsonValue::String(s) => format!("{}=len{}", key, s.chars().count()),
                JsonValue::Number(n) => format!("{key}={n}"),
                JsonValue::Bool(b) => format!("{key}={b}"),
                JsonValue::Null => format!("{key}=null"),
                JsonValue::Array(arr) => format!("{}=[{}]", key, arr.len()),
                JsonValue::Object(obj) => format!("{}={{{}}}", key, obj.len()),
            };
            parts.push(desc);
            if parts.len() >= 4 {
                parts.push("…".into());
                break;
            }
        }
    }
    format!("{}: {}", tool_name, parts.join(", "))
}

fn enqueue_pending_approval(
    call_id: &str,
    invoke: &ToolInvoke,
    gate: &runtime::PermissionGateReport,
) {
    let Ok(mut pending) = pending_approvals().lock() else {
        return;
    };
    let now = Instant::now();
    pending.retain(|_, record| now.duration_since(record.created_at) < PENDING_APPROVAL_TTL);
    let record = PendingApprovalRecord {
        call_id: call_id.to_string(),
        tool_name: invoke.tool_name.clone(),
        caller: invoke.caller.as_str().to_string(),
        workspace_id: invoke.workspace_id.clone(),
        session_id: invoke.session_id.clone(),
        input_summary: build_input_summary(&invoke.tool_name, &invoke.input),
        permission: PendingApprovalPermission {
            required: gate.required.as_str().to_string(),
            decision: gate.decision.as_str().to_string(),
            reason: gate.reason.clone(),
            workspace_relative: gate.workspace_relative,
            protected_match: gate.protected_match.clone(),
            affected_paths: gate.affected_paths.clone(),
        },
        invoke: invoke.clone(),
        workspace_root: active_workspace_path(),
        created_at: now,
    };
    pending.insert(call_id.to_string(), record.clone());
    drop(pending);
    broadcast_tool_event(ToolEvent::PermissionRequired(record));
}

#[cfg(test)]
fn clear_pending_approvals_for_test() {
    if let Ok(mut pending) = pending_approvals().lock() {
        pending.clear();
    }
}

#[derive(Debug, Clone, Serialize)]
#[serde(tag = "kind", rename_all = "kebab-case")]
enum ToolEvent {
    #[serde(rename = "permission-required")]
    PermissionRequired(PendingApprovalRecord),
    Approved {
        call_id: String,
        scope: String,
        confirmed_twice: bool,
        #[serde(skip_serializing_if = "Option::is_none")]
        ttl_secs: Option<u64>,
        #[serde(skip_serializing_if = "Option::is_none")]
        summary_text: Option<String>,
        #[serde(skip_serializing_if = "Option::is_none")]
        tool_name: Option<String>,
    },
    Rejected {
        call_id: String,
        #[serde(skip_serializing_if = "Option::is_none")]
        reason: Option<String>,
    },
}

impl ToolEvent {
    fn event_name(&self) -> &'static str {
        match self {
            Self::PermissionRequired(_) => "permission-required",
            Self::Approved { .. } => "approved",
            Self::Rejected { .. } => "rejected",
        }
    }
}

