fn showui_service_process() -> &'static Mutex<Option<std::process::Child>> {
    static PROCESS: OnceLock<Mutex<Option<std::process::Child>>> = OnceLock::new();
    PROCESS.get_or_init(|| Mutex::new(None))
}

/// 全局 compute-use 真实输入串行化闸门。
///
/// 物理键鼠注入是全机唯一资源：多个聊天室会话同时触发 compute-use 动作会互相
/// 抢占光标/焦点造成错乱。这里用一个进程级 `tokio::sync::Mutex` 作为公平排队锁——
/// 所有真实输入（点击/键入/拖拽/热键）在执行前必须先拿到该锁，从而天然串行、
/// 先到先得，且因为是 async 锁不会阻塞 worker 线程（高效排队，不自旋）。
fn compute_use_input_gate() -> &'static tokio::sync::Mutex<()> {
    static GATE: OnceLock<tokio::sync::Mutex<()>> = OnceLock::new();
    GATE.get_or_init(|| tokio::sync::Mutex::new(()))
}

fn showui_console_url_store() -> &'static Mutex<Option<String>> {
    static URL: OnceLock<Mutex<Option<String>>> = OnceLock::new();
    URL.get_or_init(|| Mutex::new(None))
}

fn vision_realtime_state() -> &'static Mutex<VisionRealtimeElementState> {
    static STATE: OnceLock<Mutex<VisionRealtimeElementState>> = OnceLock::new();
    STATE.get_or_init(|| Mutex::new(VisionRealtimeElementState::default()))
}

fn vision_realtime_loop_handle() -> &'static Mutex<Option<tokio::task::JoinHandle<()>>> {
    static HANDLE: OnceLock<Mutex<Option<tokio::task::JoinHandle<()>>>> = OnceLock::new();
    HANDLE.get_or_init(|| Mutex::new(None))
}

fn set_showui_console_url(url: &str) {
    if let Ok(mut stored) = showui_console_url_store().lock() {
        *stored = Some(url.to_string());
    }
}

fn showui_console_url() -> String {
    showui_console_url_store()
        .lock()
        .ok()
        .and_then(|stored| stored.clone())
        .unwrap_or_else(|| format!("http://{}/", config_web_bind_addr()))
}

fn showui_service_config_disabled() -> bool {
    !config_pet_enabled()
}

fn poll_showui_service_process(process: &mut Option<std::process::Child>) -> Option<u32> {
    let child = process.as_mut()?;
    match child.try_wait() {
        Ok(Some(status)) => {
            info!("ShowUI service exited with status {status}");
            *process = None;
            None
        }
        Ok(None) => Some(child.id()),
        Err(error) => {
            warn!("Failed to poll ShowUI service status: {error}");
            None
        }
    }
}

fn mark_showui_service_process_exited(pid: u32) {
    let mut cleared = false;
    if let Ok(mut process) = showui_service_process().lock() {
        let matches = process
            .as_ref()
            .map(|child| child.id() == pid)
            .unwrap_or(false);
        if matches {
            if let Some(mut child) = process.take() {
                let _ = child.try_wait();
                cleared = true;
            }
        }
    }
    if cleared {
        info!("ShowUI service process {pid} cleared; enabled intent is preserved.");
    }
}

fn showui_service_status_with_message(message: impl Into<String>) -> ShowUiServiceResponse {
    let (running, pid) = showui_service_process()
        .lock()
        .ok()
        .map(|mut process| {
            let pid = poll_showui_service_process(&mut process);
            (pid.is_some(), pid)
        })
        .unwrap_or((false, None));
    ShowUiServiceResponse {
        enabled: SHOWUI_SERVICE_ENABLED.load(Ordering::Relaxed)
            && !showui_service_config_disabled(),
        running,
        pid,
        disabled: showui_service_config_disabled(),
        desktop_pet_exe: desktop_pet_executable().map(|path| path.display().to_string()),
        console_url: showui_console_url_store()
            .lock()
            .ok()
            .and_then(|stored| stored.clone()),
        message: message.into(),
    }
}

fn desktop_shell_managed_value(value: Option<&std::ffi::OsStr>) -> bool {
    value.is_some_and(|value| {
        matches!(
            value.to_string_lossy().trim().to_ascii_lowercase().as_str(),
            "1" | "true" | "yes" | "on"
        )
    })
}

fn desktop_shell_managed_by_launcher() -> bool {
    desktop_shell_managed_value(std::env::var_os("COOLZHU_DESKTOP_SHELL_MANAGED").as_deref())
}

fn managed_showui_service_status(message: impl Into<String>) -> ShowUiServiceResponse {
    ShowUiServiceResponse {
        enabled: true,
        running: true,
        pid: None,
        disabled: false,
        desktop_pet_exe: desktop_pet_executable().map(|path| path.display().to_string()),
        console_url: showui_console_url_store()
            .lock()
            .ok()
            .and_then(|stored| stored.clone()),
        message: message.into(),
    }
}

fn start_showui_service(console_url: &str) -> ShowUiServiceResponse {
    SHOWUI_SERVICE_ENABLED.store(true, Ordering::Relaxed);
    set_showui_console_url(console_url);
    if desktop_shell_managed_by_launcher() {
        return managed_showui_service_status("Desktop shell is managed by package launcher.");
    }
    if showui_service_config_disabled() {
        return showui_service_status_with_message("ShowUI service is disabled by config.");
    }
    let mut process = match showui_service_process().lock() {
        Ok(process) => process,
        Err(_) => return showui_service_status_with_message("ShowUI service lock failed."),
    };
    if let Some(pid) = poll_showui_service_process(&mut process) {
        return ShowUiServiceResponse {
            enabled: true,
            running: true,
            pid: Some(pid),
            disabled: false,
            desktop_pet_exe: desktop_pet_executable().map(|path| path.display().to_string()),
            console_url: Some(console_url.to_string()),
            message: "ShowUI service is already running.".to_string(),
        };
    }
    *process = launch_desktop_pet(console_url);
    let pid = process.as_ref().map(std::process::Child::id);
    ShowUiServiceResponse {
        enabled: true,
        running: pid.is_some(),
        pid,
        disabled: false,
        desktop_pet_exe: desktop_pet_executable().map(|path| path.display().to_string()),
        console_url: Some(console_url.to_string()),
        message: if pid.is_some() {
            "ShowUI service started.".to_string()
        } else {
            "ShowUI executable is unavailable or failed to start.".to_string()
        },
    }
}

fn web_console_parent_pid_arg(pid: u32) -> String {
    format!("--web-console-pid={pid}")
}

fn stop_showui_service() -> ShowUiServiceResponse {
    if desktop_shell_managed_by_launcher() {
        return managed_showui_service_status(
            "Desktop shell is managed by package launcher and remains available.",
        );
    }
    terminate_showui_service_process_with_messages(
        "ShowUI service stopped; web shell kept open.",
        "ShowUI service is already stopped; web shell kept open.",
    )
}

fn terminate_showui_service_process() -> ShowUiServiceResponse {
    terminate_showui_service_process_with_messages(
        "ShowUI service stopped.",
        "ShowUI service is already stopped.",
    )
}

fn terminate_showui_service_process_with_messages(
    stopped_message: &str,
    already_stopped_message: &str,
) -> ShowUiServiceResponse {
    SHOWUI_SERVICE_ENABLED.store(false, Ordering::Relaxed);
    let mut stopped = false;
    if let Ok(mut process) = showui_service_process().lock() {
        if let Some(mut child) = process.take() {
            shutdown_desktop_pet(&mut child);
            stopped = true;
        }
    }
    showui_service_status_with_message(if stopped {
        stopped_message
    } else {
        already_stopped_message
    })
}

// ===================== 本地模型服务开关 =====================
// 8GB 显存单活跃：chat=本地文本推理(8082) ⇆ vision=UI-DETR(7860)+ShowUI(8000)。
// 停用按端口杀进程（释放显存，无论谁启动）；启用按已验证命令 spawn。bge-m3(8081) 不随切换。

const LOCAL_UIDETR_PORT: u16 = 7860;
const LOCAL_SHOWUI_PORT: u16 = 8000;
const LOCAL_EMBED_PORT: u16 = 8081;

#[derive(Debug, Clone, Copy)]
struct LocalChatRuntimeConfig {
    port: u16,
    context_window: u32,
    max_output_tokens: u32,
    reasoning_budget: u32,
    gpu_layers: u32,
    parallel_slots: u32,
    startup_timeout_ms: u64,
}

fn local_chat_runtime_config() -> LocalChatRuntimeConfig {
    read_config(|config| {
        normalized_local_chat_runtime_config(
            config.model.local_chat_port,
            config.model.local_chat_context_window,
            config.model.local_chat_max_output_tokens,
            config.model.local_chat_reasoning_budget,
            config.model.local_chat_gpu_layers,
            config.model.local_chat_parallel_slots,
            config.model.local_chat_startup_timeout_ms,
        )
    })
}

fn normalized_local_chat_runtime_config(
    port: u16,
    context_window: u32,
    max_output_tokens: u32,
    reasoning_budget: u32,
    gpu_layers: u32,
    parallel_slots: u32,
    startup_timeout_ms: u64,
) -> LocalChatRuntimeConfig {
    let context_window = context_window.max(1);
    let max_output_tokens = max_output_tokens
        .max(1)
        .min(context_window.saturating_sub(1).max(1));
    LocalChatRuntimeConfig {
        port,
        context_window,
        max_output_tokens,
        reasoning_budget: reasoning_budget.min(max_output_tokens.saturating_sub(1)),
        gpu_layers,
        parallel_slots: parallel_slots.clamp(1, 8),
        startup_timeout_ms: startup_timeout_ms.clamp(1_000, 120_000),
    }
}

fn local_gemma_runtime_args(runtime: LocalChatRuntimeConfig) -> Vec<String> {
    vec![
        "--host".to_string(),
        "127.0.0.1".to_string(),
        "--port".to_string(),
        runtime.port.to_string(),
        "-ngl".to_string(),
        runtime.gpu_layers.to_string(),
        "-c".to_string(),
        runtime.context_window.to_string(),
        "-np".to_string(),
        runtime.parallel_slots.to_string(),
        "--reasoning-budget".to_string(),
        runtime.reasoning_budget.to_string(),
        "--jinja".to_string(),
    ]
}

/// 切换后的活跃模式纯逻辑映射（便于单测 / 状态展示）。
fn local_active_mode(gemma: bool, vision: bool) -> &'static str {
    match (gemma, vision) {
        (true, false) => "chat",
        (false, true) => "vision",
        (true, true) => "mixed",
        (false, false) => "off",
    }
}

fn local_port_listening(port: u16) -> bool {
    let addr = std::net::SocketAddr::from(([127, 0, 0, 1], port));
    std::net::TcpStream::connect_timeout(&addr, std::time::Duration::from_millis(300)).is_ok()
}

fn local_gemma_ready(port: u16) -> bool {
    use std::io::Write as _;

    let addr = std::net::SocketAddr::from(([127, 0, 0, 1], port));
    let timeout = std::time::Duration::from_millis(800);
    let Ok(mut stream) = std::net::TcpStream::connect_timeout(&addr, timeout) else {
        return false;
    };
    let _ = stream.set_read_timeout(Some(timeout));
    let _ = stream.set_write_timeout(Some(timeout));
    let request =
        format!("GET /health HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nConnection: close\r\n\r\n");
    if stream.write_all(request.as_bytes()).is_err() {
        return false;
    }
    let mut response = [0_u8; 256];
    let Ok(read) = stream.read(&mut response) else {
        return false;
    };
    let head = String::from_utf8_lossy(&response[..read]);
    head.starts_with("HTTP/1.1 200") || head.starts_with("HTTP/1.0 200")
}

/// 按端口杀掉监听进程（释放显存），与启动者无关。
#[cfg(windows)]
fn kill_listeners_on_port(port: u16) {
    let script = format!(
        "Get-NetTCPConnection -LocalPort {port} -State Listen -ErrorAction SilentlyContinue | \
         ForEach-Object {{ Stop-Process -Id $_.OwningProcess -Force -ErrorAction SilentlyContinue }}"
    );
    let _ = std::process::Command::new("powershell")
        .args(["-NoProfile", "-NonInteractive", "-Command", &script])
        .stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null())
        .status();
}
#[cfg(not(windows))]
fn kill_listeners_on_port(_port: u16) {}

/// 在 exe 上溯目录中定位仓库内资源（脚本路径）。
fn repo_resource_path(rel: &str) -> Option<std::path::PathBuf> {
    if let Ok(exe) = std::env::current_exe() {
        for anc in exe.ancestors() {
            let candidate = anc.join(rel);
            if candidate.exists() {
                return Some(candidate);
            }
        }
    }
    std::env::current_dir()
        .ok()
        .map(|cwd| cwd.join(rel))
        .filter(|p| p.exists())
}

/// 定位 llama-server.exe（优先 cuda-12.4 构建）。
fn find_llama_server_exe() -> Option<std::path::PathBuf> {
    let base = user_home_dir()?.join("llama.cpp");
    let mut fallback = None;
    for entry in std::fs::read_dir(&base).ok()?.flatten() {
        let dir = entry.path();
        let exe = dir.join("llama-server.exe");
        if !dir.is_dir() || !exe.exists() {
            continue;
        }
        let name = dir
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("")
            .to_ascii_lowercase();
        if name.contains("cuda-12.4") {
            return Some(exe);
        }
        if fallback.is_none() {
            fallback = Some(exe);
        }
    }
    fallback
}

fn local_model_log_path() -> PathBuf {
    let workspace = active_workspace_path();
    read_config(|config| {
        workspace_data_dir_for(&workspace, config)
            .join("logs")
            .join("local-gemma.log")
    })
}

fn spawn_detached_logged(mut cmd: std::process::Command, log_path: &Path) -> Result<u32, String> {
    if let Some(parent) = log_path.parent() {
        std::fs::create_dir_all(parent)
            .map_err(|error| format!("创建本地模型日志目录失败: {error}"))?;
    }
    let stdout = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_path)
        .map_err(|error| format!("打开本地模型日志失败: {error}"))?;
    let stderr = stdout
        .try_clone()
        .map_err(|error| format!("复制本地模型日志句柄失败: {error}"))?;
    cmd.stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::from(stdout))
        .stderr(std::process::Stdio::from(stderr));
    #[cfg(windows)]
    cmd.creation_flags(CREATE_NO_WINDOW);

    let mut child = cmd
        .spawn()
        .map_err(|error| format!("启动本地模型进程失败: {error}"))?;
    #[cfg(windows)]
    {
        if let Err(error) = local_model_child_job()?.assign(&child) {
            let _ = child.kill();
            let _ = child.wait();
            return Err(format!("绑定本地模型进程生命周期失败: {error}"));
        }
    }
    Ok(child.id())
}

#[cfg(windows)]
fn local_model_child_job() -> Result<&'static windows_process_guard::ChildProcessJob, String> {
    static JOB: OnceLock<windows_process_guard::ChildProcessJob> = OnceLock::new();
    if JOB.get().is_none() {
        let job = windows_process_guard::ChildProcessJob::new_kill_on_close()
            .map_err(|error| format!("创建本地模型 Job Object 失败: {error}"))?;
        let _ = JOB.set(job);
    }
    JOB.get()
        .ok_or_else(|| "本地模型 Job Object 初始化失败".to_string())
}

fn spawn_detached(mut cmd: std::process::Command) -> bool {
    cmd.stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null());
    #[cfg(windows)]
    cmd.creation_flags(CREATE_NO_WINDOW);

    let mut child = match cmd.spawn() {
        Ok(child) => child,
        Err(error) => {
            warn!("本地模型服务进程启动失败: {error}");
            return false;
        }
    };
    #[cfg(windows)]
    {
        if let Err(error) = local_model_child_job().and_then(|job| {
            job.assign(&child)
                .map_err(|error| format!("绑定本地模型进程生命周期失败: {error}"))
        }) {
            warn!("{error}");
            let _ = child.kill();
            let _ = child.wait();
            return false;
        }
    }
    true
}

fn configured_local_chat_model_path() -> Option<PathBuf> {
    read_config(|config| {
        config
            .model
            .local_chat_model_path
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(PathBuf::from)
    })
}

fn configured_local_chat_mmproj_path() -> Option<PathBuf> {
    read_config(|config| {
        config
            .model
            .local_chat_mmproj_path
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(PathBuf::from)
    })
}

fn validate_local_chat_model_path(raw: &str) -> Result<String, String> {
    let value = raw.trim();
    if value.is_empty() {
        return Err("本地模型文件路径不能为空".to_string());
    }
    let path = PathBuf::from(value);
    let canonical = path
        .canonicalize()
        .map_err(|error| format!("本地模型文件不存在或不可访问: {error}"))?;
    if !canonical.is_file() {
        return Err("本地模型路径必须指向文件".to_string());
    }
    let is_gguf = canonical
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| extension.eq_ignore_ascii_case("gguf"));
    if !is_gguf {
        return Err("本地模型文件必须是 .gguf 格式".to_string());
    }
    Ok(canonical.to_string_lossy().to_string())
}

fn start_local_gemma() -> (bool, String) {
    let runtime = local_chat_runtime_config();
    if local_gemma_ready(runtime.port) {
        return (true, format!("{LOCAL_MODEL_BRAND} 已在运行"));
    }
    if local_port_listening(runtime.port) {
        return (
            false,
            format!(
                "端口 {} 已被非健康服务占用；请关闭占用进程后重试",
                runtime.port
            ),
        );
    }
    let Some(exe) = find_llama_server_exe() else {
        return (
            false,
            "未找到 llama-server.exe（~/llama.cpp/*cuda-12.4*/）".to_string(),
        );
    };
    let Some(model) = configured_local_chat_model_path() else {
        return (false, "尚未配置本地文本推理的 GGUF 模型文件".to_string());
    };
    if !model.is_file() {
        return (false, "配置的本地模型文件不存在或不可访问".to_string());
    }
    let mut cmd = std::process::Command::new(exe);
    cmd.arg("-m").arg(&model);
    if let Some(mmproj) = configured_local_chat_mmproj_path().filter(|path| path.is_file()) {
        cmd.arg("--mmproj").arg(&mmproj);
    }
    cmd.args(local_gemma_runtime_args(runtime));
    let log_path = local_model_log_path();
    let pid = match spawn_detached_logged(cmd, &log_path) {
        Ok(pid) => pid,
        Err(error) => return (false, error),
    };
    let deadline = Instant::now() + Duration::from_millis(runtime.startup_timeout_ms);
    while Instant::now() < deadline {
        if local_gemma_ready(runtime.port) {
            return (
                true,
                format!(
                    "{LOCAL_MODEL_BRAND} ready（PID {pid}，context={}，max_output={}，reasoning_budget={}，slots={}，日志={}）",
                    runtime.context_window,
                    runtime.max_output_tokens,
                    runtime.reasoning_budget,
                    runtime.parallel_slots,
                    log_path.display()
                ),
            );
        }
        std::thread::sleep(Duration::from_millis(500));
    }
    (
        false,
        format!(
            "{LOCAL_MODEL_BRAND} 启动超时（PID {pid}，请检查日志 {}）",
            log_path.display()
        ),
    )
}

fn start_local_uidetr() -> (bool, String) {
    if local_port_listening(LOCAL_UIDETR_PORT) {
        return (true, "UI-DETR 已在运行".to_string());
    }
    let Some(script) = repo_resource_path("modules/vision/resources/uidetr/uidetr_service.py")
    else {
        return (false, "未找到 uidetr_service.py".to_string());
    };
    let model_path = active_vision_router_config()
        .detection
        .model_path
        .unwrap_or_default();
    let mut cmd = std::process::Command::new("python");
    cmd.arg(&script).arg("--model").arg(&model_path).args([
        "--host",
        "127.0.0.1",
        "--port",
        "7860",
    ]);
    if spawn_detached(cmd) {
        (true, "UI-DETR 启动中".to_string())
    } else {
        (false, "UI-DETR 启动失败（需 python 环境）".to_string())
    }
}

fn start_local_showui() -> (bool, String) {
    if local_port_listening(LOCAL_SHOWUI_PORT) {
        return (true, "ShowUI 已在运行".to_string());
    }
    let Some(script) = repo_resource_path("modules/vision/resources/local-vlm/start-local-vlm.ps1")
    else {
        return (false, "未找到 start-local-vlm.ps1".to_string());
    };
    let mut cmd = std::process::Command::new("powershell");
    cmd.args(["-NoProfile", "-ExecutionPolicy", "Bypass", "-File"])
        .arg(&script)
        .args(["-Profile", "showui"]);
    if spawn_detached(cmd) {
        (true, "ShowUI 启动中（首次加载较久）".to_string())
    } else {
        (false, "ShowUI 启动失败".to_string())
    }
}

#[derive(Debug, Clone, Serialize)]
struct LocalServiceStatus {
    name: String,
    role: String,
    port: u16,
    running: bool,
}

#[derive(Debug, Clone, Serialize)]
struct LocalModelsStatusResponse {
    active_mode: String,
    services: Vec<LocalServiceStatus>,
    model_path: Option<String>,
    model_path_exists: bool,
    message: String,
}

fn local_models_status_response(message: impl Into<String>) -> LocalModelsStatusResponse {
    let gemma_port = local_chat_runtime_config().port;
    let gemma = local_gemma_ready(gemma_port);
    let uidetr = local_port_listening(LOCAL_UIDETR_PORT);
    let showui = local_port_listening(LOCAL_SHOWUI_PORT);
    let embed = local_port_listening(LOCAL_EMBED_PORT);
    let model_path = configured_local_chat_model_path();
    let model_path_exists = model_path.as_ref().is_some_and(|path| path.is_file());
    LocalModelsStatusResponse {
        active_mode: local_active_mode(gemma, uidetr || showui).to_string(),
        services: vec![
            LocalServiceStatus {
                name: LOCAL_MODEL_BRAND.to_string(),
                role: "chat".to_string(),
                port: gemma_port,
                running: gemma,
            },
            LocalServiceStatus {
                name: "UI-DETR".to_string(),
                role: "vision".to_string(),
                port: LOCAL_UIDETR_PORT,
                running: uidetr,
            },
            LocalServiceStatus {
                name: "ShowUI".to_string(),
                role: "vision".to_string(),
                port: LOCAL_SHOWUI_PORT,
                running: showui,
            },
            LocalServiceStatus {
                name: "bge-m3 (embeddings)".to_string(),
                role: "memory".to_string(),
                port: LOCAL_EMBED_PORT,
                running: embed,
            },
        ],
        model_path: model_path.map(|path| path.to_string_lossy().to_string()),
        model_path_exists,
        message: message.into(),
    }
}

/// 本地模型服务开关：chat / vision / off。停用按端口杀进程释放显存，再启用目标组。
fn switch_local_models(mode: &str) -> LocalModelsStatusResponse {
    let message = match mode {
        "chat" => {
            kill_listeners_on_port(LOCAL_UIDETR_PORT);
            kill_listeners_on_port(LOCAL_SHOWUI_PORT);
            let (_, gemma) = start_local_gemma();
            format!("切到 chat：已停 UI-DETR/ShowUI 释放显存。{gemma}")
        }
        "vision" => {
            kill_listeners_on_port(local_chat_runtime_config().port);
            let (_, uidetr) = start_local_uidetr();
            let (_, showui) = start_local_showui();
            format!("切到 vision：已停本地文本推理释放显存。UI-DETR：{uidetr}；ShowUI：{showui}")
        }
        "off" => {
            kill_listeners_on_port(local_chat_runtime_config().port);
            kill_listeners_on_port(LOCAL_UIDETR_PORT);
            kill_listeners_on_port(LOCAL_SHOWUI_PORT);
            "已停用全部本地模型服务（bge-m3 嵌入不受影响）".to_string()
        }
        other => {
            return local_models_status_response(format!(
                "未知模式: {other}（支持 chat / vision / off）"
            ));
        }
    };
    local_models_status_response(message)
}

fn local_model_exit_shutdown_ports() -> Vec<u16> {
    let mut ports = vec![
        local_chat_runtime_config().port,
        LOCAL_UIDETR_PORT,
        LOCAL_SHOWUI_PORT,
        LOCAL_EMBED_PORT,
    ];
    ports.sort_unstable();
    ports.dedup();
    ports
}

fn shutdown_local_model_services_on_exit() {
    let ports = local_model_exit_shutdown_ports();
    info!(
        "web-console 退出清理：停止本地模型服务端口 {}",
        ports
            .iter()
            .map(u16::to_string)
            .collect::<Vec<_>>()
            .join(", ")
    );
    for port in ports {
        kill_listeners_on_port(port);
    }
}

async fn api_local_models_status() -> Json<LocalModelsStatusResponse> {
    Json(local_models_status_response("ok"))
}

#[derive(Debug, Deserialize)]
struct LocalModelsSwitchRequest {
    mode: String,
}

async fn api_local_models_switch(
    Json(payload): Json<LocalModelsSwitchRequest>,
) -> Json<LocalModelsStatusResponse> {
    Json(switch_local_models(&payload.mode))
}

#[derive(Debug, Deserialize)]
struct LocalModelPathRequest {
    model_path: String,
}

fn persist_local_chat_model_path(raw: &str) -> ApiResult<LocalModelsStatusResponse> {
    let normalized = validate_local_chat_model_path(raw)
        .map_err(|message| api_error(StatusCode::BAD_REQUEST, &message))?;
    mutate_workspace_config(|config| {
        config.model.local_chat_model_path = Some(normalized.clone());
        Ok(())
    })?;
    Ok(local_models_status_response("本地模型文件路径已保存"))
}

async fn api_local_model_path_update(
    Json(payload): Json<LocalModelPathRequest>,
) -> ApiResult<Json<LocalModelsStatusResponse>> {
    persist_local_chat_model_path(&payload.model_path).map(Json)
}

#[cfg(windows)]
fn pick_local_chat_model_file() -> Result<Option<String>, String> {
    let script = r#"
Add-Type -AssemblyName System.Windows.Forms
[System.Windows.Forms.Application]::EnableVisualStyles()
$dialog = New-Object System.Windows.Forms.OpenFileDialog
$dialog.Title = '选择本地文本推理 GGUF 模型'
$dialog.Filter = 'GGUF 模型 (*.gguf)|*.gguf'
$dialog.CheckFileExists = $true
$dialog.Multiselect = $false
if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
  [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
  Write-Output $dialog.FileName
}
"#;
    let mut command = std::process::Command::new("powershell");
    command.args(["-NoProfile", "-STA", "-Command", script]);
    command.creation_flags(CREATE_NO_WINDOW);
    let output = command
        .output()
        .map_err(|error| format!("打开模型文件选择器失败: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "模型文件选择器执行失败: {}",
            decode_console_output(&output.stderr).trim()
        ));
    }
    let selected = decode_console_output(&output.stdout).trim().to_string();
    Ok((!selected.is_empty()).then_some(selected))
}

#[cfg(not(windows))]
fn pick_local_chat_model_file() -> Result<Option<String>, String> {
    Err("当前平台暂不支持系统模型文件选择器".to_string())
}

async fn api_local_model_pick_file() -> ApiResult<Json<LocalModelsStatusResponse>> {
    let selected = tokio::task::spawn_blocking(pick_local_chat_model_file)
        .await
        .map_err(|error| {
            let message = format!("模型文件选择器任务失败: {error}");
            api_error(StatusCode::INTERNAL_SERVER_ERROR, &message)
        })?
        .map_err(|message| api_error(StatusCode::INTERNAL_SERVER_ERROR, &message))?;
    match selected {
        Some(path) => persist_local_chat_model_path(&path).map(Json),
        None => Ok(Json(local_models_status_response("已取消选择模型文件"))),
    }
}

fn subscribe_pet_events() -> broadcast::Receiver<PetStateSnapshot> {
    pet_event_bus().subscribe()
}

fn broadcast_pet_event(event: PetStateSnapshot) {
    let _ = pet_event_bus().send(event);
}

#[cfg(test)]
fn reset_pet_state_for_test() {
    PET_EVENT_SEQUENCE.store(0, Ordering::Relaxed);
    if let Ok(mut state) = pet_state_store().lock() {
        *state = default_pet_state_snapshot();
    }
}

fn pet_status_for_backend_event(
    event_type: &str,
    message: Option<&str>,
    source: &str,
) -> PetStateSnapshot {
    let normalized_event = event_type.trim().to_ascii_lowercase();
    let (state, default_message) = if normalized_event.starts_with("chat.completed")
        || normalized_event.starts_with("chat.done")
    {
        ("success", "Chat response completed")
    } else if normalized_event.starts_with("chat.failed")
        || normalized_event.starts_with("chat.error")
    {
        ("warning", "Chat request failed")
    } else if normalized_event.starts_with("chat")
        || normalized_event.starts_with("llm")
        || normalized_event.contains("reasoning")
    {
        ("thinking", "Agent is working")
    } else if normalized_event.starts_with("goal.completed") {
        ("success", "Goal completed")
    } else if normalized_event.starts_with("goal.failed") {
        ("warning", "Goal needs attention")
    } else if normalized_event.starts_with("goal.paused") {
        ("attention", "Goal is paused")
    } else if normalized_event.starts_with("goal") {
        ("working", "Goal task is running")
    } else if normalized_event.starts_with("permission") {
        ("attention", "Waiting for permission approval")
    } else if normalized_event.starts_with("notification") {
        ("notification", "New task update")
    } else if normalized_event.starts_with("tool.ok")
        || normalized_event.starts_with("tool.success")
        || normalized_event.starts_with("success")
        || normalized_event.starts_with("complete")
    {
        ("success", "Task completed")
    } else if normalized_event.starts_with("tool.failed")
        || normalized_event.starts_with("tool.rejected")
        || normalized_event.starts_with("tool.timeout")
        || normalized_event.starts_with("error")
        || normalized_event.starts_with("warning")
    {
        ("warning", "Attention needed")
    } else if normalized_event.starts_with("tool") {
        ("working", "Tool is running")
    } else if normalized_event.starts_with("audio") {
        ("blink", "Listening")
    } else {
        ("idle", "Desktop pet is idle")
    };
    let message = message
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(default_message);
    PetStateSnapshot {
        sequence: 0,
        state: state.to_string(),
        message: message.to_string(),
        event_type: normalized_event,
        source: source.trim().to_string(),
        updated_at_ms: unix_timestamp_millis(),
    }
}

fn desktop_pet_action_args(state: &str, message: &str) -> Vec<String> {
    vec![
        "--pet-state".to_string(),
        state.to_string(),
        "--pet-message".to_string(),
        message.to_string(),
    ]
}

fn dispatch_desktop_pet_action(snapshot: &PetStateSnapshot) -> bool {
    #[cfg(test)]
    {
        let _ = snapshot;
        false
    }
    #[cfg(not(test))]
    {
        if desktop_pet_disabled() {
            return false;
        }
        let Some(exe) = desktop_pet_executable() else {
            return false;
        };
        let mut command = std::process::Command::new(&exe);
        command.args(desktop_pet_action_args(&snapshot.state, &snapshot.message));
        #[cfg(windows)]
        command.creation_flags(CREATE_NO_WINDOW);
        match command.spawn() {
            Ok(_) => true,
            Err(error) => {
                warn!("桌宠状态触发失败: {error}");
                false
            }
        }
    }
}

fn record_pet_event(event_type: &str, message: Option<&str>, source: &str) -> PetEventResponse {
    let mut snapshot = pet_status_for_backend_event(event_type, message, source);
    snapshot.sequence = PET_EVENT_SEQUENCE.fetch_add(1, Ordering::Relaxed) + 1;
    snapshot.updated_at_ms = unix_timestamp_millis();
    let delivered_to_tauri = dispatch_desktop_pet_action(&snapshot);
    if let Ok(mut state) = pet_state_store().lock() {
        *state = snapshot.clone();
    }
    broadcast_pet_event(snapshot.clone());
    PetEventResponse {
        snapshot,
        delivered_to_tauri,
    }
}

fn emit_backend_pet_event(event_type: &str, message: Option<&str>, source: &str) {
    let _ = record_pet_event(event_type, message, source);
}

fn emit_pet_event_for_tool_outcome(tool_name: &str, outcome: &ToolOutcome) {
    let event_type = match outcome.status {
        ToolOutcomeStatus::Ok => "tool.ok",
        ToolOutcomeStatus::DryRunOnly => {
            if outcome.permission_gate.decision.requires_ui() {
                "tool.rejected"
            } else {
                "tool.dry-run"
            }
        }
        ToolOutcomeStatus::Rejected => "tool.rejected",
        ToolOutcomeStatus::Failed => "tool.failed",
        ToolOutcomeStatus::Timeout => "tool.timeout",
    };
    let message = format!("{}: {}", tool_name, outcome.summary_text);
    emit_backend_pet_event(event_type, Some(&message), "tool");
}

async fn api_pet_state() -> Json<PetStateResponse> {
    let snapshot = pet_state_store()
        .lock()
        .map(|state| state.clone())
        .unwrap_or_else(|_| default_pet_state_snapshot());
    Json(PetStateResponse {
        snapshot,
        desktop_pet_disabled: desktop_pet_disabled(),
        desktop_pet_exe: desktop_pet_executable().map(|path| path.display().to_string()),
    })
}

async fn api_showui_service() -> Json<ShowUiServiceResponse> {
    Json(showui_service_status_with_message(
        "ShowUI service status loaded.",
    ))
}

async fn api_showui_service_update(
    Json(payload): Json<ShowUiServiceRequest>,
) -> ApiResult<Json<ShowUiServiceResponse>> {
    let action = payload
        .action
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_ascii_lowercase);
    let response = match (payload.enabled, action.as_deref()) {
        (Some(true), _) | (_, Some("start")) => start_showui_service(&showui_console_url()),
        (Some(false), _) | (_, Some("stop")) => stop_showui_service(),
        (_, Some("restart")) => {
            let url = showui_console_url();
            let _ = stop_showui_service();
            start_showui_service(&url)
        }
        (None, None) => showui_service_status_with_message("ShowUI service status loaded."),
        (_, Some(_)) => {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "action must be start, stop, or restart",
            ));
        }
    };
    Ok(Json(response))
}

async fn api_pet_event(Json(payload): Json<PetEventRequest>) -> ApiResult<Json<PetEventResponse>> {
    if payload.event_type.trim().is_empty() {
        return Err(api_error(StatusCode::BAD_REQUEST, "event_type 不能为空"));
    }
    let response = record_pet_event(
        &payload.event_type,
        payload.message.as_deref(),
        payload.source.as_deref().unwrap_or("api"),
    );
    Ok(Json(response))
}

/// 桌宠拖入文件的"待取附件"队列：drop-files 把移好的附件入队，聊天室前端轮询
/// `GET /api/pet/pending-attachments` 取出并加进 composer（桌宠进程与浏览器前端是两个端，
/// 需要这个队列桥接）。
fn pet_dropped_attachments_queue() -> &'static Mutex<Vec<ChatAttachmentDto>> {
    static QUEUE: OnceLock<Mutex<Vec<ChatAttachmentDto>>> = OnceLock::new();
    QUEUE.get_or_init(|| Mutex::new(Vec::new()))
}

/// GET /api/pet/pending-attachments：取出并清空待加入 composer 的拖入附件。
async fn api_pet_pending_attachments() -> Json<PetDropFilesResponse> {
    let attachments = pet_dropped_attachments_queue()
        .lock()
        .map(|mut q| std::mem::take(&mut *q))
        .unwrap_or_default();
    Json(PetDropFilesResponse {
        attachments,
        moved: Vec::new(),
        skipped: Vec::new(),
    })
}

/// 桌宠文件拖放：把拖到桌宠图标的本地文件"移动"进当前 workspace 的附件目录
/// （`attachment_store_dir()` 本就在 workspace 作用域下，满足"放进 workspace"语义，
/// 且复用现有 `/api/attachments/files/{name}` 二进制服务与图片/视频/音频内联预览），
/// 并返回附件 DTO 供前端加入 composer 附件区；同时让桌宠播 carrying 动画。
async fn api_pet_drop_files(
    Json(payload): Json<PetDropFilesRequest>,
) -> ApiResult<Json<PetDropFilesResponse>> {
    let store_dir = attachment_store_dir();
    tokio::fs::create_dir_all(&store_dir)
        .await
        .map_err(|error| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                &format!("无法创建附件目录: {error}"),
            )
        })?;

    let mut attachments = Vec::new();
    let mut moved = Vec::new();
    let mut skipped = Vec::new();
    for raw in &payload.paths {
        let src = PathBuf::from(raw.trim());
        let meta = match std::fs::metadata(&src) {
            Ok(meta) if meta.is_file() => meta,
            _ => {
                skipped.push(format!("{raw}（不存在或非文件）"));
                continue;
            }
        };
        if meta.len() > attachment_upload_limit_bytes() as u64 {
            skipped.push(format!("{raw}（超过附件大小上限）"));
            continue;
        }
        let original_name = src
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("dropped-file")
            .to_string();
        let attachment_id = format!(
            "att-{}-{:016x}",
            unix_timestamp_millis(),
            hash_bytes(raw.as_bytes())
        );
        let mut file_name = attachment_file_name(&attachment_id, &original_name);
        // 目标名冲突时加序号，避免覆盖已有附件。
        let mut dest = store_dir.join(&file_name);
        let mut dedupe = 1u32;
        while dest.exists() {
            file_name = format!(
                "{attachment_id}-{dedupe}-{}",
                sanitize_attachment_file_name(&original_name)
            );
            dest = store_dir.join(&file_name);
            dedupe = dedupe.saturating_add(1);
        }
        // 移动：同盘 rename，跨盘 copy+remove（按用户要求删原件）。
        let moved_ok = match std::fs::rename(&src, &dest) {
            Ok(()) => true,
            Err(_) => match std::fs::copy(&src, &dest) {
                Ok(_) => std::fs::remove_file(&src).is_ok() || true,
                Err(error) => {
                    skipped.push(format!("{raw}（移动失败: {error}）"));
                    false
                }
            },
        };
        if !moved_ok {
            continue;
        }
        let response = uploaded_attachment_response(
            &attachment_id,
            &original_name,
            "file",
            mime_type_for_url(&original_name).map(str::to_string),
            meta.len(),
        );
        // 用去重后的真实文件名覆盖 url（uploaded_attachment_response 按原始 id+name 生成，需对齐 dedupe 名）。
        let mut attachment = response.attachment;
        attachment.url = attachment_file_url(&file_name);
        attachments.push(attachment);
        moved.push(original_name);
    }

    let pet_message = if attachments.is_empty() {
        "没有可接收的文件".to_string()
    } else {
        format!("已接收 {} 个文件，放进工作区附件", attachments.len())
    };
    emit_backend_pet_event("file.dropped", Some(&pet_message), "pet");

    // 入队，供聊天室前端轮询取出加进 composer（桌宠进程拿到的响应到不了浏览器前端）。
    if let Ok(mut queue) = pet_dropped_attachments_queue().lock() {
        queue.extend(attachments.iter().cloned());
    }

    Ok(Json(PetDropFilesResponse {
        attachments,
        moved,
        skipped,
    }))
}

/// 桌宠 HTML5 拖放上传：WebView2 网页层接收 drop 拿不到磁盘路径，改由前端读出文件内容（base64）
/// 经 Tauri command + reqwest 转发到此端点。这里 decode 后写入 workspace 附件目录、登记并入队，
/// 与 `api_pet_drop_files` 等价（差别仅在数据来源：内容 vs 路径，且无法删除原磁盘文件）。
async fn api_pet_drop_upload(
    Json(payload): Json<PetDropUploadRequest>,
) -> ApiResult<Json<PetDropFilesResponse>> {
    use base64::Engine;
    let store_dir = attachment_store_dir();
    tokio::fs::create_dir_all(&store_dir)
        .await
        .map_err(|error| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                &format!("无法创建附件目录: {error}"),
            )
        })?;

    let mut attachments = Vec::new();
    let mut moved = Vec::new();
    let mut skipped = Vec::new();
    for f in &payload.files {
        let trimmed = f.name.trim();
        let name = if trimmed.is_empty() {
            "dropped-file"
        } else {
            trimmed
        };
        // 兼容带 "data:...;base64," 前缀的内容：取最后一段逗号之后的纯 base64。
        let b64 = f
            .content_base64
            .rsplit(',')
            .next()
            .unwrap_or(f.content_base64.as_str())
            .trim();
        let data = match base64::engine::general_purpose::STANDARD.decode(b64.as_bytes()) {
            Ok(bytes) => bytes,
            Err(error) => {
                skipped.push(format!("{name}（内容解码失败: {error}）"));
                continue;
            }
        };
        if data.is_empty() {
            skipped.push(format!("{name}（空文件）"));
            continue;
        }
        if data.len() > attachment_upload_limit_bytes() {
            skipped.push(format!("{name}（超过附件大小上限）"));
            continue;
        }
        let attachment_id = format!("att-{}-{:016x}", unix_timestamp_millis(), hash_bytes(&data));
        // 存盘用原始文件名（清理非法字符），仅在重名时加序号，保持文件名可读（不加 att-id 前缀）。
        let base = sanitize_attachment_file_name(name);
        let mut file_name = base.clone();
        let mut dest = store_dir.join(&file_name);
        let mut dedupe = 1u32;
        while dest.exists() {
            file_name = match base.rsplit_once('.') {
                Some((stem, ext)) => format!("{stem}-{dedupe}.{ext}"),
                None => format!("{base}-{dedupe}"),
            };
            dest = store_dir.join(&file_name);
            dedupe = dedupe.saturating_add(1);
        }
        if let Err(error) = tokio::fs::write(&dest, &data).await {
            skipped.push(format!("{name}（写入失败: {error}）"));
            continue;
        }
        let mime = f
            .mime_type
            .as_deref()
            .map(str::trim)
            .filter(|m| !m.is_empty())
            .map(str::to_string)
            .or_else(|| mime_type_for_url(name).map(str::to_string));
        // 按 MIME 推断 kind，让图片/视频在聊天室正文内联预览（R-RICHTEXT-MEDIA）。
        let kind = match mime.as_deref() {
            Some(m) if m.starts_with("image/") => "image",
            Some(m) if m.starts_with("video/") => "video",
            Some(m) if m.starts_with("audio/") => "audio",
            _ => "file",
        };
        let response =
            uploaded_attachment_response(&attachment_id, name, kind, mime, data.len() as u64);
        let mut attachment = response.attachment;
        attachment.url = attachment_file_url(&file_name);
        attachments.push(attachment);
        moved.push(name.to_string());
    }

    let pet_message = if attachments.is_empty() {
        "没有可接收的文件".to_string()
    } else {
        format!("已接收 {} 个文件，放进工作区附件", attachments.len())
    };
    emit_backend_pet_event("file.dropped", Some(&pet_message), "pet");

    if let Ok(mut queue) = pet_dropped_attachments_queue().lock() {
        queue.extend(attachments.iter().cloned());
    }

    Ok(Json(PetDropFilesResponse {
        attachments,
        moved,
        skipped,
    }))
}

async fn api_pet_events(
) -> Sse<impl futures_core::Stream<Item = Result<Event, std::convert::Infallible>>> {
    let mut rx = subscribe_pet_events();
    let stream = async_stream::stream! {
        let current = pet_state_store()
            .lock()
            .map(|state| state.clone())
            .unwrap_or_else(|_| default_pet_state_snapshot());
        yield Ok::<Event, std::convert::Infallible>(sse_json_event("current", &current));
        loop {
            match rx.recv().await {
                Ok(event) => {
                    yield Ok(sse_json_event("pet-status", &event));
                }
                Err(broadcast::error::RecvError::Lagged(n)) => {
                    let payload = format!(r#"{{"skipped":{n}}}"#);
                    yield Ok(Event::default().event("lagged").data(payload));
                }
                Err(broadcast::error::RecvError::Closed) => break,
            }
        }
    };
    Sse::new(stream)
}

/// REQ-TOOL-009：审计日志路径。与 computer-use-audit 分开文件，便于独立归档。
///
/// 默认位置：`<workspace>/.coolzhu/tool-audit.jsonl`。
#[cfg(test)]
fn session_db_path_override_for_test() -> &'static Mutex<Option<PathBuf>> {
    static OVERRIDE: OnceLock<Mutex<Option<PathBuf>>> = OnceLock::new();
    OVERRIDE.get_or_init(|| Mutex::new(None))
}

#[cfg(test)]
fn current_session_db_path_override_for_test() -> Option<PathBuf> {
    session_db_path_override_for_test()
        .lock()
        .ok()
        .and_then(|path| path.clone())
}

#[cfg(test)]
fn replace_session_db_path_override_for_test(path: Option<PathBuf>) -> Option<PathBuf> {
    let mut guard = session_db_path_override_for_test()
        .lock()
        .unwrap_or_else(|error| error.into_inner());
    std::mem::replace(&mut *guard, path)
}

fn tool_audit_log_path() -> PathBuf {
    #[cfg(test)]
    if let Some(path) = current_session_db_path_override_for_test() {
        return PathBuf::from(path)
            .parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| {
                env::current_dir()
                    .unwrap_or_else(|_| PathBuf::from("."))
                    .join(DATA_DIR_NAME)
            })
            .join("tool-audit.jsonl");
    }
    if let Ok(path) = env::var("COOLZHU_WEB_SESSION_DB") {
        let trimmed = path.trim();
        if !trimmed.is_empty() {
            return PathBuf::from(trimmed)
                .parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| {
                    env::current_dir()
                        .unwrap_or_else(|_| PathBuf::from("."))
                        .join(DATA_DIR_NAME)
                })
                .join("tool-audit.jsonl");
        }
    }
    let config = read_config(Clone::clone);
    workspace_scope_paths_for(&active_workspace_path(), &config).audit_log
}

/// 每条审计记录的写入单元。
///
/// **严禁** 落原"`input` JSON 值（可能"API key / 密码）；只存
/// `build_input_summary` 投影出的字段"+ 长度摘要。
#[derive(Debug, Clone, Serialize, Deserialize)]
struct ToolAuditEntry {
    ts: String,
    call_id: String,
    tool_name: String,
    caller: String,
    workspace_id: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    session_id: Option<String>,
    input_summary: String,
    status: String,
    elapsed_ms: u64,
    permission: PendingApprovalPermission,
    summary_text: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    evidence: Option<JsonValue>,
}

/// REQ-TOOL-009：把一"`ToolOutcome` 追加"`tool-audit.jsonl`，失败降级为 warn。
///
/// 单调追加 (O_APPEND)，避免并"writer 覆盖；每行一"JSON，方"`jq` 离线分析。
fn append_tool_audit_record(invoke: &ToolInvoke, outcome: &ToolOutcome) {
    let ts = match SystemTime::now().duration_since(UNIX_EPOCH) {
        Ok(dur) => {
            let secs = dur.as_secs();
            let millis = dur.subsec_millis();
            format!("{secs}.{millis:03}")
        }
        Err(_) => "0".to_string(),
    };
    let entry = ToolAuditEntry {
        ts,
        call_id: outcome.call_id.clone(),
        tool_name: outcome.tool_name.clone(),
        caller: invoke.caller.as_str().to_string(),
        workspace_id: invoke.workspace_id.clone(),
        session_id: invoke.session_id.clone(),
        input_summary: build_input_summary(&invoke.tool_name, &invoke.input),
        status: outcome.status.as_str().to_string(),
        elapsed_ms: outcome.elapsed_ms,
        permission: PendingApprovalPermission {
            required: outcome.permission_gate.required.as_str().to_string(),
            decision: outcome.permission_gate.decision.as_str().to_string(),
            reason: outcome.permission_gate.reason.clone(),
            workspace_relative: outcome.permission_gate.workspace_relative,
            protected_match: outcome.permission_gate.protected_match.clone(),
            affected_paths: outcome.permission_gate.affected_paths.clone(),
        },
        summary_text: outcome.summary_text.chars().take(320).collect::<String>(),
        evidence: outcome.evidence.clone(),
    };
    let line = match serde_json::to_string(&entry) {
        Ok(s) => s,
        Err(err) => {
            warn!("[TOOL-AUDIT] serialize failed: {err}");
            return;
        }
    };
    let path = tool_audit_log_path();
    if let Some(parent) = path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let write_result = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&path)
        .and_then(|mut f| {
            use std::io::Write as IoWrite;
            f.write_all(line.as_bytes())?;
            f.write_all(b"\n")?;
            Ok(())
        });
    if let Err(err) = write_result {
        warn!(
            "[TOOL-AUDIT] append failed: path={}, err={err}",
            path.display()
        );
    }
}

#[derive(Debug, Deserialize)]
struct ToolAuditQuery {
    #[serde(default)]
    limit: Option<usize>,
}

#[derive(Debug, Serialize)]
struct ToolAuditResponse {
    entries: Vec<ToolAuditEntry>,
    path: String,
}

/// REQ-TOOL-009：`GET /api/tools/audit?limit=N`，读最"N 行（默认 50，上"500）。
///
/// 小规模场景下一次性读文件再从尾部截取；未来数据量大可改为 `BufRead::lines().rev()`。
async fn api_tools_audit(Query(query): Query<ToolAuditQuery>) -> Json<ToolAuditResponse> {
    let limit = query.limit.unwrap_or(50).clamp(1, 500);
    let path = tool_audit_log_path();
    let entries = read_tool_audit_entries(limit);
    Json(ToolAuditResponse {
        entries,
        path: path.display().to_string(),
    })
}

fn read_tool_audit_entries(limit: usize) -> Vec<ToolAuditEntry> {
    let limit = limit.clamp(1, 500);
    let path = tool_audit_log_path();
    std::fs::read_to_string(&path)
        .ok()
        .map(|content| {
            let mut collected: Vec<ToolAuditEntry> = content
                .lines()
                .filter(|line| !line.trim().is_empty())
                .filter_map(|line| serde_json::from_str::<ToolAuditEntry>(line).ok())
                .collect();
            if collected.len() > limit {
                let drop = collected.len() - limit;
                collected.drain(..drop);
            }
            collected
        })
        .unwrap_or_default()
}

async fn api_tools_events(
) -> Sse<impl futures_core::Stream<Item = Result<Event, std::convert::Infallible>>> {
    let mut rx = tool_event_bus().subscribe();
    let stream = async_stream::stream! {
        // 连接建立时发一"hello，方便前端确认通道可用
        yield Ok::<Event, std::convert::Infallible>(
            Event::default().event("hello").data("{\"ok\":true}"),
        );
        loop {
            match rx.recv().await {
                Ok(event) => {
                    let name = event.event_name().to_string();
                    yield Ok(sse_json_event(&name, &event));
                }
                Err(broadcast::error::RecvError::Lagged(n)) => {
                    let payload = format!(r#"{{"skipped":{n}}}"#);
                    yield Ok(Event::default().event("lagged").data(payload));
                }
                Err(broadcast::error::RecvError::Closed) => break,
            }
        }
    };
    Sse::new(stream)
}

