#[derive(Debug, Clone, Deserialize)]
struct ChatRoomPermissionUpdateRequest {
    permission_profile: String,
    #[serde(default)]
    risk_acknowledged: bool,
    #[serde(default)]
    confirmed_twice: bool,
}

#[derive(Debug, Clone, Serialize)]
struct ChatRoomPermissionStatus {
    room_id: String,
    room_name: String,
    permission_profile: String,
    full_access: bool,
    warning: String,
    updated_at: Option<u64>,
}

fn validate_chat_room_permission_update(
    payload: &ChatRoomPermissionUpdateRequest,
) -> ApiResult<String> {
    let profile = payload.permission_profile.trim();
    match profile {
        ROOM_PERMISSION_WORKSPACE_WRITE => Ok(profile.to_string()),
        ROOM_PERMISSION_FULL_ACCESS if !payload.risk_acknowledged => Err(api_error(
            StatusCode::BAD_REQUEST,
            "full access requires risk_acknowledged=true",
        )),
        ROOM_PERMISSION_FULL_ACCESS if !payload.confirmed_twice => Err(api_error(
            StatusCode::BAD_REQUEST,
            "full access requires confirmed_twice=true",
        )),
        ROOM_PERMISSION_FULL_ACCESS => Ok(profile.to_string()),
        _ => Err(api_error(
            StatusCode::BAD_REQUEST,
            "permission_profile must be workspace-write or full-access",
        )),
    }
}

async fn api_tools_pending() -> Json<PendingApprovalsResponse> {
    let pending = pending_approvals()
        .lock()
        .map(|map| {
            let now = Instant::now();
            map.values()
                .filter(|record| now.duration_since(record.created_at) < PENDING_APPROVAL_TTL)
                .cloned()
                .collect()
        })
        .unwrap_or_default();
    Json(PendingApprovalsResponse { pending })
}

fn resolve_full_access_session_id(requested: Option<String>) -> ApiResult<Option<String>> {
    let store = session_store()
        .lock()
        .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
    let session_id = requested.or_else(|| store.active_session_id());
    if let Some(session_id) = &session_id {
        if !store
            .state
            .sessions
            .iter()
            .any(|session| session.id == *session_id)
        {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        }
    }
    Ok(session_id)
}

async fn api_tools_full_access_status() -> ApiResult<Json<FullAccessGrantStatus>> {
    let workspace = active_workspace_path();
    let workspace_id = workspace_identity(&workspace);
    let session_id = resolve_full_access_session_id(None)?;
    Ok(Json(full_access_grant_status_for(
        &workspace_id,
        session_id.as_deref(),
    )))
}

async fn api_tools_full_access_grant(
    Json(mut payload): Json<FullAccessGrantRequest>,
) -> ApiResult<Json<FullAccessGrantStatus>> {
    let workspace = active_workspace_path();
    let workspace_id = workspace_identity(&workspace);
    payload.session_id = resolve_full_access_session_id(payload.session_id)?;
    let status = grant_full_access_for_session(&workspace_id, payload)?;
    append_full_access_audit_record(
        &workspace_id,
        status.session_id.as_deref(),
        "grant",
        &status,
    );
    Ok(Json(status))
}

async fn api_tools_full_access_revoke() -> ApiResult<Json<FullAccessGrantStatus>> {
    let workspace = active_workspace_path();
    let workspace_id = workspace_identity(&workspace);
    let session_id = resolve_full_access_session_id(None)?;
    let status = revoke_full_access_for_session(&workspace_id, session_id.as_deref());
    append_full_access_audit_record(
        &workspace_id,
        status.session_id.as_deref(),
        "revoke",
        &status,
    );
    Ok(Json(status))
}

#[derive(Debug, Deserialize)]
struct ApproveRequest {
    call_id: String,
    /// "once" / "session"。默""once"。
    #[serde(default)]
    scope: Option<String>,
    /// 针对 Protected / Danger 外部的二次确认。
    #[serde(default)]
    confirmed_twice: bool,
}

#[derive(Debug, Serialize)]
struct ApproveResponse {
    call_id: String,
    scope: String,
    confirmed_twice: bool,
    /// 会话级授权将维持 `ttl_secs` 秒。
    #[serde(skip_serializing_if = "Option::is_none")]
    ttl_secs: Option<u64>,
    #[serde(skip_serializing_if = "Option::is_none")]
    outcome: Option<ToolOutcome>,
}

async fn api_tools_approve(
    Json(payload): Json<ApproveRequest>,
) -> ApiResult<Json<ApproveResponse>> {
    let scope = payload.scope.as_deref().unwrap_or("once").to_string();
    let record = pending_approvals()
        .lock()
        .ok()
        .and_then(|mut pending| pending.remove(&payload.call_id));
    let Some(record) = record else {
        return Err(api_error(
            StatusCode::NOT_FOUND,
            "未找到对应待审批的工具调用，可能已过期或已被处理",
        ));
    };

    let confirmed_twice = payload.confirmed_twice
        || record.permission.decision == PermissionDecision::RequireConfirm.as_str();
    let ttl_secs = if scope == "session" {
        record_session_grant(
            &record.workspace_id,
            record.session_id.as_deref(),
            &record.tool_name,
            confirmed_twice,
        );
        Some(SESSION_GRANT_TTL.as_secs())
    } else {
        None
    };

    let outcome = execute_approved_pending_record(&record, confirmed_twice).await;

    append_tool_result_to_session(&record, &outcome);

    broadcast_tool_event(ToolEvent::Approved {
        call_id: payload.call_id.clone(),
        scope: scope.clone(),
        confirmed_twice,
        ttl_secs,
        summary_text: Some(outcome.summary_text.clone()),
        tool_name: Some(outcome.tool_name.clone()),
    });

    Ok(Json(ApproveResponse {
        call_id: payload.call_id,
        scope,
        confirmed_twice,
        ttl_secs,
        outcome: Some(outcome),
    }))
}

async fn execute_approved_pending_record(
    record: &PendingApprovalRecord,
    confirmed_twice: bool,
) -> ToolOutcome {
    let mut invoke = record.invoke.clone();
    invoke.user_authorized = true;
    invoke.user_confirmed_twice = confirmed_twice;
    invoke.input = runtime_tool_input_with_defaults(&invoke.tool_name, &invoke.input);
    let timeout_ms = tool_timeout_ms_for(&invoke.tool_name, &invoke.input);
    let outcome = execute_runtime_tool_with_timeout(
        invoke.clone(),
        record.workspace_root.clone(),
        timeout_ms,
        None,
    )
    .await;
    append_tool_audit_record(&invoke, &outcome);
    emit_pet_event_for_tool_outcome(&invoke.tool_name, &outcome);
    outcome
}

#[derive(Debug, Deserialize)]
struct RejectRequest {
    call_id: String,
    #[serde(default)]
    reason: Option<String>,
}

#[derive(Debug, Serialize)]
struct RejectResponse {
    call_id: String,
    reason: Option<String>,
}

async fn api_tools_reject(Json(payload): Json<RejectRequest>) -> ApiResult<Json<RejectResponse>> {
    let removed = pending_approvals()
        .lock()
        .ok()
        .and_then(|mut pending| pending.remove(&payload.call_id));
    if removed.is_none() {
        return Err(api_error(StatusCode::NOT_FOUND, "未找到对应待审批的工具调"));
    }
    broadcast_tool_event(ToolEvent::Rejected {
        call_id: payload.call_id.clone(),
        reason: payload.reason.clone(),
    });
    Ok(Json(RejectResponse {
        call_id: payload.call_id,
        reason: payload.reason,
    }))
}

/// REQ-TOOL-007 Phase C-3：`runtime_tool_execute` "HTTP 入口。
///
/// 这是首个"runtime 统一链路挂到 prod 请求路径上的端点，故意用"URL
/// （`/api/tools/runtime-execute`）而不是复"`/api/tools/execute`，让"Tool
/// Loop / Computer Use 闸门保持原样，便于逐个客户端灰度切换。
///
/// 行为。
/// 1. 构"`ToolInvoke{caller = WebUi}`；`session_id` 默认当前 active session。
/// 2. "`path_targets`、查 `required_permission`、查 `session_grant_view_for` 会话级授权。
/// 3. "`runtime_tool_execute(invoke, ctx)`。executor 负责执行 registry 工具。
///    是否允许执行"runtime permission gate 统一判定。
/// 4. 若结果是 `DryRunOnly` 且决策是 `RequireApproval` / `RequireConfirm`。
///    自动 `enqueue_pending_approval`，前端可立即 `/api/tools/pending` 拉到。
#[derive(Debug, Deserialize)]
struct RuntimeExecuteRequest {
    call_id: Option<String>,
    tool_name: String,
    #[serde(default)]
    input: JsonValue,
    #[serde(default)]
    session_id: Option<String>,
    #[serde(default)]
    user_authorized: bool,
    #[serde(default)]
    user_confirmed_twice: bool,
}

#[derive(Debug, Serialize)]
struct RuntimeExecuteResponse {
    outcome: ToolOutcome,
    /// "outcome 触发"pending 登记，前端可用此 id "`/api/tools/pending` 查看。
    #[serde(skip_serializing_if = "Option::is_none")]
    pending_call_id: Option<String>,
}

async fn api_tools_runtime_execute(
    Json(payload): Json<RuntimeExecuteRequest>,
) -> ApiResult<Json<RuntimeExecuteResponse>> {
    if payload.tool_name.trim().is_empty() {
        return Err(api_error(StatusCode::BAD_REQUEST, "tool_name 不能为空"));
    }

    let call_id = payload
        .call_id
        .clone()
        .unwrap_or_else(|| format!("rt-{}", unix_timestamp_millis()));
    let workspace_root = active_workspace_path();
    let workspace_id = workspace_identity(&workspace_root);

    let invoke = ToolInvoke {
        call_id: call_id.clone(),
        tool_name: payload.tool_name.clone(),
        input: payload.input.clone(),
        caller: ToolCaller::WebUi,
        workspace_id: workspace_id.clone(),
        session_id: payload.session_id.clone(),
        user_authorized: payload.user_authorized,
        user_confirmed_twice: payload.user_confirmed_twice,
    };

    let timeout_ms = tool_timeout_ms_for(&payload.tool_name, &payload.input);
    let outcome =
        execute_runtime_tool_with_timeout(invoke.clone(), workspace_root.clone(), timeout_ms, None)
            .await;

    let pending_call_id = if matches!(outcome.status, ToolOutcomeStatus::DryRunOnly)
        && outcome.permission_gate.decision.requires_ui()
    {
        enqueue_pending_approval(&call_id, &invoke, &outcome.permission_gate);
        info!(
            "[TOOL-GATE] tool='{}' decision={} enqueued pending call_id={}",
            invoke.tool_name,
            outcome.permission_gate.decision.as_str(),
            call_id
        );
        Some(call_id.clone())
    } else {
        info!(
            "[TOOL-EXEC] tool='{}' status={} elapsed_ms={}",
            invoke.tool_name,
            outcome.status.as_str(),
            outcome.elapsed_ms
        );
        None
    };

    // REQ-TOOL-009：无"Ok/DryRunOnly/Failed/Rejected，一律落审计；只写摘要"    append_tool_audit_record(&invoke, &outcome);
    emit_pet_event_for_tool_outcome(&invoke.tool_name, &outcome);

    Ok(Json(RuntimeExecuteResponse {
        outcome,
        pending_call_id,
    }))
}

