fn default_audio_streaming_tts_timeout_seconds() -> u64 {
    30
}

fn configured_streaming_tts_url(config: &ConfigAudioRealtime) -> Option<String> {
    config
        .streaming_tts_url
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
}

fn streaming_tts_url_from_request_or_config(
    request_url: Option<&str>,
    config: &ConfigAudioRealtime,
) -> Option<String> {
    request_url
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .or_else(|| configured_streaming_tts_url(config))
}

fn default_audio_index_tts_timeout_secs() -> u64 {
    30
}

