#[derive(Debug, Clone, Serialize, Deserialize)]
struct ConfigModel {
    #[serde(default)]
    reasoning: Option<String>,
    #[serde(default)]
    enable_real_llm: bool,
    #[serde(default)]
    enable_llm_tools: bool,
    /// REQ-TOOL-007 Phase C-10：LLM 可见工具暴露策略。
    ///
    /// - `"dispatch-only"`：只暴露 `tools_semantic_dispatch`（Phase C-9 前的行为。
    /// - `"whitelist"`（默认）：`tools_semantic_dispatch` + ReadOnly 档工。
    /// - `"all"`：`tools_semantic_dispatch` + `mvp_tool_specs` 全部工具
    ///
    /// 未设置时默认 `"whitelist"`；开发开放模式下会强制全量暴露。
    #[serde(default)]
    llm_tool_exposure: Option<String>,
    /// P1.5：启用真实语义记忆召回（/v1/embeddings）。默认关 → 维持 keyword + hash 回退。
    #[serde(default)]
    enable_semantic_memory: bool,
    /// 语义记忆嵌入模型名（默认 bge-m3）；base_url/api_key 复用 custom provider/env。
    #[serde(default)]
    semantic_memory_model: Option<String>,
    /// 语义嵌入端点 base_url（默认本地 llama.cpp `--embeddings` 端口 `http://127.0.0.1:8081/v1`）。
    #[serde(default)]
    semantic_embedder_base_url: Option<String>,
    /// B 衰减：召回按 effective_recall_score 重排（默认关 → 现序不变）。
    #[serde(default)]
    enable_memory_decay_ordering: bool,
    /// 本地文本推理使用的 GGUF 模型文件；只从 workspace config 读取。
    #[serde(default)]
    local_chat_model_path: Option<String>,
    /// 可选的多模态投影 GGUF 文件；文本模型可留空。
    #[serde(default)]
    local_chat_mmproj_path: Option<String>,
    /// coolzhu 本地聊天模型服务端口；会话预算、健康检查和启动命令共用此配置。
    #[serde(default = "default_local_chat_port")]
    local_chat_port: u16,
    /// llama-server 实际上下文窗口，必须与启动参数 `-c` 一致。
    #[serde(default = "default_local_chat_context_window")]
    local_chat_context_window: u32,
    /// 本地模型单轮最大输出；同时用于上下文预留和 OpenAI-compatible 请求。
    #[serde(default = "default_local_chat_max_output_tokens")]
    local_chat_max_output_tokens: u32,
    /// Gemma 思考 token 上限；必须小于最大输出，避免只返回 reasoning_content 而没有最终正文。
    #[serde(default = "default_local_chat_reasoning_budget")]
    local_chat_reasoning_budget: u32,
    /// llama-server GPU layers。
    #[serde(default = "default_local_chat_gpu_layers")]
    local_chat_gpu_layers: u32,
    /// llama-server 并发槽位。8GB 显存默认单槽，避免 KV cache 被自动拆成多份。
    #[serde(default = "default_local_chat_parallel_slots")]
    local_chat_parallel_slots: u32,
    /// 启动后等待 `/health` ready 的最长时间。
    #[serde(default = "default_local_chat_startup_timeout_ms")]
    local_chat_startup_timeout_ms: u64,
}

