fn plugin_catalog_items() -> Vec<ToolCatalogItemDetail> {
    let mut items = Vec::new();
    let mut seen = HashSet::new();

    for root in plugin_source_roots() {
        let source = root.source;
        let source_label = root.label;
        for plugin_dir in child_directories(&root.path) {
            let plugin_key = plugin_dir
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or_default()
                .to_string();
            if plugin_key.is_empty() {
                continue;
            }
            let dedupe_key = format!("{source}:{plugin_key}");
            if !seen.insert(dedupe_key) {
                continue;
            }

            match plugins::load_plugin_from_directory(&plugin_dir) {
                Ok(manifest) => {
                    let source_kind = if source == "opencode" {
                        "opencode-candidate"
                    } else {
                        "local-plugin"
                    };
                    let status = if source == "opencode" {
                        "candidate"
                    } else if manifest.default_enabled {
                        "available"
                    } else {
                        "disabled"
                    };
                    let plugin_permissions = manifest
                        .permissions
                        .iter()
                        .map(|permission| permission.as_str().to_string())
                        .collect::<Vec<_>>();
                    let children = manifest
                        .tools
                        .iter()
                        .map(|tool| {
                            let permission = tool.required_permission.as_str().to_string();
                            ToolCatalogChildDto {
                                id: format!("plugin.{}.{}", manifest.name, tool.name),
                                name: tool.name.clone(),
                                display_name: tool.name.clone(),
                                kind: "plugin-tool".to_string(),
                                status: if source == "opencode" {
                                    "candidate".to_string()
                                } else {
                                    "available".to_string()
                                },
                                risk: risk_for_permission(&permission),
                                permissions: vec![permission],
                                executable_now: false,
                                summary: tool.description.clone(),
                                input_schema: Some(tool.input_schema.clone()),
                                command: Some(tool.command.clone()),
                                args: tool.args.clone(),
                                path: Some(plugin_dir.display().to_string()),
                            }
                        })
                        .collect::<Vec<_>>();
                    let risk = children
                        .iter()
                        .map(|child| child.risk.as_str())
                        .max_by_key(|risk| risk_rank(risk))
                        .unwrap_or_else(|| risk_for_plugin_permissions(&plugin_permissions));
                    let summary = if manifest.tools.is_empty() {
                        manifest.description.clone()
                    } else {
                        format!(
                            "{}；包含 {} 个工具",
                            manifest.description,
                            manifest.tools.len()
                        )
                    };
                    let mut notes = vec![
                        format!("插件清单来源：{}", plugin_dir.display()),
                        "catalog 阶段不执行插件 hook、生命周期或工具命令。".to_string(),
                    ];
                    if source == "opencode" {
                        notes.push(
                            "候选插件来自 opencode，迁移前需要路径、权限和脚本 dry-run 验证。"
                                .to_string(),
                        );
                    }
                    items.push(tool_detail_with_children(
                        ToolCatalogItemSummary {
                            id: format!("plugin.{}", manifest.name),
                            name: manifest.name.clone(),
                            display_name: manifest.name,
                            category_id: "plugins".to_string(),
                            category_name: "Plugins".to_string(),
                            source: source_kind.to_string(),
                            source_label: source_label.clone(),
                            status: status.to_string(),
                            risk: risk.to_string(),
                            permissions: plugin_permissions,
                            executable_now: false,
                            summary,
                            action_hint: "点可用查看插件工具；真实执行后续 dry-run/execute"
                                .to_string(),
                            tool_count: Some(manifest.tools.len()),
                        },
                        None,
                        children,
                        notes,
                        vec!["迁移前检查脚本路径、工作目录假设和权限声明".to_string()],
                    ));
                }
                Err(error) => {
                    items.push(tool_detail(
                        ToolCatalogItemSummary {
                            id: format!("plugin.invalid.{plugin_key}"),
                            name: plugin_key.clone(),
                            display_name: plugin_key,
                            category_id: "plugins".to_string(),
                            category_name: "Plugins".to_string(),
                            source: if source == "opencode" {
                                "opencode-candidate".to_string()
                            } else {
                                "local-plugin".to_string()
                            },
                            source_label: source_label.clone(),
                            status: "invalid".to_string(),
                            risk: "medium".to_string(),
                            permissions: Vec::new(),
                            executable_now: false,
                            summary: format!("插件清单读取失败：{error}"),
                            action_hint: "需要修复清单或脚本路径后再纳入目录".to_string(),
                            tool_count: None,
                        },
                        None,
                        Some(plugin_dir.display().to_string()),
                        vec![format!("目录：{}", plugin_dir.display())],
                    ));
                }
            }
        }
    }

    items
}

fn skill_catalog_items() -> Vec<ToolCatalogItemDetail> {
    let mut items = Vec::new();
    let mut seen = HashSet::new();

    for root in skill_source_roots() {
        let source = root.source;
        let source_label = root.label;
        for skill_dir in child_directories(&root.path) {
            let skill_file = skill_dir.join("SKILL.md");
            if !skill_file.exists() {
                continue;
            }
            let Some(name_from_dir) = skill_dir.file_name().and_then(|name| name.to_str()) else {
                continue;
            };
            let parsed = parse_skill_metadata(&skill_file);
            let name = parsed.name.unwrap_or_else(|| name_from_dir.to_string());
            let dedupe_key = format!("{source}:{name}");
            if !seen.insert(dedupe_key) {
                continue;
            }
            let is_candidate = source == "opencode";
            let status = if is_candidate {
                "candidate"
            } else {
                "available"
            };
            let summary = parsed
                .description
                .unwrap_or_else(|| "本地技能说明，加载后向模型提供专用工作流".to_string());
            let mut notes = vec![
                "SKILL 只读展示，不在 catalog 阶段自动加载或执行。".to_string(),
                format!("文件：{}", skill_file.display()),
            ];
            if is_candidate {
                notes.push(
                    "候选 SKILL 来自 opencode，迁移前需要检查路径、命令和依赖假设。".to_string(),
                );
            }
            items.push(tool_detail(
                ToolCatalogItemSummary {
                    id: format!("skill.{name}"),
                    name: name.clone(),
                    display_name: name,
                    category_id: "skills".to_string(),
                    category_name: "Skills".to_string(),
                    source: if is_candidate {
                        "opencode-candidate".to_string()
                    } else {
                        "local-skill".to_string()
                    },
                    source_label: source_label.clone(),
                    status: status.to_string(),
                    risk: "low".to_string(),
                    permissions: vec!["read-only".to_string()],
                    executable_now: false,
                    summary,
                    action_hint: "点可用查看来源；迁移后再接入 Skill 调用".to_string(),
                    tool_count: None,
                },
                Some(schema_with_required(&["skill", "args"])),
                None,
                notes,
            ));
        }
    }

    items
}

fn tool_detail(
    item: ToolCatalogItemSummary,
    input_schema: Option<JsonValue>,
    path: Option<String>,
    notes: Vec<String>,
) -> ToolCatalogItemDetail {
    let mut detail = tool_detail_with_children(item, input_schema, Vec::new(), notes, Vec::new());
    detail.path = path;
    detail
}

fn tool_detail_with_children(
    item: ToolCatalogItemSummary,
    input_schema: Option<JsonValue>,
    children: Vec<ToolCatalogChildDto>,
    notes: Vec<String>,
    migration_notes: Vec<String>,
) -> ToolCatalogItemDetail {
    let dry_run_enabled = tool_supports_dry_run(&item);
    let actions = vec![
        ToolActionDto {
            id: "inspect".to_string(),
            label: "可用".to_string(),
            enabled: true,
            hint: "展开 schema、来源和风险说明".to_string(),
        },
        ToolActionDto {
            id: "dry-run".to_string(),
            label: "dry-run".to_string(),
            enabled: dry_run_enabled,
            hint: if dry_run_enabled {
                "执行安全预演；不触发真实键鼠、文件写入或插件脚本"
            } else {
                "该目录项暂未接入 dry-run 执行协议"
            }
            .to_string(),
        },
        ToolActionDto {
            id: "execute".to_string(),
            label: "execute".to_string(),
            enabled: false,
            hint: "真实执行暂未开放".to_string(),
        },
    ];

    ToolCatalogItemDetail {
        item,
        actions,
        input_schema,
        path: None,
        command: None,
        args: Vec::new(),
        children,
        notes,
        migration_notes,
    }
}

fn tool_supports_dry_run(item: &ToolCatalogItemSummary) -> bool {
    matches!(
        item.id.as_str(),
        "vision.capture_desktop"
            | "vision.describe_screen"
            | "vision.find_target"
            | "vision.find_region"
            | "computer.safe_context_menu"
            | "computer.safe_drag_select"
            | "computer.left_click"
            | "computer.right_click"
            | "computer.double_click"
            | "computer.context_menu_select"
            | "computer.drag_select"
            | "computer.visual_action"
            | "computer.scroll"
            | "computer.text_input"
            | "computer.press_key"
            | "computer.hotkey"
            | "computer.closed_loop"
            | "computer.profile"
            | "tools.semantic_dispatch"
            | "core.read_file"
            | "core.glob_search"
            | "core.grep_search"
            | "core.ToolSearch"
            | "core.Sleep"
    )
}

