async fn api_config_vision_agent() -> ApiResult<Json<VisionAgentConfigResponse>> {
    let store = session_store()
        .lock()
        .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
    let session_id = store.state.active_vision_session_id.clone();
    drop(store);
    let session = session_id.as_deref().and_then(|id| session_by_id(id));
    Ok(Json(VisionAgentConfigResponse { session }))
}

async fn api_config_set_vision_agent(
    Json(payload): Json<VisionAgentSetRequest>,
) -> ApiResult<Json<VisionAgentConfigResponse>> {
    let session_id = payload.agent_id.trim();
    diag!("[VISION-API] set_vision_agent: agent_id='{session_id}'");
    if session_id.is_empty() {
        let mut store = session_store()
            .lock()
            .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
        store.state.active_vision_session_id = None;
        store.save()?;
        return Ok(Json(VisionAgentConfigResponse { session: None }));
    }
    let session = session_by_id(session_id)
        .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "指定视觉会话不存"))?;
    if !is_understanding_model_type(&session.model_type) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "指定会话不是视觉/多模态类型 Agent",
        ));
    }
    let mut store = session_store()
        .lock()
        .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
    store.state.active_vision_session_id = Some(session_id.to_string());
    store.save()?;
    Ok(Json(VisionAgentConfigResponse {
        session: Some(session),
    }))
}

fn session_by_id(session_id: &str) -> Option<SessionSummaryDto> {
    let store = session_store().lock().ok()?;
    store
        .state
        .sessions
        .iter()
        .find(|session| session.id == session_id)
        .map(|session| {
            session.summary(store.state.active_session_id.as_deref() == Some(&session.id))
        })
}

