struct SessionModelLimitResponse {
    session_id: String,
    model: String,
    context_window: u32,
    max_output_tokens: u32,
    default_context_window: u32,
    default_max_output_tokens: u32,
    overridden: bool,
}

#[derive(Debug, Deserialize)]
struct SessionModelLimitUpdateRequest {
    #[serde(default)]
    context_window: u32,
    #[serde(default)]
    max_output_tokens: u32,
}

fn session_model_limit_response(
    session_id: String,
    model: String,
    overridden: bool,
) -> SessionModelLimitResponse {
    let default_limit = api::model_token_limit(&model);
    let (eff_ctx, eff_out) = effective_model_limit_for(&session_id, &model);
    SessionModelLimitResponse {
        session_id,
        model,
        context_window: eff_ctx,
        max_output_tokens: eff_out,
        default_context_window: default_limit.context_tokens,
        default_max_output_tokens: default_limit.max_output_tokens,
        overridden,
    }
}

/// GET /api/sessions/{id}/model-limit：返回该会话当前生效与默认的 token 限制，供前端 custom provider 手填回显。
async fn api_get_session_model_limit(
    AxumPath(session_id): AxumPath<String>,
) -> ApiResult<Json<SessionModelLimitResponse>> {
    let model = {
        let store = session_store()
            .lock()
            .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
        store
            .find_session(&session_id)
            .map(|s| s.model.clone())
            .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "会话不存在"))?
    };
    let overridden = read_config(|c| {
        c.session_model_limits
            .get(&session_id)
            .map(|o| o.context_window > 0 || o.max_output_tokens > 0)
            .unwrap_or(false)
    });
    Ok(Json(session_model_limit_response(
        session_id, model, overridden,
    )))
}

/// POST /api/sessions/{id}/model-limit：写入手填覆盖（context_window/max_output_tokens）；两者皆 0 则清除覆盖、回退默认表。
async fn api_set_session_model_limit(
    AxumPath(session_id): AxumPath<String>,
    Json(payload): Json<SessionModelLimitUpdateRequest>,
) -> ApiResult<Json<SessionModelLimitResponse>> {
    let model = {
        let store = session_store()
            .lock()
            .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
        store
            .find_session(&session_id)
            .map(|s| s.model.clone())
            .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "会话不存在"))?
    };
    // 上限保护，避免误填超大值导致预算计算异常。
    let ctx = payload.context_window.min(4_000_000);
    let out = payload.max_output_tokens.min(1_000_000);
    mutate_workspace_config(|config| {
        if ctx == 0 && out == 0 {
            config.session_model_limits.remove(&session_id);
        } else {
            config.session_model_limits.insert(
                session_id.clone(),
                SessionModelLimitOverride {
                    context_window: ctx,
                    max_output_tokens: out,
                },
            );
        }
        Ok(())
    })?;
    Ok(Json(session_model_limit_response(
        session_id,
        model,
        ctx > 0 || out > 0,
    )))
}

async fn api_session_context_preview(
    AxumPath(session_id): AxumPath<String>,
    Query(query): Query<ContextPreviewQuery>,
) -> ApiResult<Json<ContextAssembly>> {
    let store = session_store()
        .lock()
        .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
    let Some(session) = store.find_session(&session_id).cloned() else {
        return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
    };
    let room_id = query
        .room_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .or_else(|| store.active_chat_room_id())
        .unwrap_or_else(|| DEFAULT_CHAT_ROOM_ID.to_string());
    let room_history = store
        .state
        .chat_rooms
        .iter()
        .find(|room| room.id == room_id)
        .map(|room| room.messages.clone())
        .unwrap_or_default();
    let context_reset_floor = context_reset_floor_from_value(session.context_reset_at);
    let agent = session.to_agent_session(store.is_active(&session_id));
    let prompt = query.prompt.unwrap_or_default();
    drop(store);
    Ok(Json(build_context_assembly(
        &agent,
        &room_history,
        &prompt,
        &[],
        context_build_options_for_agent_with_floor(&agent, context_reset_floor),
    )))
}

