fn clawbot_channel_state() -> &'static Mutex<clawbot_channel::ClawbotChannelState> {
    static STATE: OnceLock<Mutex<clawbot_channel::ClawbotChannelState>> = OnceLock::new();
    STATE.get_or_init(|| {
        let path = clawbot_channel_state_path();
        let state =
            clawbot_channel::ClawbotChannelState::load_from_path(&path).unwrap_or_else(|error| {
                warn!("加载 ClawBot 通道状态失败，将使用空状态: {error}");
                clawbot_channel::ClawbotChannelState::default()
            });
        Mutex::new(state)
    })
}

fn clawbot_channel_state_path() -> PathBuf {
    active_workspace_path()
        .join(DATA_DIR_NAME)
        .join("clawbot-channel.json")
}

fn clawbot_gateway_state_path() -> PathBuf {
    active_workspace_path()
        .join(DATA_DIR_NAME)
        .join("clawbot-gateway.sqlite3")
}

fn clawbot_gateway_state() -> ApiResult<&'static Mutex<clawbot_gateway::ClawbotGatewayStore>> {
    static STATE: OnceLock<Result<Mutex<clawbot_gateway::ClawbotGatewayStore>, String>> =
        OnceLock::new();
    match STATE.get_or_init(|| {
        clawbot_gateway::ClawbotGatewayStore::open(&clawbot_gateway_state_path()).map(Mutex::new)
    }) {
        Ok(state) => Ok(state),
        Err(error) => Err(api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("初始化 ClawBot gateway 失败：{error}"),
        )),
    }
}

fn clawbot_gateway_lock() -> ApiResult<MutexGuard<'static, clawbot_gateway::ClawbotGatewayStore>> {
    clawbot_gateway_state()?.lock().map_err(|_| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            "ClawBot gateway 状态锁已损坏",
        )
    })
}

