async fn api_clawbot_gateway_login() -> ApiResult<Json<clawbot_gateway::ClawbotLoginSnapshot>> {
    let store = clawbot_gateway_lock()?;
    let mut snapshot = store
        .load_login_snapshot()
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
    let effective_state = snapshot.effective_state(uuid_timestamp());
    if effective_state != snapshot.state {
        snapshot.state = effective_state;
        store
            .save_login_snapshot(&snapshot)
            .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
    }
    Ok(Json(snapshot))
}

fn clawbot_login_poll_needed(state: &clawbot_gateway::ClawbotLoginState) -> bool {
    matches!(
        state,
        clawbot_gateway::ClawbotLoginState::RefreshRequested
            | clawbot_gateway::ClawbotLoginState::AwaitingScan
    )
}

async fn api_clawbot_gateway_login_poll() -> ApiResult<Json<clawbot_gateway::ClawbotLoginSnapshot>>
{
    let now_ms = uuid_timestamp();
    let snapshot = {
        let store = clawbot_gateway_lock()?;
        store
            .load_login_snapshot()
            .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?
    };
    if !clawbot_login_poll_needed(&snapshot.state) {
        return Ok(Json(snapshot));
    }

    let generation = snapshot.generation;
    let snapshot = match call_clawbot_sidecar_login_refresh(generation, now_ms).await {
        ClawbotSidecarLoginRefreshResult::Report(report) => {
            record_clawbot_login_refresh_report(report, uuid_timestamp())?
        }
        ClawbotSidecarLoginRefreshResult::Error(error) => {
            diag!("[CLAWBOT] login poll transient error: {error}");
            snapshot
        }
    };
    Ok(Json(snapshot))
}

async fn api_clawbot_gateway_login_refresh(
) -> ApiResult<Json<clawbot_gateway::ClawbotLoginSnapshot>> {
    Ok(Json(refresh_clawbot_login_now().await?))
}

async fn refresh_clawbot_login_now() -> ApiResult<clawbot_gateway::ClawbotLoginSnapshot> {
    let now_ms = uuid_timestamp();
    let generation = {
        let store = clawbot_gateway_lock()?;
        let mut snapshot = store
            .load_login_snapshot()
            .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
        snapshot.request_refresh(now_ms);
        let generation = snapshot.generation;
        store
            .save_login_snapshot(&snapshot)
            .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
        generation
    };

    let sidecar_result = call_clawbot_sidecar_login_refresh(generation, now_ms).await;
    let snapshot = match sidecar_result {
        ClawbotSidecarLoginRefreshResult::Report(report) => {
            record_clawbot_login_refresh_report(report, uuid_timestamp())?
        }
        ClawbotSidecarLoginRefreshResult::Error(error) => {
            record_clawbot_login_refresh_error(generation, error, uuid_timestamp())?
        }
    };
    Ok(snapshot)
}

#[cfg(test)]
fn clawbot_sidecar_url_override_for_test() -> &'static Mutex<Option<String>> {
    static OVERRIDE: OnceLock<Mutex<Option<String>>> = OnceLock::new();
    OVERRIDE.get_or_init(|| Mutex::new(None))
}

#[cfg(test)]
fn current_clawbot_sidecar_url_override_for_test() -> Option<String> {
    clawbot_sidecar_url_override_for_test()
        .lock()
        .ok()
        .and_then(|url| url.clone())
}

#[cfg(test)]
fn replace_clawbot_sidecar_url_override_for_test(url: Option<String>) -> Option<String> {
    let mut guard = clawbot_sidecar_url_override_for_test()
        .lock()
        .unwrap_or_else(|error| error.into_inner());
    std::mem::replace(&mut *guard, url)
}

fn clawbot_sidecar_base_url() -> String {
    #[cfg(test)]
    if let Some(url) = current_clawbot_sidecar_url_override_for_test() {
        return url;
    }
    env::var("COOLZHU_CLAWBOT_SIDECAR_URL")
        .unwrap_or_else(|_| "http://127.0.0.1:8787".to_string())
}

async fn call_clawbot_sidecar_login_refresh(
    generation: u64,
    now_ms: u64,
) -> ClawbotSidecarLoginRefreshResult {
    let sidecar_url = clawbot_sidecar_base_url();
    let refresh_url = format!("{}/login/refresh", sidecar_url.trim_end_matches('/'));
    let client = match reqwest::Client::builder()
        .timeout(Duration::from_secs(15))
        .build()
    {
        Ok(client) => client,
        Err(error) => {
            return ClawbotSidecarLoginRefreshResult::Error(format!(
                "初始化 ClawBot sidecar 登录刷新 client 失败：{error}"
            ));
        }
    };

    let response = match client
        .post(&refresh_url)
        .json(&json!({
            "generation": generation,
            "now_ms": now_ms,
        }))
        .send()
        .await
    {
        Ok(response) => response,
        Err(error) => {
            return ClawbotSidecarLoginRefreshResult::Error(format!(
                "调用 ClawBot sidecar 登录刷新失败：{error}"
            ));
        }
    };

    let response = match response.error_for_status() {
        Ok(response) => response,
        Err(error) => {
            return ClawbotSidecarLoginRefreshResult::Error(format!(
                "ClawBot sidecar 登录刷新返回错误：{error}"
            ));
        }
    };

    let payload = match response.json::<JsonValue>().await {
        Ok(payload) => payload,
        Err(error) => {
            return ClawbotSidecarLoginRefreshResult::Error(format!(
                "解析 ClawBot sidecar 登录刷新响应失败：{error}"
            ));
        }
    };

    if let Some(ok) = payload.get("Ok") {
        return match serde_json::from_value::<clawbot_gateway::ClawbotLoginReport>(ok.clone()) {
            Ok(report) => ClawbotSidecarLoginRefreshResult::Report(report),
            Err(error) => ClawbotSidecarLoginRefreshResult::Error(format!(
                "解析 ClawBot sidecar 登录报告失败：{error}"
            )),
        };
    }

    if let Some(error) = payload.get("Err").and_then(JsonValue::as_str) {
        return ClawbotSidecarLoginRefreshResult::Error(error.to_string());
    }

    ClawbotSidecarLoginRefreshResult::Error(format!(
        "ClawBot sidecar 登录刷新响应格式异常：{}",
        payload
    ))
}

fn record_clawbot_login_refresh_report(
    report: clawbot_gateway::ClawbotLoginReport,
    now_ms: u64,
) -> ApiResult<clawbot_gateway::ClawbotLoginSnapshot> {
    let store = clawbot_gateway_lock()?;
    let mut snapshot = store
        .load_login_snapshot()
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
    snapshot
        .report(report, now_ms)
        .map_err(|error| api_error(StatusCode::BAD_REQUEST, &error))?;
    store
        .save_login_snapshot(&snapshot)
        .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error))?;
    Ok(snapshot)
}

fn record_clawbot_login_refresh_error(
    generation: u64,
    error: String,
    now_ms: u64,
) -> ApiResult<clawbot_gateway::ClawbotLoginSnapshot> {
    record_clawbot_login_refresh_report(
        clawbot_gateway::ClawbotLoginReport {
            generation,
            account_id: None,
            state: clawbot_gateway::ClawbotLoginState::Error,
            qr_code_data_url: None,
            expires_at_ms: None,
            last_error: Some(error),
        },
        now_ms,
    )
}

