async fn api_create_goal(
    Json(payload): Json<CreateGoalRequest>,
) -> ApiResult<Json<GoalMutationResponse>> {
    let workspace = active_workspace_path();
    let workspace_id = workspace_identity(&workspace);
    let chat_room_id = {
        let mut store = session_store()
            .lock()
            .map_err(|_| api_error(StatusCode::INTERNAL_SERVER_ERROR, "会话存储锁已损坏"))?;
        store.ensure_chat_room();
        let room_id = payload
            .chat_room_id
            .clone()
            .filter(|value| !value.trim().is_empty())
            .or_else(|| store.active_chat_room_id());
        let Some(room_id) = room_id else {
            return Err(api_error(StatusCode::BAD_REQUEST, "没有可用聊天"));
        };
        if !store.state.chat_rooms.iter().any(|room| room.id == room_id) {
            return Err(api_error(StatusCode::NOT_FOUND, "聊天室不存在"));
        }
        room_id
    };
    let db_path = default_session_sqlite_path();
    let goal = create_goal_sqlite(&db_path, &workspace_id, &chat_room_id, payload)?;
    Ok(Json(GoalMutationResponse { goal }))
}

