async fn api_goal_events(
    AxumPath(goal_id): AxumPath<String>,
) -> ApiResult<Sse<impl futures_core::Stream<Item = Result<Event, std::convert::Infallible>>>> {
    let workspace = active_workspace_path();
    let workspace_id = workspace_identity(&workspace);
    let db_path = default_session_sqlite_path();
    let goal = get_goal_sqlite(&db_path, &workspace_id, &goal_id)?;
    let initial_events = goal.recent_events.clone();
    let mut rx = subscribe_goal_events();
    let stream_goal_id = goal_id.clone();
    let stream = async_stream::stream! {
        yield Ok::<Event, std::convert::Infallible>(
            sse_json_event("hello", &json!({ "goal_id": stream_goal_id.clone() }))
        );
        for event in initial_events.into_iter().rev() {
            yield Ok(sse_json_event(&event.event_type, &event));
        }
        loop {
            match rx.recv().await {
                Ok(event) if event.goal_id == stream_goal_id => {
                    yield Ok(sse_json_event(&event.event_type, &event));
                }
                Ok(_) => {}
                Err(broadcast::error::RecvError::Lagged(n)) => {
                    let payload = format!("{{\"missed\":{n}}}");
                    yield Ok(Event::default().event("lagged").data(payload));
                }
                Err(broadcast::error::RecvError::Closed) => break,
            }
        }
    };
    Ok(Sse::new(stream))
}

