/// harness 运行时指标计数器：L1 监管触发次数、幂等命中次数（进程级，重启清零）。
static HARNESS_L1_TRIGGERS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
static HARNESS_IDEMPOTENT_HITS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

#[derive(Debug, Serialize)]
struct HarnessMetricsResponse {
    /// goal_events 聚合（跨所有 goal）。
    command_gate_failures: i64,
    verification_blocks: i64,
    replan_requests: i64,
    escalations: i64,
    /// 运行时计数器。
    l1_supervisor_triggers: u64,
    idempotent_request_hits: u64,
}

/// harness 效果指标：聚合 goal_events 关键事件 + 运行时计数器（L1 监管触发、请求幂等命中）。
/// 供观测 harness 优化效果（门控失败/回退/重试/监管/弱网去重的发生频率）。
async fn api_harness_metrics() -> ApiResult<Json<HarnessMetricsResponse>> {
    let path = {
        let store = session_store().lock().map_err(|_| {
            api_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "session store lock poisoned",
            )
        })?;
        store.path.clone()
    };
    let connection = open_session_connection(&path).map_err(sqlite_api_error)?;
    initialize_session_schema(&connection).map_err(sqlite_api_error)?;
    let mut counts: HashMap<String, i64> = HashMap::new();
    if let Ok(mut stmt) =
        connection.prepare("SELECT event_type, COUNT(*) FROM goal_events GROUP BY event_type")
    {
        if let Ok(rows) = stmt.query_map([], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)?))
        }) {
            for row in rows.flatten() {
                counts.insert(row.0, row.1);
            }
        }
    }
    let get = |key: &str| counts.get(key).copied().unwrap_or(0);
    Ok(Json(HarnessMetricsResponse {
        command_gate_failures: get("goal-phase-command-gate-failed"),
        verification_blocks: get("goal-phase-verification-blocked"),
        replan_requests: get("goal-phase-blocked-needs-replan"),
        // GL-05/06：blocked（超重试上限）是新的升级信号；旧的两个 attention 事件已不再产生，
        // 保留在和式里只为回看历史计数。
        escalations: get("goal-phase-replan-escalated")
            + get("goal-phase-blocked")
            + get("goal-phase-verification-attention-required")
            + get("goal-phase-command-gate-attention-required"),
        l1_supervisor_triggers: HARNESS_L1_TRIGGERS.load(std::sync::atomic::Ordering::Relaxed),
        idempotent_request_hits: HARNESS_IDEMPOTENT_HITS.load(std::sync::atomic::Ordering::Relaxed),
    }))
}

