// ── Grounding Router API ──

async fn api_vision_locate(
    Json(req): Json<vision::locate::LocateRequest>,
) -> ApiResult<Json<vision::locate::LocateResponse>> {
    Ok(Json(run_grounding_router(req).await?))
}

async fn run_grounding_router(
    req: vision::locate::LocateRequest,
) -> ApiResult<vision::locate::LocateResponse> {
    let t0 = std::time::Instant::now();
    let config = active_vision_router_config();
    let capture_path = req
        .capture_path
        .as_deref()
        .map(PathBuf::from)
        .unwrap_or_else(default_latest_desktop_capture_path);
    if !capture_path.exists() {
        capture_desktop(&capture_path).await?;
    }
    let screen_dimensions = read_png_dimensions(&capture_path).unwrap_or_else(|_| {
        let (width, height, _) = read_screen_info();
        ScreenDimensions { width, height }
    });
    let (_, _, dpi_scale) = read_screen_info();
    let screen = vision::locate::ScreenInfo {
        logical_width: screen_dimensions.width,
        logical_height: screen_dimensions.height,
        dpi_scale: dpi_scale as f32,
    };

    let mut attempts = Vec::new();
    let mut best: Option<vision::locate::BackendAttempt> = None;
    let effective_min_confidence = effective_locate_min_confidence(&req, &config);

    let pipeline = locate_pipeline(&req, &config);

    for backend in &pipeline {
        let attempt = match backend {
            vision::locate::BackendId::Uia => {
                if !config.uia.enabled {
                    vision::locate::BackendAttempt::skipped(*backend, "uia disabled by config")
                } else if let Some(target) = locate_system_control(&req.target) {
                    let t1 = std::time::Instant::now();
                    match uia_resolver::resolve_system_control(target) {
                        Ok(hit) => {
                            let status = if hit.confidence >= effective_min_confidence {
                                vision::locate::AttemptStatus::Ok
                            } else {
                                vision::locate::AttemptStatus::LowConfidence
                            };
                            vision::locate::BackendAttempt {
                                backend: vision::locate::BackendId::Uia,
                                status,
                                point: Some(vision::locate::PointPx {
                                    x: hit.bounding_rect.x + hit.bounding_rect.width / 2,
                                    y: hit.bounding_rect.y + hit.bounding_rect.height / 2,
                                }),
                                bbox: Some(hit.bounding_rect),
                                confidence: Some(hit.confidence),
                                raw_response: None,
                                model: Some("windows-uiautomation".to_string()),
                                base_url: None,
                                elapsed_ms: t1.elapsed().as_millis() as u64,
                                error: None,
                            }
                        }
                        Err(e) => vision::locate::BackendAttempt {
                            backend: vision::locate::BackendId::Uia,
                            status: vision::locate::AttemptStatus::Failed,
                            point: None,
                            bbox: None,
                            confidence: None,
                            raw_response: None,
                            model: None,
                            base_url: None,
                            elapsed_ms: 0,
                            error: Some(e.to_string()),
                        },
                    }
                } else {
                    vision::locate::BackendAttempt::skipped(
                        *backend,
                        "target is not a known system control",
                    )
                }
            }
            vision::locate::BackendId::LocalVlm => {
                local_vlm_locate_attempt(
                    &req,
                    &capture_path,
                    screen_dimensions,
                    &config,
                    effective_min_confidence,
                )
                .await
            }
            vision::locate::BackendId::RemoteVlm => {
                remote_vlm_locate_attempt(
                    &req,
                    &capture_path,
                    screen_dimensions,
                    &config,
                    effective_min_confidence,
                )
                .await
            }
        };

        if attempt.status == vision::locate::AttemptStatus::Ok && best.is_none() {
            best = Some(attempt.clone());
        }
        attempts.push(attempt);
        if best.is_some() && !req.cross_verify && !config.cross_verify {
            break;
        }
    }

    let status = locate_status_from_attempts(best.as_ref(), &attempts);
    let degradation_reason = if status == vision::locate::LocateStatus::Ok {
        None
    } else {
        Some("grounding router did not produce a verified high-confidence point; no hardcoded anchor fallback is used".to_string())
    };

    Ok(vision::locate::LocateResponse {
        status,
        target_description: locate_target_text(&req.target),
        point: best.as_ref().and_then(|a| a.point),
        bbox: best.as_ref().and_then(|a| a.bbox),
        confidence: best.as_ref().and_then(|a| a.confidence).unwrap_or(0.0),
        chosen_backend: best.as_ref().map(|a| a.backend),
        attempts,
        capture_path: capture_path.display().to_string(),
        screen,
        elapsed_ms: t0.elapsed().as_millis() as u64,
        degradation_reason,
        notes: vec![
            "Grounding backend is separate from user-selectable vision understanding agents.".to_string(),
            "Real click execution consumes this locate result and does not fall back to taskbar anchors.".to_string(),
        ],
    })
}

fn active_vision_router_config() -> ConfigVisionRouter {
    read_config(|config| config.vision.router.clone().unwrap_or_default())
}

fn effective_locate_min_confidence(
    req: &vision::locate::LocateRequest,
    config: &ConfigVisionRouter,
) -> f32 {
    if (req.min_confidence - default_router_min_confidence()).abs() < f32::EPSILON {
        config.min_confidence
    } else {
        req.min_confidence
    }
    .clamp(0.0, 1.0)
}

fn locate_pipeline(
    req: &vision::locate::LocateRequest,
    config: &ConfigVisionRouter,
) -> Vec<vision::locate::BackendId> {
    req.backends.clone().unwrap_or_else(|| {
        let parsed = config
            .pipeline
            .iter()
            .filter_map(|name| parse_locate_backend_id(name))
            .collect::<Vec<_>>();
        if parsed.is_empty() {
            default_router_pipeline()
                .iter()
                .filter_map(|name| parse_locate_backend_id(name))
                .collect()
        } else {
            parsed
        }
    })
}

fn parse_locate_backend_id(name: &str) -> Option<vision::locate::BackendId> {
    match name.trim().to_ascii_lowercase().replace('-', "_").as_str() {
        "uia" | "ui_automation" => Some(vision::locate::BackendId::Uia),
        "local_vlm" | "local" | "showui" => Some(vision::locate::BackendId::LocalVlm),
        "remote_vlm" | "remote" => Some(vision::locate::BackendId::RemoteVlm),
        _ => None,
    }
}

fn inferred_point_only_confidence(
    point_found: bool,
    clustered: bool,
    accepted_points: usize,
    sample_count: usize,
) -> f32 {
    if !point_found {
        return 0.0;
    }
    if clustered && accepted_points >= 2 {
        return 0.56;
    }
    if sample_count == 1 && accepted_points == 1 {
        return 0.35;
    }
    0.35
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum VisualColorHint {
    Green,
    Gold,
}

impl VisualColorHint {
    fn as_str(self) -> &'static str {
        match self {
            Self::Green => "green",
            Self::Gold => "gold",
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct ColorRegionGrounding {
    point: vision::locate::PointPx,
    bbox: vision::locate::BBoxPx,
    pixel_count: u32,
}

fn colored_button_hint(target: &str) -> Option<VisualColorHint> {
    let target = target.to_ascii_lowercase();
    let button_like = target.contains("button")
        || target.contains("confirm")
        || target.contains("target")
        || target.contains("按钮")
        || target.contains("确认");
    if !button_like {
        return None;
    }
    if target.contains("green") || target.contains("绿色") {
        return Some(VisualColorHint::Green);
    }
    if target.contains("gold")
        || target.contains("yellow")
        || target.contains("金色")
        || target.contains("黄色")
    {
        return Some(VisualColorHint::Gold);
    }
    None
}

fn parse_color_region_scan_output(output: &str) -> Option<ColorRegionGrounding> {
    let line = output
        .lines()
        .map(str::trim)
        .find(|line| line.starts_with("hit|"))?;
    let mut parts = line.split('|');
    if parts.next()? != "hit" {
        return None;
    }
    let x = parts.next()?.parse::<i32>().ok()?;
    let y = parts.next()?.parse::<i32>().ok()?;
    let width = parts.next()?.parse::<i32>().ok()?;
    let height = parts.next()?.parse::<i32>().ok()?;
    let pixel_count = parts.next()?.parse::<u32>().ok()?;
    if width <= 0 || height <= 0 || pixel_count == 0 {
        return None;
    }
    Some(ColorRegionGrounding {
        point: vision::locate::PointPx {
            x: x + width / 2,
            y: y + height / 2,
        },
        bbox: vision::locate::BBoxPx {
            x,
            y,
            width,
            height,
        },
        pixel_count,
    })
}

fn point_in_bbox(point: PointDto, bbox: vision::locate::BBoxPx, padding: i32) -> bool {
    point.x >= bbox.x.saturating_sub(padding)
        && point.x <= bbox.x.saturating_add(bbox.width).saturating_add(padding)
        && point.y >= bbox.y.saturating_sub(padding)
        && point.y <= bbox.y.saturating_add(bbox.height).saturating_add(padding)
}

async fn locate_colored_button_region(
    capture_path: &Path,
    color_hint: VisualColorHint,
    screen: ScreenDimensions,
    region_hint: Option<RoiDto>,
) -> Option<ColorRegionGrounding> {
    let path = escape_powershell_single_quoted(&capture_path.display().to_string());
    let color = color_hint.as_str();
    let (roi_x, roi_y, roi_w, roi_h) = region_hint
        .map(|roi| (roi.left, roi.top, roi.width, roi.height))
        .unwrap_or((-1, -1, -1, -1));
    let script = r#"
Add-Type -AssemblyName System.Drawing
$source = @'
using System;
using System.Drawing;
using System.Drawing.Imaging;

public static class ColorRegionScanner {
    private static bool IsMatch(byte r, byte g, byte b, string color) {
        if (color == "green") {
            return g >= 95 && g >= r + 20 && g >= b + 10 && r <= 150 && b <= 170;
        }
        if (color == "gold") {
            return r >= 170 && g >= 140 && b <= 120 && r >= g && g >= b + 35;
        }
        return false;
    }

    public static string Scan(string path, string color, int roiX, int roiY, int roiW, int roiH) {
        using (var source = new Bitmap(path))
        using (var bitmap = source.Clone(new Rectangle(0, 0, source.Width, source.Height), PixelFormat.Format32bppArgb)) {
            int width = bitmap.Width;
            int height = bitmap.Height;
            int startX = roiW > 0 ? Math.Max(0, roiX) : 0;
            int startY = roiH > 0 ? Math.Max(0, roiY) : 0;
            int endX = roiW > 0 ? Math.Min(width, roiX + roiW) : width;
            int endY = roiH > 0 ? Math.Min(height, roiY + roiH) : height;
            var rect = new Rectangle(0, 0, width, height);
            var data = bitmap.LockBits(rect, ImageLockMode.ReadOnly, PixelFormat.Format32bppArgb);
            try {
                int stride = data.Stride;
                int byteCount = Math.Abs(stride) * height;
                byte[] bytes = new byte[byteCount];
                System.Runtime.InteropServices.Marshal.Copy(data.Scan0, bytes, 0, byteCount);
                bool[] match = new bool[width * height];
                for (int y = startY; y < endY; y++) {
                    int row = y * Math.Abs(stride);
                    for (int x = startX; x < endX; x++) {
                        int offset = row + (x * 4);
                        byte b = bytes[offset];
                        byte g = bytes[offset + 1];
                        byte r = bytes[offset + 2];
                        match[(y * width) + x] = IsMatch(r, g, b, color);
                    }
                }

                bool[] visited = new bool[width * height];
                int bestX = 0, bestY = 0, bestW = 0, bestH = 0, bestCount = 0;
                double bestScore = 0.0;
                int[] queue = new int[width * height];
                int[] dx = new int[] { 1, -1, 0, 0 };
                int[] dy = new int[] { 0, 0, 1, -1 };

                for (int i = 0; i < match.Length; i++) {
                    if (!match[i] || visited[i]) {
                        continue;
                    }
                    int head = 0, tail = 0;
                    queue[tail++] = i;
                    visited[i] = true;
                    int minX = i % width, maxX = minX;
                    int minY = i / width, maxY = minY;
                    int count = 0;

                    while (head < tail) {
                        int current = queue[head++];
                        count++;
                        int cx = current % width;
                        int cy = current / width;
                        if (cx < minX) minX = cx;
                        if (cx > maxX) maxX = cx;
                        if (cy < minY) minY = cy;
                        if (cy > maxY) maxY = cy;

                        for (int n = 0; n < 4; n++) {
                            int nx = cx + dx[n];
                            int ny = cy + dy[n];
                            if (nx < 0 || ny < 0 || nx >= width || ny >= height) {
                                continue;
                            }
                            int next = (ny * width) + nx;
                            if (match[next] && !visited[next]) {
                                visited[next] = true;
                                queue[tail++] = next;
                            }
                        }
                    }

                    int componentW = maxX - minX + 1;
                    int componentH = maxY - minY + 1;
                    if (componentW < 80 || componentH < 45 || count < 1200) {
                        continue;
                    }
                    double fill = count / (double)(componentW * componentH);
                    double aspect = componentW / (double)componentH;
                    if (fill < 0.35 || aspect < 1.0 || aspect > 8.0) {
                        continue;
                    }
                    double score = count * fill;
                    if (score > bestScore) {
                        bestScore = score;
                        bestX = minX;
                        bestY = minY;
                        bestW = componentW;
                        bestH = componentH;
                        bestCount = count;
                    }
                }

                if (bestCount <= 0) {
                    return "miss";
                }
                return "hit|" + bestX + "|" + bestY + "|" + bestW + "|" + bestH + "|" + bestCount;
            } finally {
                bitmap.UnlockBits(data);
            }
        }
    }
}
'@
Add-Type -TypeDefinition $source -ReferencedAssemblies System.Drawing
[ColorRegionScanner]::Scan('__CAPTURE_PATH__', '__COLOR_HINT__', __ROI_X__, __ROI_Y__, __ROI_W__, __ROI_H__)
"#
    .replace("__CAPTURE_PATH__", &path)
    .replace("__COLOR_HINT__", color)
    .replace("__ROI_X__", &roi_x.to_string())
    .replace("__ROI_Y__", &roi_y.to_string())
    .replace("__ROI_W__", &roi_w.to_string())
    .replace("__ROI_H__", &roi_h.to_string());

    let mut command = Command::new("powershell.exe");
    command
        .arg("-NoLogo")
        .arg("-NoProfile")
        .arg("-ExecutionPolicy")
        .arg("Bypass")
        .arg("-Command")
        .arg(script)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .kill_on_drop(true);

    let child = match command.spawn() {
        Ok(child) => child,
        Err(error) => {
            diag!("[GROUNDING] color region scanner failed to start: {error}");
            return None;
        }
    };
    let output = match tokio::time::timeout(Duration::from_secs(5), child.wait_with_output()).await
    {
        Ok(Ok(output)) => output,
        Ok(Err(error)) => {
            diag!("[GROUNDING] color region scanner failed: {error}");
            return None;
        }
        Err(_) => {
            diag!("[GROUNDING] color region scanner timed out");
            return None;
        }
    };
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        diag!("[GROUNDING] color region scanner stderr: {stderr}");
        return None;
    }
    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut grounding = parse_color_region_scan_output(&stdout)?;
    grounding.point.x = grounding
        .point
        .x
        .clamp(0, screen.width.saturating_sub(1) as i32);
    grounding.point.y = grounding
        .point
        .y
        .clamp(0, screen.height.saturating_sub(1) as i32);
    Some(grounding)
}

fn locate_status_from_attempts(
    best: Option<&vision::locate::BackendAttempt>,
    attempts: &[vision::locate::BackendAttempt],
) -> vision::locate::LocateStatus {
    if best.is_some() {
        vision::locate::LocateStatus::Ok
    } else if attempts
        .iter()
        .any(|a| a.status == vision::locate::AttemptStatus::LowConfidence)
    {
        vision::locate::LocateStatus::LowConfidence
    } else if attempts
        .iter()
        .any(|a| a.status == vision::locate::AttemptStatus::Failed)
    {
        vision::locate::LocateStatus::NotFound
    } else {
        vision::locate::LocateStatus::Unavailable
    }
}

fn extract_system_control(
    target: &vision::locate::LocateTarget,
) -> Option<vision::locate::SystemControlId> {
    match target {
        vision::locate::LocateTarget::System { id } => Some(*id),
        _ => None,
    }
}

fn locate_system_control(
    target: &vision::locate::LocateTarget,
) -> Option<vision::locate::SystemControlId> {
    extract_system_control(target)
        .or_else(|| detect_system_control_from_target(&locate_target_text(target)))
}

fn locate_target_text(target: &vision::locate::LocateTarget) -> String {
    match target {
        vision::locate::LocateTarget::Natural { text } => text.clone(),
        vision::locate::LocateTarget::System { id } => format!("{id:?}"),
        vision::locate::LocateTarget::Uia {
            automation_id,
            class_name,
            name,
            control_type,
        } => [automation_id, class_name, name, control_type]
            .into_iter()
            .filter_map(|value| value.as_deref())
            .filter(|value| !value.trim().is_empty())
            .collect::<Vec<_>>()
            .join(" "),
    }
}

async fn local_vlm_locate_attempt(
    req: &vision::locate::LocateRequest,
    capture_path: &Path,
    screen: ScreenDimensions,
    config: &ConfigVisionRouter,
    min_confidence: f32,
) -> vision::locate::BackendAttempt {
    if !config.local_vlm.enabled {
        return vision::locate::BackendAttempt::skipped(
            vision::locate::BackendId::LocalVlm,
            "local_vlm disabled by config",
        );
    }
    let base_url = config
        .local_vlm
        .base_url
        .clone()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(authoritative_local_vision_base_url);
    let model = config
        .local_vlm
        .model
        .clone()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(authoritative_local_vision_model);
    let timeout_seconds = config.local_vlm.timeout_seconds.clamp(5, 180);
    let sample_count = config.local_vlm.sample_count.clamp(1, 5);
    let threshold = min_confidence.max(config.local_vlm.confidence_floor.clamp(0.0, 1.0));
    let target = locate_target_text(&req.target);
    let t0 = std::time::Instant::now();
    let mut points = Vec::new();
    let mut bbox: Option<vision::locate::BBoxPx> = None;
    let mut best_confidence: Option<f32> = None;
    let mut last_error = None;

    let variants = vision::local_backend::prompt_variants(&target);
    for index in 0..sample_count as usize {
        let prompt = variants
            .get(index % variants.len())
            .cloned()
            .unwrap_or_else(|| target.clone());
        match run_vision_find_target(VisionFindTargetRequest {
            target: Some(prompt),
            use_model: Some(true),
            use_latest_capture: Some(false),
            raw_response: None,
            capture_path: Some(capture_path.display().to_string()),
            model: Some(model.clone()),
            base_url: Some(base_url.clone()),
            api_key: authoritative_local_vision_api_key(),
            timeout_seconds: Some(timeout_seconds),
        })
        .await
        {
            Ok(response) => {
                if let Some(grounding) = response.grounding {
                    if let Some(point) = grounding.point {
                        points.push(vision::locate::PointPx {
                            x: point.x,
                            y: point.y,
                        });
                    }
                    bbox = bbox.or_else(|| {
                        grounding.bbox.map(|roi| vision::locate::BBoxPx {
                            x: roi.left,
                            y: roi.top,
                            width: roi.width,
                            height: roi.height,
                        })
                    });
                    if let Some(confidence) = grounding.confidence {
                        best_confidence = Some(
                            best_confidence.map_or(confidence, |best: f32| best.max(confidence)),
                        );
                    }
                }
                if let Some(error) = response.backend.and_then(|trace| trace.error) {
                    last_error = Some(error);
                }
            }
            Err(error) => {
                let (_, Json(err)) = error;
                last_error = Some(err.error);
            }
        }
    }

    let clustered_point =
        vision::local_backend::cluster_median(&points, 48.0, if sample_count >= 2 { 2 } else { 1 });
    let mut point = clustered_point.or_else(|| points.first().copied());
    let mut bbox = bbox;
    let mut confidence = best_confidence.unwrap_or_else(|| {
        inferred_point_only_confidence(
            point.is_some(),
            clustered_point.is_some(),
            points.len(),
            sample_count as usize,
        )
    });
    let mut grounding_note = format!(
        "samples={}, accepted_points={}, inferred_confidence={:.2}",
        sample_count,
        points.len(),
        confidence
    );
    if confidence < threshold {
        if let Some(color_hint) = colored_button_hint(&target) {
            if let Some(region) =
                locate_colored_button_region(capture_path, color_hint, screen, None).await
            {
                point = Some(region.point);
                bbox = Some(region.bbox);
                confidence = confidence.max(0.72);
                grounding_note.push_str(&format!(
                    ", color_region_fallback={}, bbox=({},{} {}x{}), pixels={}",
                    color_hint.as_str(),
                    region.bbox.x,
                    region.bbox.y,
                    region.bbox.width,
                    region.bbox.height,
                    region.pixel_count
                ));
            }
        }
    }
    let status = if point.is_some() && confidence >= threshold {
        vision::locate::AttemptStatus::Ok
    } else if point.is_some() {
        vision::locate::AttemptStatus::LowConfidence
    } else {
        vision::locate::AttemptStatus::Failed
    };

    vision::locate::BackendAttempt {
        backend: vision::locate::BackendId::LocalVlm,
        status,
        point,
        bbox,
        confidence: point.map(|_| confidence),
        raw_response: Some(grounding_note),
        model: Some(model),
        base_url: Some(base_url),
        elapsed_ms: t0.elapsed().as_millis() as u64,
        error: last_error,
    }
}

async fn remote_vlm_locate_attempt(
    req: &vision::locate::LocateRequest,
    capture_path: &Path,
    _screen: ScreenDimensions,
    config: &ConfigVisionRouter,
    min_confidence: f32,
) -> vision::locate::BackendAttempt {
    if !config.remote_vlm.enabled {
        return vision::locate::BackendAttempt::skipped(
            vision::locate::BackendId::RemoteVlm,
            "remote_vlm disabled by config",
        );
    }
    let Some(provider) = config.remote_vlm.providers.first() else {
        return vision::locate::BackendAttempt::skipped(
            vision::locate::BackendId::RemoteVlm,
            "no remote_vlm providers configured",
        );
    };
    let Some(base_url) = provider
        .base_url
        .clone()
        .filter(|value| !value.trim().is_empty())
    else {
        return vision::locate::BackendAttempt::skipped(
            vision::locate::BackendId::RemoteVlm,
            "remote_vlm provider has no base_url",
        );
    };
    let api_key = provider
        .api_key_ref
        .as_deref()
        .and_then(resolve_api_key_ref);
    let threshold = min_confidence.max(provider.confidence_floor.clamp(0.0, 1.0));
    let t0 = std::time::Instant::now();
    match run_vision_find_target(VisionFindTargetRequest {
        target: Some(locate_target_text(&req.target)),
        use_model: Some(true),
        use_latest_capture: Some(false),
        raw_response: None,
        capture_path: Some(capture_path.display().to_string()),
        model: Some(provider.model.clone()),
        base_url: Some(base_url.clone()),
        api_key,
        timeout_seconds: Some(config.timeout_ms.saturating_div(1000).clamp(5, 180)),
    })
    .await
    {
        Ok(response) => {
            let grounding = response.grounding;
            let point = grounding
                .as_ref()
                .and_then(|grounding| grounding.point)
                .map(|point| vision::locate::PointPx {
                    x: point.x,
                    y: point.y,
                });
            let bbox = grounding.as_ref().and_then(|grounding| {
                grounding.bbox.map(|roi| vision::locate::BBoxPx {
                    x: roi.left,
                    y: roi.top,
                    width: roi.width,
                    height: roi.height,
                })
            });
            let confidence = grounding
                .as_ref()
                .and_then(|grounding| grounding.confidence)
                .unwrap_or(if point.is_some() { 0.35 } else { 0.0 });
            let status = if point.is_some() && confidence >= threshold {
                vision::locate::AttemptStatus::Ok
            } else if point.is_some() {
                vision::locate::AttemptStatus::LowConfidence
            } else {
                vision::locate::AttemptStatus::Failed
            };
            vision::locate::BackendAttempt {
                backend: vision::locate::BackendId::RemoteVlm,
                status,
                point,
                bbox,
                confidence: point.map(|_| confidence),
                raw_response: None,
                model: Some(provider.model.clone()),
                base_url: Some(base_url),
                elapsed_ms: t0.elapsed().as_millis() as u64,
                error: response.backend.and_then(|trace| trace.error),
            }
        }
        Err(error) => {
            let (_, Json(err)) = error;
            vision::locate::BackendAttempt {
                backend: vision::locate::BackendId::RemoteVlm,
                status: vision::locate::AttemptStatus::Failed,
                point: None,
                bbox: None,
                confidence: None,
                raw_response: None,
                model: Some(provider.model.clone()),
                base_url: Some(base_url),
                elapsed_ms: t0.elapsed().as_millis() as u64,
                error: Some(err.error),
            }
        }
    }
}

