async fn build_semantic_dispatch_plan(
    intent: &str,
    payload: &ToolDispatchRequest,
) -> ApiResult<Option<ToolDispatchPlan>> {
    let Some(action) = semantic_action_from_intent(intent) else {
        return Ok(None);
    };
    let target = payload
        .target
        .clone()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| semantic_target_from_intent(intent));
    let menu_item = payload
        .menu_item
        .clone()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| "target menu item".to_string());
    let mut dry_run_input = semantic_tool_input(&action, &target, &menu_item);
    if let JsonValue::Object(map) = &mut dry_run_input {
        if let Some(raw_response) = payload
            .raw_response
            .clone()
            .filter(|value| !value.trim().is_empty())
        {
            map.insert("raw_response".to_string(), JsonValue::String(raw_response));
        }
        if let Some(capture_path) = payload
            .capture_path
            .clone()
            .filter(|value| !value.trim().is_empty())
        {
            map.insert("capture_path".to_string(), JsonValue::String(capture_path));
        }
        if let Some(use_latest_capture) = payload.use_latest_capture {
            map.insert(
                "use_latest_capture".to_string(),
                JsonValue::Bool(use_latest_capture),
            );
        }
        if let Some(use_model) = payload.use_model {
            map.insert("use_model".to_string(), JsonValue::Bool(use_model));
        }
    }
    let visual_action = if semantic_dispatch_should_use_visual_action(&action, payload) {
        Some(
            run_visual_action_dry_run(VisualActionRequest {
                target: Some(target.clone()),
                action: visual_action_name_for_dispatch(&action, &dry_run_input),
                raw_response: payload.raw_response.clone(),
                capture_path: payload.capture_path.clone(),
                use_latest_capture: payload.use_latest_capture.or(Some(true)),
                use_model: payload.use_model.or(Some(false)),
                base_url: None,
                model: None,
                api_key: None,
                timeout_seconds: None,
                execute: Some(false),
            })
            .await?,
        )
    } else {
        None
    };
    let action_plan = if let Some(visual_action) = &visual_action {
        visual_action.action_plan.clone()
    } else {
        Some(
            run_action_plan(ComputerActionPlanRequest {
                action: Some(action.clone()),
                target: Some(target.clone()),
                menu_item: Some(menu_item.clone()),
                x: dry_run_input
                    .get("x")
                    .and_then(JsonValue::as_i64)
                    .and_then(|value| i32::try_from(value).ok()),
                y: dry_run_input
                    .get("y")
                    .and_then(JsonValue::as_i64)
                    .and_then(|value| i32::try_from(value).ok()),
                start: input_point(&dry_run_input, "start"),
                end: input_point(&dry_run_input, "end"),
                bbox: input_bbox(&dry_run_input, "bbox"),
                text: input_string(&dry_run_input, "text"),
                key: input_string(&dry_run_input, "key"),
                keys: input_string_array(&dry_run_input, "keys"),
                delta: input_i32(&dry_run_input, "delta"),
                execute: Some(false),
            })
            .await?,
        )
    };
    let tool_id = format!("computer.{action}");
    let audit = visual_action
        .as_ref()
        .map(|visual| visual.audit.clone())
        .or_else(|| action_plan.as_ref().map(|plan| plan.audit.clone()))
        .unwrap_or_else(|| {
            computer_use_audit_record(
                &action,
                &target,
                payload.execute.unwrap_or(false),
                false,
                None,
            )
        });
    Ok(Some(ToolDispatchPlan {
        tool_id: tool_id.clone(),
        action: action.clone(),
        target,
        dry_run_input: dry_run_input.clone(),
        llm_tool_call: ToolCallPreview {
            name: tool_id,
            arguments: dry_run_input,
            mode: "dry-run".to_string(),
        },
        requires_visual_grounding: action_requires_visual_grounding(&action)
            || visual_action.is_some(),
        execute_allowed: payload.execute.unwrap_or(false),
        action_plan,
        visual_action,
        audit,
        safety_gate: if payload.execute.unwrap_or(false) {
            "execute=true; computer-use execution allowed by permission profile".to_string()
        } else {
            COMPUTER_USE_PERMISSION_GATE.to_string()
        },
        rationale: if payload.execute.unwrap_or(false) {
            "semantic dispatch allows real computer-use execution under current permission profile"
                .to_string()
        } else {
            "semantic dispatch only builds a dry-run plan; execute is never exposed here."
                .to_string()
        },
    }))
}

fn semantic_dispatch_should_use_visual_action(action: &str, payload: &ToolDispatchRequest) -> bool {
    if action == "visual_action" {
        return true;
    }

    let visual_input_available = payload.use_model.unwrap_or(false)
        || payload
            .raw_response
            .as_deref()
            .is_some_and(|value| !value.trim().is_empty());
    visual_input_available
        && matches!(
            action,
            "left_click" | "right_click" | "double_click" | "context_menu_select" | "drag_select"
        )
}

fn visual_action_name_for_dispatch(action: &str, dry_run_input: &JsonValue) -> Option<String> {
    if action == "visual_action" {
        input_string(dry_run_input, "action")
    } else {
        Some(action.to_string())
    }
}

fn computer_use_audit_record(
    action: &str,
    target: &str,
    execute_requested: bool,
    executed: bool,
    screenshot_path: Option<String>,
) -> ComputerUseAuditRecord {
    let log_path = computer_use_audit_log_path();
    let seed = format!(
        "{action}|{target}|{execute_requested}|{executed}|{}|{log_path}",
        screenshot_path.as_deref().unwrap_or("")
    );
    let execute_allowed = execute_requested && is_computer_use_execution_allowed();
    ComputerUseAuditRecord {
        audit_id: format!("cu-audit-{:016x}", hash_bytes(seed.as_bytes())),
        mode: if executed {
            "executed"
        } else if execute_requested {
            "requested"
        } else {
            "dry-run"
        }
        .to_string(),
        execute_requested,
        execute_allowed,
        executed,
        requires_human_confirmation: !executed,
        requires_screenshot_evidence: !executed,
        screenshot_path,
        permission_gate: if executed {
            "execute=true; allowed by permission profile".to_string()
        } else {
            COMPUTER_USE_PERMISSION_GATE.to_string()
        },
        log_path,
    }
}

fn computer_use_audit_log_path() -> String {
    default_session_sqlite_path()
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| {
            env::current_dir()
                .unwrap_or_else(|_| PathBuf::from("."))
                .join(".coolzhu")
        })
        .join("computer-use-audit.jsonl")
        .display()
        .to_string()
}

fn tool_run_audit_record(output: &JsonValue) -> Option<ComputerUseAuditRecord> {
    output
        .get("audit")
        .cloned()
        .or_else(|| output.pointer("/dispatch_plan/audit").cloned())
        .and_then(|value| serde_json::from_value(value).ok())
}

async fn run_vision_find_target(
    payload: VisionFindTargetRequest,
) -> ApiResult<VisionFindTargetResponse> {
    let vision_started = std::time::Instant::now();
    diagnostics::info(
        "vision",
        "locate.begin",
        "视觉目标定位",
        &[
            (
                "target",
                compact_message_snippet(payload.target.as_deref().unwrap_or(""), 80),
            ),
            ("use_model", payload.use_model.unwrap_or(false).to_string()),
        ],
    );
    let capture_path = payload
        .capture_path
        .as_deref()
        .map(PathBuf::from)
        .unwrap_or_else(default_latest_desktop_capture_path);
    if payload.use_latest_capture.unwrap_or(true) || !capture_path.exists() {
        capture_desktop(&capture_path).await?;
    }

    let screen = read_png_dimensions(&capture_path)?;
    let capture = capture_file_info(&capture_path).await?;
    let raw_response = payload.raw_response.clone();
    let model_requested = payload.use_model.unwrap_or(false);
    let mut backend_trace = None;
    let mut parsed = raw_response
        .as_deref()
        .and_then(parse_grounding_result)
        .map(|grounding| grounding_to_dto(grounding, screen));

    if model_requested {
        match run_vision_grounding_model(&payload, &capture_path, screen).await {
            Ok(result) => {
                backend_trace = Some(result.trace);
                parsed = result.grounding;
            }
            Err(error) => {
                backend_trace = Some(VisionBackendTrace {
                    backend: "local-openai-compatible".to_string(),
                    model: payload
                        .model
                        .clone()
                        .filter(|value| !value.trim().is_empty())
                        .unwrap_or_else(|| default_local_vision_model().to_string()),
                    base_url: Some(
                        payload
                            .base_url
                            .clone()
                            .filter(|value| !value.trim().is_empty())
                            .unwrap_or_else(|| default_local_vision_base_url().to_string()),
                    ),
                    request_id: None,
                    total_tokens: None,
                    error: Some(error),
                });
            }
        }
    }

    diagnostics::info(
        "vision",
        "locate.ok",
        "视觉定位完成",
        &[
            ("grounded", parsed.is_some().to_string()),
            ("model_requested", model_requested.to_string()),
            (
                "latency_ms",
                vision_started.elapsed().as_millis().to_string(),
            ),
        ],
    );
    Ok(VisionFindTargetResponse {
        status: vision_find_target_status(parsed.as_ref(), backend_trace.as_ref(), model_requested)
            .to_string(),
        target: payload
            .target
            .unwrap_or_else(|| "unspecified visual target".to_string()),
        screen,
        capture,
        grounding: parsed,
        raw_response,
        backend: backend_trace,
        notes: vec![
            "dry-run 不调用真实输入".to_string(),
            "传入 raw_response 可验证 [x,y]、JSON point、bbox 和 confidence 解析。".to_string(),
            "use_model=true 时会走本地 VLM/OpenAI 兼容端点并返回 backend trace。".to_string(),
        ],
    })
}

async fn run_vision_describe_screen(
    payload: VisionDescribeScreenRequest,
) -> ApiResult<VisionDescribeScreenResponse> {
    let describe_started = std::time::Instant::now();
    diagnostics::info(
        "vision",
        "describe.begin",
        "视觉描述屏幕",
        &[("use_model", payload.use_model.unwrap_or(false).to_string())],
    );
    let capture_path = payload
        .capture_path
        .as_deref()
        .map(PathBuf::from)
        .unwrap_or_else(default_latest_desktop_capture_path);
    if payload.use_latest_capture.unwrap_or(true) || !capture_path.exists() {
        capture_desktop(&capture_path).await?;
    }

    let screen = read_png_dimensions(&capture_path)?;
    let capture = capture_file_info(&capture_path).await?;
    let prompt = payload
        .prompt
        .clone()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| {
            "Describe the current desktop screen for a tool caller. Summarize visible windows, UI regions, text-like areas and possible clickable targets.".to_string()
        });
    let use_model = payload.use_model.unwrap_or(false);
    let (description, model_text, backend, status) = if use_model {
        match run_vision_describe_screen_model(&payload, &capture_path, screen, &prompt).await {
            Ok(result) => (
                result.description.clone(),
                Some(result.description),
                Some(result.trace),
                "model-described",
            ),
            Err(error) => (
                heuristic_screen_description(&screen, &capture, &prompt),
                None,
                Some(VisionBackendTrace {
                    backend: "local-openai-compatible".to_string(),
                    model: payload
                        .model
                        .clone()
                        .filter(|value| !value.trim().is_empty())
                        .unwrap_or_else(|| default_local_vision_model().to_string()),
                    base_url: Some(
                        payload
                            .base_url
                            .clone()
                            .filter(|value| !value.trim().is_empty())
                            .unwrap_or_else(|| default_local_vision_base_url().to_string()),
                    ),
                    request_id: None,
                    total_tokens: None,
                    error: Some(error),
                }),
                "model-backend-error",
            ),
        }
    } else {
        (
            heuristic_screen_description(&screen, &capture, &prompt),
            None,
            None,
            "metadata-only",
        )
    };

    diagnostics::info(
        "vision",
        "describe.ok",
        "视觉描述完成",
        &[
            ("status", status.to_string()),
            (
                "latency_ms",
                describe_started.elapsed().as_millis().to_string(),
            ),
        ],
    );
    Ok(VisionDescribeScreenResponse {
        status: status.to_string(),
        prompt,
        screen,
        capture,
        description,
        model_text,
        backend,
        notes: vec![
            "默认只读描述，不执行键鼠输入".to_string(),
            "use_model=true 时可接本地 VLM/OpenAI-compatible 视觉端点。".to_string(),
            "输出可供 LLM tooling 调用，用于筛查屏幕窗口、文本块和候选点击目标".to_string(),
        ],
    })
}

fn vision_find_target_status(
    grounding: Option<&VisionGroundingDto>,
    backend: Option<&VisionBackendTrace>,
    model_requested: bool,
) -> &'static str {
    if grounding.is_some() {
        if model_requested {
            "grounding-model-parsed"
        } else {
            "grounding-parsed"
        }
    } else if backend.and_then(|trace| trace.error.as_ref()).is_some() {
        "grounding-backend-error"
    } else {
        "dry-run-capture-ready"
    }
}

fn vision_tool_service_capabilities_response() -> VisionToolServiceCapabilitiesResponse {
    let service = VisionToolService;
    let capabilities = service
        .capabilities()
        .into_iter()
        .map(|capability| VisionToolCapabilityDto {
            capability: vision_tool_capability_id(capability.capability).to_string(),
            status: vision_tool_status_label(capability.status).to_string(),
            endpoint: vision_tool_capability_endpoint(capability.capability).to_string(),
            model_invoked_by_default: false,
            notes: vision_tool_capability_notes(capability.capability),
        })
        .collect();

    VisionToolServiceCapabilitiesResponse {
        status: "available".to_string(),
        service: "vision-tool-service".to_string(),
        capabilities,
        backend_policy: "local grounding first; describe/ocr reserved in this round; external OpenAI-compatible VLM remains explicit opt-in".to_string(),
        notes: vec![
            "业务层应依赖 service capability surface，不直接耦合 Qwen/ShowUI。".to_string(),
            "ground-point/ground-bbox 当前复用 find-target grounding pipeline".to_string(),
            "describe/ocr 端点只返回 reserved，不触发模型调用。".to_string(),
        ],
    }
}

fn vision_reserved_capability_response(
    capability: VisionToolCapability,
    name: &str,
    payload: VisionReservedCapabilityRequest,
) -> VisionReservedCapabilityResponse {
    let service = VisionToolService;
    let reserved = match capability {
        VisionToolCapability::Describe => service.describe_reserved(),
        VisionToolCapability::Ocr => service.ocr_reserved(),
        VisionToolCapability::RealtimePerception => vision::VisionToolReservedResponse {
            capability,
            status: service.capability_status(capability),
            message: format!(
                "{name} capability reserved until realtime detector runtime is configured"
            ),
        },
        _ => vision::VisionToolReservedResponse {
            capability,
            status: service.capability_status(capability),
            message: format!("{name} capability is not reserved"),
        },
    };

    VisionReservedCapabilityResponse {
        status: vision_tool_status_label(reserved.status).to_string(),
        capability: vision_tool_capability_id(reserved.capability).to_string(),
        prompt: payload.prompt.unwrap_or_default(),
        capture_path: payload.capture_path,
        model_invoked: false,
        message: reserved.message,
        notes: vec![
            "本轮只预留 describe/ocr 能力接口，不做 grounding/action 并行联测。".to_string(),
            "后续由本地 Qwen profile 或外部 OpenAI-compatible VLM agent 显式接入。".to_string(),
        ],
    }
}

fn vision_tool_capability_id(capability: VisionToolCapability) -> &'static str {
    match capability {
        VisionToolCapability::Describe => "describe",
        VisionToolCapability::Ocr => "ocr",
        VisionToolCapability::GroundPoint => "ground_point",
        VisionToolCapability::GroundBbox => "ground_bbox",
        VisionToolCapability::DetectElements => "detect_elements",
        VisionToolCapability::RealtimePerception => "realtime_perception",
        VisionToolCapability::VisualAction => "visual_action",
    }
}

fn vision_tool_status_label(status: VisionToolCapabilityStatus) -> &'static str {
    match status {
        VisionToolCapabilityStatus::Available => "available",
        VisionToolCapabilityStatus::Reserved => "reserved",
    }
}

fn vision_tool_capability_endpoint(capability: VisionToolCapability) -> &'static str {
    match capability {
        VisionToolCapability::Describe => "/api/vision/tool-service/describe",
        VisionToolCapability::Ocr => "/api/vision/tool-service/ocr",
        VisionToolCapability::GroundPoint => "/api/vision/tool-service/ground-point",
        VisionToolCapability::GroundBbox => "/api/vision/tool-service/ground-bbox",
        VisionToolCapability::DetectElements => "/api/vision/realtime/frame",
        VisionToolCapability::RealtimePerception => "/api/vision/realtime/status",
        VisionToolCapability::VisualAction => "/api/tools/computer.visual_action/dry-run",
    }
}

fn vision_tool_capability_notes(capability: VisionToolCapability) -> Vec<String> {
    match capability {
        VisionToolCapability::Describe | VisionToolCapability::Ocr => vec![
            "reserved interface only".to_string(),
            "does not invoke local or remote VLM in this round".to_string(),
        ],
        VisionToolCapability::GroundPoint => vec![
            "uses ShowUI-compatible point grounding when model is enabled".to_string(),
            "point-only output gets low-confidence downgrade metadata".to_string(),
        ],
        VisionToolCapability::GroundBbox => vec![
            "returns bbox when backend emits one".to_string(),
            "does not synthesize bbox from point-only results".to_string(),
        ],
        VisionToolCapability::DetectElements => vec![
            "parses UI-DETR-style bbox candidates into a normalized element table".to_string(),
            "does not invoke a detector model by default".to_string(),
        ],
        VisionToolCapability::RealtimePerception => vec![
            "reserved service loop for UI-DETR + OCR continuous perception".to_string(),
            "uses resource switch state to avoid keeping ShowUI and UI-DETR resident together"
                .to_string(),
        ],
        VisionToolCapability::VisualAction => vec![
            "combines grounding evidence with computer-use dry-run action plan".to_string(),
            "execute_allowed is always false in this phase".to_string(),
        ],
    }
}

async fn run_vision_grounding_model(
    payload: &VisionFindTargetRequest,
    capture_path: &Path,
    screen: ScreenDimensions,
) -> Result<VisionGroundingModelResult, String> {
    let target = payload
        .target
        .clone()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| "unspecified visual target".to_string());
    let base_url = payload
        .base_url
        .clone()
        .filter(|value| !value.trim().is_empty())
        .or_else(config_vision_base_url)
        .or_else(|| read_config(|c| c.vision.local_base_url.clone()))
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| default_local_vision_base_url().to_string());
    let model = payload
        .model
        .clone()
        .filter(|value| !value.trim().is_empty())
        .or_else(config_vision_model)
        .or_else(|| read_config(|c| c.vision.local_model.clone()))
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| default_local_vision_model().to_string());
    let api_key = payload
        .api_key
        .clone()
        .filter(|value| !value.trim().is_empty())
        .or_else(authoritative_local_vision_api_key)
        .unwrap_or_default();
    let timeout_seconds = payload.timeout_seconds.unwrap_or(20).clamp(5, 180);
    diag!(
        "[VISION-MODEL] url={base_url}, model={model}, has_key={}",
        !api_key.is_empty()
    );
    let backend = LocalOpenAiVisionBackend::new(base_url.clone(), model.clone())
        .with_api_key(api_key)
        .with_timeout_seconds(timeout_seconds);
    let request =
        build_showui_grounding_request(target, VisionImageSource::Path(capture_path.to_path_buf()));
    let response = tokio::task::spawn_blocking(move || backend.analyze(&request))
        .await
        .map_err(|error| {
            diag!("[VISION-MODEL] task failed: {error}");
            format!("vision grounding task failed: {error}")
        })?
        .map_err(|error| {
            diag!("[VISION-MODEL] analyze failed: {error}");
            classify_vision_error(&error.to_string())
        })?;
    Ok(vision_model_result_from_response(
        response,
        screen,
        Some(base_url),
    ))
}

async fn run_vision_describe_screen_model(
    payload: &VisionDescribeScreenRequest,
    capture_path: &Path,
    screen: ScreenDimensions,
    prompt: &str,
) -> Result<VisionDescribeScreenModelResult, String> {
    let session_config = vision_session_config();
    let base_url = payload
        .base_url
        .clone()
        .filter(|value| !value.trim().is_empty())
        .or_else(|| session_config.base_url.clone())
        .or_else(config_vision_base_url)
        .or_else(|| read_config(|c| c.vision.local_base_url.clone()))
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| default_local_vision_base_url().to_string());
    let model = payload
        .model
        .clone()
        .filter(|value| !value.trim().is_empty())
        .or_else(|| session_config.model.clone())
        .or_else(config_vision_model)
        .or_else(|| read_config(|c| c.vision.local_model.clone()))
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| default_local_vision_model().to_string());
    let api_key = payload
        .api_key
        .clone()
        .filter(|value| !value.trim().is_empty())
        .or_else(|| session_config.api_key.clone())
        .or_else(authoritative_local_vision_api_key)
        .unwrap_or_default();
    let timeout_seconds = payload.timeout_seconds.unwrap_or(20).clamp(5, 180);
    let backend = LocalOpenAiVisionBackend::new(base_url.clone(), model.clone())
        .with_api_key(api_key)
        .with_timeout_seconds(timeout_seconds);
    let request = VisionRequest {
        prompt: prompt.to_string(),
        images: vec![VisionImageSource::Path(capture_path.to_path_buf())],
        post_prompt: Some(
            format!(
                "Screen size is {}x{}. Return a concise Chinese screen summary with visible windows, text regions, and clickable targets. Prefer short structured bullets.",
                screen.width, screen.height
            ),
        ),
    };
    let response = tokio::task::spawn_blocking(move || backend.analyze(&request))
        .await
        .map_err(|error| format!("vision describe task failed: {error}"))?
        .map_err(|error| classify_vision_error(&error.to_string()))?;
    Ok(VisionDescribeScreenModelResult {
        description: response.text.clone(),
        trace: VisionBackendTrace {
            backend: vision_backend_label(response.backend).to_string(),
            model: response.model,
            base_url: Some(base_url),
            request_id: response.request_id,
            total_tokens: Some(response.total_tokens),
            error: None,
        },
    })
}

fn vision_model_result_from_response(
    response: VisionResponse,
    screen: ScreenDimensions,
    base_url: Option<String>,
) -> VisionGroundingModelResult {
    let grounding =
        parse_grounding_result(&response.text).map(|grounding| grounding_to_dto(grounding, screen));
    VisionGroundingModelResult {
        grounding,
        trace: VisionBackendTrace {
            backend: vision_backend_label(response.backend).to_string(),
            model: response.model,
            base_url,
            request_id: response.request_id,
            total_tokens: Some(response.total_tokens),
            error: None,
        },
    }
}

#[derive(Debug)]
struct VisionDescribeScreenModelResult {
    description: String,
    trace: VisionBackendTrace,
}

fn heuristic_screen_description(
    screen: &ScreenDimensions,
    capture: &CaptureFileInfo,
    prompt: &str,
) -> String {
    let mut lines = vec![
        format!("screen: {}x{}", screen.width, screen.height),
        format!("capture bytes: {}", capture.bytes),
        format!("capture hash: {}", capture.hash),
        format!("capture path: {}", capture.path),
    ];
    if !prompt.trim().is_empty() {
        lines.push(format!("prompt: {}", prompt.trim()));
    }
    lines.push(
        "visible summary: latest desktop capture is available for downstream vision/tool callers."
            .to_string(),
    );
    lines.join(" | ")
}

fn vision_backend_label(kind: VisionBackendKind) -> &'static str {
    match kind {
        VisionBackendKind::ZhipuGlm46VFlash => "zhipu-glm-4.6v-flash",
        VisionBackendKind::LocalOpenAiCompatible => "local-openai-compatible",
    }
}

fn classify_vision_error(error: &str) -> String {
    let lower = error.to_ascii_lowercase();
    if lower.contains("connection refused")
        || lower.contains("failed to connect")
        || lower.contains("tcp connect")
        || lower.contains("error sending request")
    {
        return format!("local vision backend unreachable: {error}");
    }
    if lower.contains("timed out") || lower.contains("timeout") {
        return format!("local vision backend timeout: {error}");
    }
    if lower.contains("401") || lower.contains("403") {
        return format!("local vision backend auth failed: {error}");
    }
    if lower.contains("404") {
        return format!("local vision backend route/model not found: {error}");
    }
    format!("local vision backend failed: {error}")
}

async fn api_action_plan(
    payload: Option<Json<ComputerActionPlanRequest>>,
) -> ApiResult<Json<ComputerActionPlanResponse>> {
    let payload = payload.map(|Json(payload)| payload).unwrap_or_default();
    Ok(Json(run_action_plan(payload).await?))
}

async fn run_action_plan(
    payload: ComputerActionPlanRequest,
) -> ApiResult<ComputerActionPlanResponse> {
    let requested_action = payload
        .action
        .as_deref()
        .map(normalize_action_name)
        .unwrap_or_else(|| "left_click".to_string());
    if payload.execute.unwrap_or(false) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "action-plan 阶段不开放真实 execute，请使用 dry-run 先验证计划。",
        ));
    }

    let target = payload
        .target
        .clone()
        .unwrap_or_else(|| "explicit coordinates".to_string());
    let (point, roi, path) = action_geometry(&requested_action, &payload)?;
    let mut steps = Vec::new();
    let mut recovery_action = None;
    let mut requires_visual_grounding = false;

    match requested_action.as_str() {
        "left_click" => steps.push(format!(
            "move to ({}, {}) and send left click",
            point.x, point.y
        )),
        "double_click" => steps.push(format!(
            "move to ({}, {}) and send double click",
            point.x, point.y
        )),
        "right_click" => {
            steps.push(format!(
                "move to ({}, {}) and send right click",
                point.x, point.y
            ));
            recovery_action = Some("press_escape".to_string());
        }
        "context_menu_select" => {
            requires_visual_grounding = true;
            steps.push(format!(
                "right click target `{target}` at ({}, {})",
                point.x, point.y
            ));
            steps.push(format!(
                "ground context menu item `{}` from after-right-click screenshot",
                payload
                    .menu_item
                    .as_deref()
                    .unwrap_or("unspecified menu item")
            ));
            steps.push("left click grounded menu item center".to_string());
            recovery_action = Some("press_escape".to_string());
        }
        "drag_select" => {
            let Some(end) = path.last().copied() else {
                return Err(api_error(
                    StatusCode::BAD_REQUEST,
                    "drag_select 需要 end 点。",
                ));
            };
            steps.push(format!("left button down at ({}, {})", point.x, point.y));
            steps.push(format!(
                "drag through {} points to ({}, {})",
                path.len(),
                end.x,
                end.y
            ));
            steps.push("left button up".to_string());
        }
        "visual_action" => {
            requires_visual_grounding = true;
            steps.push(format!("capture screen and ground target `{target}`"));
            steps.push(format!(
                "build `{}` action from grounded point or bbox",
                payload.action.as_deref().unwrap_or("left_click")
            ));
        }
        "scroll" => {
            let delta = payload.delta.unwrap_or(-480);
            steps.push(format!(
                "move to ({}, {}) if target focus is required",
                point.x, point.y
            ));
            steps.push(format!("send mouse wheel delta {delta}"));
        }
        "text_input" => {
            let text = payload
                .text
                .as_deref()
                .filter(|value| !value.is_empty())
                .ok_or_else(|| api_error(StatusCode::BAD_REQUEST, "text_input 需要 text 字段"))?;
            requires_visual_grounding = payload.target.is_some();
            if payload.target.is_some() {
                steps.push(format!(
                    "focus grounded target `{target}` at ({}, {})",
                    point.x, point.y
                ));
            }
            steps.push(format!(
                "type text with {} characters",
                text.chars().count()
            ));
        }
        "press_key" => {
            let key = payload
                .key
                .as_deref()
                .filter(|value| !value.is_empty())
                .ok_or_else(|| api_error(StatusCode::BAD_REQUEST, "press_key 需要 key 字段"))?;
            let Some(vk) = virtual_key_code(key) else {
                return Err(api_error(
                    StatusCode::BAD_REQUEST,
                    &format!("unsupported virtual key: {key}"),
                ));
            };
            steps.push(format!("press virtual key `{}` (0x{vk:02X})", key.trim()));
        }
        "hotkey" => {
            let keys = payload
                .keys
                .as_deref()
                .ok_or_else(|| api_error(StatusCode::BAD_REQUEST, "hotkey 需要 keys 数组"))?;
            let mut codes = Vec::new();
            for key in keys {
                let Some(code) = virtual_key_code(key) else {
                    return Err(api_error(
                        StatusCode::BAD_REQUEST,
                        &format!("unsupported hotkey key: {key}"),
                    ));
                };
                codes.push(code);
            }
            steps.push(format!("press hotkey `{}`", keys.join("+")));
            steps.push(format!(
                "virtual key codes: {}",
                format_virtual_key_codes(&codes)
            ));
        }
        other => {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                &format!("unsupported computer action: {other}"),
            ));
        }
    }

    let audit = computer_use_audit_record(
        &requested_action,
        &target,
        payload.execute.unwrap_or(false),
        false,
        None,
    );

    Ok(ComputerActionPlanResponse {
        status: "dry-run action plan ready".to_string(),
        action: requested_action,
        target,
        execute: false,
        executed: false,
        requires_visual_grounding,
        point,
        roi,
        path,
        recovery_action,
        action_steps: steps,
        audit,
        notes: vec![
            "工具卡片 LLM tool calling 初期只能拿到 action plan，不执行真实键鼠。".to_string(),
            "真实执行必须另走显式授权和截图审计".to_string(),
        ],
    })
}

async fn run_visual_action_dry_run(
    payload: VisualActionRequest,
) -> ApiResult<VisualActionResponse> {
    if payload.execute.unwrap_or(false) {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "visual_action 阶段不开放真实 execute；请先查看视觉 grounding action plan。",
        ));
    }

    let target = payload
        .target
        .clone()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| "current screen target".to_string());
    let action = payload
        .action
        .as_deref()
        .map(normalize_action_name)
        .filter(|value| value != "visual_action")
        .unwrap_or_else(|| "left_click".to_string());
    let vision = run_vision_find_target(VisionFindTargetRequest {
        target: Some(target.clone()),
        capture_path: payload.capture_path.clone(),
        raw_response: payload.raw_response.clone(),
        use_latest_capture: payload.use_latest_capture.or(Some(true)),
        use_model: payload.use_model.or(Some(false)),
        base_url: payload.base_url.clone(),
        model: payload.model.clone(),
        api_key: payload.api_key.clone(),
        timeout_seconds: payload.timeout_seconds,
    })
    .await?;

    let action_plan_request =
        visual_action_plan_from_grounding(&action, &target, vision.grounding.as_ref());
    let action_plan = if let Some(request) = action_plan_request {
        Some(run_action_plan(request).await?)
    } else {
        None
    };
    let status = if action_plan.is_some() {
        "visual-action-plan-ready"
    } else if vision
        .backend
        .as_ref()
        .and_then(|trace| trace.error.as_ref())
        .is_some()
    {
        "visual-grounding-backend-error"
    } else {
        "visual-grounding-missing"
    };
    let evidence = visual_action_evidence(&target, &vision);
    let audit = computer_use_audit_record(
        &action,
        &target,
        payload.execute.unwrap_or(false),
        false,
        Some(vision.capture.path.clone()),
    );

    Ok(VisualActionResponse {
        status: status.to_string(),
        target,
        action,
        execute: false,
        executed: false,
        execute_allowed: false,
        audit,
        vision,
        evidence,
        action_plan,
        safety_gate: COMPUTER_USE_PERMISSION_GATE.to_string(),
        notes: vec![
            "visual_action 只组合内视觉 grounding 和 computer-use action plan。".to_string(),
            "未获得 grounding 时不会退回固定几何点。".to_string(),
            "真实点击/拖拽需后续显式 execute gate、截图审计和人工确认".to_string(),
        ],
    })
}

fn visual_action_evidence(target: &str, vision: &VisionFindTargetResponse) -> VisualActionEvidence {
    let grounding = vision.grounding.as_ref();
    VisualActionEvidence {
        screenshot: vision.capture.clone(),
        target: target.to_string(),
        point: grounding.and_then(|grounding| grounding.point),
        bbox: grounding.and_then(|grounding| grounding.bbox),
        confidence: grounding.and_then(|grounding| grounding.confidence),
        confidence_reason: grounding.and_then(|grounding| grounding.confidence_reason.clone()),
        backend: vision.backend.clone(),
    }
}

fn visual_action_plan_from_grounding(
    action: &str,
    target: &str,
    grounding: Option<&VisionGroundingDto>,
) -> Option<ComputerActionPlanRequest> {
    let grounding = grounding?;
    let point = grounding.point.or_else(|| grounding.bbox.map(roi_center))?;
    Some(ComputerActionPlanRequest {
        action: Some(action.to_string()),
        target: Some(target.to_string()),
        menu_item: None,
        x: Some(point.x),
        y: Some(point.y),
        start: None,
        end: None,
        bbox: grounding.bbox,
        text: None,
        key: None,
        keys: None,
        delta: None,
        execute: Some(false),
    })
}

fn roi_center(roi: RoiDto) -> PointDto {
    PointDto {
        x: roi.left + roi.width / 2,
        y: roi.top + roi.height / 2,
    }
}

async fn api_tool_dispatch(
    Json(payload): Json<ToolDispatchRequest>,
) -> ApiResult<Json<ToolDispatchResponse>> {
    Ok(Json(run_tool_dispatch(payload).await?))
}

fn file_write_runtime_input_from_intent(intent: &str) -> Option<JsonValue> {
    let path = extract_first_file_path_from_intent(intent)?;
    let content = extract_file_write_content_from_intent(intent, &path)?;
    let raw_path = PathBuf::from(path.trim());
    let target = if raw_path.is_absolute() {
        raw_path
    } else {
        active_workspace_path().join(raw_path)
    };
    Some(json!({
        "path": target.to_string_lossy(),
        "content": content
    }))
}

fn file_write_runtime_input_from_semantic_dispatch_input(input: &JsonValue) -> Option<JsonValue> {
    if let Some(intent) = input_string(input, "intent") {
        if let Some(runtime_input) = file_write_runtime_input_from_intent(&intent) {
            return Some(runtime_input);
        }
    }

    let target = input_string(input, "target").or_else(|| input_string(input, "path"))?;
    let path = extract_first_file_path_from_intent(&target).unwrap_or(target);
    let content = input_string(input, "text").or_else(|| input_string(input, "content"))?;
    if extract_first_file_path_from_intent(&path).is_none() {
        return None;
    }
    let raw_path = PathBuf::from(path.trim());
    let target = if raw_path.is_absolute() {
        raw_path
    } else {
        active_workspace_path().join(raw_path)
    };
    Some(json!({
        "path": target.to_string_lossy(),
        "content": content
    }))
}

fn extract_first_file_path_from_intent(intent: &str) -> Option<String> {
    let lower = intent.to_ascii_lowercase();
    const SUFFIXES: &[&str] = &[
        ".txt", ".md", ".json", ".toml", ".rs", ".js", ".ts", ".tsx", ".jsx", ".py", ".html",
        ".css", ".yaml", ".yml", ".csv", ".log",
    ];
    for suffix in SUFFIXES {
        let Some(suffix_start) = lower.find(suffix) else {
            continue;
        };
        let suffix_end = suffix_start + suffix.len();
        let bytes = intent.as_bytes();
        let mut start = suffix_start;
        while start > 0 && is_ascii_path_byte(bytes[start - 1]) {
            start -= 1;
        }
        let candidate = intent[start..suffix_end]
            .trim_matches(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '`' | '“' | '”'))
            .to_string();
        if !candidate.is_empty() {
            return Some(candidate);
        }
    }
    None
}

fn is_ascii_path_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'-' | b'.' | b'/' | b'\\' | b':')
}

fn extract_file_write_content_from_intent(intent: &str, path: &str) -> Option<String> {
    for segment in quoted_segments(intent) {
        let value = trim_intent_content(&segment);
        if !value.is_empty()
            && value != path
            && extract_first_file_path_from_intent(&value).is_none()
        {
            return Some(value);
        }
    }

    for marker in [
        "写上",
        "写入",
        "写进",
        "内容为",
        "内容是",
        "content is",
        "content:",
        "with content",
        "write",
    ] {
        let index = if marker.is_ascii() {
            intent.to_ascii_lowercase().find(marker)
        } else {
            intent.find(marker)
        };
        if let Some(index) = index {
            let value = trim_intent_content(&intent[index + marker.len()..]);
            if !value.is_empty() && value != path {
                return Some(value);
            }
        }
    }
    extract_ascii_tail_after_path(intent, path)
}

fn extract_ascii_tail_after_path(intent: &str, path: &str) -> Option<String> {
    let lower_intent = intent.to_ascii_lowercase();
    let lower_path = path.to_ascii_lowercase();
    let path_start = lower_intent.find(&lower_path)?;
    let mut tail = trim_intent_content(&intent[path_start + path.len()..]);
    if tail.is_empty() {
        return None;
    }

    if !tail
        .chars()
        .next()
        .is_some_and(|ch| ch.is_ascii_alphanumeric())
    {
        let ascii_start = tail
            .char_indices()
            .find(|(_, ch)| ch.is_ascii_alphanumeric())
            .map(|(index, _)| index)?;
        tail = trim_intent_content(&tail[ascii_start..]);
    }

    for prefix in ["file", "then", "and", "with", "content"] {
        let lower_tail = tail.to_ascii_lowercase();
        if lower_tail == prefix {
            return None;
        }
        if let Some(rest) = lower_tail.strip_prefix(prefix) {
            if rest.starts_with(char::is_whitespace)
                || rest.starts_with(':')
                || rest.starts_with('=')
            {
                tail = trim_intent_content(&tail[prefix.len()..]);
            }
        }
    }

    if tail.is_empty() || extract_first_file_path_from_intent(&tail).is_some() {
        None
    } else {
        Some(tail)
    }
}

fn quoted_segments(input: &str) -> Vec<String> {
    let mut segments = Vec::new();
    for (open, close) in [('"', '"'), ('\'', '\''), ('“', '”'), ('‘', '’')] {
        let mut rest = input;
        while let Some(start) = rest.find(open) {
            let after_open = &rest[start + open.len_utf8()..];
            let Some(end) = after_open.find(close) else {
                break;
            };
            segments.push(after_open[..end].to_string());
            rest = &after_open[end + close.len_utf8()..];
        }
    }
    segments
}

fn trim_intent_content(value: &str) -> String {
    value
        .trim()
        .trim_matches(|c: char| {
            c.is_whitespace()
                || matches!(
                    c,
                    ':' | '：'
                        | '"'
                        | '\''
                        | '`'
                        | '“'
                        | '”'
                        | '。'
                        | '，'
                        | ','
                        | ';'
                        | '；'
                        | '?'
                        | '？'
                )
        })
        .trim_end_matches('吗')
        .trim()
        .to_string()
}

async fn execute_authorized_webui_runtime_dispatch(
    tool_name: &str,
    input: JsonValue,
) -> ToolDispatchResponse {
    let workspace_root = active_workspace_path();
    let workspace_id = workspace_identity(&workspace_root);
    let session_id = session_store()
        .lock()
        .ok()
        .and_then(|store| store.state.active_session_id.clone());
    let input = runtime_tool_input_with_defaults(tool_name, &input);
    let invoke = ToolInvoke {
        call_id: format!("web-{}", unix_timestamp_millis()),
        tool_name: tool_name.to_string(),
        input: input.clone(),
        caller: ToolCaller::WebUi,
        workspace_id,
        session_id,
        user_authorized: true,
        user_confirmed_twice: true,
    };
    let timeout_ms = tool_timeout_ms_for(tool_name, &input);
    let outcome =
        execute_runtime_tool_with_timeout(invoke.clone(), workspace_root.clone(), timeout_ms, None)
            .await;
    append_tool_audit_record(&invoke, &outcome);
    emit_pet_event_for_tool_outcome(&invoke.tool_name, &outcome);
    tool_outcome_to_dispatch_response(tool_name, &input, outcome)
}

fn append_tool_result_to_session(record: &PendingApprovalRecord, outcome: &ToolOutcome) {
    let Some(session_id) = record.session_id.as_deref() else {
        return;
    };
    let Ok(mut store) = session_store().lock() else {
        return;
    };
    let status_text = match outcome.status {
        ToolOutcomeStatus::Ok => "执行成功",
        ToolOutcomeStatus::Failed => "执行失败",
        ToolOutcomeStatus::Timeout => "执行超时",
        ToolOutcomeStatus::Rejected => "权限拒绝",
        ToolOutcomeStatus::DryRunOnly => "模拟执行",
    };
    let message = ChatMessageDto {
        id: format!("approved-{}", unix_timestamp_millis()),
        author: "工具审批执行".to_string(),
        role: "system".to_string(),
        target: session_id.to_string(),
        content: format!(
            "已审批执行 {}: {}\n结果: {}{}",
            outcome.tool_name,
            status_text,
            outcome.summary_text,
            if outcome.status.is_error() { "" } else { "" }
        ),
        kind: "tool-result".to_string(),
        attachments: Vec::new(),
    };
    let _ = store.append_chat_messages(session_id, vec![message]);
}

async fn api_tool_execute(
    Json(mut payload): Json<ToolDispatchRequest>,
) -> ApiResult<Json<ToolDispatchResponse>> {
    diag!(
        "[TOOL-CHAIN] api_tool_execute: intent='{}', execute=true",
        payload.intent
    );
    if payload.execute.unwrap_or(false) {
        if let Some(input) = file_write_runtime_input_from_intent(&payload.intent) {
            diag!("[TOOL-CHAIN] api_tool_execute: routing file-write intent to runtime write_file");
            return Ok(Json(
                execute_authorized_webui_runtime_dispatch("write_file", input).await,
            ));
        }
    }
    let target = payload
        .target
        .clone()
        .unwrap_or_else(|| payload.intent.clone());
    diag!("[TOOL-CHAIN] api_tool_execute: target='{target}'");

    let locate = run_grounding_router(locate_request_from_tool_payload(&payload, &target)).await?;
    let verified = if let Some(point) = locate.point {
        diag!(
            "[TOOL-CHAIN] locate chose {:?} point=({}, {}) conf={}",
            locate.chosen_backend,
            point.x,
            point.y,
            locate.confidence
        );
        verify_cursor_on_target(point.x, point.y, &target).await
    } else {
        diag!(
            "[TOOL-CHAIN] locate failed status={:?}; no hardcoded anchor fallback",
            locate.status
        );
        false
    };

    if verified {
        if let Some(point) = locate.point {
            let input_screen = input_screen_dimensions();
            let input_point = map_capture_point_to_input(
                PointDto {
                    x: point.x,
                    y: point.y,
                },
                ScreenDimensions {
                    width: locate.screen.logical_width,
                    height: locate.screen.logical_height,
                },
                input_screen,
            );
            diag!(
                "[TOOL-CHAIN] LLM verification PASSED, executing click logical=({},{}) input=({},{})",
                point.x,
                point.y,
                input_point.x,
                input_point.y
            );
            let scenario =
                find_scenario(Some("desktop-left-click"))
                    .ok()
                    .unwrap_or(&InteractionScenario {
                        name: "user-click",
                        target: UiTargetKind::DesktopIcon,
                        action: MouseActionKind::LeftClick,
                        anchor: RelativeAnchor { x: 0.5, y: 0.5 },
                        intent: "用户授权点击",
                    });
            match execute_mouse_action(scenario, input_point.x, input_point.y, None).await {
                Ok(()) => diag!(
                    "[TOOL-CHAIN] api_tool_execute: click executed at input ({},{})",
                    input_point.x,
                    input_point.y
                ),
                Err(e) => diag!("[TOOL-CHAIN] api_tool_execute: click FAILED: {e}"),
            }
        }
    } else {
        diag!("[TOOL-CHAIN] locate/verification FAILED, skipping click");
    }

    payload.execute = Some(verified);
    Ok(Json(run_tool_dispatch(payload).await?))
}

fn locate_request_from_tool_payload(
    payload: &ToolDispatchRequest,
    target: &str,
) -> vision::locate::LocateRequest {
    let target = payload
        .system_control
        .as_deref()
        .and_then(try_parse_system_control)
        .or_else(|| detect_system_control_from_target(target))
        .map(|id| vision::locate::LocateTarget::System { id })
        .unwrap_or_else(|| vision::locate::LocateTarget::Natural {
            text: target.to_string(),
        });
    let router = active_vision_router_config();
    vision::locate::LocateRequest {
        target,
        backends: None,
        min_confidence: router.min_confidence,
        cross_verify: router.cross_verify,
        region_hint: None,
        capture_path: None,
        timeout_ms: router.timeout_ms,
        diagnostics: true,
    }
}

#[allow(dead_code)]
fn try_parse_system_control(name: &str) -> Option<vision::locate::SystemControlId> {
    use vision::locate::SystemControlId;
    match name {
        "start-button" | "StartButton" => Some(SystemControlId::StartButton),
        "taskbar" | "Taskbar" => Some(SystemControlId::Taskbar),
        "system-tray" | "SystemTray" => Some(SystemControlId::SystemTray),
        "window-close" | "WindowCloseButton" => Some(SystemControlId::WindowCloseButton),
        "window-minimize" | "WindowMinimizeButton" => Some(SystemControlId::WindowMinimizeButton),
        _ => None,
    }
}

#[allow(dead_code)]
fn detect_system_control_from_target(target: &str) -> Option<vision::locate::SystemControlId> {
    use vision::locate::SystemControlId;
    let lower = target.to_lowercase();
    if lower.contains("start") || lower.contains("开") {
        Some(SystemControlId::StartButton)
    } else if lower.contains("taskbar") || lower.contains("任务") {
        Some(SystemControlId::Taskbar)
    } else if lower.contains("tray") || lower.contains("托盘") {
        Some(SystemControlId::SystemTray)
    } else if lower.contains("close") || lower.contains("关闭") {
        Some(SystemControlId::WindowCloseButton)
    } else {
        None
    }
}

fn tool_route_label(calls_vision: bool, calls_tool: bool) -> &'static str {
    match (calls_vision, calls_tool) {
        (true, true) => "vision-computer-use",
        (true, false) => "vision",
        (false, true) => "computer-use",
        (false, false) => "none",
    }
}

fn semantic_action_from_intent(intent: &str) -> Option<String> {
    let lower = intent.to_ascii_lowercase();
    if contains_any(
        &lower,
        &["右键菜单", "上下文菜", "context menu", "menu item"],
    ) {
        Some("context_menu_select".to_string())
    } else if contains_any(&lower, &["双击", "double click", "double-click"]) {
        Some("double_click".to_string())
    } else if contains_any(&lower, &["右键", "right click", "right-click"]) {
        Some("right_click".to_string())
    } else if contains_any(
        &lower,
        &["拖拽", "框", "drag", "select region", "drag select"],
    ) {
        Some("drag_select".to_string())
    } else if contains_any(&lower, &["滚动", "滚轮", "scroll", "wheel"]) {
        Some("scroll".to_string())
    } else if contains_any(
        &lower,
        &[
            "输入文字",
            "键入",
            "打字",
            "type text",
            "text input",
            "输入",
        ],
    ) {
        Some("text_input".to_string())
    } else if contains_any(
        &lower,
        &["快捷", "组合", "hotkey", "shortcut", "ctrl+", "alt+"],
    ) {
        Some("hotkey".to_string())
    } else if contains_any(
        &lower,
        &["按下", "回车", "enter", "esc", "escape", "tab", "press key"],
    ) {
        Some("press_key".to_string())
    } else if contains_any(
        &lower,
        &["看", "视觉", "截图", "screen", "desktop", "vision"],
    ) && vision_request_has_action_intent(intent)
    {
        // 仅"视觉对象 + 明确操作意图"才作为 computer-use 视觉动作；
        // 纯"看 / 描述屏幕"返回 None（不进 calls_tool / 不执行点击，交多模态会话看图理解）。
        Some("visual_action".to_string())
    } else if contains_any(&lower, &["点击", "click", "press", "点一"]) {
        Some("left_click".to_string())
    } else {
        None
    }
}

fn semantic_target_from_intent(intent: &str) -> String {
    let trimmed = intent.trim();
    if trimmed.is_empty() {
        "current screen target".to_string()
    } else {
        trimmed.chars().take(120).collect()
    }
}

fn semantic_tool_input(action: &str, target: &str, menu_item: &str) -> JsonValue {
    match action {
        "context_menu_select" => json!({
            "target": target,
            "menu_item": menu_item,
            "x": 200,
            "y": 180,
            "execute": false
        }),
        "drag_select" => json!({
            "target": target,
            "start": { "x": 220, "y": 220 },
            "end": { "x": 520, "y": 420 },
            "execute": false
        }),
        "right_click" => json!({
            "target": target,
            "x": 200,
            "y": 180,
            "execute": false
        }),
        "double_click" => json!({
            "target": target,
            "x": 200,
            "y": 180,
            "execute": false
        }),
        "visual_action" => json!({
            "target": target,
            "action": "left_click",
            "execute": false
        }),
        "scroll" => json!({
            "target": target,
            "x": 420,
            "y": 360,
            "delta": semantic_scroll_delta(target),
            "execute": false
        }),
        "text_input" => json!({
            "target": target,
            "x": 420,
            "y": 88,
            "text": semantic_text_input(target),
            "execute": false
        }),
        "press_key" => json!({
            "key": semantic_key_from_intent(target),
            "execute": false
        }),
        "hotkey" => json!({
            "keys": semantic_hotkey_from_intent(target),
            "execute": false
        }),
        _ => json!({
            "target": target,
            "x": 200,
            "y": 180,
            "execute": false
        }),
    }
}

fn action_requires_visual_grounding(action: &str) -> bool {
    matches!(
        action,
        "context_menu_select" | "visual_action" | "drag_select" | "text_input"
    )
}

fn semantic_scroll_delta(intent: &str) -> i32 {
    let lower = intent.to_ascii_lowercase();
    if contains_any(&lower, &["向上", "上滚", "scroll up", "wheel up"]) {
        480
    } else {
        -480
    }
}

fn semantic_text_input(intent: &str) -> String {
    for marker in ["输入", "键入", "type", "text"] {
        if let Some((_, value)) = intent.split_once(marker) {
            let value = value
                .trim()
                .trim_matches([':', '：', '"', '\'', '`', ' '])
                .chars()
                .take(200)
                .collect::<String>();
            if !value.is_empty() {
                return value;
            }
        }
    }
    "dry-run text".to_string()
}

fn semantic_key_from_intent(intent: &str) -> String {
    let lower = intent.to_ascii_lowercase();
    if contains_any(&lower, &["esc", "escape", "退出", "取消"]) {
        "Escape".to_string()
    } else if contains_any(&lower, &["tab", "切换焦点"]) {
        "Tab".to_string()
    } else if contains_any(&lower, &["space", "空格"]) {
        "Space".to_string()
    } else {
        "Enter".to_string()
    }
}

fn semantic_hotkey_from_intent(intent: &str) -> Vec<String> {
    let lower = intent.to_ascii_lowercase();
    if contains_any(&lower, &["ctrl+l", "ctrl + l", "地址栏", "address"]) {
        vec!["Ctrl".to_string(), "L".to_string()]
    } else if contains_any(&lower, &["ctrl+f", "ctrl + f", "查找", "find"]) {
        vec!["Ctrl".to_string(), "F".to_string()]
    } else if contains_any(&lower, &["alt+tab", "alt + tab"]) {
        vec!["Alt".to_string(), "Tab".to_string()]
    } else {
        vec!["Ctrl".to_string(), "L".to_string()]
    }
}

fn virtual_key_code(key: &str) -> Option<u8> {
    let normalized = key
        .trim()
        .trim_matches('+')
        .replace('-', "_")
        .replace(' ', "_")
        .to_ascii_lowercase();
    match normalized.as_str() {
        "ctrl" | "control" => Some(0x11),
        "shift" => Some(0x10),
        "alt" | "menu" => Some(0x12),
        "win" | "windows" | "meta" => Some(0x5B),
        "enter" | "return" => Some(0x0D),
        "esc" | "escape" => Some(0x1B),
        "tab" => Some(0x09),
        "space" | "spacebar" => Some(0x20),
        "backspace" => Some(0x08),
        "delete" | "del" => Some(0x2E),
        "up" | "arrow_up" => Some(0x26),
        "down" | "arrow_down" => Some(0x28),
        "left" | "arrow_left" => Some(0x25),
        "right" | "arrow_right" => Some(0x27),
        "home" => Some(0x24),
        "end" => Some(0x23),
        "page_up" | "pageup" => Some(0x21),
        "page_down" | "pagedown" => Some(0x22),
        "f1" => Some(0x70),
        "f2" => Some(0x71),
        "f3" => Some(0x72),
        "f4" => Some(0x73),
        "f5" => Some(0x74),
        "f6" => Some(0x75),
        "f7" => Some(0x76),
        "f8" => Some(0x77),
        "f9" => Some(0x78),
        "f10" => Some(0x79),
        "f11" => Some(0x7A),
        "f12" => Some(0x7B),
        value if value.len() == 1 => {
            let byte = value.as_bytes()[0];
            if byte.is_ascii_alphabetic() {
                Some(byte.to_ascii_uppercase())
            } else if byte.is_ascii_digit() {
                Some(byte)
            } else {
                None
            }
        }
        _ => None,
    }
}

fn format_virtual_key_codes(codes: &[u8]) -> String {
    codes
        .iter()
        .map(|code| format!("0x{code:02X}"))
        .collect::<Vec<_>>()
        .join("+")
}

fn contains_any(text: &str, keywords: &[&str]) -> bool {
    keywords.iter().any(|keyword| text.contains(keyword))
}

fn grounding_to_dto(
    grounding: vision::VisionGroundingResult,
    screen: ScreenDimensions,
) -> VisionGroundingDto {
    let (grounding, confidence_reason) = apply_grounding_confidence_policy(grounding);
    let point = grounding
        .point
        .and_then(|point| relative_point_to_pixel(point, (screen.width, screen.height)))
        .map(|(x, y)| PointDto { x, y });
    let bbox = grounding
        .bbox
        .and_then(|bbox| relative_bbox_to_pixel(bbox, (screen.width, screen.height)))
        .map(|(left, top, right, bottom)| RoiDto {
            left,
            top,
            width: right.saturating_sub(left).saturating_add(1),
            height: bottom.saturating_sub(top).saturating_add(1),
        });

    VisionGroundingDto {
        point,
        bbox,
        confidence: grounding.confidence,
        confidence_reason,
        label: grounding.label,
    }
}

fn normalize_action_name(action: &str) -> String {
    action
        .trim()
        .trim_start_matches("computer.")
        .replace('-', "_")
        .to_ascii_lowercase()
}

fn action_geometry(
    action: &str,
    payload: &ComputerActionPlanRequest,
) -> ApiResult<(PointDto, RoiDto, Vec<PointDto>)> {
    if matches!(action, "press_key" | "hotkey") {
        let point = PointDto { x: 0, y: 0 };
        return Ok((point, point_roi(point, 0), Vec::new()));
    }

    if action == "drag_select" {
        let (start, end) = drag_points_from_payload(payload)?;
        let path = drag_path(
            MousePoint {
                x: start.x,
                y: start.y,
            },
            MousePoint { x: end.x, y: end.y },
            16,
        )
        .into_iter()
        .map(|point| PointDto {
            x: point.x,
            y: point.y,
        })
        .collect::<Vec<_>>();
        let roi = roi_from_points(start, end);
        return Ok((start, roi, path));
    }

    if let Some(roi) = payload.bbox {
        let point = PointDto {
            x: roi.left + roi.width / 2,
            y: roi.top + roi.height / 2,
        };
        return Ok((point, roi, vec![point]));
    }

    let point = payload
        .start
        .or_else(|| match (payload.x, payload.y) {
            (Some(x), Some(y)) => Some(PointDto { x, y }),
            _ => None,
        })
        .unwrap_or(PointDto { x: 200, y: 180 });
    Ok((point, point_roi(point, 24), vec![point]))
}

fn drag_points_from_payload(
    payload: &ComputerActionPlanRequest,
) -> ApiResult<(PointDto, PointDto)> {
    if let (Some(start), Some(end)) = (payload.start, payload.end) {
        return Ok((start, end));
    }

    if let Some(roi) = payload.bbox {
        let start = PointDto {
            x: roi.left,
            y: roi.top,
        };
        let end = PointDto {
            x: roi.left + roi.width.saturating_sub(1),
            y: roi.top + roi.height.saturating_sub(1),
        };
        return Ok((start, end));
    }

    Err(api_error(
        StatusCode::BAD_REQUEST,
        "drag_select 需要 start/end bbox。",
    ))
}

fn point_roi(point: PointDto, radius: i32) -> RoiDto {
    let left = point.x.saturating_sub(radius).max(0);
    let top = point.y.saturating_sub(radius).max(0);
    RoiDto {
        left,
        top,
        width: radius.saturating_mul(2).saturating_add(1),
        height: radius.saturating_mul(2).saturating_add(1),
    }
}

fn roi_from_points(start: PointDto, end: PointDto) -> RoiDto {
    let left = start.x.min(end.x);
    let top = start.y.min(end.y);
    let right = start.x.max(end.x);
    let bottom = start.y.max(end.y);
    RoiDto {
        left,
        top,
        width: right.saturating_sub(left).saturating_add(1),
        height: bottom.saturating_sub(top).saturating_add(1),
    }
}

async fn api_stability_matrix() -> Json<StabilityMatrixResponse> {
    Json(build_stability_matrix())
}

async fn api_run_stability(
    payload: Option<Json<RunStabilityRequest>>,
) -> ApiResult<Json<RunStabilityResponse>> {
    let dry_run = payload
        .as_ref()
        .and_then(|Json(payload)| payload.dry_run)
        .unwrap_or(true);

    if !dry_run {
        return Err(api_error(
            StatusCode::BAD_REQUEST,
            "真实键鼠注入仍处于安全闸门内，请先通过 dry-run 确认坐标矩阵",
        ));
    }

    let matrix = build_stability_matrix();
    let total_checks = matrix
        .scenarios
        .iter()
        .map(|scenario| scenario.points.len())
        .sum();

    Ok(Json(RunStabilityResponse {
        dry_run,
        status: "通过".to_string(),
        total_checks,
        matrix,
        notes: vec![
            "覆盖桌面图标、任务栏、浏览器输入、窗口控件和全屏表面锚点".to_string(),
            "覆盖左键、右键、左右键组合、文本输入等动作类型".to_string(),
            "当前只验证锚点到物理坐标的映射，不执行真实点击".to_string(),
        ],
    }))
}

async fn api_computer_use_profile(
    payload: Option<Json<ComputerUseProfileRequest>>,
) -> ApiResult<Json<ComputerUseProfileResponse>> {
    let payload = payload.map(|Json(payload)| payload).unwrap_or_default();
    Ok(Json(run_computer_use_profile(payload).await?))
}

async fn run_computer_use_profile(
    payload: ComputerUseProfileRequest,
) -> ApiResult<ComputerUseProfileResponse> {
    let profile_start = Instant::now();
    let scenario = find_scenario(payload.scenario.as_deref())?;
    let timestamp = unix_timestamp_millis();
    let before_capture = closed_loop_capture_path(timestamp, "profile-before");
    let after_capture = closed_loop_capture_path(timestamp, "profile-after");
    let mut phases = Vec::new();

    let phase_start = Instant::now();
    capture_desktop(&before_capture).await?;
    phases.push(timed_phase(
        "capture_before",
        "采集操作前原始分辨率截图",
        phase_start,
        "完成",
    ));

    let phase_start = Instant::now();
    let screen = read_png_dimensions(&before_capture)?;
    let plan = build_closed_loop_plan(
        scenario,
        screen,
        payload.roi_radius.unwrap_or(64).clamp(12, 240),
    )?;
    let before_file = capture_file_info(&before_capture).await?;
    phases.push(timed_phase(
        "anchor_mapping",
        "解析屏幕尺寸并把语义锚点映射为物理坐",
        phase_start,
        "完成",
    ));

    let execute = payload.execute.unwrap_or(false);
    let mut executed = false;
    let mut input_error = None;
    let phase_start = Instant::now();
    if execute {
        diagnostics::info(
            "cu",
            "action.begin",
            "执行 computer-use 输入注入",
            &[
                ("scenario", scenario.name.to_string()),
                ("x", plan.point.x.to_string()),
                ("y", plan.point.y.to_string()),
            ],
        );
        match execute_mouse_action(
            scenario,
            plan.point.x,
            plan.point.y,
            payload.text.as_deref(),
        )
        .await
        {
            Ok(()) => {
                executed = true;
                diagnostics::info(
                    "cu",
                    "action.ok",
                    "输入注入完成",
                    &[("scenario", scenario.name.to_string())],
                );
            }
            Err(error) => {
                diagnostics::error(
                    "cu",
                    "action.error",
                    "输入注入失败",
                    &[
                        ("scenario", scenario.name.to_string()),
                        ("hint", compact_message_snippet(&error.to_string(), 160)),
                    ],
                );
                input_error = Some(error);
            }
        }
        phases.push(timed_phase(
            "input_injection",
            "执行鼠标/键盘输入注入",
            phase_start,
            if input_error.is_some() {
                "失败"
            } else {
                "完成"
            },
        ));
    } else {
        phases.push(TimedPhase {
            name: "input_injection".to_string(),
            description: "dry-run 跳过真实鼠标/键盘注入".to_string(),
            elapsed_ms: 0,
            status: "跳过".to_string(),
        });
    }

    let confirm_after = payload.confirm_after.unwrap_or(true);
    let after_file = if confirm_after {
        let phase_start = Instant::now();
        tokio::time::sleep(Duration::from_millis(
            payload.after_delay_ms.unwrap_or(160).min(1_000),
        ))
        .await;
        capture_desktop(&after_capture).await?;
        let file = capture_file_info(&after_capture).await?;
        phases.push(timed_phase(
            "capture_after",
            "输入后延迟并采集确认截图",
            phase_start,
            "完成",
        ));
        Some(file)
    } else {
        phases.push(TimedPhase {
            name: "capture_after".to_string(),
            description: "本次未要求操作后截图确认".to_string(),
            elapsed_ms: 0,
            status: "跳过".to_string(),
        });
        None
    };

    let phase_start = Instant::now();
    let screen_changed = after_file
        .as_ref()
        .map(|after| before_file.hash != after.hash || before_file.bytes != after.bytes)
        .unwrap_or(false);
    phases.push(timed_phase(
        "screen_diff",
        "比较前后截图 hash 和文件大",
        phase_start,
        "完成",
    ));

    Ok(ComputerUseProfileResponse {
        scenario: scenario.name.to_string(),
        target: target_name(scenario.target).to_string(),
        action: action_name(scenario.action).to_string(),
        execute,
        executed,
        input_error,
        screen,
        point: plan.point,
        roi: plan.roi,
        before_capture: before_file,
        after_capture: after_file,
        screen_changed,
        phases,
        total_elapsed_ms: elapsed_millis(profile_start),
        optimization_hint: "优先看 capture_before/capture_after。如果截图耗时占比最高，下一步应把 PowerShell 截图替换为平台原生截图后端或长驻采集进程。".to_string(),
    })
}

async fn api_closed_loop(
    Json(payload): Json<ClosedLoopRequest>,
) -> ApiResult<Json<ClosedLoopResponse>> {
    let scenario = find_scenario(payload.scenario.as_deref())?;
    let response = run_closed_loop_scenario(
        scenario,
        payload.execute.unwrap_or(false),
        payload.confirm_after.unwrap_or(true),
        payload.roi_radius.unwrap_or(48).clamp(12, 240),
        payload.text.as_deref(),
    )
    .await?;
    Ok(Json(response))
}

async fn run_closed_loop_scenario(
    scenario: &InteractionScenario,
    execute: bool,
    confirm_after: bool,
    roi_radius: u32,
    text: Option<&str>,
) -> ApiResult<ClosedLoopResponse> {
    let timestamp = unix_timestamp_millis();
    let before_capture = closed_loop_capture_path(timestamp, "before");
    let after_capture = closed_loop_capture_path(timestamp, "after");

    capture_desktop(&before_capture).await?;
    let screen = read_png_dimensions(&before_capture)?;
    let plan = build_closed_loop_plan(scenario, screen, roi_radius)?;
    let before_file = capture_file_info(&before_capture).await?;

    let mut executed = false;
    let mut input_error = None;
    if execute {
        match execute_mouse_action(scenario, plan.point.x, plan.point.y, text).await {
            Ok(()) => executed = true,
            Err(error) => input_error = Some(error),
        }
    }

    let after_file = if confirm_after {
        tokio::time::sleep(Duration::from_millis(220)).await;
        capture_desktop(&after_capture).await?;
        Some(capture_file_info(&after_capture).await?)
    } else {
        None
    };

    let changed = after_file
        .as_ref()
        .map(|after| before_file.hash != after.hash || before_file.bytes != after.bytes)
        .unwrap_or(false);

    Ok(ClosedLoopResponse {
        status: if input_error.is_some() {
            "输入执行失败".to_string()
        } else if execute {
            "闭环已执".to_string()
        } else {
            "闭环 dry-run 完成".to_string()
        },
        execute,
        executed,
        input_error,
        scenario: scenario.name.to_string(),
        target: target_name(scenario.target).to_string(),
        action: action_name(scenario.action).to_string(),
        intent: scenario.intent.to_string(),
        screen,
        point: plan.point,
        roi: plan.roi,
        before_capture: before_file,
        after_capture: after_file,
        screen_changed: changed,
        notes: closed_loop_notes(execute, scenario.action),
    })
}

async fn api_safe_click_test(
    payload: Option<Json<SafeClickTestRequest>>,
) -> ApiResult<Json<SafeClickTestResponse>> {
    let payload = payload.map(|Json(payload)| payload).unwrap_or_default();
    let timestamp = unix_timestamp_millis();
    let before_capture = closed_loop_capture_path(timestamp, "safe-before");
    let after_capture = closed_loop_capture_path(timestamp, "safe-after");
    let marker_path = safe_click_marker_path(timestamp);
    let ready_path = safe_click_ready_path(&marker_path);
    let target_number = payload
        .target_number
        .filter(|number| (100..=999).contains(number))
        .unwrap_or_else(random_target_number);

    capture_desktop(&before_capture).await?;
    let screen = read_png_dimensions(&before_capture)?;
    let layout = payload.layout.as_deref().unwrap_or("random");
    let window = safe_click_window_for_layout(
        screen,
        payload.window_width.unwrap_or(420),
        payload.window_height.unwrap_or(260),
        layout,
    );
    tokio::fs::create_dir_all(
        marker_path.parent().ok_or_else(|| {
            api_error(StatusCode::INTERNAL_SERVER_ERROR, "marker path 缺少父目录")
        })?,
    )
    .await
    .map_err(io_api_error)?;
    let _ = tokio::fs::remove_file(&marker_path).await;
    let _ = tokio::fs::remove_file(&ready_path).await;

    launch_safe_click_window(&window, target_number, &marker_path, &ready_path).await?;
    let window_ready = wait_for_marker(
        &ready_path,
        Duration::from_millis(payload.startup_timeout_ms.unwrap_or(4_000)),
    )
    .await;
    tokio::time::sleep(Duration::from_millis(
        payload.startup_delay_ms.unwrap_or(250),
    ))
    .await;

    let before_file = capture_file_info(&before_capture).await?;
    let target_capture = closed_loop_capture_path(timestamp, "safe-target");
    capture_desktop(&target_capture).await?;
    let target_file = capture_file_info(&target_capture).await?;
    let requires_visual_grounding = payload.use_visual_grounding.unwrap_or(false);
    let vision = if requires_visual_grounding {
        visual_ground_safe_click_point(&target_capture, screen, target_number, window)
            .await
            .unwrap_or_else(|error| SafeClickVisionResult {
                source: "visual-grounding-error".to_string(),
                target_description: safe_click_target_description(target_number),
                point: window.click_point,
                raw_response: None,
                error: Some(error),
            })
    } else {
        SafeClickVisionResult {
            source: "geometry-fallback".to_string(),
            target_description: safe_click_target_description(target_number),
            point: window.click_point,
            raw_response: None,
            error: None,
        }
    };
    let mut input_error = None;
    let mut executed = false;
    if requires_visual_grounding && vision.error.is_some() {
        input_error =
            Some("safe-click 强视觉模式下 grounding 失败，已拒绝几何回退点击".to_string());
    } else if window_ready.hit {
        let input_screen = input_screen_dimensions();
        let input_point = map_capture_point_to_input(vision.point, screen, input_screen);
        diag!(
            "[SAFE-CLICK] logical=({},{}), input=({},{}), capture={}x{}, input_screen={}x{}",
            vision.point.x,
            vision.point.y,
            input_point.x,
            input_point.y,
            screen.width,
            screen.height,
            input_screen.width,
            input_screen.height
        );
        match send_mouse_action(input_point.x, input_point.y, MouseButtonAction::LeftClick).await {
            Ok(()) => executed = true,
            Err(error) => input_error = Some(error),
        }
    } else {
        input_error = Some("safe-click 测试窗口未在超时时间内进入可点击状".to_string());
    }

    let marker = wait_for_marker(
        &marker_path,
        Duration::from_millis(payload.marker_timeout_ms.unwrap_or(9_000)),
    )
    .await;
    capture_desktop(&after_capture).await?;
    let after_file = capture_file_info(&after_capture).await?;

    Ok(Json(SafeClickTestResponse {
        status: if marker.hit {
            "真实点击命中".to_string()
        } else if input_error.is_some() {
            "真实点击执行失败".to_string()
        } else {
            "真实点击未命".to_string()
        },
        executed,
        input_error,
        screen,
        window,
        target_number,
        vision,
        window_ready,
        marker,
        before_capture: before_file,
        target_capture: target_file,
        after_capture: after_file,
    }))
}

