async fn run_safe_context_menu_test(
    payload: SafeContextMenuRequest,
) -> ApiResult<SafeContextMenuResponse> {
    let timestamp = unix_timestamp_millis();
    let before_capture = closed_loop_capture_path(timestamp, "context-before");
    let target_capture = closed_loop_capture_path(timestamp, "context-target");
    let after_capture = closed_loop_capture_path(timestamp, "context-after");
    let marker_path = safe_context_marker_path(timestamp);
    let ready_path = safe_click_ready_path(&marker_path);
    let menu_target_point_path = marker_path.with_extension("target-point.txt");
    let target_number = payload
        .target_number
        .filter(|number| (100..=999).contains(number))
        .unwrap_or_else(random_target_number);

    capture_desktop(&before_capture).await?;
    let screen = read_png_dimensions(&before_capture)?;
    let window = safe_click_window_for_layout(
        screen,
        payload.window_width.unwrap_or(460),
        payload.window_height.unwrap_or(320),
        payload.layout.as_deref().unwrap_or("random"),
    );
    let menu_point = PointDto {
        x: window.left + 96,
        y: window.top + 92,
    };
    let mut menu_item_point = PointDto {
        x: window.left + 176,
        y: window.top + 226,
    };

    let before_file = capture_file_info(&before_capture).await?;
    let mut window_ready = SafeClickMarker {
        path: ready_path.display().to_string(),
        hit: false,
        value: None,
    };
    let mut marker = SafeClickMarker {
        path: marker_path.display().to_string(),
        hit: false,
        value: None,
    };
    let mut executed = false;
    let mut input_error = None;

    if payload.execute.unwrap_or(false) {
        prepare_marker_files(&marker_path, &ready_path).await?;
        let _ = tokio::fs::remove_file(&menu_target_point_path).await;
        launch_safe_context_menu_window(
            &window,
            target_number,
            &marker_path,
            &ready_path,
            &menu_target_point_path,
        )
        .await?;
        window_ready = wait_for_marker(
            &ready_path,
            Duration::from_millis(payload.startup_timeout_ms.unwrap_or(4_000)),
        )
        .await;
        tokio::time::sleep(Duration::from_millis(
            payload.startup_delay_ms.unwrap_or(300),
        ))
        .await;
        capture_desktop(&target_capture).await?;
        if window_ready.hit {
            let input_screen = input_screen_dimensions();
            let input_menu_point = map_capture_point_to_input(menu_point, screen, input_screen);
            let input_menu_item_point =
                map_capture_point_to_input(menu_item_point, screen, input_screen);
            diag!(
                "[SAFE-CONTEXT] menu logical=({},{})->input=({},{}), item logical=({},{})->input=({},{}), capture={}x{}, input_screen={}x{}",
                menu_point.x,
                menu_point.y,
                input_menu_point.x,
                input_menu_point.y,
                menu_item_point.x,
                menu_item_point.y,
                input_menu_item_point.x,
                input_menu_item_point.y,
                screen.width,
                screen.height,
                input_screen.width,
                input_screen.height
            );
            if let Err(error) = send_mouse_action(
                input_menu_point.x,
                input_menu_point.y,
                MouseButtonAction::RightClick,
            )
            .await
            {
                input_error = Some(error);
            } else {
                tokio::time::sleep(Duration::from_millis(180)).await;
                let input_menu_item_point =
                    wait_for_point_marker(&menu_target_point_path, Duration::from_millis(1_200))
                        .await
                        .unwrap_or(input_menu_item_point);
                menu_item_point =
                    map_input_point_to_capture(input_menu_item_point, screen, input_screen);
                diag!(
                    "[SAFE-CONTEXT] ACTION item resolved input=({},{}), logical=({},{})",
                    input_menu_item_point.x,
                    input_menu_item_point.y,
                    menu_item_point.x,
                    menu_item_point.y
                );
                if let Err(error) = send_mouse_action(
                    input_menu_item_point.x,
                    input_menu_item_point.y,
                    MouseButtonAction::LeftClick,
                )
                .await
                {
                    input_error = Some(error);
                    let _ = send_escape_key().await;
                } else {
                    executed = true;
                }
            }
        } else {
            input_error = Some("safe-context-menu 窗口未进入 ready 状态。".to_string());
        }
        marker = wait_for_marker(
            &marker_path,
            Duration::from_millis(payload.marker_timeout_ms.unwrap_or(6_000)),
        )
        .await;
    } else {
        capture_desktop(&target_capture).await?;
    }

    capture_desktop(&after_capture).await?;
    let target_file = capture_file_info(&target_capture).await?;
    let after_file = capture_file_info(&after_capture).await?;

    Ok(SafeContextMenuResponse {
        status: if payload.execute.unwrap_or(false) {
            if marker.hit {
                "context-menu-hit".to_string()
            } else if input_error.is_some() {
                "context-menu-execute-failed".to_string()
            } else {
                "context-menu-not-hit".to_string()
            }
        } else {
            "context-menu-dry-run".to_string()
        },
        execute: payload.execute.unwrap_or(false),
        executed,
        input_error,
        screen,
        window,
        target_number,
        menu_point,
        menu_item_point,
        action_steps: vec![
            format!(
                "right click target area at ({}, {})",
                menu_point.x, menu_point.y
            ),
            format!(
                "left click ACTION {target_number} menu item at ({}, {})",
                menu_item_point.x, menu_item_point.y
            ),
            "press Esc on failure to clear context menu".to_string(),
        ],
        window_ready,
        marker,
        before_capture: before_file,
        target_capture: target_file,
        after_capture: after_file,
    })
}

