fn read_png_dimensions(path: &Path) -> ApiResult<ScreenDimensions> {
    let bytes = std::fs::read(path).map_err(io_api_error)?;
    parse_png_dimensions(&bytes).ok_or_else(|| {
        api_error(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("无法解析截图尺寸: {}", path.display()),
        )
    })
}

fn parse_png_dimensions(bytes: &[u8]) -> Option<ScreenDimensions> {
    let signature = [0x89, b'P', b'N', b'G', b'\r', b'\n', 0x1A, b'\n'];
    if bytes.len() < 24 || bytes[..8] != signature {
        return None;
    }
    if &bytes[12..16] != b"IHDR" {
        return None;
    }
    let width = u32::from_be_bytes(bytes[16..20].try_into().ok()?);
    let height = u32::from_be_bytes(bytes[20..24].try_into().ok()?);
    if width == 0 || height == 0 {
        return None;
    }
    Some(ScreenDimensions { width, height })
}

async fn capture_file_info(path: &Path) -> ApiResult<CaptureFileInfo> {
    let bytes = tokio::fs::read(path).await.map_err(io_api_error)?;
    let metadata = tokio::fs::metadata(path).await.map_err(io_api_error)?;
    Ok(CaptureFileInfo {
        path: path.display().to_string(),
        bytes: metadata.len(),
        modified_at: metadata.modified().ok().and_then(system_time_millis),
        hash: hash_bytes(&bytes),
    })
}

fn hash_bytes(bytes: &[u8]) -> u64 {
    let mut hasher = DefaultHasher::new();
    bytes.hash(&mut hasher);
    hasher.finish()
}

async fn execute_mouse_action(
    scenario: &InteractionScenario,
    x: i32,
    y: i32,
    text: Option<&str>,
) -> Result<(), String> {
    match scenario.action {
        MouseActionKind::LeftClick => send_mouse_action(x, y, MouseButtonAction::LeftClick).await,
        MouseActionKind::RightClick => send_mouse_action(x, y, MouseButtonAction::RightClick).await,
        MouseActionKind::LeftRightChord => {
            send_mouse_action(x, y, MouseButtonAction::LeftRightChord).await
        }
        MouseActionKind::DoubleClick => {
            send_mouse_action(x, y, MouseButtonAction::DoubleClick).await
        }
        MouseActionKind::TextInput => {
            let Some(text) = text.filter(|value| !value.is_empty()) else {
                return Err("文本输入场景需要传 text，避免误输入。".to_string());
            };
            send_mouse_action(x, y, MouseButtonAction::LeftClick).await?;
            send_text_input(text.to_string()).await
        }
        MouseActionKind::Drag => Err("拖拽动作尚未开放真实执行".to_string()),
        MouseActionKind::KeyPress
        | MouseActionKind::Hotkey
        | MouseActionKind::VerticalScroll
        | MouseActionKind::HorizontalScroll => {
            Err("该评测动作尚未在 closed-loop 执行器开放真实执行".to_string())
        }
    }
}

async fn send_mouse_action(x: i32, y: i32, action: MouseButtonAction) -> Result<(), String> {
    run_blocking_input(move || mouse_button_action_point(x, y, action, Duration::from_secs(6)))
        .await
}

async fn send_drag_action(start: PointDto, end: PointDto) -> Result<(), String> {
    run_blocking_input(move || {
        drag_point(
            MousePoint {
                x: start.x,
                y: start.y,
            },
            MousePoint { x: end.x, y: end.y },
            16,
            Duration::from_millis(18),
            Duration::from_secs(8),
        )
    })
    .await
}

async fn send_escape_key() -> Result<(), String> {
    run_blocking_input(move || press_escape(Duration::from_secs(3))).await
}

async fn send_text_input(text: String) -> Result<(), String> {
    run_blocking_input(move || input_type_text(&text, Duration::from_secs(8))).await
}

async fn run_blocking_input<F>(operation: F) -> Result<(), String>
where
    F: FnOnce() -> Result<(), String> + Send + 'static,
{
    // 先排队拿到全局输入闸门，确保任意时刻只有一个 compute-use 动作在真实操作键鼠，
    // 避免多会话并发注入冲突。锁在本次注入完成（spawn_blocking 结束）后自动释放。
    let _guard = compute_use_input_gate().lock().await;
    tokio::task::spawn_blocking(operation)
        .await
        .map_err(|error| format!("input backend task failed: {error}"))?
}

fn closed_loop_notes(execute: bool, action: MouseActionKind) -> Vec<String> {
    let mut notes = vec![
        "执行前截图使用原始分辨率，避免缩略图缩放误差".to_string(),
        "ROI 是围绕锚点的小区域，可作为后续本地 VLM 或模板确认输入。".to_string(),
        "执行后截图会通过文件哈希和大小判断画面是否变化".to_string(),
    ];
    if !execute {
        notes.push("当前 dry-run，未触发真实鼠标或键盘输入。".to_string());
    }
    if action == MouseActionKind::RightClick {
        notes.push("右键场景真实执行后可能留下上下文菜单，后续可增加恢复动作".to_string());
    }
    notes
}

fn safe_click_window(
    screen: ScreenDimensions,
    requested_width: u32,
    requested_height: u32,
) -> SafeClickWindow {
    let width = requested_width.clamp(320, 640);
    let height = requested_height.clamp(220, 420);
    let screen_width = i32::try_from(screen.width).unwrap_or(i32::MAX);
    let screen_height = i32::try_from(screen.height).unwrap_or(i32::MAX);
    let width_i32 = i32::try_from(width).unwrap_or(420);
    let height_i32 = i32::try_from(height).unwrap_or(260);
    let left = ((screen_width - width_i32) / 2).max(0);
    let top = ((screen_height - height_i32) / 2).max(0);
    SafeClickWindow {
        left,
        top,
        width: width_i32,
        height: height_i32,
        click_point: PointDto {
            x: left + width_i32 / 2,
            y: top + height_i32 / 2 + 8,
        },
    }
}

fn safe_click_window_for_layout(
    screen: ScreenDimensions,
    requested_width: u32,
    requested_height: u32,
    layout: &str,
) -> SafeClickWindow {
    if layout.eq_ignore_ascii_case("center") {
        return safe_click_window(screen, requested_width, requested_height);
    }

    let width = requested_width.clamp(320, 640);
    let height = requested_height.clamp(220, 420);
    let screen_width = i32::try_from(screen.width).unwrap_or(i32::MAX);
    let screen_height = i32::try_from(screen.height).unwrap_or(i32::MAX);
    let width_i32 = i32::try_from(width).unwrap_or(420);
    let height_i32 = i32::try_from(height).unwrap_or(260);
    let margin = 16;
    let max_left = screen_width
        .saturating_sub(width_i32)
        .saturating_sub(margin);
    let max_top = screen_height
        .saturating_sub(height_i32)
        .saturating_sub(margin);
    let left = if max_left <= margin {
        0
    } else {
        random_range_i32(margin, max_left)
    };
    let top = if max_top <= margin {
        0
    } else {
        random_range_i32(margin, max_top)
    };

    SafeClickWindow {
        left,
        top,
        width: width_i32,
        height: height_i32,
        click_point: PointDto {
            x: left + width_i32 / 2,
            y: top + height_i32 / 2 + 8,
        },
    }
}

fn random_target_number() -> u16 {
    u16::try_from(random_range_u32(100, 999)).unwrap_or(777)
}

fn random_range_i32(min: i32, max: i32) -> i32 {
    if max <= min {
        return min;
    }
    let span = u32::try_from(max - min + 1).unwrap_or(1);
    min + i32::try_from(random_u32() % span).unwrap_or(0)
}

fn random_range_u32(min: u32, max: u32) -> u32 {
    if max <= min {
        return min;
    }
    min + random_u32() % (max - min + 1)
}

fn random_u32() -> u32 {
    let mut bytes = [0_u8; 4];
    if getrandom::fill(&mut bytes).is_ok() {
        return u32::from_le_bytes(bytes);
    }
    (unix_timestamp_millis() & u64::from(u32::MAX)) as u32
}

