async fn visual_ground_safe_click_point(
    capture_path: &Path,
    screen: ScreenDimensions,
    target_number: u16,
    window: SafeClickWindow,
) -> Result<SafeClickVisionResult, String> {
    let base_url = config_vision_base_url()
        .or_else(|| read_config(|c| c.vision.local_base_url.clone()))
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| default_local_vision_base_url().to_string());
    let model = config_vision_model()
        .or_else(|| read_config(|c| c.vision.local_model.clone()))
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| default_local_vision_model().to_string());
    let api_key = authoritative_local_vision_api_key().unwrap_or_default();
    let backend = LocalOpenAiVisionBackend::new(base_url, model)
        .with_api_key(api_key)
        .with_timeout_seconds(20);
    let target_description = safe_click_target_description(target_number);
    let request = build_showui_grounding_request(
        target_description.clone(),
        VisionImageSource::Path(capture_path.to_path_buf()),
    );
    let response = tokio::task::spawn_blocking(move || backend.analyze(&request))
        .await
        .map_err(|error| format!("视觉 grounding 任务失败: {error}"))?
        .map_err(|error| format!("视觉 grounding 调用失败: {error}"))?;
    let color_region = locate_colored_button_region(
        capture_path,
        VisualColorHint::Gold,
        screen,
        Some(RoiDto {
            left: window.left,
            top: window.top,
            width: window.width,
            height: window.height,
        }),
    )
    .await;
    let relative = match parse_relative_point(&response.text) {
        Some(relative) => relative,
        None => {
            if let Some(region) = color_region {
                return Ok(SafeClickVisionResult {
                    source: "visual-color-region".to_string(),
                    target_description,
                    point: PointDto {
                        x: region.point.x,
                        y: region.point.y,
                    },
                    raw_response: Some(format!(
                        "model_response={}; color_region_fallback=gold, bbox=({},{} {}x{}), pixels={}",
                        response.text,
                        region.bbox.x,
                        region.bbox.y,
                        region.bbox.width,
                        region.bbox.height,
                        region.pixel_count
                    )),
                    error: None,
                });
            }
            return Err(format!("视觉 grounding 未返回相对坐标: {}", response.text));
        }
    };
    let (x, y) = relative_point_to_pixel(relative, (screen.width, screen.height))
        .ok_or_else(|| format!("视觉 grounding 坐标越界: {:?}", relative))?;
    let point = PointDto { x, y };
    if let Some(region) = color_region {
        if !point_in_bbox(point, region.bbox, 12) {
            return Ok(SafeClickVisionResult {
                source: "visual-color-region".to_string(),
                target_description,
                point: PointDto {
                    x: region.point.x,
                    y: region.point.y,
                },
                raw_response: Some(format!(
                    "model_response={}; color_region_fallback=gold, bbox=({},{} {}x{}), pixels={}",
                    response.text,
                    region.bbox.x,
                    region.bbox.y,
                    region.bbox.width,
                    region.bbox.height,
                    region.pixel_count
                )),
                error: None,
            });
        }
    }
    Ok(SafeClickVisionResult {
        source: "visual-grounding".to_string(),
        target_description,
        point,
        raw_response: Some(response.text),
        error: None,
    })
}

fn safe_click_target_description(target_number: u16) -> String {
    format!("the center of the gold button labeled CONFIRM {target_number}")
}

async fn launch_safe_click_window(
    window: &SafeClickWindow,
    target_number: u16,
    marker_path: &Path,
    ready_path: &Path,
) -> ApiResult<()> {
    let marker = escape_powershell_single_quoted(&marker_path.display().to_string());
    let ready = escape_powershell_single_quoted(&ready_path.display().to_string());
    let script = format!(
        r#"
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
$dpiSignature = @'
using System.Runtime.InteropServices;
public static class DpiAwareness {{
    [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
}}
'@
Add-Type $dpiSignature
[DpiAwareness]::SetProcessDPIAware() | Out-Null
$windowSignature = @'
using System;
using System.Runtime.InteropServices;
public static class WindowOps {{
    [DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow();
    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
}}
'@
Add-Type $windowSignature
$console = [WindowOps]::GetConsoleWindow()
if ($console -ne [IntPtr]::Zero) {{
    [WindowOps]::ShowWindow($console, 0) | Out-Null
}}
[System.Windows.Forms.Application]::EnableVisualStyles()
$form = New-Object System.Windows.Forms.Form
$form.Text = 'COOLZHU SAFE INPUT TEST'
$form.StartPosition = 'Manual'
$form.FormBorderStyle = 'None'
$form.TopMost = $true
$form.ShowInTaskbar = $true
$form.WindowState = 'Normal'
$form.BackColor = [System.Drawing.Color]::FromArgb(7, 22, 34)
$form.Size = New-Object System.Drawing.Size({width}, {height})
$form.Location = New-Object System.Drawing.Point({left}, {top})

$label = New-Object System.Windows.Forms.Label
$label.Text = 'COOLZHU SAFE INPUT TEST'
$label.ForeColor = [System.Drawing.Color]::White
$label.Font = New-Object System.Drawing.Font('Consolas', 16, [System.Drawing.FontStyle]::Bold)
$label.AutoSize = $false
$label.TextAlign = 'MiddleCenter'
$label.Location = New-Object System.Drawing.Point(0, 24)
$label.Size = New-Object System.Drawing.Size({width}, 42)
$form.Controls.Add($label)

$button = New-Object System.Windows.Forms.Button
$button.Text = 'CONFIRM {target_number}'
$button.Font = New-Object System.Drawing.Font('Consolas', 18, [System.Drawing.FontStyle]::Bold)
$button.BackColor = [System.Drawing.Color]::Gold
$button.ForeColor = [System.Drawing.Color]::Black
$button.FlatStyle = 'Popup'
$button.Location = New-Object System.Drawing.Point(80, 90)
$button.Size = New-Object System.Drawing.Size(({width} - 160), ({height} - 150))
$button.Add_Click({{
    Set-Content -Path '{marker}' -Value 'hit' -Encoding UTF8
    $form.Close()
}})
$form.Controls.Add($button)

$timer = New-Object System.Windows.Forms.Timer
$timer.Interval = 8000
$timer.Add_Tick({{
    $timer.Stop()
    if (-not (Test-Path '{marker}')) {{
        Set-Content -Path '{marker}' -Value 'timeout' -Encoding UTF8
    }}
    $form.Close()
}})
$timer.Start()
$form.Add_Shown({{
    Set-Content -Path '{ready}' -Value 'hit' -Encoding UTF8
    [WindowOps]::ShowWindow($form.Handle, 9) | Out-Null
    [WindowOps]::SetForegroundWindow($form.Handle) | Out-Null
    $form.WindowState = 'Normal'
    $form.Activate()
    $form.BringToFront()
}})
$restoreCount = 0
$restoreTimer = New-Object System.Windows.Forms.Timer
$restoreTimer.Interval = 250
$restoreTimer.Add_Tick({{
    $script:restoreCount = $script:restoreCount + 1
    $form.WindowState = 'Normal'
    [WindowOps]::ShowWindow($form.Handle, 9) | Out-Null
    [WindowOps]::SetForegroundWindow($form.Handle) | Out-Null
    $form.Activate()
    $form.BringToFront()
    if ($script:restoreCount -ge 8) {{
        $restoreTimer.Stop()
    }}
}})
$restoreTimer.Start()
[System.Windows.Forms.Application]::Run($form)
"#,
        left = window.left,
        top = window.top,
        width = window.width,
        height = window.height,
        target_number = target_number,
    );

    let script_path = marker_path.with_extension("ps1");
    tokio::fs::write(&script_path, script)
        .await
        .map_err(io_api_error)?;

    let mut command = Command::new("powershell.exe");
    command
        .arg("-NoLogo")
        .arg("-NoProfile")
        .arg("-Sta")
        .arg("-ExecutionPolicy")
        .arg("Bypass")
        .arg("-File")
        .arg(&script_path);
    attach_safe_window_logs(&mut command, marker_path)?;
    #[cfg(windows)]
    command.creation_flags(CREATE_NEW_CONSOLE);
    command.spawn().map_err(io_api_error)?;
    Ok(())
}

