fn attach_safe_window_logs(command: &mut Command, marker_path: &Path) -> ApiResult<()> {
    if let Some(parent) = marker_path.parent() {
        std::fs::create_dir_all(parent).map_err(io_api_error)?;
    }
    let stdout =
        std::fs::File::create(marker_path.with_extension("stdout.log")).map_err(io_api_error)?;
    let stderr =
        std::fs::File::create(marker_path.with_extension("stderr.log")).map_err(io_api_error)?;
    command
        .stdout(Stdio::from(stdout))
        .stderr(Stdio::from(stderr));
    Ok(())
}

async fn wait_for_marker(path: &Path, timeout: Duration) -> SafeClickMarker {
    let start = Instant::now();
    while start.elapsed() < timeout {
        if let Ok(value) = tokio::fs::read_to_string(path).await {
            let value = value.trim().trim_start_matches('\u{feff}').to_string();
            return SafeClickMarker {
                path: path.display().to_string(),
                hit: value == "hit",
                value: Some(value),
            };
        }
        tokio::time::sleep(Duration::from_millis(80)).await;
    }
    SafeClickMarker {
        path: path.display().to_string(),
        hit: false,
        value: None,
    }
}

fn parse_point_marker(value: &str) -> Option<PointDto> {
    let value = value.trim().trim_start_matches('\u{feff}');
    let mut parts = value.split(',');
    let x = parts.next()?.trim().parse::<i32>().ok()?;
    let y = parts.next()?.trim().parse::<i32>().ok()?;
    Some(PointDto { x, y })
}

async fn wait_for_point_marker(path: &Path, timeout: Duration) -> Option<PointDto> {
    let start = Instant::now();
    while start.elapsed() < timeout {
        if let Ok(value) = tokio::fs::read_to_string(path).await {
            if let Some(point) = parse_point_marker(&value) {
                return Some(point);
            }
        }
        tokio::time::sleep(Duration::from_millis(40)).await;
    }
    None
}

fn escape_powershell_single_quoted(value: &str) -> String {
    value.replace('\'', "''")
}

