async fn git_output<const N: usize>(args: [&str; N]) -> Option<String> {
    let mut command = Command::new("git");
    command.args(args);
    #[cfg(windows)]
    command.creation_flags(CREATE_NO_WINDOW);

    let output = command.output().await.ok()?;
    if !output.status.success() {
        return None;
    }
    let text = String::from_utf8_lossy(&output.stdout).trim().to_string();
    (!text.is_empty()).then_some(text)
}

fn open_browser(url: &str) {
    #[cfg(windows)]
    {
        let mut command = std::process::Command::new("rundll32.exe");
        command
            .arg("url.dll,FileProtocolHandler")
            .arg(url)
            .creation_flags(CREATE_NO_WINDOW);
        let _ = command.spawn();
    }

    #[cfg(not(windows))]
    {
        let _ = std::process::Command::new("xdg-open").arg(url).spawn();
    }
}

fn launch_desktop_pet(console_url: &str) -> Option<std::process::Child> {
    if desktop_pet_disabled() {
        info!("桌宠启动已通过配置禁用 (pet.enabled=false)");
        return None;
    }

    let Some(exe) = desktop_pet_executable() else {
        warn!("未找到桌宠桌面壳，跳过自动启");
        return None;
    };

    let mut command = std::process::Command::new(&exe);
    let parent_pid = std::process::id();
    command.arg("--pet");
    command.arg(web_console_parent_pid_arg(parent_pid));
    command.env("COOLZHU_GUI_WEB_URL", console_url.trim_end_matches('/'));
    command.env("COOLZHU_WEB_CONSOLE_PID", parent_pid.to_string());
    command
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    #[cfg(windows)]
    command.creation_flags(CREATE_NO_WINDOW);

    match command.spawn() {
        Ok(child) => {
            info!("已尝试拉起桌宠: {}", exe.display());
            Some(child)
        }
        Err(error) => {
            warn!("桌宠启动失败: {error}");
            None
        }
    }
}

fn shutdown_desktop_pet(child: &mut std::process::Child) {
    match child.try_wait() {
        Ok(Some(status)) => {
            info!("Desktop pet already exited with status {status}");
        }
        Ok(None) => {
            let pid = child.id();
            info!("Stopping desktop pet process {pid}");
            if let Err(error) = child.kill() {
                warn!("Failed to kill desktop pet process {pid}: {error}");
            }
            if let Err(error) = child.wait() {
                warn!("Failed to wait for desktop pet process {pid}: {error}");
            }
        }
        Err(error) => {
            warn!("Failed to inspect desktop pet before shutdown: {error}");
        }
    }
}

fn desktop_pet_executable() -> Option<PathBuf> {
    if let Some(cfg_path) = desktop_pet_exe_path() {
        let path = PathBuf::from(&cfg_path);
        if path.exists() {
            return Some(path);
        }
    }
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let current_exe = std::env::current_exe().ok();
    let candidates = desktop_pet_executable_candidates(&manifest_dir, current_exe.as_deref());

    candidates.into_iter().find(|path| path.exists())
}

fn desktop_pet_executable_candidates(
    manifest_dir: &Path,
    current_exe: Option<&Path>,
) -> Vec<PathBuf> {
    let mut candidates = Vec::new();
    if let Some(exe) = current_exe {
        if let Some(bin_dir) = exe.parent() {
            candidates.push(bin_dir.join("coolzhu-tauri-shell.exe"));
        }
    }
    candidates.extend([
        manifest_dir.join("../../../gui-desktop/packages/tauri-shell/src-tauri/target/debug/coolzhu-tauri-shell.exe"),
        manifest_dir.join("../../../gui-desktop/packages/tauri-shell/src-tauri/target/release/coolzhu-tauri-shell.exe"),
        manifest_dir.join("../../../../target/debug/coolzhu-tauri-shell.exe"),
        manifest_dir.join("../../../../target/release/coolzhu-tauri-shell.exe"),
    ]);
    candidates
}

fn plain_response(status: StatusCode, text: &str) -> Response<Body> {
    let mut response = Response::new(Body::from(text.to_string()));
    *response.status_mut() = status;
    response.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("text/plain; charset=utf-8"),
    );
    response
}

fn api_error(status: StatusCode, message: &str) -> ApiError {
    (
        status,
        Json(ErrorResponse {
            error: message.to_string(),
        }),
    )
}

fn io_api_error(error: std::io::Error) -> ApiError {
    api_error(StatusCode::INTERNAL_SERVER_ERROR, &error.to_string())
}

fn sqlite_api_error(error: rusqlite::Error) -> ApiError {
    api_error(StatusCode::INTERNAL_SERVER_ERROR, &error.to_string())
}

fn system_time_millis(time: SystemTime) -> Option<u64> {
    time.duration_since(UNIX_EPOCH)
        .ok()
        .and_then(|duration| u64::try_from(duration.as_millis()).ok())
}

fn unix_timestamp_millis() -> u64 {
    system_time_millis(SystemTime::now()).unwrap_or(0)
}

fn elapsed_millis(start: Instant) -> u64 {
    u64::try_from(start.elapsed().as_millis()).unwrap_or(u64::MAX)
}

fn timed_phase(name: &str, description: &str, start: Instant, status: &str) -> TimedPhase {
    TimedPhase {
        name: name.to_string(),
        description: description.to_string(),
        elapsed_ms: elapsed_millis(start),
        status: status.to_string(),
    }
}

fn session_store() -> &'static TrackedSessionStore {
    static STORE: OnceLock<TrackedSessionStore> = OnceLock::new();
    STORE.get_or_init(|| {
        let started = Instant::now();
        diag!("[SESSION-STORE] init start");
        let store = SessionStore::load();
        diag!(
            "[SESSION-STORE] init done: sessions={}, rooms={}, elapsed_ms={}",
            store.state.sessions.len(),
            store.state.chat_rooms.len(),
            elapsed_millis(started)
        );
        TrackedSessionStore::new(store)
    })
}

fn default_session_store_path() -> PathBuf {
    if let Ok(path) = env::var("COOLZHU_WEB_SESSION_STORE") {
        let trimmed = path.trim();
        if !trimmed.is_empty() {
            return PathBuf::from(trimmed);
        }
    }
    let config = read_config(Clone::clone);
    workspace_scope_paths_for(&active_workspace_path(), &config).legacy_session_json
}

fn default_session_sqlite_path() -> PathBuf {
    #[cfg(test)]
    if let Some(path) = current_session_db_path_override_for_test() {
        return path;
    }
    if let Ok(path) = env::var("COOLZHU_WEB_SESSION_DB") {
        let trimmed = path.trim();
        if !trimmed.is_empty() {
            return PathBuf::from(trimmed);
        }
    }
    let config = read_config(Clone::clone);
    workspace_scope_paths_for(&active_workspace_path(), &config).session_db
}

#[derive(Debug, Clone, Copy)]
struct SessionStoreCapacity {
    max_room_messages: usize,
    max_session_messages: usize,
    max_total_messages: usize,
    max_beads_per_session: usize,
    max_estimated_bytes: usize,
}

impl Default for SessionStoreCapacity {
    fn default() -> Self {
        Self {
            max_room_messages: DEFAULT_SQLITE_MAX_ROOM_MESSAGES,
            max_session_messages: DEFAULT_SQLITE_MAX_SESSION_MESSAGES,
            max_total_messages: DEFAULT_SQLITE_MAX_TOTAL_MESSAGES,
            max_beads_per_session: MAX_MEMORY_BEADS_PER_SESSION,
            max_estimated_bytes: DEFAULT_SQLITE_MAX_ESTIMATED_BYTES,
        }
    }
}

impl SessionStoreCapacity {
    fn normalize(&mut self) {
        self.max_room_messages = self.max_room_messages.clamp(100, 50_000);
        self.max_session_messages = self.max_session_messages.clamp(100, 50_000);
        self.max_total_messages = self
            .max_total_messages
            .max(self.max_room_messages)
            .max(self.max_session_messages)
            .clamp(100, 200_000);
        self.max_beads_per_session = self.max_beads_per_session.clamp(32, 10_000);
        self.max_estimated_bytes = self
            .max_estimated_bytes
            .clamp(16 * 1024 * 1024, 2 * 1024 * 1024 * 1024);
    }
}

#[derive(Debug)]
struct SessionStore {
    path: PathBuf,
    legacy_json_path: PathBuf,
    capacity: SessionStoreCapacity,
    state: PersistedSessionState,
}

#[derive(Debug, Clone)]
struct SessionStoreLockHolder {
    file: &'static str,
    line: u32,
    acquired_at: Instant,
}

struct TrackedSessionStore {
    inner: Mutex<SessionStore>,
    holder: Mutex<Option<SessionStoreLockHolder>>,
}

struct TrackedSessionStoreGuard<'a> {
    guard: MutexGuard<'a, SessionStore>,
    holder: &'a Mutex<Option<SessionStoreLockHolder>>,
    file: &'static str,
    line: u32,
}

impl TrackedSessionStore {
    fn new(store: SessionStore) -> Self {
        Self {
            inner: Mutex::new(store),
            holder: Mutex::new(None),
        }
    }

    #[track_caller]
    fn lock(&self) -> Result<TrackedSessionStoreGuard<'_>, ()> {
        let caller = Location::caller();
        match self.inner.try_lock() {
            Ok(guard) => Ok(self.wrap_guard(guard, caller)),
            Err(TryLockError::Poisoned(_)) => Err(()),
            Err(TryLockError::WouldBlock) => {
                log_session_lock_wait(caller, self.current_holder());
                let started = Instant::now();
                let guard = self.inner.lock().map_err(|_| ())?;
                log_session_lock_acquired_after_wait(caller, elapsed_millis(started));
                Ok(self.wrap_guard(guard, caller))
            }
        }
    }

    fn wrap_guard<'a>(
        &'a self,
        guard: MutexGuard<'a, SessionStore>,
        caller: &'static Location<'static>,
    ) -> TrackedSessionStoreGuard<'a> {
        if let Ok(mut holder) = self.holder.lock() {
            *holder = Some(SessionStoreLockHolder {
                file: caller.file(),
                line: caller.line(),
                acquired_at: Instant::now(),
            });
        }
        TrackedSessionStoreGuard {
            guard,
            holder: &self.holder,
            file: caller.file(),
            line: caller.line(),
        }
    }

    fn current_holder(&self) -> Option<SessionStoreLockHolder> {
        self.holder.lock().ok().and_then(|holder| holder.clone())
    }
}

impl Deref for TrackedSessionStoreGuard<'_> {
    type Target = SessionStore;

    fn deref(&self) -> &Self::Target {
        &self.guard
    }
}

impl DerefMut for TrackedSessionStoreGuard<'_> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.guard
    }
}

impl Drop for TrackedSessionStoreGuard<'_> {
    fn drop(&mut self) {
        if let Ok(mut holder) = self.holder.lock() {
            if holder
                .as_ref()
                .is_some_and(|current| current.file == self.file && current.line == self.line)
            {
                *holder = None;
            }
        }
    }
}

fn session_lock_log_path() -> PathBuf {
    env::temp_dir().join("coolzhu-session-lock.log")
}

fn log_session_lock_line(line: &str) {
    if let Ok(mut file) = std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(session_lock_log_path())
    {
        let _ = std::io::Write::write_all(&mut file, format!("{line}\n").as_bytes());
    }
}

fn log_session_lock_wait(
    caller: &'static Location<'static>,
    holder: Option<SessionStoreLockHolder>,
) {
    let holder_text = holder
        .map(|holder| {
            format!(
                "{}:{} held_ms={}",
                holder.file,
                holder.line,
                elapsed_millis(holder.acquired_at)
            )
        })
        .unwrap_or_else(|| "unknown".to_string());
    log_session_lock_line(&format!(
        "[SESSION-LOCK] wait at {}:{}; held_by={holder_text}",
        caller.file(),
        caller.line()
    ));
}

fn log_session_lock_acquired_after_wait(caller: &'static Location<'static>, elapsed_ms: u64) {
    log_session_lock_line(&format!(
        "[SESSION-LOCK] acquired at {}:{} after_wait_ms={elapsed_ms}",
        caller.file(),
        caller.line()
    ));
}

impl SessionStore {
    fn load() -> Self {
        let path = default_session_sqlite_path();
        let legacy_json_path = default_session_store_path();
        let capacity = config_session_capacity();
        Self::load_from_paths(path, legacy_json_path, capacity)
    }

    fn load_for_workspace(workspace: &Path, config: &WorkspaceConfig) -> Self {
        let paths = workspace_scope_paths_for(workspace, config);
        Self::load_from_paths(
            paths.session_db,
            paths.legacy_session_json,
            session_capacity_from_config(config),
        )
    }

    fn load_from_paths(
        path: PathBuf,
        legacy_json_path: PathBuf,
        capacity: SessionStoreCapacity,
    ) -> Self {
        let started = Instant::now();
        diag!(
            "[SESSION-STORE] load_from_paths start: sqlite={}, json={}",
            path.display(),
            legacy_json_path.display()
        );
        let load_started = Instant::now();
        let state = load_session_state_from_sqlite(&path)
            .or_else(|| load_session_state_from_json(&legacy_json_path))
            .unwrap_or_default();
        diag!(
            "[SESSION-STORE] state loaded: sessions={}, rooms={}, elapsed_ms={}, total_ms={}",
            state.sessions.len(),
            state.chat_rooms.len(),
            elapsed_millis(load_started),
            elapsed_millis(started)
        );
        let mut store = Self {
            path,
            legacy_json_path,
            capacity,
            state,
        };
        if store.state.sessions.is_empty() {
            store.state.sessions.push(seed_session());
            store.state.active_session_id = store
                .state
                .sessions
                .first()
                .map(|session| session.id.clone());
        }
        let room_started = Instant::now();
        store.ensure_chat_room();
        let _ = store.ensure_scheduled_task_system_room();
        diag!(
            "[SESSION-STORE] ensure_chat_room done: rooms={}, elapsed_ms={}, total_ms={}",
            store.state.chat_rooms.len(),
            elapsed_millis(room_started),
            elapsed_millis(started)
        );
        let migrate_started = Instant::now();
        store.migrate_session_messages_into_default_chat_room();
        diag!(
            "[SESSION-STORE] migrate messages done: sessions={}, room_messages={}, elapsed_ms={}, total_ms={}",
            store.state.sessions.len(),
            store
                .state
                .chat_rooms
                .iter()
                .map(|room| room.messages.len())
                .sum::<usize>(),
            elapsed_millis(migrate_started),
            elapsed_millis(started)
        );
        let scrub_started = Instant::now();
        let removed_goal_memory = store.scrub_temporary_goal_memories_from_state();
        if removed_goal_memory > 0 {
            diag!("[MEMORY] scrubbed {removed_goal_memory} stale temporary Goal memory beads");
        }
        let removed_goal_chat = store.scrub_goal_scratch_chat_messages_from_state(None);
        if removed_goal_chat > 0 {
            diag!("[MEMORY] scrubbed {removed_goal_chat} stale temporary Goal chat messages");
        }
        diag!(
            "[SESSION-STORE] scrub goal memory done: removed={}, chat_removed={}, elapsed_ms={}, total_ms={}",
            removed_goal_memory,
            removed_goal_chat,
            elapsed_millis(scrub_started),
            elapsed_millis(started)
        );
        let save_started = Instant::now();
        store.save().ok();
        diag!(
            "[SESSION-STORE] initial save done: elapsed_ms={}, total_ms={}",
            elapsed_millis(save_started),
            elapsed_millis(started)
        );
        store
    }

    fn save(&mut self) -> ApiResult<()> {
        let started = Instant::now();
        self.enforce_capacity();
        diag!(
            "[SESSION-STORE] save enforce_capacity done: sessions={}, rooms={}, elapsed_ms={}",
            self.state.sessions.len(),
            self.state.chat_rooms.len(),
            elapsed_millis(started)
        );
        save_session_state_to_sqlite(&self.path, &self.state, self.capacity)?;
        diag!(
            "[SESSION-STORE] save sqlite done: elapsed_ms={}",
            elapsed_millis(started)
        );
        self.save_legacy_json()
    }

    fn save_legacy_json(&self) -> ApiResult<()> {
        if let Some(parent) = self.path.parent() {
            std::fs::create_dir_all(parent).map_err(io_api_error)?;
        }
        if let Some(parent) = self.legacy_json_path.parent() {
            std::fs::create_dir_all(parent).map_err(io_api_error)?;
        }
        let content = serde_json::to_string_pretty(&self.state)
            .map_err(|error| api_error(StatusCode::INTERNAL_SERVER_ERROR, &error.to_string()))?;
        std::fs::write(&self.legacy_json_path, content).map_err(io_api_error)?;
        Ok(())
    }

    fn enforce_capacity(&mut self) {
        self.ensure_chat_room();
        for session in &mut self.state.sessions {
            prune_messages_by_created_at(&mut session.messages, self.capacity.max_session_messages);
            session.prune_memory_beads_to(self.capacity.max_beads_per_session);
        }
        for room in &mut self.state.chat_rooms {
            prune_messages_by_created_at(&mut room.messages, self.capacity.max_room_messages);
        }
        enforce_total_message_capacity(&mut self.state, self.capacity.max_total_messages);
        enforce_estimated_byte_capacity(&mut self.state, self.capacity.max_estimated_bytes);
    }

    fn scrub_temporary_goal_memories_from_state(&mut self) -> usize {
        let terminal_goal_sources = terminal_goal_memory_sources_from_sqlite(&self.path);
        let mut removed = 0usize;
        for session in &mut self.state.sessions {
            let before = session.memory_beads.len();
            session.memory_beads.retain(|bead| {
                !is_goal_temporary_memory_bead(bead)
                    && !((bead.kind == "goal-task-skill" || bead.source.starts_with("goal-task:"))
                        && terminal_goal_sources.contains(&bead.source))
            });
            removed += before.saturating_sub(session.memory_beads.len());
        }
        removed
    }

    fn scrub_goal_scratch_chat_messages_from_state(&mut self, room_id: Option<&str>) -> usize {
        let mut removed = 0usize;
        for room in &mut self.state.chat_rooms {
            if room_id.is_some_and(|id| id != room.id) {
                continue;
            }
            let before = room.messages.len();
            room.messages
                .retain(|message| !is_goal_temporary_persisted_message(message));
            removed += before.saturating_sub(room.messages.len());
            if before != room.messages.len() {
                room.updated_at = unix_timestamp_millis();
            }
        }
        for session in &mut self.state.sessions {
            let before = session.messages.len();
            session
                .messages
                .retain(|message| !is_goal_temporary_persisted_message(message));
            removed += before.saturating_sub(session.messages.len());
            if before != session.messages.len() {
                session.updated_at = unix_timestamp_millis();
            }
        }
        removed
    }

    fn apply_context_lifecycle_after_turn(
        &mut self,
        session_id: &str,
        room_id: &str,
        snapshot: &ContextUsageSnapshot,
        policy: ContextLifecyclePolicy,
    ) -> ApiResult<ContextLifecycleResult> {
        if !snapshot.auto_compact_reached {
            return Ok(ContextLifecycleResult::default());
        }
        let room_messages = self
            .state
            .chat_rooms
            .iter()
            .find(|room| room.id == room_id)
            .map(|room| room.messages.clone())
            .unwrap_or_default();
        let summary = context_compaction_memory_summary(&room_messages, policy);
        let now = unix_timestamp_millis();
        let removed_goal_memory_beads = self.scrub_temporary_goal_memories_from_state();
        let removed_goal_chat_messages = if policy.cleanup_goal_scratch_on_compact {
            self.scrub_goal_scratch_chat_messages_from_state(Some(room_id))
        } else {
            0
        };
        let Some(session) = self
            .state
            .sessions
            .iter_mut()
            .find(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };
        session.context_reset_at = now;
        session.updated_at = now;
        let mut added_memory_beads = 0usize;
        if let Some(summary) = summary {
            let signature =
                memory_bead_signature("L2", "conversation", "context:auto-compact", &summary);
            if !session
                .memory_beads
                .iter()
                .any(|bead| bead.signature() == signature)
            {
                session.memory_beads.push(MemoryBeadDto {
                    id: format!("ctx-compact-{now}-{:016x}", hash_bytes(summary.as_bytes())),
                    kind: "conversation".to_string(),
                    layer: "L2".to_string(),
                    summary: summary.clone(),
                    source: "context:auto-compact".to_string(),
                    pinned: false,
                    confidence: 0.82,
                    created_at: now,
                    origin_message_id: None,
                    origin_table: Some("chat_room_messages".to_string()),
                    token_count: Some(estimate_bead_tokens(&summary)),
                });
                added_memory_beads = 1;
            }
        }
        self.save()?;
        diag!(
            "[CONTEXT-LIFECYCLE] auto_compact session={} room={} usage={}.{}% added_memory={} removed_goal_memory={} removed_goal_chat={}",
            session_id,
            room_id,
            snapshot.percent_tenths / 10,
            snapshot.percent_tenths % 10,
            added_memory_beads,
            removed_goal_memory_beads,
            removed_goal_chat_messages
        );
        Ok(ContextLifecycleResult {
            compacted: true,
            added_memory_beads,
            removed_goal_memory_beads,
            removed_goal_chat_messages,
        })
    }

    fn session_list_response(&self) -> SessionListResponse {
        SessionListResponse {
            sessions: self
                .state
                .sessions
                .iter()
                .map(|session| session.summary(self.is_active(&session.id)))
                .collect(),
            active_session_id: self.active_session_id(),
            max_sessions: MAX_USER_SESSIONS,
        }
    }

    fn ensure_chat_room(&mut self) {
        if self.state.chat_rooms.is_empty() {
            self.state.chat_rooms.push(seed_chat_room());
        }
        let active_room_id = self
            .state
            .active_chat_room_id
            .clone()
            .filter(|id| self.state.chat_rooms.iter().any(|room| room.id == *id))
            .or_else(|| self.state.chat_rooms.first().map(|room| room.id.clone()));
        self.state.active_chat_room_id = active_room_id;
    }

    fn migrate_session_messages_into_default_chat_room(&mut self) {
        let Some(room_index) = self
            .state
            .chat_rooms
            .iter_mut()
            .position(|room| room.id == DEFAULT_CHAT_ROOM_ID)
            .or_else(|| (!self.state.chat_rooms.is_empty()).then_some(0))
        else {
            return;
        };
        let room = &mut self.state.chat_rooms[room_index];

        let mut known_ids = room
            .messages
            .iter()
            .map(|message| message.id.clone())
            .collect::<HashSet<_>>();
        let mut known_signatures = room
            .messages
            .iter()
            .map(message_signature)
            .collect::<HashSet<_>>();

        for message in self
            .state
            .sessions
            .iter()
            .flat_map(|session| session.messages.iter())
        {
            let signature = message_signature(message);
            if known_ids.insert(message.id.clone()) && known_signatures.insert(signature) {
                room.messages.push(message.clone());
            }
        }

        room.messages.sort_by_key(|message| message.created_at);
        room.updated_at = room
            .messages
            .last()
            .map(|message| message.created_at)
            .unwrap_or(room.updated_at);
    }

    fn chat_room_list_response(&self) -> ChatRoomListResponse {
        ChatRoomListResponse {
            rooms: self
                .state
                .chat_rooms
                .iter()
                .map(|room| room.summary(self.is_active_chat_room(&room.id)))
                .collect(),
            active_room_id: self.active_chat_room_id(),
            max_rooms: 8,
        }
    }

    fn list_chat_handoffs(
        &self,
        room_id: &str,
        query: HandoffQuery,
    ) -> ApiResult<Json<ChatHandoffListResponse>> {
        if !self.state.chat_rooms.iter().any(|room| room.id == room_id) {
            return Err(api_error(StatusCode::NOT_FOUND, "聊天室不存在"));
        }
        let limit = query.limit.unwrap_or(50).clamp(1, 200);
        let handoffs = query_chat_handoffs_sqlite(&self.path, room_id, limit, query.since)
            .map_err(sqlite_api_error)?;
        Ok(Json(ChatHandoffListResponse {
            room_id: room_id.to_string(),
            handoffs,
        }))
    }

    fn create_manual_handoff(
        &mut self,
        room_id: &str,
        payload: ManualHandoffRequest,
    ) -> ApiResult<Json<ManualHandoffResponse>> {
        let room_index = self
            .state
            .chat_rooms
            .iter()
            .position(|room| room.id == room_id)
            .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "聊天室不存在"))?;
        let from_agent = self
            .state
            .sessions
            .iter()
            .find(|session| session.id == payload.from_agent_id)
            .cloned()
            .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "发起 Agent 不存"))?;
        let roster = chat_room_roster_from_state(&self.state, room_id, None)?;
        let target = resolve_handoff_target(&payload.to, &roster)
            .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "目标 Agent 不存在或不可"))?;
        let intent = payload.intent.trim();
        if intent.is_empty() {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "handoff intent 不能为空",
            ));
        }
        let now = unix_timestamp_millis();
        self.save()?;
        let existing = query_chat_handoffs_sqlite(&self.path, room_id, 10_000, None)
            .map_err(sqlite_api_error)?;
        let originating_user_msg_id = payload
            .originating_user_msg_id
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| {
                latest_room_user_message_id(&self.state.chat_rooms[room_index])
                    .unwrap_or_else(|| format!("manual-{now}"))
            });
        let depth = payload.depth.unwrap_or(0);
        let gate = validate_handoff_gate(
            room_id,
            &from_agent.id,
            &target.session_id,
            intent,
            &originating_user_msg_id,
            depth,
            now,
            &existing,
            HandoffGateOptions::default(),
        );
        let attach = normalize_handoff_attach(payload.attach.as_deref());
        let attach_message_ids = payload.attach_message_ids.unwrap_or_default();
        let rejected_reason = gate.rejected_reason().map(str::to_string);
        let status = if rejected_reason.is_some() {
            "rejected"
        } else {
            "delivered"
        };
        let mut record = ChatHandoffRecord {
            id: format!("handoff-{now}-{}", handoff_intent_hash(intent)),
            chat_room_id: room_id.to_string(),
            from_agent_id: from_agent.id.clone(),
            to_agent_id: target.session_id.clone(),
            intent: intent.to_string(),
            intent_hash: handoff_intent_hash(intent),
            attach: attach.clone(),
            attach_message_ids: attach_message_ids.clone(),
            originating_user_msg_id,
            depth,
            status: status.to_string(),
            rejected_reason,
            // GL-10：结构化契约由调用方（goal 回退派发）通过 payload 传入；普通手工交接为 None。
            contract: payload.contract.clone(),
            created_at: now,
            delivered_at: None,
            completed_at: None,
        };

        let inbound_message = if status == "delivered" {
            record.delivered_at = Some(now);
            let attach_text = render_handoff_attachment(
                &self.state.chat_rooms[room_index],
                &attach,
                &attach_message_ids,
            );
            let message = PersistedChatMessage {
                id: format!("msg-{now}-handoff"),
                author: format!("@{} via handoff", from_agent.name),
                role: "user".to_string(),
                target: target.display_name.clone(),
                content: render_handoff_inbound_content(&from_agent.name, intent, &attach_text),
                kind: "handoff-inbound".to_string(),
                attachments: Vec::new(),
                created_at: now,
            };
            self.state.chat_rooms[room_index]
                .messages
                .push(message.clone());
            self.state.chat_rooms[room_index].updated_at = now;
            self.save()?;
            Some(message)
        } else {
            None
        };
        insert_chat_handoff_sqlite(&self.path, &record)?;
        Ok(Json(ManualHandoffResponse {
            handoff: record,
            inbound_message,
        }))
    }

    /// GL-13：把 review 判为 `awaiting_human_ack` 且尚未标记过的阶段置成 `awaiting`，
    /// 发等待确认事件并暂停 goal。
    ///
    /// 只在 `human_ack IS NULL` 时写入（条件 UPDATE + rows_affected 判定），所以反复调用
    /// dispatch 不会重复刷事件——幂等靠数据库而不是内存标志。
    fn mark_goal_phases_awaiting_ack(
        &self,
        workspace_id: &str,
        goal_id: &str,
        review: &GoalCommanderReviewResponse,
    ) -> ApiResult<()> {
        let awaiting: Vec<&GoalCommanderPhaseReview> = review
            .phase_reviews
            .iter()
            .filter(|phase| phase.action == "awaiting_human_ack")
            .collect();
        if awaiting.is_empty() {
            return Ok(());
        }
        let mut connection = open_session_connection(&self.path).map_err(sqlite_api_error)?;
        initialize_session_schema(&connection).map_err(sqlite_api_error)?;
        let mut pending_events = Vec::new();
        {
            let tx = connection
                .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
                .map_err(sqlite_api_error)?;
            for phase in &awaiting {
                // codex 场景实测 #3：review 是在事务外算的，中间可能有并发 replan 把同 ID 的
                // phase 改成不需要确认/已在跑。所以事务内用条件 UPDATE 重新校验前提，
                // 而不只看 human_ack IS NULL——否则会给一个新 phase 错误地挂上等待并暂停 goal。
                let changed = tx
                    .execute(
                        "UPDATE goal_phases SET human_ack = 'awaiting', updated_at = ?1 \
                         WHERE goal_id = ?2 AND id = ?3 AND human_ack IS NULL \
                           AND requires_human_ack = 1 AND status = 'pending'",
                        params![
                            u64_to_i64(unix_timestamp_millis()),
                            goal_id,
                            &phase.phase_id
                        ],
                    )
                    .map_err(sqlite_api_error)?;
                if changed == 0 {
                    // 已经是 awaiting/approved/rejected，或前提已变 —— 不重复发事件。
                    continue;
                }
                pending_events.push(
                    insert_goal_event_connection_deferred(
                        &tx,
                        goal_id,
                        "goal-phase-awaiting-ack",
                        &format!(
                            "Phase {} requires human acknowledgement before dispatch.",
                            phase.phase_id
                        ),
                        json!({
                            "caller": "goal-loop",
                            "phase_id": phase.phase_id,
                            "title": phase.title,
                            "assigned_role": phase.assigned_role,
                        }),
                    )
                    .map_err(sqlite_api_error)?,
                );
            }
            if !pending_events.is_empty() {
                // 有新进入等待的阶段才暂停 goal，等人工处理。
                tx.execute(
                    r#"
                    UPDATE goals SET status = 'paused', updated_at = ?1
                    WHERE workspace_id = ?2 AND id = ?3
                      AND status NOT IN ('completed', 'cancelled', 'paused')
                    "#,
                    params![u64_to_i64(unix_timestamp_millis()), workspace_id, goal_id],
                )
                .map_err(sqlite_api_error)?;
            }
            tx.commit().map_err(sqlite_api_error)?;
        }
        for event in pending_events {
            broadcast_goal_event(event);
        }
        Ok(())
    }

    fn dispatch_ready_goal_phases(
        &mut self,
        workspace_id: &str,
        goal_id: &str,
    ) -> ApiResult<GoalDispatchReadyResponse> {
        self.save()?;
        let review =
            review_goal_commander_sqlite(&self.path, workspace_id, goal_id, &self.state.sessions)?;
        let generated_at = unix_timestamp_millis();
        let mut dispatched = Vec::new();
        let mut skipped = Vec::new();

        if review.pause_recommended {
            // GL-13：命中 human-in-the-loop 断点——首次遇到 awaiting_human_ack 阶段时，
            // 记 human_ack='awaiting'（幂等标志）、发 goal-phase-awaiting-ack 事件、暂停 goal，
            // 等人工经 /ack 接口批准或拒绝。仅在 human_ack IS NULL 时触发，避免重复刷事件。
            self.mark_goal_phases_awaiting_ack(workspace_id, goal_id, &review)?;
            skipped.extend(
                review
                    .phase_reviews
                    .iter()
                    .map(|phase| GoalPhaseDispatchDto {
                        phase_id: phase.phase_id.clone(),
                        title: phase.title.clone(),
                        assigned_role: phase.assigned_role.clone(),
                        assigned_session_id: phase.assigned_session_id.clone(),
                        action: phase.action.clone(),
                        reason: phase.reason.clone(),
                        handoff_id: None,
                    }),
            );
            return Ok(GoalDispatchReadyResponse {
                goal_id: goal_id.to_string(),
                pause_recommended: true,
                blocking_reasons: review.blocking_reasons.clone(),
                dispatched,
                skipped,
                review,
                generated_at,
            });
        }

        let commander_session_id = review.commander_session_id.clone().ok_or_else(|| {
            api_error(
                StatusCode::BAD_REQUEST,
                "Goal commander session is required before dispatch.",
            )
        })?;
        let goal = get_goal_sqlite(&self.path, workspace_id, goal_id)?;
        let room_id = goal.chat_room_id.clone();
        let originating_user_msg_id = goal
            .originating_user_msg_id
            .clone()
            .unwrap_or_else(|| format!("goal-{}", goal.id));
        let phases = goal
            .phases
            .iter()
            .map(|phase| (phase.id.clone(), phase.clone()))
            .collect::<BTreeMap<_, _>>();

        for phase_review in &review.phase_reviews {
            if phase_review.action != "ready_to_dispatch" {
                skipped.push(GoalPhaseDispatchDto {
                    phase_id: phase_review.phase_id.clone(),
                    title: phase_review.title.clone(),
                    assigned_role: phase_review.assigned_role.clone(),
                    assigned_session_id: phase_review.assigned_session_id.clone(),
                    action: phase_review.action.clone(),
                    reason: phase_review.reason.clone(),
                    handoff_id: None,
                });
                continue;
            }
            let Some(target_session_id) = phase_review.assigned_session_id.clone() else {
                skipped.push(GoalPhaseDispatchDto {
                    phase_id: phase_review.phase_id.clone(),
                    title: phase_review.title.clone(),
                    assigned_role: phase_review.assigned_role.clone(),
                    assigned_session_id: None,
                    action: "dispatch_skipped".to_string(),
                    reason: "Ready phase has no assigned session.".to_string(),
                    handoff_id: None,
                });
                continue;
            };
            let Some(phase) = phases.get(&phase_review.phase_id) else {
                skipped.push(GoalPhaseDispatchDto {
                    phase_id: phase_review.phase_id.clone(),
                    title: phase_review.title.clone(),
                    assigned_role: phase_review.assigned_role.clone(),
                    assigned_session_id: phase_review.assigned_session_id.clone(),
                    action: "dispatch_skipped".to_string(),
                    reason: "Phase no longer exists.".to_string(),
                    handoff_id: None,
                });
                continue;
            };

            let required_skills = if phase.skills_required.is_empty() {
                "none".to_string()
            } else {
                phase.skills_required.join(", ")
            };
            let output_artifacts = if phase.output_artifacts.is_empty() {
                "none".to_string()
            } else {
                phase.output_artifacts.join(", ")
            };
            let verification = phase
                .verification
                .as_ref()
                .map(JsonValue::to_string)
                .unwrap_or_else(|| "none".to_string());
            let retry_context = goal_phase_retry_intent_context(phase);
            let intent = format!(
                "Goal: {}\nPhase: {} ({})\nAssigned role: {}\nRequired skills: {}\nOutput artifacts: {}\nVerification: {}{}\nTask-scoped skill overlay: install/use the required skills for this phase only; remove task-scoped role skills and temporary task memory after reporting completion.\nCommander request: execute this phase and report completion evidence for review.",
                goal.title,
                phase.title,
                phase.id,
                phase.assigned_role,
                required_skills,
                output_artifacts,
                verification,
                retry_context
            );
            if target_session_id == commander_session_id {
                self.install_goal_task_skill_overlay(
                    &target_session_id,
                    &goal,
                    phase,
                    &required_skills,
                    &output_artifacts,
                    &verification,
                )?;
                let connection = open_session_connection(&self.path).map_err(sqlite_api_error)?;
                initialize_session_schema(&connection).map_err(sqlite_api_error)?;
                update_goal_phase_status_connection(
                    &connection,
                    workspace_id,
                    goal_id,
                    &phase.id,
                    "running",
                )
                .map_err(sqlite_api_error)?;
                insert_goal_event_connection(
                    &connection,
                    goal_id,
                    "goal-phase-dispatched",
                    &format!(
                        "Phase {} self-dispatched to {}.",
                        phase.id, target_session_id
                    ),
                    json!({
                        "caller": "goal-loop",
                        "phase_id": phase.id.clone(),
                        "assigned_role": phase.assigned_role.clone(),
                        "assigned_session_id": target_session_id.clone(),
                        "handoff_id": JsonValue::Null,
                        "dispatch_mode": "self-role",
                        "chat_room_id": room_id.clone(),
                        "originating_user_msg_id": originating_user_msg_id.clone(),
                        "commander_session_id": commander_session_id.clone(),
                        // GL-14（codex #4）：self-dispatch 分支同样要带前进决策的因果链，
                        // 否则这条路径派发出去的阶段在事件流里查不到「为什么现在轮到它」。
                        "route_reason": if phase.retry_count > 0 { "retry" } else { "advance" },
                        "retry_count": phase.retry_count,
                        "depends_on": phase.depends_on.clone(),
                    }),
                )
                .map_err(sqlite_api_error)?;
                // GL-07（codex #5 + 二轮 #3）：self-dispatch 不走 handoff，intent 原本被直接丢弃——
                // 被打回的 self-role 阶段拿不到失败原因/证据。必须写进**聊天室**：自动执行的
                // context_history 取自聊天室消息，写 session messages 不会进下一次模型请求。
                if !retry_context.is_empty() {
                    let retry_message = ChatMessageDto {
                        id: format!(
                            "msg-goal-{}-{}-self-retry",
                            unix_timestamp_millis(),
                            phase.id
                        ),
                        author: "Goal commander".to_string(),
                        role: "assistant".to_string(),
                        target: "Goal phase".to_string(),
                        content: intent.clone(),
                        kind: "task-summary".to_string(),
                        attachments: Vec::new(),
                    };
                    self.append_chat_room_messages(&room_id, vec![retry_message.clone()])?;
                    self.append_chat_messages(&target_session_id, vec![retry_message])?;
                }
                dispatched.push(GoalPhaseDispatchDto {
                    phase_id: phase_review.phase_id.clone(),
                    title: phase_review.title.clone(),
                    assigned_role: phase_review.assigned_role.clone(),
                    assigned_session_id: phase_review.assigned_session_id.clone(),
                    action: "self_dispatched".to_string(),
                    reason:
                        "Same session holds commander and phase role; phase marked running without chat handoff."
                            .to_string(),
                    handoff_id: None,
                });
                continue;
            }
            // GL-10：被打回重跑的 phase（retry_count>0）产出结构化交接契约，
            // 让交接记录本身携带 from/to/verdict/reason/evidence/retry，而非只塞进 intent 文本。
            let contract = (phase.retry_count > 0).then(|| {
                // codex #3：evidence 存**有界摘要**而非整份 JSON——完整证据已在
                // goal_phases.last_evidence_json，每次重试复制全文会撑爆 handoff 列表/save/响应。
                // 需要全文时按 goal_id+phase_id 回查。
                let evidence_digest = phase
                    .last_evidence
                    .as_ref()
                    .map(goal_phase_evidence_digest);
                json!({
                    "kind": "goal-phase-retry",
                    "goal_id": goal.id,
                    "phase_id": phase.id,
                    "from_role": "commander",
                    "to_role": phase.assigned_role,
                    "verdict": phase.last_verdict.clone().unwrap_or_else(|| "fail".to_string()),
                    "reason": phase.last_reason,
                    "evidence_digest": evidence_digest,
                    "retry_count": phase.retry_count,
                    "max_retries": phase.max_retries,
                })
            });
            let response = self
                .create_manual_handoff(
                    &room_id,
                    ManualHandoffRequest {
                        from_agent_id: commander_session_id.clone(),
                        to: target_session_id.clone(),
                        intent,
                        attach: Some("none".to_string()),
                        attach_message_ids: Some(Vec::new()),
                        originating_user_msg_id: Some(originating_user_msg_id.clone()),
                        depth: Some(0),
                        contract,
                    },
                )?
                .0;
            if response.handoff.status == "delivered" {
                self.install_goal_task_skill_overlay(
                    &target_session_id,
                    &goal,
                    phase,
                    &required_skills,
                    &output_artifacts,
                    &verification,
                )?;
                let connection = open_session_connection(&self.path).map_err(sqlite_api_error)?;
                initialize_session_schema(&connection).map_err(sqlite_api_error)?;
                update_goal_phase_status_connection(
                    &connection,
                    workspace_id,
                    goal_id,
                    &phase.id,
                    "running",
                )
                .map_err(sqlite_api_error)?;
                insert_goal_event_connection(
                    &connection,
                    goal_id,
                    "goal-phase-dispatched",
                    &format!("Phase {} dispatched to {}.", phase.id, target_session_id),
                    json!({
                        "caller": "goal-loop",
                        "phase_id": phase.id.clone(),
                        "assigned_role": phase.assigned_role.clone(),
                        "assigned_session_id": target_session_id.clone(),
                        "handoff_id": response.handoff.id.clone(),
                        "chat_room_id": room_id.clone(),
                        "originating_user_msg_id": originating_user_msg_id.clone(),
                        "commander_session_id": commander_session_id.clone(),
                        // GL-14：前进决策的因果链——是首次派发还是被打回后重跑、
                        // 依赖了谁。让事件流能回看"为什么现在轮到这个阶段"。
                        "route_reason": if phase.retry_count > 0 { "retry" } else { "advance" },
                        "retry_count": phase.retry_count,
                        "depends_on": phase.depends_on.clone(),
                    }),
                )
                .map_err(sqlite_api_error)?;
                dispatched.push(GoalPhaseDispatchDto {
                    phase_id: phase_review.phase_id.clone(),
                    title: phase_review.title.clone(),
                    assigned_role: phase_review.assigned_role.clone(),
                    assigned_session_id: phase_review.assigned_session_id.clone(),
                    action: "dispatched".to_string(),
                    reason: "Handoff delivered and phase marked running.".to_string(),
                    handoff_id: Some(response.handoff.id),
                });
            } else {
                skipped.push(GoalPhaseDispatchDto {
                    phase_id: phase_review.phase_id.clone(),
                    title: phase_review.title.clone(),
                    assigned_role: phase_review.assigned_role.clone(),
                    assigned_session_id: phase_review.assigned_session_id.clone(),
                    action: "handoff_rejected".to_string(),
                    reason: response
                        .handoff
                        .rejected_reason
                        .unwrap_or_else(|| "handoff rejected".to_string()),
                    handoff_id: Some(response.handoff.id),
                });
            }
        }

        Ok(GoalDispatchReadyResponse {
            goal_id: goal_id.to_string(),
            pause_recommended: false,
            blocking_reasons: review.blocking_reasons.clone(),
            dispatched,
            skipped,
            review,
            generated_at,
        })
    }

    fn install_goal_task_skill_overlay(
        &mut self,
        target_session_id: &str,
        goal: &GoalDto,
        phase: &GoalPhaseDto,
        required_skills: &str,
        output_artifacts: &str,
        verification: &str,
    ) -> ApiResult<()> {
        let Some(session) = self
            .state
            .sessions
            .iter_mut()
            .find(|session| session.id == target_session_id)
        else {
            return Err(api_error(
                StatusCode::NOT_FOUND,
                "Goal phase target session is missing.",
            ));
        };
        let source = goal_task_skill_memory_source(&goal.id);
        let id = goal_task_skill_memory_id(&goal.id, &phase.id);
        let summary = format!(
            "Task-scoped goal role skill overlay. Goal: {}; Phase: {} ({}); Assigned role: {}; Required skills: {}; Output artifacts: {}; Verification: {}; Cleanup: remove this bead when the goal task completes.",
            goal.title,
            phase.title,
            phase.id,
            phase.assigned_role,
            required_skills,
            output_artifacts,
            verification
        )
        .chars()
        .take(240)
        .collect::<String>();
        session
            .memory_beads
            .retain(|bead| !(bead.kind == "goal-task-skill" && bead.id == id));
        session.memory_beads.push(MemoryBeadDto {
            id,
            kind: "goal-task-skill".to_string(),
            layer: "L1".to_string(),
            source,
            pinned: false,
            confidence: 0.95,
            created_at: unix_timestamp_millis(),
            token_count: Some(estimate_bead_tokens(&summary)),
            summary,
            origin_message_id: Some(goal.id.clone()),
            origin_table: Some("goals".to_string()),
        });
        session.prune_memory_beads();
        self.save()?;
        Ok(())
    }

    fn remove_goal_task_skill_overlays_from_state(&mut self, goal_id: &str) -> usize {
        let source = goal_task_skill_memory_source(goal_id);
        let mut removed = 0usize;
        for session in &mut self.state.sessions {
            let before = session.memory_beads.len();
            session
                .memory_beads
                .retain(|bead| !(bead.kind == "goal-task-skill" && bead.source == source));
            removed += before.saturating_sub(session.memory_beads.len());
        }
        removed
    }

    fn complete_goal_phase(
        &mut self,
        workspace_id: &str,
        goal_id: &str,
        phase_id: &str,
        payload: GoalPhaseCompleteRequest,
    ) -> ApiResult<GoalStatusResponse> {
        self.save()?;
        let mut connection = open_session_connection(&self.path).map_err(sqlite_api_error)?;
        initialize_session_schema(&connection).map_err(sqlite_api_error)?;
        let goal = get_goal_sqlite(&self.path, workspace_id, goal_id)?;
        let phase = goal
            .phases
            .iter()
            .find(|phase| phase.id == phase_id)
            .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "Goal phase does not exist."))?;
        if matches!(phase.status.as_str(), "cancelled" | "skipped") {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "cancelled or skipped goal phases cannot be completed",
            ));
        }
        let evidence = payload
            .evidence
            .unwrap_or_default()
            .trim()
            .chars()
            .take(2_000)
            .collect::<String>();
        // GL-04：verdict 只由调用方显式给出——自动运行路径确认校验通过后传 Some("pass")；
        // 通用/手工完成传 None，不推断结论、绝不伪造 pass。归一在 record 里做。
        let recorded_verdict = payload
            .verdict
            .as_deref()
            .map(|value| if value.trim().eq_ignore_ascii_case("pass") { "pass" } else { "fail" });
        // GL-04（codex 审查）：status + verdict + 事件放进同一事务，避免出现「status=completed
        // 但 last_verdict 仍是旧值/NULL」的撕裂中间态。用 Immediate 先拿写锁。
        let tx = connection
            .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
            .map_err(sqlite_api_error)?;
        update_goal_phase_status_connection(&tx, workspace_id, goal_id, phase_id, "completed")
            .map_err(sqlite_api_error)?;
        // 事件在事务内只写库不广播，commit 成功后再统一广播（防回滚幽灵事件，codex #4）。
        let mut pending_events = Vec::new();
        if let Some(verdict) = recorded_verdict {
            let verdict_evidence = (!evidence.is_empty()).then(|| json!({ "text": evidence }));
            record_phase_verdict_connection(
                &tx,
                goal_id,
                phase_id,
                verdict,
                None,
                verdict_evidence.as_ref(),
            )
            .map_err(sqlite_api_error)?;
            pending_events.push(
                insert_goal_event_connection_deferred(
                    &tx,
                    goal_id,
                    "goal-phase-verdict",
                    &format!("Phase {phase_id} verdict: {verdict}."),
                    json!({
                        "caller": "goal-loop",
                        "phase_id": phase_id,
                        "verdict": verdict,
                        "assigned_role": phase.assigned_role.clone(),
                    }),
                )
                .map_err(sqlite_api_error)?,
            );
        }
        pending_events.push(
            insert_goal_event_connection_deferred(
                &tx,
                goal_id,
                "phase-completed",
                &format!("Phase {phase_id} completed with evidence."),
                json!({
                    "caller": "goal-loop",
                    "phase_id": phase_id,
                    "assigned_role": phase.assigned_role.clone(),
                    "assigned_session_id": phase.assigned_session_id.clone(),
                    "evidence": evidence,
                }),
            )
            .map_err(sqlite_api_error)?,
        );
        tx.commit().map_err(sqlite_api_error)?;
        for event in pending_events {
            broadcast_goal_event(event);
        }
        let status = goal_status_sqlite(&self.path, workspace_id, goal_id)?;
        if status.goal.status == "completed" {
            let removed = self.remove_goal_task_skill_overlays_from_state(goal_id);
            if removed > 0 {
                self.save()?;
            }
        }
        Ok(status)
    }

    fn prepare_goal_phase_run_context(
        &self,
        workspace_id: &str,
        goal_id: &str,
        phase_id: &str,
    ) -> ApiResult<GoalPhaseRunContext> {
        let goal = get_goal_sqlite(&self.path, workspace_id, goal_id)?;
        if matches!(goal.status.as_str(), "paused" | "cancelled" | "completed") {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "Goal is not runnable in its current status.",
            ));
        }
        let phase = goal
            .phases
            .iter()
            .find(|phase| phase.id == phase_id)
            .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "Goal phase does not exist."))?;
        if phase.status != "running" {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "Only running goal phases can be executed.",
            ));
        }
        // GL-08（codex 二轮 #1）：在模型调用前**原子占用**一次迭代额度。
        // 全局刹车必须挡在真正的执行入口上——commander review 只能拦派发，run-next 会绕过
        // review 直接跑 running 阶段。且必须是条件 UPDATE 占用而不是先读后判，否则并发下
        // 两个请求会同时通过检查、双双执行把计数顶到 max+1。
        {
            let connection = open_session_connection(&self.path).map_err(sqlite_api_error)?;
            initialize_session_schema(&connection).map_err(sqlite_api_error)?;
            if reserve_goal_iteration_connection(&connection, workspace_id, goal_id)
                .map_err(sqlite_api_error)?
                .is_none()
            {
                return Err(api_error(
                    StatusCode::BAD_REQUEST,
                    &format!(
                        "Goal iteration budget exhausted ({}/{}); raise max_iterations via /api/goals/{{goal_id}}/budget or close the goal.",
                        goal.current_iteration, goal.max_iterations
                    ),
                ));
            }
        }
        let assigned_session_id = phase.assigned_session_id.as_deref().ok_or_else(|| {
            api_error(
                StatusCode::BAD_REQUEST,
                "Goal phase has no assigned session to run.",
            )
        })?;
        let session = self
            .state
            .sessions
            .iter()
            .find(|session| session.id == assigned_session_id)
            .ok_or_else(|| {
                api_error(
                    StatusCode::NOT_FOUND,
                    "Goal phase assigned session does not exist.",
                )
            })?;
        let agent = session.to_agent_session(self.is_active(&session.id));
        let context_history = self
            .state
            .chat_rooms
            .iter()
            .find(|room| room.id == goal.chat_room_id)
            .map(|room| room.messages.clone())
            .unwrap_or_default();
        let collaboration_roster =
            chat_room_roster_from_state(&self.state, &goal.chat_room_id, Some(&agent.id)).ok();
        // 结构化进度注入：把本 phase 已发生的回退/重试/上轮验证失败聚合进 prompt，减少模型靠历史推断。
        let progress = open_session_connection(&self.path)
            .ok()
            .map(|connection| goal_phase_progress_block(&connection, &goal.id, phase))
            .unwrap_or_default();
        Ok(GoalPhaseRunContext {
            prompt: goal_phase_run_prompt_with_progress(&goal, phase, &progress),
            agent,
            chat_room_id: goal.chat_room_id.clone(),
            context_history,
            collaboration_roster,
        })
    }

    fn record_goal_phase_model_result(
        &mut self,
        workspace_id: &str,
        goal_id: &str,
        phase_id: &str,
        agent: &AgentSessionDto,
        response: AgentModelResponse,
        mut tool_messages: Vec<ChatMessageDto>,
        command_failures: Vec<String>,
    ) -> ApiResult<GoalPhaseRunResponse> {
        let goal = get_goal_sqlite(&self.path, workspace_id, goal_id)?;
        let phase = goal
            .phases
            .iter()
            .find(|phase| phase.id == phase_id)
            .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "Goal phase does not exist."))?;
        if phase.assigned_session_id.as_deref() != Some(agent.id.as_str()) {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "Goal phase result came from a different session.",
            ));
        }
        // GL-08（codex #2）：拒收陈旧/失效结果。phase 不再 running，或 goal 已被取消/收尾，
        // 都说明这次执行的结果已经过期（并发 run-next、重复点击、执行途中被取消）。
        // 迭代额度已在 prepare_goal_phase_run_context 里原子占用，这里不再重复计数。
        if phase.status != "running" {
            return Err(api_error(
                StatusCode::CONFLICT,
                "Goal phase is no longer running; this result is stale and was not recorded.",
            ));
        }
        if matches!(goal.status.as_str(), "cancelled" | "completed") {
            return Err(api_error(
                StatusCode::CONFLICT,
                "Goal is already cancelled or completed; this in-flight result was not recorded.",
            ));
        }
        let mut messages = Vec::new();
        let now = unix_timestamp_millis();
        if !response.reasoning_text.trim().is_empty() {
            messages.push(ChatMessageDto {
                id: format!("msg-goal-{now}-{phase_id}-thinking"),
                author: visible_reasoning_author(agent),
                role: "assistant".to_string(),
                target: "Goal phase reasoning".to_string(),
                content: sanitize_visible_model_text(agent, &response.reasoning_text),
                kind: "reasoning".to_string(),
                attachments: Vec::new(),
            });
        }
        if !response.answer_text.trim().is_empty() {
            let mut answer_content = sanitize_visible_model_text(agent, &response.answer_text);
            append_context_footer(&mut answer_content, response.context_footer.as_deref());
            messages.push(ChatMessageDto {
                id: format!("msg-goal-{now}-{phase_id}"),
                author: visible_agent_author(agent),
                role: "assistant".to_string(),
                target: "Goal phase".to_string(),
                content: answer_content,
                kind: if response.used_real_model {
                    "assistant-reply".to_string()
                } else {
                    "assistant-fallback".to_string()
                },
                attachments: Vec::new(),
            });
        }
        let evidence = goal_phase_result_evidence(&response.answer_text, &tool_messages);
        if let Some(snapshot) = response.context_usage.as_ref() {
            match self.apply_context_lifecycle_after_turn(
                &agent.id,
                &goal.chat_room_id,
                snapshot,
                context_lifecycle_policy(),
            ) {
                Ok(result) if result.compacted => {
                    let connection =
                        open_session_connection(&self.path).map_err(sqlite_api_error)?;
                    initialize_session_schema(&connection).map_err(sqlite_api_error)?;
                    insert_goal_event_connection(
                        &connection,
                        goal_id,
                        "goal-context-compacted",
                        "Goal phase context reached the configured threshold; compact memory was written and temporary Goal scratch was cleaned.",
                        json!({
                            "caller": "goal-loop",
                            "phase_id": phase_id,
                            "assigned_session_id": agent.id.clone(),
                            "added_memory_beads": result.added_memory_beads,
                            "removed_goal_memory_beads": result.removed_goal_memory_beads,
                            "removed_goal_chat_messages": result.removed_goal_chat_messages,
                        }),
                    )
                    .map_err(sqlite_api_error)?;
                }
                Ok(_) => {}
                Err(error) => diag!(
                    "[CONTEXT-LIFECYCLE] goal apply failed for agent={} goal={} phase={}: {}",
                    agent.id,
                    goal_id,
                    phase_id,
                    error.1.error
                ),
            }
        }

        // 反馈/回退（implementer → planner）：当 implementer 明确报告"无法完成此计划"时，
        // 不再让其原地空转，而是把失败原因回退给上层 planner 重新规划。
        // 复用现有 goal 暂停 + 事件机制，并用重试上限防止 planner↔implementer 死循环。
        if let Some(blocked_reason) = goal_phase_implementer_blocked_reason(&response.answer_text) {
            messages.append(&mut tool_messages);
            let mut connection = open_session_connection(&self.path).map_err(sqlite_api_error)?;
            initialize_session_schema(&connection).map_err(sqlite_api_error)?;
            // GL-05/06（codex 二轮 #2）：implementer→planner 回退也统一到 retry_count，不再用事件
            // 条数。未超上限 → phase 回 pending 交 planner 重规划、goal 暂停；超上限 → phase 置
            // blocked、goal 暂停（此前只升级不 blocked，resume 后 pending 会被重新派发导致死循环）。
            // codex 三轮 #低：note 保持事实陈述（implementer 报阻），不预判「回退 planner」——
            // 最终是回退还是超限 blocked 由 outcome 决定，见下方 summary。
            let note = format!("Goal phase reported blocked by implementer: {blocked_reason}.");
            let outcome;
            let replan_event;
            {
                let tx = connection
                    .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
                    .map_err(sqlite_api_error)?;
                replan_event = insert_goal_event_connection_deferred(
                    &tx,
                    goal_id,
                    "goal-phase-blocked-needs-replan",
                    &note,
                    json!({
                        "caller": "goal-loop",
                        "phase_id": phase_id,
                        "assigned_role": phase.assigned_role.clone(),
                        "assigned_session_id": phase.assigned_session_id.clone(),
                        "blocked_reason": blocked_reason,
                        "evidence": evidence,
                    }),
                )
                .map_err(sqlite_api_error)?;
                outcome = apply_phase_fail_retry_connection(
                    &tx,
                    workspace_id,
                    goal_id,
                    phase_id,
                    &format!("implementer blocked: {blocked_reason}"),
                    &json!({ "blocked_reason": blocked_reason, "text": evidence }),
                    // 重规划回退：phase 回 pending 交 planner，goal 暂停等重规划。
                    "pending",
                    true,
                )
                .map_err(sqlite_api_error)?;
                tx.commit().map_err(sqlite_api_error)?;
            }
            broadcast_goal_event(replan_event);
            broadcast_goal_event(outcome.event.clone());
            // retry_count 是「校验门 + implementer 报阻」两条边共享的累计失败次数，文案据实措辞。
            let summary = if outcome.blocked {
                format!(
                    "Goal escalation: phase {phase_id} blocked after {}/{} cumulative failures. Commander/human intervention required before further dispatch.",
                    outcome.retry_count, outcome.max_retries
                )
            } else {
                format!(
                    "Goal phase reported blocked by implementer (cumulative failures {}/{}): {blocked_reason}. Routed back to planner to revise the plan; goal paused.",
                    outcome.retry_count, outcome.max_retries
                )
            };
            messages.push(ChatMessageDto {
                id: format!("msg-goal-{now}-{phase_id}-replan"),
                author: if outcome.blocked { "Goal guardrail" } else { "Goal feedback" }.to_string(),
                role: "assistant".to_string(),
                target: "Goal phase".to_string(),
                content: summary,
                kind: "task-summary".to_string(),
                attachments: Vec::new(),
            });
            self.append_chat_room_messages(&goal.chat_room_id, messages.clone())?;
            self.append_chat_messages(&agent.id, messages.clone())?;
            let status = goal_status_sqlite(&self.path, workspace_id, goal_id)?;
            return Ok(GoalPhaseRunResponse {
                goal_id: goal_id.to_string(),
                phase_id: phase_id.to_string(),
                assigned_session_id: agent.id.clone(),
                messages,
                status,
                generated_at: unix_timestamp_millis(),
            });
        }

        let missing_artifacts = goal_phase_missing_files(phase);
        if !missing_artifacts.is_empty() {
            messages.append(&mut tool_messages);
            let mut connection = open_session_connection(&self.path).map_err(sqlite_api_error)?;
            initialize_session_schema(&connection).map_err(sqlite_api_error)?;
            // GL-05/06：拒绝事件 + retry/verdict 统一处理放进同一事务。retry_count 超 max_retries
            // 则 phase 置 blocked、goal 暂停（取代旧的「事件条数 >= 3」阈值）。事件延后到 commit
            // 之后广播，避免回滚留下幽灵事件（codex #4）。
            let verdict_reason = format!(
                "required file artifact(s) missing or invalid: {}",
                missing_artifacts.join(", ")
            );
            let note = format!(
                "Goal verifier rejected the phase: required file artifact(s) missing or invalid: {}. Feedback routed back to implementer to revise.",
                missing_artifacts.join(", ")
            );
            let outcome;
            let blocked_event;
            {
                let tx = connection
                    .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
                    .map_err(sqlite_api_error)?;
                blocked_event = insert_goal_event_connection_deferred(
                    &tx,
                    goal_id,
                    "goal-phase-verification-blocked",
                    &note,
                    json!({
                        "caller": "goal-loop",
                        "phase_id": phase_id,
                        "assigned_role": phase.assigned_role.clone(),
                        "assigned_session_id": phase.assigned_session_id.clone(),
                        "missing_artifacts": missing_artifacts,
                        "evidence": evidence,
                    }),
                )
                .map_err(sqlite_api_error)?;
                outcome = apply_phase_fail_retry_connection(
                    &tx,
                    workspace_id,
                    goal_id,
                    phase_id,
                    &verdict_reason,
                    &json!({ "missing_artifacts": missing_artifacts, "text": evidence }),
                    // 校验门重试：phase 留 running 原地重试，不暂停 goal。
                    "running",
                    false,
                )
                .map_err(sqlite_api_error)?;
                tx.commit().map_err(sqlite_api_error)?;
            }
            broadcast_goal_event(blocked_event);
            broadcast_goal_event(outcome.event.clone());
            // codex #5：只发一条与最终状态一致的说明（重试中 / 已 blocked），不再自相矛盾。
            let summary = if outcome.blocked {
                format!(
                    "Goal phase blocked: required file artifact(s) still missing or invalid after {}/{} attempts: {}. The goal loop is paused; rerun after the assigned role creates valid exact file(s) or the plan is adjusted.",
                    outcome.retry_count,
                    outcome.max_retries,
                    missing_artifacts.join(", ")
                )
            } else {
                format!(
                    "Goal verifier rejected the phase (retry {}/{}): required file artifact(s) missing or invalid: {}. The phase stays running for the implementer to revise.",
                    outcome.retry_count,
                    outcome.max_retries,
                    missing_artifacts.join(", ")
                )
            };
            messages.push(ChatMessageDto {
                id: format!("msg-goal-{now}-{phase_id}-verification"),
                author: if outcome.blocked { "Goal guardrail" } else { "Goal verification" }.to_string(),
                role: "assistant".to_string(),
                target: "Goal phase".to_string(),
                content: summary,
                kind: "task-summary".to_string(),
                attachments: Vec::new(),
            });
            self.append_chat_room_messages(&goal.chat_room_id, messages.clone())?;
            self.append_chat_messages(&agent.id, messages.clone())?;
            let status = goal_status_sqlite(&self.path, workspace_id, goal_id)?;
            return Ok(GoalPhaseRunResponse {
                goal_id: goal_id.to_string(),
                phase_id: phase_id.to_string(),
                assigned_session_id: agent.id.clone(),
                messages,
                status,
                generated_at: unix_timestamp_millis(),
            });
        }

        // 确定性命令门控未过（cargo build/test 等非零退出）：把结构化失败证据回退给 implementer
        // 重改，phase 保持 running。与 FilesExist 分支对称，复用同款计数 + 阈值升级。
        // command_failures 已由 run_goal_phase_command_gate 在不持锁时预先算好传入（见 run_goal_phase_once）。
        if !command_failures.is_empty() {
            messages.append(&mut tool_messages);
            let note = format!(
                "Goal verifier rejected the phase: command gate failed:\n{}\nFeedback routed back to implementer to fix.",
                command_failures.join("\n---\n")
            );
            let mut connection = open_session_connection(&self.path).map_err(sqlite_api_error)?;
            initialize_session_schema(&connection).map_err(sqlite_api_error)?;
            // GL-05/06：拒绝事件 + retry/verdict 统一处理（与 FilesExist 分支对称），
            // 事件延后到 commit 之后广播。
            let outcome;
            let gate_event;
            {
                let tx = connection
                    .transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
                    .map_err(sqlite_api_error)?;
                gate_event = insert_goal_event_connection_deferred(
                    &tx,
                    goal_id,
                    "goal-phase-command-gate-failed",
                    &note,
                    json!({
                        "caller": "goal-loop",
                        "phase_id": phase_id,
                        "assigned_role": phase.assigned_role.clone(),
                        "assigned_session_id": phase.assigned_session_id.clone(),
                        "failures": command_failures.clone(),
                        "evidence": evidence.clone(),
                    }),
                )
                .map_err(sqlite_api_error)?;
                outcome = apply_phase_fail_retry_connection(
                    &tx,
                    workspace_id,
                    goal_id,
                    phase_id,
                    "command gate failed",
                    &json!({ "command_failures": command_failures, "text": evidence }),
                    // 命令门重试：phase 留 running 原地重试，不暂停 goal。
                    "running",
                    false,
                )
                .map_err(sqlite_api_error)?;
                tx.commit().map_err(sqlite_api_error)?;
            }
            broadcast_goal_event(gate_event);
            broadcast_goal_event(outcome.event.clone());
            let summary = if outcome.blocked {
                format!(
                    "Goal phase blocked: command gate still failing after {}/{} attempts. The goal loop is paused; rerun after the implementer fixes the build/test failures or the plan is adjusted.",
                    outcome.retry_count, outcome.max_retries
                )
            } else {
                format!(
                    "Goal verifier rejected the phase (retry {}/{}): command gate failed. The phase stays running for the implementer to fix.",
                    outcome.retry_count, outcome.max_retries
                )
            };
            messages.push(ChatMessageDto {
                id: format!("msg-goal-{now}-{phase_id}-command"),
                author: if outcome.blocked { "Goal guardrail" } else { "Goal verification" }.to_string(),
                role: "assistant".to_string(),
                target: "Goal phase".to_string(),
                content: summary,
                kind: "task-summary".to_string(),
                attachments: Vec::new(),
            });
            self.append_chat_room_messages(&goal.chat_room_id, messages.clone())?;
            self.append_chat_messages(&agent.id, messages.clone())?;
            let status = goal_status_sqlite(&self.path, workspace_id, goal_id)?;
            return Ok(GoalPhaseRunResponse {
                goal_id: goal_id.to_string(),
                phase_id: phase_id.to_string(),
                assigned_session_id: agent.id.clone(),
                messages,
                status,
                generated_at: unix_timestamp_millis(),
            });
        }

        messages.append(&mut tool_messages);
        self.append_chat_room_messages(&goal.chat_room_id, messages.clone())?;
        self.append_chat_messages(&agent.id, messages.clone())?;
        // GL-04：能走到这里说明本 phase 适用的确定性校验门（FilesExist / 命令门）都未拒绝——
        // 上面两个 fail 分支会提前 return。只有此路径有资格断言 pass。
        let status = self.complete_goal_phase(
            workspace_id,
            goal_id,
            phase_id,
            GoalPhaseCompleteRequest {
                evidence: Some(evidence),
                verdict: Some("pass".to_string()),
            },
        )?;
        Ok(GoalPhaseRunResponse {
            goal_id: goal_id.to_string(),
            phase_id: phase_id.to_string(),
            assigned_session_id: agent.id.clone(),
            messages,
            status,
            generated_at: unix_timestamp_millis(),
        })
    }

    fn create_auto_handoffs_from_reply(
        &mut self,
        room_id: &str,
        candidate: &AutoHandoffCandidate,
    ) -> ApiResult<Vec<ManualHandoffResponse>> {
        let directives = parse_handoff_directives(&candidate.content);
        if directives.is_empty() {
            return Ok(Vec::new());
        }
        let (originating_user_msg_id, depth) =
            self.infer_auto_handoff_chain_position(room_id, &candidate.from_agent_id)?;
        let mut responses = Vec::new();
        for directive in directives {
            let attach = normalize_handoff_attach(Some(&directive.attach));
            let (payload_attach, attach_message_ids) = if attach == "last_assistant" {
                (
                    Some("message_ids".to_string()),
                    vec![candidate.assistant_message_id.clone()],
                )
            } else {
                (Some(attach), directive.attach_message_ids.clone())
            };
            let response = self
                .create_manual_handoff(
                    room_id,
                    ManualHandoffRequest {
                        from_agent_id: candidate.from_agent_id.clone(),
                        to: directive.raw_to,
                        intent: directive.intent,
                        attach: payload_attach,
                        attach_message_ids: Some(attach_message_ids),
                        originating_user_msg_id: originating_user_msg_id.clone(),
                        depth: Some(depth),
                        contract: None,
                    },
                )?
                .0;
            responses.push(response);
        }
        Ok(responses)
    }

    fn infer_auto_handoff_chain_position(
        &self,
        room_id: &str,
        from_agent_id: &str,
    ) -> ApiResult<(Option<String>, u8)> {
        let room = self
            .state
            .chat_rooms
            .iter()
            .find(|room| room.id == room_id)
            .ok_or_else(|| api_error(StatusCode::NOT_FOUND, "聊天室不存在"))?;
        let latest_user_msg_id = latest_room_user_message_id(room);
        let existing = query_chat_handoffs_sqlite(&self.path, room_id, 10_000, None)
            .map_err(sqlite_api_error)?;
        if let Some(parent) = existing
            .iter()
            .filter(|record| record.status == "delivered" && record.to_agent_id == from_agent_id)
            .max_by_key(|record| record.created_at)
        {
            return Ok((
                Some(parent.originating_user_msg_id.clone()),
                parent.depth.saturating_add(1),
            ));
        }
        Ok((latest_user_msg_id, 0))
    }

    fn create_chat_room(
        &mut self,
        payload: CreateChatRoomRequest,
    ) -> ApiResult<ChatRoomSummaryDto> {
        // 系统室不计入 8 个用户室上限：只统计非系统室。
        let user_room_count = self
            .state
            .chat_rooms
            .iter()
            .filter(|room| !is_scheduled_task_system_room(&room.id))
            .count();
        if user_room_count >= 8 {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "最多只能保留 8 个聊天室，请先清理不再使用的聊天室",
            ));
        }
        let now = unix_timestamp_millis();
        let name = payload
            .name
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(|value| value.chars().take(32).collect())
            .unwrap_or_else(|| format!("聊天 {:02}", self.state.chat_rooms.len() + 1));
        let room = PersistedChatRoom {
            id: format!("room-{now}"),
            name,
            created_at: now,
            updated_at: now,
            messages: Vec::new(),
        };
        self.state.active_chat_room_id = Some(room.id.clone());
        let summary = room.summary(true);
        self.state.chat_rooms.push(room);
        self.save()?;
        Ok(summary)
    }

    fn activate_chat_room(&mut self, room_id: &str) -> ApiResult<ChatRoomSummaryDto> {
        let Some(position) = self
            .state
            .chat_rooms
            .iter()
            .position(|room| room.id == room_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "聊天室不存在"));
        };
        self.state.active_chat_room_id = Some(room_id.to_string());
        self.save()?;
        Ok(self.state.chat_rooms[position].summary(true))
    }

    fn update_chat_room(
        &mut self,
        room_id: &str,
        payload: UpdateChatRoomRequest,
    ) -> ApiResult<ChatRoomSummaryDto> {
        // 系统室不可重命名：保持稳定显示名「定时任务」。
        if is_scheduled_task_system_room(room_id) {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "定时任务系统聊天室不可重命名",
            ));
        }
        let is_active = self.is_active_chat_room(room_id);
        let Some(room) = self
            .state
            .chat_rooms
            .iter_mut()
            .find(|room| room.id == room_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "聊天室不存在"));
        };
        let name = payload
            .name
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| api_error(StatusCode::BAD_REQUEST, "聊天室名称不能为"))?;
        room.name = name.chars().take(32).collect();
        room.updated_at = unix_timestamp_millis();
        let summary = room.summary(is_active);
        self.save()?;
        Ok(summary)
    }

    fn sync_state_after_sql_delete(&mut self) -> ApiResult<()> {
        self.state = read_session_state_from_sqlite(&self.path).map_err(sqlite_api_error)?;
        let created_seed_room = self.state.chat_rooms.is_empty();
        self.ensure_chat_room();
        if created_seed_room {
            save_session_state_to_sqlite(&self.path, &self.state, self.capacity)?;
        }
        self.save_legacy_json()
    }

    /// REQ-WEB-SESSION-007 Phase B：删除聊天室时走 SQLite transaction DELETE。
    ///
    /// `chat_room_messages.room_id` 外键负责消息级联，`trg_room_msg_cascade_beads`
    /// 负责衍生 bead 回收；`attachment_refs` 先按待删消息摘除，再对无引用文件"GC。
    fn delete_chat_room(&mut self, room_id: &str) -> ApiResult<CascadeDeleteReport> {
        let attachment_dir = attachment_store_dir();
        self.delete_chat_room_with_attachment_dir(room_id, &attachment_dir)
    }

    fn delete_chat_room_with_attachment_dir(
        &mut self,
        room_id: &str,
        attachment_dir: &Path,
    ) -> ApiResult<CascadeDeleteReport> {
        // 系统室不可删除：承载 poll 定时任务投递与 Goal 阶段镜像。
        if is_scheduled_task_system_room(room_id) {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "定时任务系统聊天室不可删除",
            ));
        }
        self.save()?;
        let Some(position) = self
            .state
            .chat_rooms
            .iter()
            .position(|room| room.id == room_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "聊天室不存在"));
        };

        let room = &self.state.chat_rooms[position];
        let room_name = room.name.clone();
        let message_ids: std::collections::BTreeSet<String> =
            room.messages.iter().map(|m| m.id.clone()).collect();
        let deleted_messages = message_ids.len();
        let deleted_beads = self
            .state
            .sessions
            .iter()
            .map(|session| {
                session
                    .memory_beads
                    .iter()
                    .filter(|b| {
                        b.origin_table.as_deref() == Some("chat_room_messages")
                            && b.origin_message_id
                                .as_deref()
                                .is_some_and(|id| message_ids.contains(id))
                    })
                    .count()
            })
            .sum();
        let next_active_room_id = if self.state.active_chat_room_id.as_deref() == Some(room_id) {
            self.state
                .chat_rooms
                .iter()
                .find(|room| room.id != room_id)
                .map(|room| room.id.as_str())
        } else {
            self.state.active_chat_room_id.as_deref()
        };
        let deleted_attachments = delete_chat_room_sqlite(
            &self.path,
            room_id,
            &message_ids,
            next_active_room_id,
            attachment_dir,
        )?;
        self.sync_state_after_sql_delete()?;

        Ok(CascadeDeleteReport {
            target_kind: "chat-room".to_string(),
            target_id: room_id.to_string(),
            target_label: room_name,
            deleted_messages,
            deleted_beads,
            deleted_attachments,
            deleted_rooms: 1,
            deleted_sessions: 0,
        })
    }

    /// REQ-WEB-SESSION-007：删除聊天室中的单条消息，连带删除由它派生的 beads。
    fn delete_chat_room_message(
        &mut self,
        room_id: &str,
        message_id: &str,
    ) -> ApiResult<CascadeDeleteReport> {
        let attachment_dir = attachment_store_dir();
        self.delete_chat_room_message_with_attachment_dir(room_id, message_id, &attachment_dir)
    }

    fn delete_chat_room_message_with_attachment_dir(
        &mut self,
        room_id: &str,
        message_id: &str,
        attachment_dir: &Path,
    ) -> ApiResult<CascadeDeleteReport> {
        self.save()?;
        let Some(room) = self.state.chat_rooms.iter().find(|room| room.id == room_id) else {
            return Err(api_error(StatusCode::NOT_FOUND, "聊天室不存在"));
        };
        if !room.messages.iter().any(|m| m.id == message_id) {
            return Err(api_error(StatusCode::NOT_FOUND, "消息不存"));
        }
        let deleted_beads = self
            .state
            .sessions
            .iter()
            .map(|session| {
                session
                    .memory_beads
                    .iter()
                    .filter(|b| {
                        b.origin_table.as_deref() == Some("chat_room_messages")
                            && b.origin_message_id.as_deref() == Some(message_id)
                    })
                    .count()
            })
            .sum();
        let deleted_attachments =
            delete_chat_room_message_sqlite(&self.path, room_id, message_id, attachment_dir)?;
        self.sync_state_after_sql_delete()?;
        Ok(CascadeDeleteReport {
            target_kind: "chat-room-message".to_string(),
            target_id: message_id.to_string(),
            target_label: room_id.to_string(),
            deleted_messages: 1,
            deleted_beads,
            deleted_attachments,
            deleted_rooms: 0,
            deleted_sessions: 0,
        })
    }

    /// REQ-WEB-SESSION-007：删除会话消息（Agent 对话流水），连带删除衍生 beads。
    fn delete_session_message(
        &mut self,
        session_id: &str,
        message_id: &str,
    ) -> ApiResult<CascadeDeleteReport> {
        let attachment_dir = attachment_store_dir();
        self.delete_session_message_with_attachment_dir(session_id, message_id, &attachment_dir)
    }

    fn delete_session_message_with_attachment_dir(
        &mut self,
        session_id: &str,
        message_id: &str,
        attachment_dir: &Path,
    ) -> ApiResult<CascadeDeleteReport> {
        self.save()?;
        let Some(session) = self
            .state
            .sessions
            .iter()
            .find(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };
        if !session.messages.iter().any(|m| m.id == message_id) {
            return Err(api_error(StatusCode::NOT_FOUND, "消息不存"));
        }
        let deleted_beads = session
            .memory_beads
            .iter()
            .filter(|b| {
                b.origin_table.as_deref() == Some("session_messages")
                    && b.origin_message_id.as_deref() == Some(message_id)
            })
            .count();
        let deleted_attachments =
            delete_session_message_sqlite(&self.path, session_id, message_id, attachment_dir)?;
        self.sync_state_after_sql_delete()?;
        Ok(CascadeDeleteReport {
            target_kind: "session-message".to_string(),
            target_id: message_id.to_string(),
            target_label: session_id.to_string(),
            deleted_messages: 1,
            deleted_beads,
            deleted_attachments,
            deleted_rooms: 0,
            deleted_sessions: 0,
        })
    }

    /// REQ-WEB-SESSION-007：预览删除聊天室的影响范围，供前端确认弹窗使用。
    fn chat_room_impact(&self, room_id: &str) -> ApiResult<ChatRoomImpactResponse> {
        let Some(room) = self.state.chat_rooms.iter().find(|r| r.id == room_id) else {
            return Err(api_error(StatusCode::NOT_FOUND, "聊天室不存在"));
        };
        let message_ids: std::collections::BTreeSet<String> =
            room.messages.iter().map(|m| m.id.clone()).collect();
        let affected_messages = message_ids.len();
        let affected_attachments = room
            .messages
            .iter()
            .flat_map(|message| message.attachments.iter())
            .filter(|attachment| attachment_file_name_from_url(&attachment.url).is_some())
            .count();
        let affected_beads: usize = self
            .state
            .sessions
            .iter()
            .map(|session| {
                session
                    .memory_beads
                    .iter()
                    .filter(|b| {
                        b.origin_table.as_deref() == Some("chat_room_messages")
                            && b.origin_message_id
                                .as_deref()
                                .is_some_and(|id| message_ids.contains(id))
                    })
                    .count()
            })
            .sum();
        Ok(ChatRoomImpactResponse {
            room_id: room.id.clone(),
            room_name: room.name.clone(),
            affected_messages,
            affected_beads,
            affected_attachments,
        })
    }

    fn chat_room_messages(
        &self,
        room_id: &str,
        query: MessageQuery,
    ) -> ApiResult<Json<ChatRoomMessagesResponse>> {
        let Some(room) = self.state.chat_rooms.iter().find(|room| room.id == room_id) else {
            return Err(api_error(StatusCode::NOT_FOUND, "聊天室不存在"));
        };
        let limit = query.limit.unwrap_or(DEFAULT_MESSAGE_LIMIT).clamp(1, 200);
        let total = room.messages.len();
        let end = query
            .before
            .as_ref()
            .and_then(|before| {
                room.messages
                    .iter()
                    .position(|message| &message.id == before)
            })
            .unwrap_or(total);
        let start = end.saturating_sub(limit);
        Ok(Json(ChatRoomMessagesResponse {
            room: room.summary(self.is_active_chat_room(room_id)),
            messages: room.messages[start..end].to_vec(),
            has_more: start > 0,
            next_before: (start > 0)
                .then(|| room.messages.get(start).map(|message| message.id.clone()))
                .flatten(),
        }))
    }

    fn chat_room_attachments(
        &self,
        room_id: Option<&str>,
        query: AttachmentIndexQuery,
    ) -> ApiResult<Json<AttachmentIndexResponse>> {
        let limit = query.limit.unwrap_or(80).clamp(1, 500);
        let kind = query
            .kind
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty());
        let mut items = Vec::new();

        for room in &self.state.chat_rooms {
            if room_id.is_some_and(|id| id != room.id) {
                continue;
            }
            for message in &room.messages {
                for attachment in &message.attachments {
                    let preview = attachment_preview(attachment);
                    if kind.is_some_and(|kind| preview.kind != kind && attachment.kind != kind) {
                        continue;
                    }
                    items.push(AttachmentIndexItem {
                        room_id: room.id.clone(),
                        room_name: room.name.clone(),
                        message_id: message.id.clone(),
                        author: message.author.clone(),
                        created_at: message.created_at,
                        attachment: attachment.clone(),
                        preview,
                    });
                }
            }
        }

        items.sort_by(|a, b| b.created_at.cmp(&a.created_at));
        items.truncate(limit);
        let total = items.len();
        Ok(Json(AttachmentIndexResponse {
            room_id: room_id.map(str::to_string),
            total,
            items,
        }))
    }

    fn selected_chat_messages(
        &self,
        room_id: &str,
        selected_ids: &[String],
    ) -> Vec<PersistedChatMessage> {
        if selected_ids.is_empty() {
            return Vec::new();
        }

        let mut messages = Vec::new();
        let mut seen = HashSet::new();
        for id in selected_ids {
            if !seen.insert(id.as_str()) {
                continue;
            }
            if let Some(message) = self
                .state
                .chat_rooms
                .iter()
                .find(|room| room.id == room_id)
                .and_then(|room| room.messages.iter().find(|message| message.id == *id))
                .or_else(|| {
                    self.state
                        .sessions
                        .iter()
                        .flat_map(|session| session.messages.iter())
                        .find(|message| message.id == *id)
                })
            {
                messages.push(message.clone());
            }
        }
        messages
    }

    fn find_session(&self, session_id: &str) -> Option<&PersistedSession> {
        self.state
            .sessions
            .iter()
            .find(|session| session.id == session_id)
    }

    fn create_session(&mut self, payload: UpsertSessionRequest) -> ApiResult<SessionSummaryDto> {
        if self.state.sessions.len() >= MAX_USER_SESSIONS {
            return Err(api_error(
                StatusCode::BAD_REQUEST,
                "最多只能保留 10 个自定义会话，请先删除不再使用的会话",
            ));
        }
        let now = unix_timestamp_millis();
        let name = normalize_session_name(payload.name.as_deref(), self.state.sessions.len() + 1);
        let model = normalize_model(payload.model.as_deref());
        let provider = normalize_provider(payload.provider.as_deref());
        let (base_url, endpoint) = custom_provider_urls(
            &provider,
            payload.base_url.as_deref(),
            payload.endpoint.as_deref(),
        );
        let model_type = payload
            .model_type
            .as_deref()
            .map(|value| value.trim().to_ascii_lowercase())
            .filter(|value| {
                matches!(
                    value.as_str(),
                    "text" | "vision" | "audio" | "video" | "embedding" | "multimodal"
                )
            })
            .unwrap_or_else(|| resolve_model_type(&model));
        let avatar = match payload.avatar.as_deref() {
            Some(value) => normalize_session_avatar(Some(value))?,
            None => default_session_avatar_for_index(self.state.sessions.len()),
        };
        let session = PersistedSession {
            id: format!("session-{now}"),
            name,
            provider,
            model: model.clone(),
            model_type,
            avatar,
            base_url,
            endpoint,
            reasoning_effort: normalize_reasoning_effort(payload.reasoning_effort.as_deref()),
            api_key_ref: payload.api_key_ref.unwrap_or_default(),
            memory_beads: Vec::new(),
            created_at: now,
            updated_at: now,
            context_reset_at: now,
            messages: Vec::new(),
        };
        self.state.active_session_id = Some(session.id.clone());
        let summary = session.summary(true);
        self.state.sessions.push(session);
        self.save()?;
        Ok(summary)
    }

    fn ensure_goal_role_sessions(
        &mut self,
        roles: Vec<String>,
    ) -> ApiResult<Vec<SessionSummaryDto>> {
        let mut normalized_roles = Vec::new();
        for role in roles {
            if let Some(normalized) = normalize_goal_role(&role)? {
                normalized_roles.push(normalized);
            }
        }
        if normalized_roles.is_empty() {
            normalized_roles = goal_role_template_names()
                .iter()
                .map(|role| (*role).to_string())
                .collect();
        }
        normalized_roles.sort();
        normalized_roles.dedup();

        let template = self
            .state
            .active_session_id
            .as_ref()
            .and_then(|id| self.state.sessions.iter().find(|session| session.id == *id))
            .or_else(|| self.state.sessions.first())
            .cloned()
            .unwrap_or_else(seed_session);
        let mut created = Vec::new();
        for role in normalized_roles {
            let session_id = format!("goal-{role}");
            if self
                .state
                .sessions
                .iter()
                .any(|session| session.id == session_id)
            {
                continue;
            }
            if self.state.sessions.len() >= MAX_USER_SESSIONS {
                return Err(api_error(
                    StatusCode::BAD_REQUEST,
                    "Goal role session bootstrap exceeds session capacity; delete unused sessions or bootstrap fewer roles.",
                ));
            }
            let now = unix_timestamp_millis();
            let mut session = PersistedSession {
                id: session_id,
                name: format!("goal-{role}"),
                provider: template.provider.clone(),
                model: template.model.clone(),
                base_url: template.base_url.clone(),
                endpoint: template.endpoint.clone(),
                reasoning_effort: template.reasoning_effort.clone(),
                model_type: "text".to_string(),
                avatar: template.avatar.clone(),
                api_key_ref: template.api_key_ref.clone(),
                memory_beads: vec![goal_role_template_bead(&role, now)],
                created_at: now,
                updated_at: now,
                context_reset_at: now,
                messages: Vec::new(),
            };
            session.prune_memory_beads();
            let summary = session.summary(false);
            self.state.sessions.push(session);
            created.push(summary);
        }
        if !created.is_empty() {
            self.save()?;
        }
        Ok(created)
    }

    fn update_session(
        &mut self,
        session_id: &str,
        payload: UpsertSessionRequest,
    ) -> ApiResult<SessionSummaryDto> {
        let is_active = self.is_active(session_id);
        let Some(session) = self
            .state
            .sessions
            .iter_mut()
            .find(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };
        if let Some(name) = payload.name {
            let trimmed = name.trim();
            if !trimmed.is_empty() {
                session.name = trimmed.chars().take(32).collect();
            }
        }
        if let Some(provider) = payload.provider {
            session.provider = normalize_provider(Some(&provider));
        }
        if let Some(model) = payload.model {
            session.model = normalize_model(Some(&model));
        }
        if let Some(model_type) = payload.model_type {
            let trimmed = model_type.trim().to_ascii_lowercase();
            if matches!(
                trimmed.as_str(),
                "text" | "vision" | "audio" | "video" | "image" | "embedding" | "multimodal"
            ) {
                session.model_type = trimmed;
            }
        }
        if let Some(avatar) = payload.avatar {
            session.avatar = normalize_session_avatar(Some(&avatar))?;
        }
        if is_custom_provider_label(&session.provider) {
            if let Some(base_url) = payload.base_url {
                session.base_url = normalize_optional_url(Some(&base_url));
            }
            if let Some(endpoint) = payload.endpoint {
                session.endpoint = normalize_optional_url(Some(&endpoint));
            }
        } else {
            session.base_url = None;
            session.endpoint = None;
        }
        if let Some(reasoning_effort) = payload.reasoning_effort {
            session.reasoning_effort = normalize_reasoning_effort(Some(&reasoning_effort));
        }
        if let Some(api_key_ref) = payload.api_key_ref {
            session.api_key_ref = api_key_ref.trim().chars().take(128).collect();
        }
        session.updated_at = unix_timestamp_millis();
        let summary = session.summary(is_active);
        self.save()?;
        Ok(summary)
    }

    fn delete_session(&mut self, session_id: &str) -> ApiResult<()> {
        if self.state.sessions.len() <= 1 {
            return Err(api_error(StatusCode::BAD_REQUEST, "至少需要保留一个会话"));
        }
        let before = self.state.sessions.len();
        self.state
            .sessions
            .retain(|session| session.id != session_id);
        if self.state.sessions.len() == before {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        }
        if self.state.active_session_id.as_deref() == Some(session_id) {
            self.state.active_session_id = self
                .state
                .sessions
                .first()
                .map(|session| session.id.clone());
        }
        if self.state.active_vision_session_id.as_deref() == Some(session_id) {
            self.state.active_vision_session_id = None;
        }
        self.save()?;
        purge_deleted_session_auxiliary_sqlite(&self.path, session_id)?;
        Ok(())
    }

    fn reset_session(&mut self, session_id: &str) -> ApiResult<SessionSummaryDto> {
        let is_active = self.is_active(session_id);
        let Some(session) = self
            .state
            .sessions
            .iter_mut()
            .find(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };
        let now = unix_timestamp_millis();
        session.messages.clear();
        session.memory_beads.clear();
        session.context_reset_at = now;
        session.updated_at = now;
        let summary = session.summary(is_active);
        self.save()?;
        Ok(summary)
    }

    fn activate_session(&mut self, session_id: &str) -> ApiResult<SessionSummaryDto> {
        let Some(position) = self
            .state
            .sessions
            .iter()
            .position(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };
        self.state.active_session_id = Some(session_id.to_string());
        self.save()?;
        Ok(self.state.sessions[position].summary(true))
    }

    fn session_messages(
        &self,
        session_id: &str,
        query: MessageQuery,
    ) -> ApiResult<Json<SessionMessagesResponse>> {
        let Some(session) = self
            .state
            .sessions
            .iter()
            .find(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };
        let limit = query.limit.unwrap_or(DEFAULT_MESSAGE_LIMIT).clamp(1, 200);
        let total = session.messages.len();
        let end = query
            .before
            .as_ref()
            .and_then(|before| {
                session
                    .messages
                    .iter()
                    .position(|message| &message.id == before)
            })
            .unwrap_or(total);
        let start = end.saturating_sub(limit);
        Ok(Json(SessionMessagesResponse {
            session: session.summary(self.is_active(session_id)),
            messages: session.messages[start..end].to_vec(),
            has_more: start > 0,
            next_before: (start > 0)
                .then(|| {
                    session
                        .messages
                        .get(start)
                        .map(|message| message.id.clone())
                })
                .flatten(),
        }))
    }

    fn append_chat_messages(
        &mut self,
        session_id: &str,
        messages: Vec<ChatMessageDto>,
    ) -> ApiResult<()> {
        if self.append_chat_messages_in_memory(session_id, &messages) {
            self.save()
        } else {
            Ok(())
        }
    }

    fn append_chat_messages_in_memory(
        &mut self,
        session_id: &str,
        messages: &[ChatMessageDto],
    ) -> bool {
        if messages.is_empty() {
            return false;
        }
        let Some(session) = self
            .state
            .sessions
            .iter_mut()
            .find(|session| session.id == session_id)
        else {
            return false;
        };
        for message in messages {
            session
                .messages
                .push(PersistedChatMessage::from(message.clone()));
        }
        session.updated_at = unix_timestamp_millis();
        true
    }

    /// 幂等创建定时任务系统聊天室（不激活，不改活动室）。
    /// 用于承载 poll 型定时任务投递与 Goal 阶段消息镜像；多次调用安全。
    fn ensure_scheduled_task_system_room(&mut self) -> ApiResult<ChatRoomSummaryDto> {
        let now = unix_timestamp_millis();
        let mut changed = false;
        if let Some(room) = self
            .state
            .chat_rooms
            .iter_mut()
            .find(|room| room.id == SCHEDULED_TASK_SYSTEM_ROOM_ID)
        {
            if room.name != SCHEDULED_TASK_SYSTEM_ROOM_DISPLAY_NAME {
                room.name = SCHEDULED_TASK_SYSTEM_ROOM_DISPLAY_NAME.to_string();
                room.updated_at = now;
                changed = true;
            }
        } else {
            self.state.chat_rooms.push(PersistedChatRoom {
                id: SCHEDULED_TASK_SYSTEM_ROOM_ID.to_string(),
                name: SCHEDULED_TASK_SYSTEM_ROOM_DISPLAY_NAME.to_string(),
                created_at: now,
                updated_at: now,
                messages: Vec::new(),
            });
            changed = true;
        }
        if changed {
            self.save()?;
        }
        let room = self
            .state
            .chat_rooms
            .iter()
            .find(|room| room.id == SCHEDULED_TASK_SYSTEM_ROOM_ID)
            .expect("scheduled task system room must exist");
        Ok(ChatRoomSummaryDto {
            id: room.id.clone(),
            name: room.name.clone(),
            active: self.is_active_chat_room(SCHEDULED_TASK_SYSTEM_ROOM_ID),
            updated_at: room.updated_at,
            message_count: room.messages.len(),
        })
    }

    /// 把本次 Goal 阶段新产生的消息镜像到系统室。
    /// SQLite 主键是 `(room_id, id)`，因此保留原消息 id，并只在系统室内按 id 去重。
    fn mirror_goal_phase_messages_to_system_room(
        &mut self,
        messages: &[ChatMessageDto],
    ) -> ApiResult<usize> {
        self.ensure_scheduled_task_system_room()?;
        let now = unix_timestamp_millis();
        let room = self
            .state
            .chat_rooms
            .iter_mut()
            .find(|room| room.id == SCHEDULED_TASK_SYSTEM_ROOM_ID)
            .expect("scheduled task system room must exist");
        let mut inserted = 0usize;
        for message in messages {
            if room.messages.iter().any(|stored| stored.id == message.id) {
                continue;
            }
            room.messages
                .push(PersistedChatMessage::from(message.clone()));
            inserted += 1;
        }
        if inserted > 0 {
            room.updated_at = now;
            self.save()?;
        }
        Ok(inserted)
    }

    /// 写入精简的定时任务状态消息（失败 / 跳过 / 无输出）到系统室。
    /// `status` ∈ {"failed","skipped","no-output","executed"}；`detail` 为简短说明。
    fn append_scheduled_task_status_message(
        &mut self,
        status: &str,
        detail: &str,
    ) -> ApiResult<()> {
        self.ensure_scheduled_task_system_room()?;
        let now = unix_timestamp_millis();
        // 精简：内容裁到 80 字符以内。
        let trimmed: String = detail.chars().take(80).collect();
        let content = match status {
            "failed" => format!("[失败] {trimmed}"),
            "skipped" => format!("[跳过] {trimmed}"),
            "no-output" => format!("[无输出] {trimmed}"),
            "executed" => format!("[完成] {trimmed}"),
            other => format!("[{other}] {trimmed}"),
        };
        let sequence = self
            .state
            .chat_rooms
            .iter()
            .find(|room| room.id == SCHEDULED_TASK_SYSTEM_ROOM_ID)
            .map(|room| room.messages.len())
            .unwrap_or(0);
        let message = PersistedChatMessage {
            id: format!("sched-status-{now}-{sequence}"),
            author: "COOLZHU AGENT".to_string(),
            role: "assistant".to_string(),
            target: "定时任务".to_string(),
            content,
            kind: "scheduled-status".to_string(),
            attachments: Vec::new(),
            created_at: now,
        };
        if let Some(room) = self
            .state
            .chat_rooms
            .iter_mut()
            .find(|room| room.id == SCHEDULED_TASK_SYSTEM_ROOM_ID)
        {
            room.messages.push(message);
            room.updated_at = now;
        }
        self.save()
    }

    fn append_chat_room_messages(
        &mut self,
        room_id: &str,
        messages: Vec<ChatMessageDto>,
    ) -> ApiResult<()> {
        if self.append_chat_room_messages_in_memory(room_id, &messages) {
            self.save()
        } else {
            Ok(())
        }
    }

    fn append_chat_room_messages_in_memory(
        &mut self,
        room_id: &str,
        messages: &[ChatMessageDto],
    ) -> bool {
        if messages.is_empty() {
            return false;
        }
        if !self.state.chat_rooms.iter().any(|room| room.id == room_id) {
            self.state.chat_rooms.push(PersistedChatRoom {
                id: room_id.to_string(),
                name: "主聊天室".to_string(),
                created_at: unix_timestamp_millis(),
                updated_at: unix_timestamp_millis(),
                messages: Vec::new(),
            });
        }
        let Some(room) = self
            .state
            .chat_rooms
            .iter_mut()
            .find(|room| room.id == room_id)
        else {
            return false;
        };
        for message in messages {
            room.messages
                .push(PersistedChatMessage::from(message.clone()));
        }
        room.updated_at = unix_timestamp_millis();
        true
    }

    fn append_chat_dispatch_once(
        &mut self,
        chat_room_id: &str,
        conversation_session_id: Option<&str>,
        targets: &[AgentSessionDto],
        messages: Vec<ChatMessageDto>,
    ) -> ApiResult<usize> {
        if messages.is_empty() {
            return Ok(0);
        }
        let mut changed = self.append_chat_room_messages_in_memory(chat_room_id, &messages);
        let mut session_ids = HashSet::new();
        if let Some(session_id) = conversation_session_id {
            if session_ids.insert(session_id.to_string()) {
                changed |= self.append_chat_messages_in_memory(session_id, &messages);
            }
        }
        for agent in targets {
            if session_ids.insert(agent.id.clone()) {
                changed |= self.append_chat_messages_in_memory(&agent.id, &messages);
            }
        }
        if changed {
            self.save()?;
            Ok(1)
        } else {
            Ok(0)
        }
    }

    /// 全局按 message_id 更新一条消息的 kind/content/attachments（chat rooms + sessions）。
    /// 用于视频异步完成后把 pending 消息持久化为带 video 附件的 assistant-video 消息，
    /// 确保刷新 / 切会话 / 重启后视频内容仍在（不依赖内存 video_jobs 与前端轮询）。
    fn update_message_everywhere(
        &mut self,
        message_id: &str,
        kind: &str,
        content: &str,
        attachments: &[ChatAttachmentDto],
    ) -> bool {
        let mut found = false;
        for room in self.state.chat_rooms.iter_mut() {
            for msg in room.messages.iter_mut() {
                if msg.id == message_id {
                    msg.kind = kind.to_string();
                    msg.content = content.to_string();
                    msg.attachments = attachments.to_vec();
                    found = true;
                }
            }
        }
        for session in self.state.sessions.iter_mut() {
            for msg in session.messages.iter_mut() {
                if msg.id == message_id {
                    msg.kind = kind.to_string();
                    msg.content = content.to_string();
                    msg.attachments = attachments.to_vec();
                    found = true;
                }
            }
        }
        if found {
            let _ = self.save();
        }
        found
    }

    fn session_beads(&self, session_id: &str) -> ApiResult<Json<SessionBeadsResponse>> {
        let Some(session) = self
            .state
            .sessions
            .iter()
            .find(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };

        Ok(Json(session_beads_response(
            session,
            self.is_active(session_id),
        )))
    }

    fn query_session_beads(
        &self,
        session_id: &str,
        query: MemoryBeadQuery,
    ) -> ApiResult<Json<SessionBeadsResponse>> {
        let Some(session) = self
            .state
            .sessions
            .iter()
            .find(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };

        let beads =
            runtime::query_memory_beads(&session.memory_beads, &query.to_runtime_options(8, 64));
        let summary = memory_beads_summary(
            &beads,
            session.memory_beads.len(),
            session.memory_beads.is_empty(),
        );

        Ok(Json(SessionBeadsResponse {
            session: session.summary(self.is_active(session_id)),
            beads,
            summary,
        }))
    }

    fn session_beads_summary(
        &self,
        session_id: &str,
    ) -> ApiResult<Json<SessionBeadsSummaryResponse>> {
        let Some(session) = self
            .state
            .sessions
            .iter()
            .find(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };
        let beads = session.memory_beads.clone();
        Ok(Json(SessionBeadsSummaryResponse {
            session: session.summary(self.is_active(session_id)),
            summary: memory_beads_summary(
                &beads,
                session.memory_beads.len(),
                session.memory_beads.is_empty(),
            ),
        }))
    }

    fn session_prompt_beads(
        &self,
        session_id: &str,
        query: PromptMemoryQuery,
    ) -> ApiResult<Json<PromptMemoryResponse>> {
        let Some(session) = self
            .state
            .sessions
            .iter()
            .find(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };
        let beads = session.query_prompt_memory_beads(query);
        let context = render_prompt_memory_context(&beads);
        Ok(Json(PromptMemoryResponse {
            session: session.summary(self.is_active(session_id)),
            beads,
            context,
        }))
    }

    fn add_memory_bead(
        &mut self,
        session_id: &str,
        payload: AddMemoryBeadRequest,
    ) -> ApiResult<Json<SessionBeadsResponse>> {
        let is_active = self.is_active(session_id);
        let Some(session) = self
            .state
            .sessions
            .iter_mut()
            .find(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };

        let summary = payload.summary.trim();
        if summary.is_empty() {
            return Err(api_error(StatusCode::BAD_REQUEST, "记忆摘要不能为空"));
        }

        let kind = payload
            .kind
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or("note")
            .chars()
            .take(32)
            .collect::<String>();
        let layer =
            runtime::normalize_memory_layer(payload.layer.as_deref(), payload.kind.as_deref())
                .as_str()
                .to_string();
        let source = payload
            .source
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .unwrap_or("chat-room")
            .chars()
            .take(64)
            .collect::<String>();
        let summary = summary.chars().take(240).collect::<String>();
        let signature = memory_bead_signature(&layer, &kind, &source, &summary);
        let now = unix_timestamp_millis();

        if let Some(existing) = session
            .memory_beads
            .iter_mut()
            .find(|bead| bead.signature() == signature)
        {
            existing.pinned = existing.pinned || payload.pinned.unwrap_or(false);
            existing.confidence = existing.confidence.max(
                payload
                    .confidence
                    .unwrap_or(existing.confidence)
                    .clamp(0.0, 1.0),
            );
            existing.created_at = existing.created_at.max(now);
            session.updated_at = now;
            let response = session_beads_response(session, is_active);
            self.save()?;
            return Ok(Json(response));
        }

        let bead_id = format!("bead-{}", unix_timestamp_millis());
        let bead = MemoryBeadDto {
            id: bead_id.clone(),
            kind,
            layer,
            summary,
            source,
            pinned: payload.pinned.unwrap_or(false),
            confidence: payload.confidence.unwrap_or(0.74).clamp(0.0, 1.0),
            created_at: now,
            origin_message_id: payload.origin_message_id.clone(),
            origin_table: payload.origin_table.clone(),
            token_count: payload.token_count,
        };

        session.memory_beads.push(bead);
        session.prune_memory_beads();
        session.updated_at = now;
        // C 冲突消解（安全版）：仅显式提供 entity_key 时取代同实体旧 active bead（零误删）。
        if let Some(entity_key) = payload
            .entity_key
            .as_deref()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            record_entity_supersede(session_id, entity_key, &bead_id);
        }
        let response = session_beads_response(session, is_active);
        self.save()?;
        Ok(Json(response))
    }

    fn update_memory_bead(
        &mut self,
        session_id: &str,
        bead_id: &str,
        payload: UpdateMemoryBeadRequest,
    ) -> ApiResult<Json<SessionBeadsResponse>> {
        let is_active = self.is_active(session_id);
        let Some(session) = self
            .state
            .sessions
            .iter_mut()
            .find(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };
        let Some(position) = session
            .memory_beads
            .iter()
            .position(|bead| bead.id == bead_id)
        else {
            return Err(api_error(
                StatusCode::NOT_FOUND,
                "记忆 bead 不存在或为默认派生 bead",
            ));
        };

        let kind_update = payload.kind.clone();
        let layer_update = payload.layer.clone();
        let source_update = payload.source.clone();
        let pinned_update = payload.pinned;
        let confidence_update = payload.confidence;

        let bead = &mut session.memory_beads[position];
        if let Some(summary) = payload.summary {
            let summary = summary.trim();
            if summary.is_empty() {
                return Err(api_error(StatusCode::BAD_REQUEST, "记忆摘要不能为空"));
            }
            bead.summary = summary.chars().take(240).collect();
        }
        if let Some(kind) = kind_update.as_deref() {
            bead.kind = kind.trim().chars().take(32).collect();
            if bead.kind.is_empty() {
                bead.kind = "note".to_string();
            }
        }
        if let Some(source) = source_update {
            bead.source = source.trim().chars().take(64).collect();
            if bead.source.is_empty() {
                bead.source = "manual".to_string();
            }
        }
        if layer_update.is_some() || kind_update.is_some() {
            bead.layer = runtime::normalize_memory_layer(layer_update.as_deref(), Some(&bead.kind))
                .as_str()
                .to_string();
        }
        if let Some(pinned) = pinned_update {
            bead.pinned = pinned;
        }
        if let Some(confidence) = confidence_update {
            bead.confidence = confidence.clamp(0.0, 1.0);
        }
        session.updated_at = unix_timestamp_millis();
        let response = session_beads_response(session, is_active);
        self.save()?;
        Ok(Json(response))
    }

    fn delete_memory_bead(
        &mut self,
        session_id: &str,
        bead_id: &str,
    ) -> ApiResult<Json<SessionBeadsResponse>> {
        let is_active = self.is_active(session_id);
        let Some(session) = self
            .state
            .sessions
            .iter_mut()
            .find(|session| session.id == session_id)
        else {
            return Err(api_error(StatusCode::NOT_FOUND, "会话不存"));
        };
        let before = session.memory_beads.len();
        session.memory_beads.retain(|bead| bead.id != bead_id);
        if before == session.memory_beads.len() {
            return Err(api_error(
                StatusCode::NOT_FOUND,
                "记忆 bead 不存在或为默认派生 bead",
            ));
        }
        session.updated_at = unix_timestamp_millis();
        let response = session_beads_response(session, is_active);
        self.save()?;
        Ok(Json(response))
    }

    fn active_session_id(&self) -> Option<String> {
        self.state.active_session_id.clone().or_else(|| {
            self.state
                .sessions
                .first()
                .map(|session| session.id.clone())
        })
    }

    fn is_active(&self, session_id: &str) -> bool {
        self.active_session_id().as_deref() == Some(session_id)
    }

    fn active_chat_room_id(&self) -> Option<String> {
        self.state
            .active_chat_room_id
            .clone()
            .or_else(|| self.state.chat_rooms.first().map(|room| room.id.clone()))
    }

    fn is_active_chat_room(&self, room_id: &str) -> bool {
        self.active_chat_room_id().as_deref() == Some(room_id)
    }
}

fn load_session_state_from_json(path: &Path) -> Option<PersistedSessionState> {
    std::fs::read_to_string(path)
        .ok()
        .and_then(|content| serde_json::from_str::<PersistedSessionState>(&content).ok())
}

fn load_session_state_from_sqlite(path: &Path) -> Option<PersistedSessionState> {
    if !path.exists() {
        return None;
    }
    match read_session_state_from_sqlite(path) {
        Ok(state) => Some(state),
        Err(error) => {
            warn!("SQLite session store load failed: {error}");
            None
        }
    }
}

fn open_session_connection(path: &Path) -> rusqlite::Result<Connection> {
    let connection = Connection::open(path)?;
    connection.execute_batch(
        r#"
        PRAGMA foreign_keys = ON;
        PRAGMA journal_mode = WAL;
        PRAGMA busy_timeout = 5000;
        "#,
    )?;
    Ok(connection)
}

fn initialize_session_schema(connection: &Connection) -> rusqlite::Result<()> {
    connection.execute_batch(
        r#"
        CREATE TABLE IF NOT EXISTS metadata (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS sessions (
            id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            provider TEXT NOT NULL,
            model TEXT NOT NULL,
            base_url TEXT,
            endpoint TEXT,
            reasoning_effort TEXT NOT NULL DEFAULT 'medium',
            api_key_ref TEXT NOT NULL,
            created_at INTEGER NOT NULL,
            updated_at INTEGER NOT NULL,
            context_reset_at INTEGER NOT NULL DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS chat_rooms (
            id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            created_at INTEGER NOT NULL,
            updated_at INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS session_messages (
            session_id TEXT NOT NULL,
            id TEXT NOT NULL,
            author TEXT NOT NULL,
            role TEXT NOT NULL,
            target TEXT NOT NULL,
            content TEXT NOT NULL,
            kind TEXT NOT NULL,
            attachments_json TEXT NOT NULL,
            created_at INTEGER NOT NULL,
            PRIMARY KEY (session_id, id),
            FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
        );
        CREATE TABLE IF NOT EXISTS chat_room_messages (
            room_id TEXT NOT NULL,
            id TEXT NOT NULL,
            author TEXT NOT NULL,
            role TEXT NOT NULL,
            target TEXT NOT NULL,
            content TEXT NOT NULL,
            kind TEXT NOT NULL,
            attachments_json TEXT NOT NULL,
            created_at INTEGER NOT NULL,
            PRIMARY KEY (room_id, id),
            FOREIGN KEY (room_id) REFERENCES chat_rooms(id) ON DELETE CASCADE
        );
        CREATE TABLE IF NOT EXISTS memory_beads (
            session_id TEXT NOT NULL,
            id TEXT NOT NULL,
            kind TEXT NOT NULL,
            layer TEXT NOT NULL,
            summary TEXT NOT NULL,
            source TEXT NOT NULL,
            pinned INTEGER NOT NULL,
            confidence REAL NOT NULL,
            created_at INTEGER NOT NULL,
            PRIMARY KEY (session_id, id),
            FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
        );
        CREATE INDEX IF NOT EXISTS idx_session_messages_created
            ON session_messages(session_id, created_at);
        CREATE INDEX IF NOT EXISTS idx_chat_room_messages_created
            ON chat_room_messages(room_id, created_at);
        CREATE INDEX IF NOT EXISTS idx_memory_beads_session_layer
            ON memory_beads(session_id, layer, created_at);
        "#,
    )?;
    ensure_session_column(connection, "base_url", "TEXT")?;
    ensure_session_column(connection, "endpoint", "TEXT")?;
    ensure_session_column(
        connection,
        "reasoning_effort",
        "TEXT NOT NULL DEFAULT 'medium'",
    )?;
    ensure_session_column(connection, "model_type", "TEXT NOT NULL DEFAULT 'text'")?;
    ensure_session_column(connection, "avatar", "TEXT")?;
    ensure_session_column(connection, "context_reset_at", "INTEGER NOT NULL DEFAULT 0")?;
    apply_session_migration_v2(connection)?;
    apply_session_migration_v3(connection)?;
    apply_session_migration_v4(connection)?;
    apply_session_migration_v5(connection)?;
    apply_session_migration_v6(connection)?;
    apply_session_migration_v7(connection)?;
    apply_session_migration_v8(connection)?;
    apply_session_migration_v9(connection)?;
    apply_session_migration_v10(connection)?;
    computer_use_store::apply_session_migration_v11(connection)?;
    apply_session_migration_v12(connection)?;
    apply_session_migration_v13(connection)?;
    apply_session_migration_v14(connection)?;
    apply_session_migration_v15(connection)?;
    Ok(())
}

fn apply_session_migration_v12(connection: &Connection) -> rusqlite::Result<()> {
    let current: i64 = connection.query_row("PRAGMA user_version", [], |row| row.get(0))?;
    connection.execute_batch(
        r#"
        CREATE TABLE IF NOT EXISTS chat_room_permissions (
            room_id TEXT PRIMARY KEY,
            permission_profile TEXT NOT NULL DEFAULT 'workspace-write'
                CHECK (permission_profile IN ('workspace-write', 'full-access')),
            updated_at INTEGER NOT NULL
        );
        "#,
    )?;
    if current < 12 {
        connection.execute_batch("PRAGMA user_version = 12;")?;
    }
    Ok(())
}

/// v13 给 `goal_phases` 补齐的回退路由列，兼作迁移与测试的单一事实源。
///
/// `retry_count` / `max_retries` 给重试上限用；`last_verdict` / `last_reason` /
/// `last_evidence_json` 承载 verifier 的结论与证据；`route_hint` 供路由决策记录
/// 下一跳意图。后三者可为空——阶段尚未产生结论时就是没有值，用 NULL 表达比用
/// 空串更诚实。
const GOAL_PHASE_ROUTING_COLUMNS: &[(&str, &str)] = &[
    ("retry_count", "INTEGER NOT NULL DEFAULT 0"),
    ("max_retries", "INTEGER NOT NULL DEFAULT 2"),
    ("last_verdict", "TEXT"),
    ("last_reason", "TEXT"),
    ("last_evidence_json", "TEXT"),
    ("route_hint", "TEXT"),
];

/// Schema v13（GL-01 · Goal 循环状态图化）：`goal_phases` 增加回退路由所需的 6 列。
///
/// 背景见 `DESIGN-GOAL-LOOP-001`：phase 此前只有 status，无法承载
/// verifier→implementer、implementer→planner 的带证据回退与重试上限，
/// Goal Runner 因此只能单向前进（`CUR-GOAL-LOOP-001`）。
///
/// 刻意逐列 `ALTER TABLE ADD COLUMN` 而不重建表：`goal_phases` 通过外键挂在
/// `goals` 上，重建会触发级联删除。加列本身不改动既有行的其它字段，旧行落到
/// `retry_count=0 / max_retries=2` 的默认值上。
fn apply_session_migration_v13(connection: &Connection) -> rusqlite::Result<()> {
    let current: i64 = connection.query_row("PRAGMA user_version", [], |row| row.get(0))?;
    // 不靠 user_version 短路：即使版本号已被写到 13，也要确认列真的存在，
    // 免得中途失败的迁移留下"版本已推进但列没加"的库。
    for (column, column_type) in GOAL_PHASE_ROUTING_COLUMNS {
        ensure_table_column(connection, "goal_phases", column, column_type)?;
    }
    if current < 13 {
        connection.execute_batch("PRAGMA user_version = 13;")?;
    }
    Ok(())
}

/// Schema v14（GL-10）：chat_handoffs 增 `contract_json`，承载结构化交接契约
/// （from/to/verdict/reason/evidence/retry_count 等）。可空——旧记录与非回退交接为 NULL，
/// 读回时降级成原有文本摘要展示，向后兼容。
fn apply_session_migration_v14(connection: &Connection) -> rusqlite::Result<()> {
    let current: i64 = connection.query_row("PRAGMA user_version", [], |row| row.get(0))?;
    ensure_table_column(connection, "chat_handoffs", "contract_json", "TEXT")?;
    if current < 14 {
        connection.execute_batch("PRAGMA user_version = 14;")?;
    }
    Ok(())
}

/// Schema v15（GL-13 · human-in-the-loop 断点）：goal_phases 增两列。
/// `requires_human_ack`（默认 0）标记「派发前必须人工确认」的高风险阶段；
/// `human_ack`（NULL/"approved"/"rejected"）记录确认结论，兼作「已发过等待事件」的幂等标志。
fn apply_session_migration_v15(connection: &Connection) -> rusqlite::Result<()> {
    let current: i64 = connection.query_row("PRAGMA user_version", [], |row| row.get(0))?;
    ensure_table_column(
        connection,
        "goal_phases",
        "requires_human_ack",
        "INTEGER NOT NULL DEFAULT 0",
    )?;
    ensure_table_column(connection, "goal_phases", "human_ack", "TEXT")?;
    if current < 15 {
        connection.execute_batch("PRAGMA user_version = 15;")?;
    }
    Ok(())
}

fn chat_room_permission_profile_sqlite(path: &Path, room_id: &str) -> rusqlite::Result<String> {
    let connection = open_session_connection(path)?;
    initialize_session_schema(&connection)?;
    connection
        .query_row(
            "SELECT permission_profile FROM chat_room_permissions WHERE room_id = ?1",
            params![room_id],
            |row| row.get(0),
        )
        .optional()
        .map(|profile| profile.unwrap_or_else(|| ROOM_PERMISSION_WORKSPACE_WRITE.to_string()))
}

fn set_chat_room_permission_profile_sqlite(
    path: &Path,
    room_id: &str,
    permission_profile: &str,
) -> rusqlite::Result<()> {
    if !matches!(
        permission_profile,
        ROOM_PERMISSION_WORKSPACE_WRITE | ROOM_PERMISSION_FULL_ACCESS
    ) {
        return Err(rusqlite::Error::InvalidParameterName(
            "permission_profile".to_string(),
        ));
    }
    let connection = open_session_connection(path)?;
    initialize_session_schema(&connection)?;
    connection.execute(
        "INSERT INTO chat_room_permissions(room_id, permission_profile, updated_at) \
         VALUES (?1, ?2, ?3) \
         ON CONFLICT(room_id) DO UPDATE SET \
           permission_profile = excluded.permission_profile, \
           updated_at = excluded.updated_at",
        params![
            room_id,
            permission_profile,
            u64_to_i64(unix_timestamp_millis())
        ],
    )?;
    Ok(())
}

fn chat_room_permission_record_sqlite(
    path: &Path,
    room_id: &str,
) -> rusqlite::Result<(String, Option<u64>)> {
    let connection = open_session_connection(path)?;
    initialize_session_schema(&connection)?;
    connection
        .query_row(
            "SELECT permission_profile, updated_at FROM chat_room_permissions WHERE room_id = ?1",
            params![room_id],
            |row| {
                let profile: String = row.get(0)?;
                let updated_at: i64 = row.get(1)?;
                Ok((profile, Some(updated_at.max(0) as u64)))
            },
        )
        .optional()
        .map(|record| record.unwrap_or_else(|| (ROOM_PERMISSION_WORKSPACE_WRITE.to_string(), None)))
}

/// REQ-WEB-SESSION-007 / REQ-MEM-006：Schema v2 迁移。
///
/// - `memory_beads` 增加 `origin_message_id / origin_table / token_count`。
///   为删除消息时连带删除衍生 bead 做准备（trigger 自动执行）。
/// - 新增 `attachment_refs` 表，登记消息 "附件文件名映射，配合未来附件 GC。
///
/// 幂等：通过 `PRAGMA user_version` + `ensure_memory_bead_column` 保护。
/// 不破"v1 读写路径：全表重"`save_session_state_to_sqlite` 不触及新"新表
/// （不"DELETE/INSERT 列表），已有数据通过 ALTER 原地保留。
fn apply_session_migration_v2(connection: &Connection) -> rusqlite::Result<()> {
    let current: i64 = connection.query_row("PRAGMA user_version", [], |row| row.get(0))?;

    ensure_memory_bead_column(connection, "origin_message_id", "TEXT")?;
    ensure_memory_bead_column(connection, "origin_table", "TEXT")?;
    ensure_memory_bead_column(connection, "token_count", "INTEGER")?;

    connection.execute_batch(
        r#"
        CREATE TABLE IF NOT EXISTS attachment_refs (
            id           TEXT PRIMARY KEY,
            message_id   TEXT NOT NULL,
            message_tbl  TEXT NOT NULL
                CHECK (message_tbl IN ('session_messages','chat_room_messages')),
            file_name    TEXT NOT NULL,
            byte_size    INTEGER NOT NULL DEFAULT 0,
            created_at   INTEGER NOT NULL
        );
        CREATE INDEX IF NOT EXISTS idx_attachment_refs_message
            ON attachment_refs(message_id);
        CREATE INDEX IF NOT EXISTS idx_attachment_refs_filename
            ON attachment_refs(file_name);
        CREATE TRIGGER IF NOT EXISTS trg_session_msg_cascade_beads
        AFTER DELETE ON session_messages
        BEGIN
            DELETE FROM memory_beads
            WHERE origin_table = 'session_messages'
              AND origin_message_id = OLD.id;
        END;
        CREATE TRIGGER IF NOT EXISTS trg_room_msg_cascade_beads
        AFTER DELETE ON chat_room_messages
        BEGIN
            DELETE FROM memory_beads
            WHERE origin_table = 'chat_room_messages'
              AND origin_message_id = OLD.id;
        END;
        "#,
    )?;

    if current < 2 {
        connection.execute_batch("PRAGMA user_version = 2;")?;
    }
    Ok(())
}

