fn goal_role_template_bead(role: &str, now: u64) -> MemoryBeadDto {
    let summary = match role {
        "commander" => "Goal role commander: run brainstorming, role allocation, handoff checkpoints, long-task monitoring, and final cleanup. Skill overlay: superpowers:brainstorming, superpowers:subagent-driven-development, superpowers:verification-before-completion.",
        "planner" => "Goal role planner: decompose user goals into ordered phases, dependencies, completion conditions, and risk checkpoints. For phases needing deterministic checks, attach Command verification (verification: {type: \"Command\", commands: [\"cargo build --offline\", ...]}) so build/test exit codes gate completion; a non-zero exit auto-routes the phase back to implementer.",
        "implementer" => "Goal role implementer: make focused code or content changes for assigned phases, keep edits scoped, and report changed files.",
        "debugger" => "Goal role debugger: isolate failures systematically before fixes, capture reproduction steps, and verify root causes. Skill overlay: superpowers:systematic-debugging.",
        "qa" => "Goal role QA: run test plans, compare expected and actual behavior, and require evidence before completion. Skill overlay: superpowers:test-driven-development, superpowers:verification-before-completion.",
        "reviewer" => "Goal role reviewer: inspect outputs for regressions, missing tests, unsafe assumptions, and incomplete acceptance criteria.",
        "designer" => "Goal role designer: refine user experience, layout, copy, and interaction details before implementation starts.",
        "tester" => "Goal role tester: create and run verification plans, collect evidence, and distinguish automated checks from human interaction tests.",
        "releaser" => "Goal role releaser: prepare release notes, migration notes, rollback guidance, and final readiness checks.",
        "documenter" => "Goal role documenter: update requirements, work logs, user-facing notes, and implementation rationale after each completed slice.",
        "verifier" => "Goal role verifier: confirm phase completion against evidence, reject weak claims, and request fixes before commander approval. Command-type verification is auto-executed by the runtime; a non-zero exit is an automatic rejection routed back to implementer with the captured error output.",
        _ => "Goal role worker: follow assigned responsibility, use approved tools, and provide concise evidence for each phase.",
    };
    MemoryBeadDto {
        id: format!("goal-role-template-{role}"),
        kind: "goal-role".to_string(),
        layer: "L1".to_string(),
        summary: summary.to_string(),
        source: "goal-role-template".to_string(),
        pinned: true,
        confidence: 1.0,
        created_at: now,
        origin_message_id: None,
        origin_table: None,
        token_count: Some(estimate_bead_tokens(summary)),
    }
}

struct SqliteMessagePage {
    messages: Vec<PersistedChatMessage>,
    total: usize,
    has_more: bool,
}

struct SqliteBeadPage {
    beads: Vec<MemoryBeadDto>,
    total: usize,
    has_more: bool,
}

fn query_session_messages_sqlite(
    conn: &rusqlite::Connection,
    session_id: &str,
    limit: usize,
    offset: usize,
) -> rusqlite::Result<SqliteMessagePage> {
    let total: usize = conn.query_row(
        "SELECT COUNT(*) FROM session_messages WHERE session_id = ?1",
        rusqlite::params![session_id],
        |row| row.get(0),
    )?;
    let mut stmt = conn.prepare(
        "SELECT id, author, role, target, content, kind, attachments_json, created_at
         FROM session_messages WHERE session_id = ?1
         ORDER BY created_at, id LIMIT ?2 OFFSET ?3",
    )?;
    let rows = stmt.query_map(
        rusqlite::params![session_id, limit as i64, offset as i64],
        persisted_message_from_row,
    )?;
    let mut messages = Vec::new();
    for msg in rows {
        messages.push(msg?);
    }
    Ok(SqliteMessagePage {
        messages,
        total,
        has_more: offset + limit < total,
    })
}

