fn active_pending_approval_count() -> usize {
    pending_approvals()
        .lock()
        .ok()
        .map(|map| {
            let now = Instant::now();
            map.values()
                .filter(|record| now.duration_since(record.created_at) < PENDING_APPROVAL_TTL)
                .count()
        })
        .unwrap_or_default()
}

fn office_tool_robot_state(pending_count: usize, audit_statuses: &[&str]) -> &'static str {
    if pending_count > 0 {
        return "waiting";
    }
    if audit_statuses.iter().any(|status| {
        let normalized = status.trim().to_ascii_lowercase();
        matches!(
            normalized.as_str(),
            "failed" | "rejected" | "timeout" | "error"
        )
    }) {
        return "warning";
    }
    if audit_statuses.iter().any(|status| {
        let normalized = status.trim().to_ascii_lowercase();
        matches!(normalized.as_str(), "ok" | "dry-run-only" | "success")
    }) {
        return "active";
    }
    "idle"
}

fn chat_room_roster_from_state(
    state: &PersistedSessionState,
    room_id: &str,
    me: Option<&str>,
) -> ApiResult<ChatRosterResponse> {
    let Some(room) = state.chat_rooms.iter().find(|room| room.id == room_id) else {
        return Err(api_error(StatusCode::NOT_FOUND, "聊天室不存在"));
    };
    let me = me.map(str::trim).filter(|value| !value.is_empty());
    let members = state
        .sessions
        .iter()
        .filter(|session| me != Some(session.id.as_str()))
        .map(|session| ChatRosterMemberDto {
            session_id: session.id.clone(),
            name: session.name.clone(),
            display_name: session_display_name_for(
                &session.name,
                &session.provider,
                &session.model,
                session.base_url.as_deref(),
                session.endpoint.as_deref(),
            ),
            provider: session.provider.clone(),
            model: session.model.clone(),
            model_type: normalize_model_type(Some(&session.model_type)),
            active: state.active_session_id.as_deref() == Some(session.id.as_str()),
            available: !session.model.trim().is_empty() && !session.provider.trim().is_empty(),
        })
        .collect::<Vec<_>>();

    Ok(ChatRosterResponse {
        room_id: room.id.clone(),
        room_name: room.name.clone(),
        generated_at: unix_timestamp_millis(),
        members,
    })
}

fn overview_vision_agent_from_session(session: &PersistedSession) -> OverviewVisionAgent {
    OverviewVisionAgent {
        id: session.id.clone(),
        name: session.name.clone(),
        display_name: session_display_name_for(
            &session.name,
            &session.provider,
            &session.model,
            session.base_url.as_deref(),
            session.endpoint.as_deref(),
        ),
        provider: session.provider.clone(),
        model: session.model.clone(),
    }
}

fn understanding_agent_from_session(
    session: &PersistedSession,
    active_session_id: Option<&str>,
) -> UnderstandingAgentDto {
    let model_type = normalize_model_type(Some(&session.model_type));
    UnderstandingAgentDto {
        session_id: session.id.clone(),
        display_name: session_display_name_for(
            &session.name,
            &session.provider,
            &session.model,
            session.base_url.as_deref(),
            session.endpoint.as_deref(),
        ),
        provider: session.provider.clone(),
        model: session.model.clone(),
        model_type: model_type.clone(),
        base_url: effective_agent_base_url_impl(session.base_url.as_deref(), &session.provider),
        api_key_status: if session.api_key_ref.trim().is_empty() {
            "待配".to_string()
        } else {
            format!("引用 {}", api_key_status_label(&session.api_key_ref))
        },
        capabilities: UnderstandingCapabilities {
            describe_screen: true,
            analyze_image: true,
            analyze_video: model_type == "video",
            multimodal_chat: model_type == "multimodal",
        },
        active: active_session_id == Some(session.id.as_str()),
        updated_at: session.updated_at,
    }
}

fn is_understanding_model_type(model_type: &str) -> bool {
    matches!(
        normalize_model_type(Some(model_type)).as_str(),
        "vision" | "multimodal" | "video"
    )
}

fn is_multimodal_agent(agent: &AgentSessionDto) -> bool {
    if is_understanding_model_type(&agent.model_type) {
        return true;
    }
    let haystack = format!("{} {}", agent.model, agent.model_type).to_lowercase();
    [
        "vision",
        "vl",
        "glm-4.1v",
        "glm-4v",
        "qwen2.5-vl",
        "multimodal",
        "image",
        "视觉",
        "多模",
    ]
    .iter()
    .any(|keyword| haystack.contains(keyword))
}

/// 是否含明确的 GUI 操作动作意图（点击 / 打开 / 拖拽 / 输入 / 选中 / 滚动…）。
/// 用于把"看 / 描述 / 识别屏幕"这类纯视觉理解请求与"对屏幕执行操作"区分开，
/// 避免纯理解请求被误路由到 computer-use 视觉动作侧路而真实点击桌面。
fn vision_request_has_action_intent(text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    contains_any(
        &lower,
        &[
            "点击",
            "单击",
            "双击",
            "右键",
            "点一下",
            "点开",
            "拖",
            "打开",
            "关闭",
            "操作",
            "选中",
            "勾选",
            "按下",
            "输入",
            "键入",
            "打字",
            "滚动",
            "滑动",
            "click",
            "open",
            "close",
            "drag",
            "select",
            "press",
            "type",
            "scroll",
            "tap",
            "operate",
        ],
    )
}

fn should_route_to_vision_agent(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    [
        "当前桌面",
        "你看",
        "看一",
        "截图",
        "视觉",
        "screen",
        "desktop",
    ]
    .iter()
    .any(|keyword| text.contains(keyword))
}

fn should_route_to_tool_agent(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    [
        "打开", "关闭", "点击", "输入", "执行", "命令", "文件", "鼠标", "键盘", "click", "type",
    ]
    .iter()
    .any(|keyword| text.contains(keyword))
}

