fn memory_bead_signature(layer: &str, kind: &str, source: &str, summary: &str) -> String {
    runtime::memory_bead_signature(layer, kind, source, summary)
}

/// 记忆 kind 的基础价值权重：任务步骤/结果/决策 > 工具 > 事实 > 普通问答。
/// 简单聊天问答价值最低，最易随老化被淘汰。
fn memory_bead_kind_weight(kind: &str) -> f64 {
    match kind.to_ascii_lowercase().as_str() {
        "decision" => 1.0,
        "tool" => 0.95,
        "result" | "task" => 0.9,
        "fact" => 0.75,
        "reasoning" => 0.6,
        "chat" => 0.3,
        _ => 0.5,
    }
}

/// 把摘要切成去重的关键词集合（长度≥2 的 token 或 CJK 单字），用于估算消息间关联度。
fn memory_bead_keywords(summary: &str) -> std::collections::HashSet<String> {
    let mut set = std::collections::HashSet::new();
    let mut ascii_token = String::new();
    for ch in summary.chars() {
        if ('\u{4E00}'..='\u{9FFF}').contains(&ch) {
            // CJK 单字作为 token
            set.insert(ch.to_string());
            if ascii_token.len() >= 2 {
                set.insert(ascii_token.to_ascii_lowercase());
            }
            ascii_token.clear();
        } else if ch.is_ascii_alphanumeric() {
            ascii_token.push(ch);
        } else {
            if ascii_token.len() >= 2 {
                set.insert(ascii_token.to_ascii_lowercase());
            }
            ascii_token.clear();
        }
    }
    if ascii_token.len() >= 2 {
        set.insert(ascii_token.to_ascii_lowercase());
    }
    set
}

/// 估算某 bead 在"记忆星图"中的关联度（连接的其它消息数）：
/// 与其它 bead 共享 source（同一发起者/任务）或关键词重叠≥2 即视为有连接。
/// 关联度越高，价值越大（星图中连线越多），越不易老化。
fn memory_bead_connection_degree(bead: &MemoryBeadDto, all: &[MemoryBeadDto]) -> usize {
    let keywords = memory_bead_keywords(&bead.summary);
    all.iter()
        .filter(|other| other.id != bead.id)
        .filter(|other| {
            if !other.source.is_empty() && other.source == bead.source {
                return true;
            }
            let other_kw = memory_bead_keywords(&other.summary);
            keywords.intersection(&other_kw).count() >= 2
        })
        .count()
}

/// 综合价值分：kind 权重 + 关联度（星图连线数）+ 置信度 + 时间新鲜度。
/// pinned 由调用方单独豁免（永不老化），此处不计入。
fn memory_bead_value_score(bead: &MemoryBeadDto, all: &[MemoryBeadDto], newest_at: u64) -> f64 {
    let degree = memory_bead_connection_degree(bead, all) as f64;
    let degree_score = (1.0 + degree).ln() * 0.6;
    let kind_score = memory_bead_kind_weight(&bead.kind);
    let confidence_score = f64::from(bead.confidence).clamp(0.0, 1.0) * 0.4;
    let recency = if newest_at > 0 {
        (bead.created_at as f64 / newest_at as f64).clamp(0.0, 1.0) * 0.3
    } else {
        0.0
    };
    kind_score + degree_score + confidence_score + recency
}

/// 价值感知老化：保留全部 pinned；非 pinned 按价值分降序保留，淘汰低价值（简单问答）。
fn age_out_memory_beads_by_value(beads: &mut Vec<MemoryBeadDto>, max_beads: usize) {
    if beads.len() <= max_beads {
        return;
    }
    let snapshot = beads.clone();
    let newest_at = snapshot.iter().map(|b| b.created_at).max().unwrap_or(0);
    let mut pinned: Vec<MemoryBeadDto> = Vec::new();
    let mut rest: Vec<(f64, MemoryBeadDto)> = Vec::new();
    for bead in &snapshot {
        if bead.pinned {
            pinned.push(bead.clone());
        } else {
            let score = memory_bead_value_score(bead, &snapshot, newest_at);
            rest.push((score, bead.clone()));
        }
    }
    rest.sort_by(|a, b| {
        b.0.total_cmp(&a.0)
            .then_with(|| b.1.created_at.cmp(&a.1.created_at))
    });
    let keep_rest = max_beads.saturating_sub(pinned.len());
    let mut result = pinned;
    result.extend(rest.into_iter().take(keep_rest).map(|(_, bead)| bead));
    result.sort_by(|a, b| b.created_at.cmp(&a.created_at));
    *beads = result;
}

fn memory_beads_summary(
    beads: &[MemoryBeadDto],
    explicit_count: usize,
    defaulted: bool,
) -> MemoryBeadsSummaryDto {
    let summary = runtime::summarize_memory_beads(
        beads,
        explicit_count,
        defaulted,
        MAX_MEMORY_BEADS_PER_SESSION,
    );
    MemoryBeadsSummaryDto {
        total: summary.total,
        explicit: summary.explicit,
        defaulted: summary.defaulted,
        pinned: summary.pinned,
        prompt_candidates: summary.prompt_candidates,
        by_layer: summary.by_layer,
        by_kind: summary.by_kind,
        max_beads: summary.max_beads,
    }
}

fn session_beads_response(session: &PersistedSession, active: bool) -> SessionBeadsResponse {
    let beads = session.memory_beads.clone();
    let summary = memory_beads_summary(
        &beads,
        session.memory_beads.len(),
        session.memory_beads.is_empty(),
    );
    SessionBeadsResponse {
        session: session.summary(active),
        beads,
        summary,
    }
}

