struct MemoryBeadQuery {
    q: Option<String>,
    layer: Option<String>,
    kind: Option<String>,
    prompt_only: Option<bool>,
    limit: Option<usize>,
}

impl MemoryBeadQuery {
    fn to_runtime_options(&self, default_limit: usize, max_limit: usize) -> MemoryBeadQueryOptions {
        MemoryBeadQueryOptions {
            q: self.q.clone(),
            layer: self.layer.clone(),
            kind: self.kind.clone(),
            prompt_only: self.prompt_only.unwrap_or(false),
            limit: self.limit.unwrap_or(default_limit).clamp(1, max_limit),
        }
    }
}

