#[derive(Debug, Deserialize)]
struct ToolDispatchRequest {
    intent: String,
    execute: Option<bool>,
    confirm_after: Option<bool>,
    roi_radius: Option<u32>,
    text: Option<String>,
    target: Option<String>,
    menu_item: Option<String>,
    raw_response: Option<String>,
    capture_path: Option<String>,
    use_latest_capture: Option<bool>,
    use_model: Option<bool>,
    #[serde(default)]
    system_control: Option<String>,
}

impl Default for ToolDispatchRequest {
    fn default() -> Self {
        Self {
            intent: String::new(),
            execute: None,
            confirm_after: None,
            roi_radius: None,
            text: None,
            target: None,
            menu_item: None,
            raw_response: None,
            capture_path: None,
            use_latest_capture: None,
            use_model: None,
            system_control: None,
        }
    }
}

