#[instrument]
async fn api_audio_stt_start(
    Json(request): Json<SttStartRequest>,
) -> Result<Json<SttStartResponse>, ApiError> {
    info!(
        "Starting STT session, encoder: {:?}, rate: {:?}",
        request.encoder, request.sample_rate
    );

    let session_id = uuid_timestamp().to_string();
    let msg = if request.audio_path.is_some() {
        "Recording session created with pre-existing audio file"
    } else {
        "Recording session created; record audio and POST to /api/audio/stt/stop with this session_id and audio_path"
    };

    Ok(Json(SttStartResponse {
        session_id,
        status: "recording".to_string(),
        message: msg.to_string(),
    }))
}

#[instrument]
async fn api_audio_stt_stop(
    Json(request): Json<SttStopRequest>,
) -> Result<Json<SttStopResponse>, ApiError> {
    info!("Stopping STT session: {}", request.session_id);

    let stt_config = audio::SttConfig::default();
    let engine = audio::SttEngine::new(stt_config);

    let audio_path = if let Some(ref path) = request.audio_path {
        path.clone()
    } else {
        let webm = std::env::temp_dir().join(format!("{}.webm", request.session_id));
        let wav = std::env::temp_dir().join(format!("{}.wav", request.session_id));
        if webm.exists() {
            webm
        } else {
            wav
        }
    };

    if !audio_path.exists() {
        warn!("No audio file found: {:?}", audio_path);
        return Err(api_error(
            StatusCode::NOT_FOUND,
            &format!("No audio file found: {:?}", audio_path),
        ));
    }

    match engine.transcribe_file(&audio_path).await {
        Ok(result) => {
            info!(
                "STT transcription completed in {}ms, {} segments",
                result.duration_ms,
                result.segments.len()
            );
            if let Ok(mut state) = audio_realtime_state().lock() {
                if state.running {
                    state.last_text = Some(result.text.clone());
                    state.last_error = None;
                    state.updated_at_ms = uuid_timestamp();
                }
            }
            let _ = tokio::fs::remove_file(&audio_path).await;
            Ok(Json(SttStopResponse {
                text: result.text,
                segments: result.segments,
                confidence: result.confidence,
                duration_ms: result.duration_ms,
            }))
        }
        Err(e) => {
            error!("STT transcription failed: {}", e);
            Err(api_error(StatusCode::INTERNAL_SERVER_ERROR, &e))
        }
    }
}

