    #[tokio::test]
    async fn dispatch_summary_exposes_llm_tool_call_contract() {
        let response = super::run_tool_dispatch(ToolDispatchRequest {
            intent: "使用 Ctrl+L 快捷键聚焦地址".to_string(),
            execute: Some(false),
            confirm_after: Some(true),
            roi_radius: Some(64),
            text: None,
            target: None,
            menu_item: None,
            raw_response: None,
            capture_path: None,
            use_latest_capture: None,
            use_model: None,
            system_control: None,
        })
        .await
        .expect("dispatch should build");

        // 详情仍暴露 LLM tool call 契约（供模型兜底 / 诊断日志）。
        let detail = super::dispatch_plan_detail(&response);
        assert!(detail.contains("LLM tool call dry-run：computer.hotkey"));
        assert!(detail.contains("execute_allowed=false"));
        assert!(detail.contains("当前只展示 dry-run 计划"));

        // #3：聊天室 summary 只保留结果，过程细节（语义工具调度 / 安全闸门）不再出现在聊天消息里。
        let summary = super::dispatch_plan_chat_summary(&response);
        assert!(summary.contains("computer.hotkey"));
        assert!(!summary.contains("安全闸门"));
        assert!(!summary.contains("语义工具调度"));
    }

