    #[test]
    fn vision_tool_service_capabilities_reserve_describe_and_ocr() {
        let response = super::vision_tool_service_capabilities_response();

        let describe = response
            .capabilities
            .iter()
            .find(|capability| capability.capability == "describe")
            .expect("describe capability");
        let ocr = response
            .capabilities
            .iter()
            .find(|capability| capability.capability == "ocr")
            .expect("ocr capability");
        let ground_point = response
            .capabilities
            .iter()
            .find(|capability| capability.capability == "ground_point")
            .expect("ground point capability");

        assert_eq!(describe.status, "reserved");
        assert_eq!(ocr.status, "reserved");
        assert_eq!(describe.endpoint, "/api/vision/tool-service/describe");
        assert_eq!(ocr.endpoint, "/api/vision/tool-service/ocr");
        assert!(!describe.model_invoked_by_default);
        assert_eq!(ground_point.status, "available");

        let reserved = super::vision_reserved_capability_response(
            VisionToolCapability::Describe,
            "describe",
            super::VisionReservedCapabilityRequest {
                prompt: Some("read the screen".to_string()),
                capture_path: Some("C:\\tmp\\screen.png".to_string()),
            },
        );
        assert_eq!(reserved.status, "reserved");
        assert!(!reserved.model_invoked);
        assert_eq!(reserved.prompt, "read the screen");
    }

