    #[test]
    fn workspace_boundary_accepts_child_paths_only() {
        let root = std::path::PathBuf::from(r"C:\Users\example\Desktop\codex");
        let child = root.join("modules").join("gui-web");
        let outside = std::path::PathBuf::from(r"C:\Users\example\Desktop\other");
        assert!(super::workspace_is_within_allowed_roots(
            &child,
            &[root.clone()]
        ));
        assert!(super::workspace_is_within_allowed_roots(
            &root,
            &[root.clone()]
        ));
        assert!(!super::workspace_is_within_allowed_roots(&outside, &[root]));
    }

