    #[test]
    fn workspace_identity_is_stable_and_path_scoped() {
        let left = std::path::PathBuf::from(r"C:\Users\example\Desktop\codex");
        let same = std::path::PathBuf::from(r"C:\Users\example\Desktop\codex");
        let right = std::path::PathBuf::from(r"C:\Users\example\Desktop\opencode\master-project");

        assert_eq!(
            super::workspace_identity(&left),
            super::workspace_identity(&same)
        );
        assert_ne!(
            super::workspace_identity(&left),
            super::workspace_identity(&right)
        );

        let response = super::workspace_response_from_path(&left);
        assert_eq!(response.workspace_id, super::workspace_identity(&left));
        assert!(response.workspace_id.starts_with("ws-"));
    }

