    #[test]
    fn context_build_options_use_model_token_table_not_default_budget() {
        let mut agent = context_test_agent();
        agent.model = "qwen3.7-max".to_string();

        let options = super::context_build_options_for_agent(&agent);

        // 2026-05-31 接入输出预留：qwen3.x ctx=1M、max_output=65536，output_reserve=max(65536, 1M×15%)=150K，
        // usable=850K，再扣 1024 token 协议安全余量 → 848976；
        // history=848976×70%=594283、memory=848976×8%=67918。
        assert_eq!(options.history_token_budget, 594_283);
        assert_eq!(options.memory_token_budget, 67_918);
        assert_ne!(options.history_token_budget, 3_000);
    }

    #[test]
    fn custom_model_budget_not_starved_by_output_reserve() {
        let mut agent = context_test_agent();
        // custom provider 模型不在 token 表，落 DEFAULT(ctx=64000, max_output=64000)。
        agent.model = "gpt-5.5".to_string();

        let options = super::context_build_options_for_agent(&agent);

        // 修复前：output_reserve=max_output(64000).min(ctx-1=63999)=63999 → usable=1 → 历史/记忆预算饿死(0)。
        // 修复后：output_reserve 上限=ctx/2=32000，再扣 1024 token 协议安全余量；
        // usable=30976 → history=30976×70%、memory=30976×8%。
        assert_eq!(options.history_token_budget, 21_683);
        assert_eq!(options.memory_token_budget, 2_478);
        assert!(options.history_token_budget > 1_000);
    }

