    #[test]
    fn context_builder_includes_relevant_beads_history_and_current_turn() {
        let agent = context_test_agent();
        let history = vec![
            persisted_role_message("h1", "user", "Earlier we discussed alpha click.", 1),
            persisted_role_message("h2", "assistant", "Use the Settings button for alpha.", 2),
        ];

        let assembly = super::build_context_assembly(
            &agent,
            &history,
            "please continue alpha click",
            &[],
            super::ContextBuildOptions {
                history_token_budget: 120,
                memory_token_budget: 80,
                max_prompt_tokens: 8_000,
                image_token_estimate: 512,
                max_memory_beads: 4,
                history_floor_millis: None,
            },
        );

        assert!(assembly.system_prompt.contains("alpha click target"));
        assert!(!assembly.system_prompt.contains("raw transcript"));
        assert_eq!(assembly.messages.len(), 3);
        assert_eq!(assembly.messages[0].role, "user");
        assert_eq!(assembly.messages[1].role, "assistant");
        assert_eq!(assembly.messages[2].role, "user");
        assert!(message_text(&assembly.messages[0]).contains("Earlier we discussed"));
        assert!(message_text(&assembly.messages[2]).contains("please continue"));
        assert_eq!(
            assembly
                .memory_beads
                .iter()
                .map(|b| b.id.as_str())
                .collect::<Vec<_>>(),
            vec!["bead-alpha"]
        );
        assert_eq!(assembly.history_message_count, 2);
        assert!(!assembly.truncated);
        assert!(assembly.token_budget.total <= assembly.token_budget.budget);
    }

    #[test]
    fn context_builder_honors_history_floor_after_session_reset() {
        let agent = context_test_agent();
        let history = vec![
            persisted_role_message("h-old", "user", "old task memory should be archived", 10),
            persisted_role_message("h-new", "assistant", "new task context is still active", 30),
        ];

        let assembly = super::build_context_assembly(
            &agent,
            &history,
            "continue from the new task",
            &[],
            super::ContextBuildOptions {
                history_token_budget: 120,
                memory_token_budget: 80,
                max_prompt_tokens: 8_000,
                image_token_estimate: 512,
                max_memory_beads: 4,
                history_floor_millis: Some(20),
            },
        );

        let joined = assembly
            .messages
            .iter()
            .map(message_text)
            .collect::<Vec<_>>()
            .join("\n");
        assert!(!joined.contains("old task memory"));
        assert!(joined.contains("new task context"));
        assert!(joined.contains("continue from the new task"));
        assert_eq!(assembly.history_message_count, 1);
    }

