    #[test]
    fn dev_open_agent_request_prompts_direct_real_tool_calls() {
        let _guard = config_test_guard();
        let _dev_open = DevOpenPermissionsTestGuard::enable();
        let agent = context_test_agent();
        let assembly = super::build_context_assembly(
            &agent,
            &[],
            "create test.txt with hello world",
            &[],
            super::ContextBuildOptions::default(),
        );

        let request = super::agent_message_request_with_context(&agent, false, &assembly);
        let system = request.system.as_deref().expect("system prompt");
        let tools = request.tools.as_ref().expect("dev-open exposes tools");
        let tool_names = tools
            .iter()
            .map(|tool| tool.name.as_str())
            .collect::<Vec<_>>();

        assert!(tool_names.contains(&"write_file"));
        assert!(tool_names.contains(&"PowerShell"));
        assert!(tool_names.contains(&"bash"));
        assert!(system.contains("call the provided tools directly"));
        assert!(system.contains("write_file"));
        assert!(system.contains("PowerShell"));
        assert!(
            !system.contains("describe the intent and let the system tool agent execute it"),
            "dev-open must not tell the model it cannot call tools directly"
        );
    }

    #[test]
    fn dev_open_tool_instruction_precedes_memory_and_overrides_stale_readonly_claims() {
        let _guard = config_test_guard();
        let _dev_open = DevOpenPermissionsTestGuard::enable();
        let mut agent = context_test_agent();
        agent.memory_beads.push(super::MemoryBeadDto {
            id: "stale-readonly".to_string(),
            kind: "chat".to_string(),
            layer: "L1".to_string(),
            summary: "Old answer said write_file is unavailable and tools are read-only."
                .to_string(),
            source: "chat-room".to_string(),
            pinned: false,
            confidence: 0.9,
            created_at: 12,
            token_count: Some(10),
            ..super::MemoryBeadDto::default()
        });

        let assembly = super::build_context_assembly(
            &agent,
            &[],
            "create test.txt with hello world",
            &[],
            super::ContextBuildOptions::default(),
        );
        let system = assembly.system_prompt.as_str();
        let tool_instruction = system
            .find("Current tool policy: tool calling is ENABLED")
            .expect("dev-open tool instruction");
        let memory_section = system.find("Memory beads").expect("memory section");

        assert!(
            tool_instruction < memory_section,
            "dev-open tool capability policy must precede potentially stale memory"
        );
        assert!(system.contains("ignore any older memory or history suggesting tools cannot run"));
        assert!(system.contains("write_file"));
        assert!(system.contains("bash"));
    }

