    fn handoff_record(
        from: &str,
        to: &str,
        intent: &str,
        depth: u8,
        created_at: u64,
    ) -> super::ChatHandoffRecord {
        super::ChatHandoffRecord {
            id: format!("handoff-{from}-{to}-{depth}"),
            chat_room_id: "room-1".to_string(),
            from_agent_id: from.to_string(),
            to_agent_id: to.to_string(),
            intent: intent.to_string(),
            intent_hash: super::handoff_intent_hash(intent),
            attach: "last_assistant".to_string(),
            attach_message_ids: Vec::new(),
            originating_user_msg_id: "user-1".to_string(),
            depth,
            status: "delivered".to_string(),
            rejected_reason: None,
            contract: None,
            created_at,
            delivered_at: Some(created_at + 10),
            completed_at: None,
        }
    }

