    #[test]
    fn manual_handoff_creates_record_and_inbound_message() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("sessions.sqlite3");
        let mut a = super::seed_session();
        a.id = "agent-a".to_string();
        a.name = "A-designer".to_string();
        a.messages = Vec::new();
        let mut b = super::seed_session();
        b.id = "agent-b".to_string();
        b.name = "B-dev".to_string();
        b.messages = Vec::new();
        let mut store = super::SessionStore {
            path: db_path.clone(),
            legacy_json_path: temp.path().join("sessions.json"),
            capacity: super::SessionStoreCapacity::default(),
            state: super::PersistedSessionState {
                sessions: vec![a, b],
                active_session_id: Some("agent-a".to_string()),
                active_vision_session_id: None,
                chat_rooms: vec![super::PersistedChatRoom {
                    id: "room-1".to_string(),
                    name: "Room 1".to_string(),
                    created_at: 1,
                    updated_at: 1,
                    messages: vec![persisted_role_message(
                        "assistant-a",
                        "assistant",
                        "Design document body",
                        10,
                    )],
                }],
                active_chat_room_id: Some("room-1".to_string()),
            },
        };

        let response = store
            .create_manual_handoff(
                "room-1",
                super::ManualHandoffRequest {
                    from_agent_id: "agent-a".to_string(),
                    to: "B-dev".to_string(),
                    intent: "Implement the design".to_string(),
                    attach: Some("last_assistant".to_string()),
                    attach_message_ids: None,
                    originating_user_msg_id: Some("user-1".to_string()),
                    depth: Some(0),
                    contract: None,
                },
            )
            .expect("manual handoff")
            .0;

        assert_eq!(response.handoff.status, "delivered");
        let inbound = response.inbound_message.expect("inbound");
        assert_eq!(inbound.kind, "handoff-inbound");
        assert!(inbound.content.contains("Implement the design"));
        assert!(inbound.content.contains("Design document body"));

        let handoffs =
            super::query_chat_handoffs_sqlite(&db_path, "room-1", 10, None).expect("handoffs");
        assert_eq!(handoffs.len(), 1);
        assert_eq!(handoffs[0].to_agent_id, "agent-b");
        assert_eq!(handoffs[0].status, "delivered");
    }

