    #[test]
    fn goal_g1_sqlite_crud_is_workspace_scoped_and_cancelable() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("sessions.sqlite3");
        let workspace_a = "ws-goal-a";
        let workspace_b = "ws-goal-b";

        let created = super::create_goal_sqlite(
            &db_path,
            workspace_a,
            "room-1",
            super::CreateGoalRequest {
                title: "Ship G1 goal contract".to_string(),
                chat_room_id: Some("room-1".to_string()),
                max_iterations: Some(7),
                background: Some(true),
                originating_user_msg_id: Some("user-1".to_string()),
                completion_condition: Some(serde_json::json!({ "type": "UserConfirm" })),
            },
        )
        .expect("create goal");

        assert!(created.id.starts_with("goal-"));
        assert_eq!(created.workspace_id, workspace_a);
        assert_eq!(created.chat_room_id, "room-1");
        assert_eq!(created.status, "planning");
        assert_eq!(created.max_iterations, 7);
        assert!(created.background);
        assert_eq!(created.recent_events[0].event_type, "goal-created");

        let visible = super::query_goals_sqlite(
            &db_path,
            workspace_a,
            super::GoalListQuery {
                status: None,
                chat_room_id: None,
                limit: Some(10),
            },
        )
        .expect("query workspace a");
        assert_eq!(visible.len(), 1);

        let hidden = super::query_goals_sqlite(
            &db_path,
            workspace_b,
            super::GoalListQuery {
                status: None,
                chat_room_id: None,
                limit: Some(10),
            },
        )
        .expect("query workspace b");
        assert!(hidden.is_empty());

        let cancelled =
            super::cancel_goal_sqlite(&db_path, workspace_a, &created.id).expect("cancel goal");
        assert_eq!(cancelled.status, "cancelled");
        assert!(cancelled.cancelled_at.is_some());
        assert!(cancelled
            .recent_events
            .iter()
            .any(|event| event.event_type == "goal-cancelled"));
    }

    #[test]
    fn goal_status_pause_resume_round_trips_and_writes_events() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("sessions.sqlite3");
        let workspace_id = "ws-goal-status";
        let goal = super::create_goal_sqlite(
            &db_path,
            workspace_id,
            "room-1",
            super::CreateGoalRequest {
                title: "Control background goal".to_string(),
                chat_room_id: Some("room-1".to_string()),
                max_iterations: Some(4),
                background: Some(true),
                originating_user_msg_id: Some("user-1".to_string()),
                completion_condition: Some(serde_json::json!({ "type": "UserConfirm" })),
            },
        )
        .expect("create goal");
        super::set_goal_plan_sqlite(
            &db_path,
            workspace_id,
            &goal.id,
            super::GoalPlanRequest {
                phases: vec![
                    super::GoalPlanPhaseRequest {
                        id: "plan".to_string(),
                        title: "Plan".to_string(),
                        assigned_role: Some("planner".to_string()),
                        depends_on: Vec::new(),
                        skills_required: vec!["plan".to_string()],
                        output_artifacts: Vec::new(),
                        verification: Some(serde_json::json!({ "type": "UserConfirm" })),
                        requires_human_ack: false,
                    },
                    super::GoalPlanPhaseRequest {
                        id: "verify".to_string(),
                        title: "Verify".to_string(),
                        assigned_role: Some("verifier".to_string()),
                        depends_on: vec!["plan".to_string()],
                        skills_required: vec!["verify".to_string()],
                        output_artifacts: Vec::new(),
                        verification: Some(serde_json::json!({ "type": "UserConfirm" })),
                        requires_human_ack: false,
                    },
                ],
            },
        )
        .expect("set plan");

        let initial =
            super::goal_status_sqlite(&db_path, workspace_id, &goal.id).expect("initial status");
        assert_eq!(initial.goal.status, "planning");
        assert_eq!(initial.phase_counts.pending, 2);
        assert!(initial.pause_available);
        assert!(!initial.resume_available);
        assert!(initial.cancel_available);

        let paused =
            super::pause_goal_sqlite(&db_path, workspace_id, &goal.id).expect("pause goal");
        assert_eq!(paused.goal.status, "paused");
        assert!(!paused.pause_available);
        assert!(paused.resume_available);
        assert_eq!(
            paused
                .latest_event
                .as_ref()
                .map(|event| event.event_type.as_str()),
            Some("goal-paused")
        );

        let resumed =
            super::resume_goal_sqlite(&db_path, workspace_id, &goal.id).expect("resume goal");
        assert_eq!(resumed.goal.status, "planning");
        assert!(resumed.pause_available);
        assert!(!resumed.resume_available);
        assert_eq!(
            resumed
                .latest_event
                .as_ref()
                .map(|event| event.event_type.as_str()),
            Some("goal-resumed")
        );

        let connection = super::open_session_connection(&db_path).expect("connection");
        super::initialize_session_schema(&connection).expect("schema");
        super::update_goal_phase_status_connection(
            &connection,
            workspace_id,
            &goal.id,
            "plan",
            "running",
        )
        .expect("running phase");
        let running =
            super::goal_status_sqlite(&db_path, workspace_id, &goal.id).expect("running status");
        assert_eq!(running.goal.status, "running");
        assert_eq!(running.phase_counts.running, 1);
        assert_eq!(running.phase_counts.pending, 1);
    }

    #[tokio::test]
    async fn goal_event_bus_broadcasts_goal_events_on_insert() {
        let mut rx = super::subscribe_goal_events();
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("sessions.sqlite3");
        let workspace_id = "ws-goal-event-stream";
        let goal = super::create_goal_sqlite(
            &db_path,
            workspace_id,
            "room-1",
            super::CreateGoalRequest {
                title: "Stream goal events".to_string(),
                chat_room_id: Some("room-1".to_string()),
                max_iterations: Some(2),
                background: Some(true),
                originating_user_msg_id: None,
                completion_condition: Some(serde_json::json!({ "type": "UserConfirm" })),
            },
        )
        .expect("create goal");

        let mut observed = None;
        for _ in 0..16 {
            let event = tokio::time::timeout(std::time::Duration::from_secs(1), rx.recv())
                .await
                .expect("goal event timeout")
                .expect("goal event");
            if event.goal_id == goal.id {
                observed = Some(event);
                break;
            }
        }
        let event = observed.expect("matching goal event");
        assert_eq!(event.event_type, "goal-created");
        assert_eq!(
            event.payload["title"],
            serde_json::json!("Stream goal events")
        );
    }

    #[test]
    fn goal_condition_validation_marks_command_runtime_and_blocks_path_escape() {
        let command = super::validate_completion_condition(&serde_json::json!({
            "type": "CommandSucceeds",
            "command": "cargo test -p coolzhu-web-console",
            "timeout_secs": 30
        }));
        assert!(command.valid);
        assert!(command.requires_runtime_tool);
        assert_eq!(
            command.normalized.unwrap()["execution"],
            "runtime_tool_execute_required"
        );

        let invalid = super::validate_completion_condition(&serde_json::json!({
            "type": "FilesExist",
            "paths": ["../secret.txt"]
        }));
        assert!(!invalid.valid);
        assert!(invalid
            .issues
            .iter()
            .any(|issue| issue.contains("escape workspace")));
    }

