    #[test]
    fn goal_role_risk_assessment_writes_deduped_goal_event() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("roles.sqlite3");
        let workspace_id = "workspace-risk";
        let now = super::unix_timestamp_millis();
        let sessions = vec![super::PersistedSession {
            id: "planner".to_string(),
            name: "Planner".to_string(),
            provider: "Custom".to_string(),
            model: "planner-model".to_string(),
            avatar: None,
            api_key_ref: String::new(),
            base_url: None,
            endpoint: None,
            reasoning_effort: "medium".to_string(),
            model_type: "text".to_string(),
            memory_beads: Vec::new(),
            created_at: now - 100,
            updated_at: now - 100,
            context_reset_at: 0,
            messages: Vec::new(),
        }];

        let goal = super::create_goal_sqlite(
            &db_path,
            workspace_id,
            "room-1",
            super::CreateGoalRequest {
                title: "Risk managed goal".to_string(),
                chat_room_id: Some("room-1".to_string()),
                max_iterations: Some(5),
                background: Some(true),
                originating_user_msg_id: None,
                completion_condition: Some(serde_json::json!({ "type": "UserConfirm" })),
            },
        )
        .expect("goal");
        super::upsert_goal_role_config_sqlite(
            &db_path,
            "planner",
            super::GoalRoleConfigUpdateRequest {
                role: Some("planner".to_string()),
                responsibility: Some("Keep the plan moving".to_string()),
                commander: Some(true),
                heartbeat_timeout_ms: Some(60_000),
                task_timeout_ms: Some(1),
            },
        )
        .expect("role config");
        super::record_goal_role_heartbeat_sqlite(
            &db_path,
            "planner",
            super::GoalRoleHeartbeatRequest {
                task_active: Some(true),
            },
        )
        .expect("heartbeat");

        let connection = super::open_session_connection(&db_path).expect("connection");
        super::initialize_session_schema(&connection).expect("schema");
        connection
            .execute(
                "UPDATE goal_role_configs SET active_task_started_at = ?1 WHERE session_id = ?2",
                rusqlite::params![super::u64_to_i64(now.saturating_sub(70_000)), "planner"],
            )
            .expect("age active task");

        let response = super::assess_goal_role_risks_sqlite(&db_path, workspace_id, &sessions)
            .expect("risk assessment");
        let planner = response
            .roles
            .iter()
            .find(|role| role.session_id == "planner")
            .expect("planner role");
        assert_eq!(planner.risk_level, "stuck");

        super::assess_goal_role_risks_sqlite(&db_path, workspace_id, &sessions)
            .expect("second assessment");
        let refreshed =
            super::get_goal_sqlite(&db_path, workspace_id, &goal.id).expect("refreshed goal");
        let risk_events = refreshed
            .recent_events
            .iter()
            .filter(|event| event.event_type == "goal-role-risk")
            .collect::<Vec<_>>();
        assert_eq!(risk_events.len(), 1);
        let event = risk_events[0];
        assert!(event.message.contains("Planner"));
        assert_eq!(event.payload["session_id"], "planner");
        assert_eq!(event.payload["risk_level"], "stuck");
    }

