    #[test]
    fn goal_runtime_refresh_extends_role_heartbeat_lease() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("roles.sqlite3");
        let now = super::unix_timestamp_millis();
        let sessions = vec![super::PersistedSession {
            id: "verifier".to_string(),
            name: "Verifier".to_string(),
            provider: "Custom".to_string(),
            model: "verify-model".to_string(),
            avatar: None,
            api_key_ref: String::new(),
            base_url: None,
            endpoint: None,
            reasoning_effort: "medium".to_string(),
            model_type: "text".to_string(),
            memory_beads: Vec::new(),
            created_at: now,
            updated_at: now,
            context_reset_at: 0,
            messages: Vec::new(),
        }];
        super::upsert_goal_role_config_sqlite(
            &db_path,
            "verifier",
            super::GoalRoleConfigUpdateRequest {
                role: Some("verifier".to_string()),
                responsibility: Some("Verify long goal output".to_string()),
                commander: Some(false),
                heartbeat_timeout_ms: Some(60_000),
                task_timeout_ms: Some(600_000),
            },
        )
        .expect("role config");
        let connection = super::open_session_connection(&db_path).expect("connection");
        super::initialize_session_schema(&connection).expect("schema");
        connection
            .execute(
                "UPDATE goal_role_configs SET last_heartbeat_at = ?1 WHERE session_id = ?2",
                rusqlite::params![0_i64, "verifier"],
            )
            .expect("age heartbeat");

        let before = super::goal_role_config_response_from_sqlite(&db_path, &sessions)
            .expect("role response before refresh");
        let verifier_before = before
            .roles
            .iter()
            .find(|role| role.session_id == "verifier")
            .expect("verifier before");
        assert_eq!(verifier_before.risk_level, "offline");

        super::refresh_goal_runtime_role_heartbeats(&db_path, "workspace-heartbeat-refresh");
        let after = super::goal_role_config_response_from_sqlite(&db_path, &sessions)
            .expect("role response after refresh");
        let verifier_after = after
            .roles
            .iter()
            .find(|role| role.session_id == "verifier")
            .expect("verifier after");
        assert!(verifier_after.online);
        assert_eq!(verifier_after.risk_level, "normal");
    }

