    #[test]
    fn session_store_capacity_prunes_oldest_messages() {
        let mut store = super::SessionStore {
            path: std::path::PathBuf::from("unused.sqlite3"),
            legacy_json_path: std::path::PathBuf::from("unused.json"),
            capacity: super::SessionStoreCapacity {
                max_room_messages: 2,
                max_session_messages: 3,
                max_total_messages: 5,
                max_beads_per_session: 2,
                max_estimated_bytes: 128 * 1024 * 1024,
            },
            state: super::PersistedSessionState {
                sessions: vec![super::PersistedSession {
                    id: "s1".to_string(),
                    name: "s1".to_string(),
                    provider: "test".to_string(),
                    model: "m".to_string(),
                    avatar: None,
                    api_key_ref: String::new(),
                    base_url: None,
                    endpoint: None,
                    reasoning_effort: "medium".to_string(),
                    model_type: "text".to_string(),
                    memory_beads: Vec::new(),
                    created_at: 0,
                    updated_at: 0,
                    context_reset_at: 0,
                    messages: vec![
                        persisted_message("s-old", 1),
                        persisted_message("s-mid", 2),
                        persisted_message("s-new", 3),
                        persisted_message("s-latest", 4),
                    ],
                }],
                active_session_id: Some("s1".to_string()),
                active_vision_session_id: None,
                chat_rooms: vec![super::PersistedChatRoom {
                    id: super::DEFAULT_CHAT_ROOM_ID.to_string(),
                    name: "main".to_string(),
                    created_at: 0,
                    updated_at: 0,
                    messages: vec![
                        persisted_message("r-old", 1),
                        persisted_message("r-new", 2),
                        persisted_message("r-latest", 3),
                    ],
                }],
                active_chat_room_id: Some(super::DEFAULT_CHAT_ROOM_ID.to_string()),
            },
        };
        store.enforce_capacity();

        let session_ids = store.state.sessions[0]
            .messages
            .iter()
            .map(|message| message.id.as_str())
            .collect::<Vec<_>>();
        assert_eq!(session_ids, vec!["s-mid", "s-new", "s-latest"]);
        let room_ids = store.state.chat_rooms[0]
            .messages
            .iter()
            .map(|message| message.id.as_str())
            .collect::<Vec<_>>();
        assert_eq!(room_ids, vec!["r-new", "r-latest"]);
    }

    #[test]
    fn chat_dispatch_persists_all_recipients_with_single_save() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("sessions.sqlite3");
        let json_path = temp.path().join("sessions.json");
        let mut store = super::SessionStore {
            path: db_path.clone(),
            legacy_json_path: json_path,
            capacity: super::SessionStoreCapacity {
                max_room_messages: 10,
                max_session_messages: 10,
                max_total_messages: 30,
                max_beads_per_session: 10,
                max_estimated_bytes: 128 * 1024 * 1024,
            },
            state: super::PersistedSessionState {
                sessions: ["agent-a", "agent-b", "agent-c"]
                    .into_iter()
                    .map(|id| super::PersistedSession {
                        id: id.to_string(),
                        name: id.to_string(),
                        provider: "test-provider".to_string(),
                        model: "test-model".to_string(),
                        avatar: None,
                        api_key_ref: String::new(),
                        base_url: None,
                        endpoint: None,
                        reasoning_effort: "medium".to_string(),
                        model_type: "text".to_string(),
                        memory_beads: Vec::new(),
                        created_at: 1,
                        updated_at: 1,
                        context_reset_at: 0,
                        messages: Vec::new(),
                    })
                    .collect(),
                active_session_id: Some("agent-a".to_string()),
                active_vision_session_id: None,
                chat_rooms: vec![super::PersistedChatRoom {
                    id: "room-main".to_string(),
                    name: "主聊天室".to_string(),
                    created_at: 1,
                    updated_at: 1,
                    messages: Vec::new(),
                }],
                active_chat_room_id: Some("room-main".to_string()),
            },
        };
        let targets = vec![
            test_chat_agent("agent-a", "agent-a"),
            test_chat_agent("agent-b", "agent-b"),
        ];
        let messages = vec![super::ChatMessageDto {
            id: "msg-one".to_string(),
            author: "用户".to_string(),
            role: "user".to_string(),
            target: "聊天".to_string(),
            content: "请检查 SQLite 写入".to_string(),
            kind: "user".to_string(),
            attachments: Vec::new(),
        }];

        let save_count = store
            .append_chat_dispatch_once("room-main", Some("agent-a"), &targets, messages.clone())
            .expect("dispatch persist");

        assert_eq!(save_count, 1);
        assert_eq!(store.state.chat_rooms[0].messages.len(), 1);
        assert_eq!(store.state.sessions[0].messages.len(), 1);
        assert_eq!(store.state.sessions[1].messages.len(), 1);
        assert_eq!(
            store.state.sessions[2].messages.len(),
            0,
            "untargeted sessions must not receive dispatch messages"
        );
        let loaded = super::read_session_state_from_sqlite(&db_path).expect("read sqlite");
        assert_eq!(loaded.chat_rooms[0].messages.len(), 1);
        assert_eq!(loaded.sessions[0].messages.len(), 1);
        assert_eq!(loaded.sessions[1].messages.len(), 1);
    }

