    #[tokio::test(flavor = "current_thread")]
    async fn task_schedule_run_due_uses_system_room_without_changing_active_room() {
        let _guard = config_test_guard();
        let temp = tempfile::tempdir().expect("tempdir");
        let now = super::unix_timestamp_millis();
        let workspace = temp.path().canonicalize().unwrap();
        let db_path = temp.path().join("sessions.sqlite3");
        let store = super::SessionStore {
            path: db_path,
            legacy_json_path: temp.path().join("sessions.json"),
            capacity: super::SessionStoreCapacity::default(),
            state: super::PersistedSessionState {
                sessions: vec![super::PersistedSession {
                    id: "target-agent".to_string(),
                    name: "target-agent".to_string(),
                    provider: "Custom".to_string(),
                    model: "qwen".to_string(),
                    avatar: None,
                    api_key_ref: String::new(),
                    base_url: None,
                    endpoint: None,
                    reasoning_effort: "medium".to_string(),
                    model_type: "text".to_string(),
                    memory_beads: Vec::new(),
                    created_at: now,
                    updated_at: now,
                    context_reset_at: 0,
                    messages: Vec::new(),
                }],
                active_session_id: Some("target-agent".to_string()),
                active_vision_session_id: None,
                chat_rooms: vec![super::PersistedChatRoom {
                    id: "room-user-active".to_string(),
                    name: "当前聊天室".to_string(),
                    created_at: now,
                    updated_at: now,
                    messages: Vec::new(),
                }],
                active_chat_room_id: Some("room-user-active".to_string()),
            },
        };
        let prev_workspace = {
            let mut guard = super::workspace_state().lock().expect("workspace state");
            std::mem::replace(&mut guard.current, workspace.clone())
        };
        let prev_config = {
            let mut guard = super::workspace_config().lock().expect("config");
            std::mem::replace(&mut *guard, super::WorkspaceConfig::default())
        };
        let prev_store = {
            let mut guard = super::session_store().lock().expect("session store");
            std::mem::replace(&mut *guard, store)
        };

        let Json(created) =
            super::api_create_task_schedule(axum::Json(super::TaskScheduleCreateRequest {
                target_session_id: "target-agent".to_string(),
                content: "run nightly verification".to_string(),
                run_at_ms: 1,
                interval_ms: None,
                permissions: vec!["full-access".to_string()],
                schedule_kind: "once".to_string(),
                wall_hour: 0,
                wall_minute: 0,
                weekdays: Vec::new(),
                tz_offset_minutes: 0,
                task_kind: "poll".to_string(),
                goal_id: None,
            }))
            .await
            .expect("create schedule");
        assert_eq!(created.tasks.len(), 1);
        assert!(created.dev_open_permissions == super::dev_open_tool_permissions_enabled());

        let Json(run) = super::api_run_due_task_schedules().await.expect("run due");
        assert_eq!(run.ran.len(), 1);
        assert_eq!(run.ran[0].status, "executed");
        {
            let guard = super::session_store().lock().expect("session store");
            assert_eq!(
                guard.active_chat_room_id().as_deref(),
                Some("room-user-active")
            );
            assert_eq!(
                guard.state.sessions[0].messages[0].content,
                "run nightly verification"
            );
            let room = guard
                .state
                .chat_rooms
                .iter()
                .find(|room| room.id == super::SCHEDULED_TASK_SYSTEM_ROOM_ID)
                .expect("scheduled task system room");
            assert_eq!(room.name, "定时任务");
            assert!(room
                .messages
                .iter()
                .any(|message| message.content == "run nightly verification"));
        }

        let _ = std::mem::replace(
            &mut super::workspace_state()
                .lock()
                .expect("workspace state")
                .current,
            prev_workspace,
        );
        let _ = std::mem::replace(
            &mut *super::workspace_config().lock().expect("config"),
            prev_config,
        );
        let _ = std::mem::replace(
            &mut *super::session_store().lock().expect("session store"),
            prev_store,
        );
    }

    #[test]
    fn stream_tool_call_tuple_retains_id_name_and_args_slots() {
        // Phase C-13：流"Tool Loop "model_tool_calls value 升级。
        // (tool_use_id, name, argsJson) —"任一 slot 丢失都会"round 2
        // ToolResult 配对失败。这"TDD 钉住 tuple 语义。
        let mut calls: std::collections::BTreeMap<u32, (String, String, String)> =
            std::collections::BTreeMap::new();
        calls.insert(
            0,
            (
                "toolu_stream_1".to_string(),
                "read_file".to_string(),
                "{\"path\":\"a.rs\"}".to_string(),
            ),
        );
        // 模拟 InputJsonDelta 分片 append 到第 3 "(arguments)
        if let Some((_, _, args)) = calls.get_mut(&0) {
            args.push_str(" extra");
        }
        let (id, name, args) = calls.get(&0).expect("present").clone();
        assert_eq!(id, "toolu_stream_1");
        assert_eq!(name, "read_file");
        assert!(args.contains("extra"));
    }

    #[test]
    fn stream_content_block_tool_use_start_populates_full_tuple() {
        // 模拟流式 ContentBlockStart 命中 ToolUse 时的 insert 逻辑。
        // (start.index, (id, name, initial_input))
        use super::OutputContentBlock;
        let block = OutputContentBlock::ToolUse {
            id: "toolu_stream_2".into(),
            name: "glob_search".into(),
            input: serde_json::json!({"pattern": "*.rs"}),
        };
        let OutputContentBlock::ToolUse { id, name, input } = block else {
            panic!("expected ToolUse");
        };
        let initial_input = if input.is_object() && input.as_object().is_some_and(|o| o.is_empty())
        {
            String::new()
        } else {
            input.to_string()
        };
        let tuple = (id.clone(), name.clone(), initial_input);
        assert_eq!(tuple.0, "toolu_stream_2");
        assert_eq!(tuple.1, "glob_search");
        assert!(tuple.2.contains("*.rs"));
    }

    #[test]
    fn model_tool_requests_from_blocks_preserves_tool_use_id() {
        // Phase C-12：tool_use_id 必须"round 0 "round 1 保留，否。
        // round 2 "ToolResult 无法配对，模型会拒绝整条 tool_result 块。
        let blocks = vec![
            super::OutputContentBlock::Text {
                text: "hello".into(),
            },
            super::OutputContentBlock::ToolUse {
                id: "toolu_abc_123".into(),
                name: "read_file".into(),
                input: serde_json::json!({"path": "a.rs"}),
            },
            super::OutputContentBlock::ToolUse {
                id: "toolu_def_456".into(),
                name: "glob_search".into(),
                input: serde_json::json!({"pattern": "*.rs"}),
            },
        ];
        let requests = super::model_tool_requests_from_blocks(&blocks);
        assert_eq!(requests.len(), 2);
        assert_eq!(requests[0].0, "toolu_abc_123");
        assert_eq!(requests[0].1, "read_file");
        assert_eq!(
            requests[0].2,
            serde_json::json!({"path": "a.rs"}),
            "input JSON 应原样传"
        );
        assert_eq!(requests[1].0, "toolu_def_456");
        assert_eq!(requests[1].1, "glob_search");
    }

