    #[test]
    fn migration_v13_upgrades_v12_database_without_losing_rows() {
        // GL-01：v12 旧库升级必须保住既有 phase 行，新列落到默认值。
        // 用 ALTER ADD COLUMN 而非重建表，正是为了避免 goal_phases 的外键级联。
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("goal-upgrade.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        // 造一个 v12 形态的库：goal_phases 只有旧的 11 列。
        // 表定义照抄线上真实形态——主键是复合的 (goal_id, id) 而不是 id 单列，
        // 所以同一个 phase id（'plan'/'implement'）会在不同 goal 下重复出现。
        connection
            .execute_batch(
                r#"
                CREATE TABLE goals (
                    id TEXT PRIMARY KEY,
                    workspace_id TEXT NOT NULL,
                    chat_room_id TEXT NOT NULL,
                    title TEXT NOT NULL,
                    status TEXT NOT NULL,
                    max_iterations INTEGER NOT NULL,
                    current_iteration INTEGER NOT NULL,
                    background INTEGER NOT NULL,
                    originating_user_msg_id TEXT,
                    completion_condition_json TEXT NOT NULL,
                    plan_json TEXT,
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL,
                    cancelled_at INTEGER
                );
                CREATE TABLE goal_phases (
                    id TEXT NOT NULL,
                    goal_id TEXT NOT NULL,
                    title TEXT NOT NULL,
                    assigned_role TEXT NOT NULL,
                    status TEXT NOT NULL,
                    depends_on_json TEXT NOT NULL,
                    skills_json TEXT NOT NULL,
                    output_artifacts_json TEXT NOT NULL,
                    verification_json TEXT,
                    created_at INTEGER NOT NULL,
                    updated_at INTEGER NOT NULL,
                    PRIMARY KEY (goal_id, id),
                    FOREIGN KEY (goal_id) REFERENCES goals(id) ON DELETE CASCADE
                );
                INSERT INTO goals VALUES
                    ('g1','ws','room','目标一','running',5,1,0,NULL,'{}',NULL,10,20,NULL),
                    ('g2','ws','room','目标二','running',5,1,0,NULL,'{}',NULL,10,20,NULL);
                INSERT INTO goal_phases VALUES
                    ('implement','g1','实现登录','implementer','completed','[]','[]','[]',NULL,100,200),
                    ('implement','g2','实现下单','implementer','running','[]','[]','[]',NULL,300,400);
                PRAGMA user_version = 12;
                "#,
            )
            .expect("seed v12");

        super::initialize_session_schema(&connection).expect("migrate");

        // 两个 goal 下的同名 phase 都必须原样保留。
        let total: i64 = connection
            .query_row("SELECT count(*) FROM goal_phases", [], |row| row.get(0))
            .expect("count");
        assert_eq!(total, 2, "升级不该丢行");

        let (title, status, created): (String, String, i64) = connection
            .query_row(
                "SELECT title, status, created_at FROM goal_phases \
                 WHERE goal_id = 'g1' AND id = 'implement'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .expect("g1 的旧行应当还在");
        assert_eq!(title, "实现登录");
        assert_eq!(status, "completed");
        assert_eq!(created, 100);

        let g2_title: String = connection
            .query_row(
                "SELECT title FROM goal_phases WHERE goal_id = 'g2' AND id = 'implement'",
                [],
                |row| row.get(0),
            )
            .expect("g2 的同名 phase 也应当还在");
        assert_eq!(g2_title, "实现下单");

        // 所有旧行的新列都落到默认值上。
        let (retry, max_retries, verdict): (i64, i64, Option<String>) = connection
            .query_row(
                "SELECT retry_count, max_retries, last_verdict FROM goal_phases \
                 WHERE goal_id = 'g1' AND id = 'implement'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .expect("新列应当可读");
        assert_eq!(retry, 0);
        assert_eq!(max_retries, 2);
        // 尚未产生结论 → NULL，而不是空串。
        assert!(verdict.is_none());

        let off_default: i64 = connection
            .query_row(
                "SELECT count(*) FROM goal_phases WHERE retry_count != 0 OR max_retries != 2",
                [],
                |row| row.get(0),
            )
            .expect("count");
        assert_eq!(off_default, 0, "所有旧行都该是 retry=0 / max=2");

        let version: i64 = connection
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .expect("user_version");
        assert_eq!(version, 15);
    }

    /// GL-02：读路径把 v13 的 6 列反序列化进 GoalPhaseDto，并能正确序列化给前端。
    #[test]
    fn goal_phase_dto_reads_and_serializes_routing_fields() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("dto.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");

        // 一个 goal + 两个 phase：p1 尚无结论（全默认），p2 已被 verifier 打回。
        connection
            .execute_batch(
                r#"
                INSERT INTO goals VALUES
                    ('g1','ws','room','目标','running',5,1,0,NULL,'{}',NULL,10,20,NULL);
                INSERT INTO goal_phases
                    (id, goal_id, title, assigned_role, status, depends_on_json,
                     skills_json, output_artifacts_json, verification_json,
                     created_at, updated_at)
                VALUES
                    ('p1','g1','规划','planner','pending','[]','[]','[]',NULL,100,100);
                INSERT INTO goal_phases
                    (id, goal_id, title, assigned_role, status, depends_on_json,
                     skills_json, output_artifacts_json, verification_json,
                     created_at, updated_at,
                     retry_count, max_retries, last_verdict, last_reason,
                     last_evidence_json, route_hint)
                VALUES
                    ('p2','g1','实现','implementer','running','["p1"]','[]','[]',NULL,200,200,
                     1, 3, 'fail', '缺少单元测试', '{"missing":["tests/foo.rs"]}', 'implementer');
                "#,
            )
            .expect("seed phases");

        let phases = super::query_goal_phases_connection(&connection, "g1").expect("query");
        assert_eq!(phases.len(), 2);

        // p1：尚无结论 → 默认值 + None。
        let p1 = phases.iter().find(|p| p.id == "p1").expect("p1");
        assert_eq!(p1.retry_count, 0);
        assert_eq!(p1.max_retries, 2);
        assert!(p1.last_verdict.is_none());
        assert!(p1.last_reason.is_none());
        assert!(p1.last_evidence.is_none());
        assert!(p1.route_hint.is_none());

        // p2：被打回 → 结论与证据完整回读，evidence 解析成 JSON 对象。
        let p2 = phases.iter().find(|p| p.id == "p2").expect("p2");
        assert_eq!(p2.retry_count, 1);
        assert_eq!(p2.max_retries, 3);
        assert_eq!(p2.last_verdict.as_deref(), Some("fail"));
        assert_eq!(p2.last_reason.as_deref(), Some("缺少单元测试"));
        assert_eq!(p2.route_hint.as_deref(), Some("implementer"));
        assert_eq!(
            p2.last_evidence,
            Some(serde_json::json!({"missing": ["tests/foo.rs"]}))
        );

        // 序列化给前端的 JSON 含新字段，且 evidence 是嵌套对象而非字符串。
        let json = serde_json::to_value(p2).expect("serialize");
        assert_eq!(json["retry_count"], serde_json::json!(1));
        assert_eq!(json["max_retries"], serde_json::json!(3));
        assert_eq!(json["last_verdict"], serde_json::json!("fail"));
        assert_eq!(json["last_evidence"]["missing"][0], serde_json::json!("tests/foo.rs"));
        // p1 的空结论序列化成 JSON null。
        let json1 = serde_json::to_value(p1).expect("serialize");
        assert!(json1["last_verdict"].is_null());
        assert!(json1["last_evidence"].is_null());
    }

    /// GL-03：re-plan（DELETE + 全量 INSERT）必须保留旧 phase 的回退路由状态，
    /// 新增 phase 落默认值。
    #[test]
    fn set_goal_plan_preserves_routing_state_across_replan() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("replan.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        connection
            .execute_batch(
                "INSERT INTO goals VALUES \
                 ('g1','ws-test','room','目标','running',5,1,0,NULL,'{}',NULL,10,20,NULL);",
            )
            .expect("seed goal");
        drop(connection);

        let plan = |ids: &[&str]| super::GoalPlanRequest {
            phases: ids
                .iter()
                .map(|id| super::GoalPlanPhaseRequest {
                    id: (*id).to_string(),
                    title: format!("阶段 {id}"),
                    assigned_role: Some("implementer".to_string()),
                    depends_on: Vec::new(),
                    skills_required: Vec::new(),
                    output_artifacts: Vec::new(),
                    verification: None,
                    requires_human_ack: false,
                })
                .collect(),
        };

        // 首次落计划。
        super::set_goal_plan_sqlite(&db, "ws-test", "g1", plan(&["impl", "verify"]))
            .expect("initial plan");

        // 模拟 GL-06 之后写入的回退状态。
        let c = super::open_session_connection(&db).expect("open");
        c.execute(
            "UPDATE goal_phases SET retry_count=3, max_retries=5, last_verdict='fail', \
             last_reason='缺测试', last_evidence_json='{\"missing\":[\"t.rs\"]}', \
             route_hint='implementer' WHERE goal_id='g1' AND id='impl'",
            [],
        )
        .expect("seed routing state");
        drop(c);

        // 再次落计划（re-plan），并新增一个 phase。旧的 DELETE+INSERT 会把状态清零。
        super::set_goal_plan_sqlite(&db, "ws-test", "g1", plan(&["impl", "verify", "polish"]))
            .expect("replan");

        let c = super::open_session_connection(&db).expect("open");
        // impl 的回退状态逐字段保留。
        let (retry, max, verdict, reason, evidence, hint): (
            i64,
            i64,
            Option<String>,
            Option<String>,
            Option<String>,
            Option<String>,
        ) = c
            .query_row(
                "SELECT retry_count, max_retries, last_verdict, last_reason, \
                 last_evidence_json, route_hint FROM goal_phases \
                 WHERE goal_id='g1' AND id='impl'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?, r.get(4)?, r.get(5)?)),
            )
            .expect("impl row");
        assert_eq!(retry, 3, "retry_count 不该被 re-plan 清零");
        assert_eq!(max, 5);
        assert_eq!(verdict.as_deref(), Some("fail"));
        assert_eq!(reason.as_deref(), Some("缺测试"));
        assert_eq!(evidence.as_deref(), Some("{\"missing\":[\"t.rs\"]}"));
        assert_eq!(hint.as_deref(), Some("implementer"));

        // 新增的 polish phase 落默认值。
        let (nretry, nmax, nverdict): (i64, i64, Option<String>) = c
            .query_row(
                "SELECT retry_count, max_retries, last_verdict FROM goal_phases \
                 WHERE goal_id='g1' AND id='polish'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?)),
            )
            .expect("polish row");
        assert_eq!(nretry, 0);
        assert_eq!(nmax, 2);
        assert!(nverdict.is_none());
    }

    /// GL-03（codex 审查补强）：re-plan 传入带首尾空白的 phase id 时，仍要按 trim 后的
    /// id 命中旧路由状态、并把干净 id 存库，不能当成新 phase 清零。
    #[test]
    fn set_goal_plan_normalizes_whitespace_phase_id_and_keeps_routing() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("ws-id.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        connection
            .execute_batch(
                "INSERT INTO goals VALUES \
                 ('g1','ws-test','room','目标','running',5,1,0,NULL,'{}',NULL,10,20,NULL);",
            )
            .expect("seed goal");
        drop(connection);

        let phase = |id: &str| super::GoalPlanRequest {
            phases: vec![super::GoalPlanPhaseRequest {
                id: id.to_string(),
                title: "实现".to_string(),
                assigned_role: Some("implementer".to_string()),
                depends_on: Vec::new(),
                skills_required: Vec::new(),
                output_artifacts: Vec::new(),
                verification: None,
                requires_human_ack: false,
            }],
        };

        super::set_goal_plan_sqlite(&db, "ws-test", "g1", phase("impl")).expect("initial");
        let c = super::open_session_connection(&db).expect("open");
        c.execute(
            "UPDATE goal_phases SET retry_count=2, last_verdict='fail' \
             WHERE goal_id='g1' AND id='impl'",
            [],
        )
        .expect("seed routing");
        drop(c);

        // 带空白的同一 id 重规划。
        super::set_goal_plan_sqlite(&db, "ws-test", "g1", phase("  impl  ")).expect("replan");

        let c = super::open_session_connection(&db).expect("open");
        // 库里只应有一行、id 是干净的 "impl"。
        let stored_id: String = c
            .query_row("SELECT id FROM goal_phases WHERE goal_id='g1'", [], |r| {
                r.get(0)
            })
            .expect("one row");
        assert_eq!(stored_id, "impl", "脏 id 应被 trim 后存库");
        // 路由状态没被当成新 phase 清零。
        let (retry, verdict): (i64, Option<String>) = c
            .query_row(
                "SELECT retry_count, last_verdict FROM goal_phases WHERE goal_id='g1' AND id='impl'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .expect("row");
        assert_eq!(retry, 2, "带空白 id 的重规划不该清零 retry_count");
        assert_eq!(verdict.as_deref(), Some("fail"));
    }

    /// GL-04：record_phase_verdict_connection 写回 verdict/reason/evidence；
    /// 非 pass/fail 的输入一律归一成 fail（绝不静默 pass），evidence 以 JSON 落库。
    #[test]
    fn record_phase_verdict_normalizes_and_persists() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("verdict.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        connection
            .execute_batch(
                "INSERT INTO goals VALUES \
                 ('g1','ws','room','目标','running',5,1,0,NULL,'{}',NULL,10,20,NULL); \
                 INSERT INTO goal_phases \
                   (id,goal_id,title,assigned_role,status,depends_on_json,skills_json,\
                    output_artifacts_json,verification_json,created_at,updated_at) \
                 VALUES ('impl','g1','实现','implementer','running','[]','[]','[]',NULL,10,10);",
            )
            .expect("seed");

        // pass（大小写不敏感）+ 证据对象。
        super::record_phase_verdict_connection(
            &connection,
            "g1",
            "impl",
            "PASS",
            None,
            Some(&serde_json::json!({ "text": "ok" })),
        )
        .expect("record pass");
        let (v, ev): (String, String) = connection
            .query_row(
                "SELECT last_verdict, last_evidence_json FROM goal_phases WHERE id='impl'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .expect("row");
        assert_eq!(v, "pass");
        assert_eq!(
            serde_json::from_str::<serde_json::Value>(&ev).unwrap(),
            serde_json::json!({ "text": "ok" })
        );

        // 无法解析的结论（"maybe"）必须落 fail，绝不静默 pass。
        super::record_phase_verdict_connection(
            &connection,
            "g1",
            "impl",
            "maybe",
            Some("模型没给明确结论"),
            None,
        )
        .expect("record fallback");
        let (v2, reason): (String, Option<String>) = connection
            .query_row(
                "SELECT last_verdict, last_reason FROM goal_phases WHERE id='impl'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .expect("row");
        assert_eq!(v2, "fail", "未知结论必须归一成 fail");
        assert_eq!(reason.as_deref(), Some("模型没给明确结论"));
    }

    /// GL-05/06：校验门失败统一走 retry_count——未超上限留 running 递增计数，
    /// 超 max_retries 则 phase 置 blocked、goal 暂停，并各记 goal-phase-retry/blocked 事件。
    #[test]
    fn apply_phase_fail_retry_bumps_then_blocks_at_limit() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("retry.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        // max_retries=2 → 第 1、2 次 fail 留 running，第 3 次超限 blocked。
        connection
            .execute_batch(
                "INSERT INTO goals VALUES \
                 ('g1','ws','room','目标','running',5,1,0,NULL,'{}',NULL,10,20,NULL); \
                 INSERT INTO goal_phases \
                   (id,goal_id,title,assigned_role,status,depends_on_json,skills_json,\
                    output_artifacts_json,verification_json,created_at,updated_at,\
                    retry_count,max_retries) \
                 VALUES ('impl','g1','实现','implementer','running','[]','[]','[]',NULL,10,10,0,2);",
            )
            .expect("seed");

        let ev = serde_json::json!({ "text": "cargo test 失败" });
        // 第 1 次：retry 1/2，未超限。
        let o1 = super::apply_phase_fail_retry_connection(&connection, "ws", "g1", "impl", "门失败", &ev, "running", false)
            .expect("retry1");
        assert_eq!(o1.retry_count, 1);
        assert!(!o1.blocked);
        let (rc, st): (i64, String) = connection
            .query_row(
                "SELECT retry_count, status FROM goal_phases WHERE id='impl'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .expect("row");
        assert_eq!(rc, 1);
        assert_eq!(st, "running", "未超限应保持 running 重试");

        // 第 2 次：retry 2/2，仍未超限（2 <= 2）。
        let o2 = super::apply_phase_fail_retry_connection(&connection, "ws", "g1", "impl", "门失败", &ev, "running", false)
            .expect("retry2");
        assert_eq!(o2.retry_count, 2);
        assert!(!o2.blocked);

        // 第 3 次：retry 3 > max 2 → blocked。
        let o3 = super::apply_phase_fail_retry_connection(&connection, "ws", "g1", "impl", "门失败", &ev, "running", false)
            .expect("retry3");
        assert_eq!(o3.retry_count, 3);
        assert!(o3.blocked, "超 max_retries 应 blocked");
        let phase_status: String = connection
            .query_row("SELECT status FROM goal_phases WHERE id='impl'", [], |r| r.get(0))
            .expect("phase");
        assert_eq!(phase_status, "blocked");
        let goal_status: String = connection
            .query_row("SELECT status FROM goals WHERE id='g1'", [], |r| r.get(0))
            .expect("goal");
        assert_eq!(goal_status, "paused", "超限应暂停 goal 等人工");

        // 事件：两条 retry + 一条 blocked。
        let events = super::query_goal_events_connection(&connection, "g1", 100).expect("events");
        let retry_events = events
            .iter()
            .filter(|e| e.event_type == "goal-phase-retry")
            .count();
        let blocked_events = events
            .iter()
            .filter(|e| e.event_type == "goal-phase-blocked")
            .count();
        assert_eq!(retry_events, 2);
        assert_eq!(blocked_events, 1);
        // verdict/reason/evidence 也落库了。
        let (verdict, reason): (String, String) = connection
            .query_row(
                "SELECT last_verdict, last_reason FROM goal_phases WHERE id='impl'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .expect("verdict");
        assert_eq!(verdict, "fail");
        assert_eq!(reason, "门失败");
    }

    /// GL-05/06（codex 审查 #2）：含 blocked phase 的 goal 绝不能被判为已完成，
    /// blocked 要单独计数（此前落进 other，导致定时任务把 blocked goal 误写成 completed）。
    #[test]
    fn blocked_phase_keeps_goal_unfinished() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("blocked.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        // goal 已 paused（apply 超限时会这么置），一个 completed + 一个 blocked phase。
        connection
            .execute_batch(
                "INSERT INTO goals VALUES \
                 ('g1','ws','room','目标','paused',5,1,0,NULL,'{}',NULL,10,20,NULL); \
                 INSERT INTO goal_phases \
                   (id,goal_id,title,assigned_role,status,depends_on_json,skills_json,\
                    output_artifacts_json,verification_json,created_at,updated_at,retry_count,max_retries) \
                 VALUES \
                   ('impl','g1','实现','implementer','completed','[]','[]','[]',NULL,10,10,0,2), \
                   ('verify','g1','验证','verifier','blocked','[\"impl\"]','[]','[]',NULL,20,20,3,2);",
            )
            .expect("seed");
        drop(connection);

        let status = super::goal_status_sqlite(&db, "ws", "g1").expect("status");
        assert_eq!(status.phase_counts.blocked, 1, "blocked 要单独计数");
        assert_eq!(status.phase_counts.completed, 1);
        assert!(
            !super::goal_status_is_finished(&status),
            "含 blocked phase 的 paused goal 不该被判为已完成"
        );
    }

    /// GL-05/06（codex 审查 #1）：commander review 绝不能把 blocked phase 归类为
    /// ready_to_dispatch——否则超重试上限后又被重新派发、绕过上限。
    #[test]
    fn commander_review_does_not_dispatch_blocked_phase() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("review.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        connection
            .execute_batch(
                "INSERT INTO goals VALUES \
                 ('g1','ws','room','目标','paused',5,1,0,NULL,'{}',NULL,10,20,NULL); \
                 INSERT INTO goal_phases \
                   (id,goal_id,title,assigned_role,status,depends_on_json,skills_json,\
                    output_artifacts_json,verification_json,created_at,updated_at,retry_count,max_retries) \
                 VALUES ('impl','g1','实现','implementer','blocked','[]','[]','[]',NULL,10,10,3,2);",
            )
            .expect("seed");
        drop(connection);

        // 空 sessions：blocked 分支排在 assigned_session_available 之前，仍应命中 blocked。
        let review = super::review_goal_commander_sqlite(&db, "ws", "g1", &[]).expect("review");
        let phase = review
            .phase_reviews
            .iter()
            .find(|p| p.phase_id == "impl")
            .expect("phase review");
        assert_eq!(
            phase.action, "blocked_retry_exhausted",
            "blocked phase 必须分类为 blocked_retry_exhausted，不能 ready_to_dispatch"
        );
        assert_ne!(phase.action, "ready_to_dispatch");
        assert!(review.pause_recommended, "有 blocked phase 应建议暂停");
    }

    /// GL-05/06（codex 二轮 #1）：re-plan 一个已 blocked 的 phase 视为显式解阻——
    /// 重置 retry_count 给干净预算，而不是沿用超限计数（否则会绕过重试上限）。
    /// 非 blocked 的 phase 仍按 GL-03 保留 retry_count。
    #[test]
    fn replan_unblocks_blocked_phase_and_resets_budget() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("unblock.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        connection
            .execute_batch(
                "INSERT INTO goals VALUES \
                 ('g1','ws','room','目标','paused',5,1,0,NULL,'{}',NULL,10,20,NULL);",
            )
            .expect("seed goal");
        drop(connection);

        let plan = || super::GoalPlanRequest {
            phases: vec![
                super::GoalPlanPhaseRequest {
                    id: "impl".to_string(),
                    title: "实现".to_string(),
                    assigned_role: Some("implementer".to_string()),
                    depends_on: Vec::new(),
                    skills_required: Vec::new(),
                    output_artifacts: Vec::new(),
                    verification: None,
                    requires_human_ack: false,
                },
                super::GoalPlanPhaseRequest {
                    id: "verify".to_string(),
                    title: "验证".to_string(),
                    assigned_role: Some("verifier".to_string()),
                    depends_on: vec!["impl".to_string()],
                    skills_required: Vec::new(),
                    output_artifacts: Vec::new(),
                    verification: None,
                    requires_human_ack: false,
                },
            ],
        };
        super::set_goal_plan_sqlite(&db, "ws", "g1", plan()).expect("initial plan");

        // impl 超限 blocked（retry=3/max=2）；verify 正常重试中（retry=1/max=2，未 blocked）。
        let c = super::open_session_connection(&db).expect("open");
        c.execute(
            "UPDATE goal_phases SET status='blocked', retry_count=3, max_retries=2, last_verdict='fail' WHERE id='impl'",
            [],
        )
        .expect("block impl");
        c.execute(
            "UPDATE goal_phases SET retry_count=1, last_verdict='fail' WHERE id='verify'",
            [],
        )
        .expect("retry verify");
        drop(c);

        // 重规划（同一份计划）。
        super::set_goal_plan_sqlite(&db, "ws", "g1", plan()).expect("replan");

        let c = super::open_session_connection(&db).expect("open");
        let (impl_status, impl_retry): (String, i64) = c
            .query_row(
                "SELECT status, retry_count FROM goal_phases WHERE id='impl'",
                [],
                |r| Ok((r.get(0)?, r.get(1)?)),
            )
            .expect("impl");
        // blocked phase：重置为 pending + retry_count=0（干净预算），不再绕过上限。
        assert_eq!(impl_status, "pending", "解阻后应回 pending");
        assert_eq!(impl_retry, 0, "blocked phase 重规划应重置 retry_count");
        // 非 blocked 的 verify：retry_count 按 GL-03 保留。
        let verify_retry: i64 = c
            .query_row("SELECT retry_count FROM goal_phases WHERE id='verify'", [], |r| r.get(0))
            .expect("verify");
        assert_eq!(verify_retry, 1, "非 blocked phase 的 retry_count 仍保留");
        // 记了解阻事件。
        let events = super::query_goal_events_connection(&c, "g1", 100).expect("events");
        assert!(events.iter().any(|e| e.event_type == "goal-phase-unblocked"
            && e.payload["phase_id"] == "impl"));
    }

    /// GL-08 全局刹车：current_iteration 真实递增，达到 max_iterations 后 commander review
    /// 给出阻断理由、建议暂停，不再派发（此前该字段恒为 0，刹车形同虚设）。
    #[test]
    fn goal_iteration_budget_blocks_further_dispatch() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("brake.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        // max_iterations=2，current 从 0 开始。
        connection
            .execute_batch(
                "INSERT INTO goals VALUES \
                 ('g1','ws','room','目标','running',2,0,0,NULL,'{}',NULL,10,20,NULL); \
                 INSERT INTO goal_phases \
                   (id,goal_id,title,assigned_role,status,depends_on_json,skills_json,\
                    output_artifacts_json,verification_json,created_at,updated_at,retry_count,max_retries) \
                 VALUES ('impl','g1','实现','implementer','pending','[]','[]','[]',NULL,10,10,0,2);",
            )
            .expect("seed");

        // 预算未耗尽时不因刹车阻断。
        let review = super::review_goal_commander_sqlite(&db, "ws", "g1", &[]).expect("review");
        assert!(
            !review.blocking_reasons.iter().any(|r| r.contains("iteration budget")),
            "预算未耗尽不该出现刹车阻断"
        );

        // 占用两次到达上限。
        let (c1, m1) = super::reserve_goal_iteration_connection(&connection, "ws", "g1")
            .expect("reserve1")
            .expect("额度充足时应占用成功");
        assert_eq!((c1, m1), (1, 2));
        let (c2, _) = super::reserve_goal_iteration_connection(&connection, "ws", "g1")
            .expect("reserve2")
            .expect("额度充足时应占用成功");
        assert_eq!(c2, 2, "current_iteration 必须真实递增");
        // 第三次必须占不到——条件 UPDATE 原子拒绝，杜绝 check-then-act 并发超额。
        assert!(
            super::reserve_goal_iteration_connection(&connection, "ws", "g1")
                .expect("reserve3")
                .is_none(),
            "额度耗尽后必须占用失败，不能顶到 max+1"
        );
        // 且不会把计数顶过上限。
        let after: i64 = connection
            .query_row("SELECT current_iteration FROM goals WHERE id='g1'", [], |r| r.get(0))
            .expect("count");
        assert_eq!(after, 2, "占用失败不该递增");
        drop(connection);

        // 达到 max_iterations → commander review 阻断并建议暂停。
        let review = super::review_goal_commander_sqlite(&db, "ws", "g1", &[]).expect("review");
        assert!(
            review.blocking_reasons.iter().any(|r| r.contains("iteration budget exhausted")),
            "预算耗尽应给出刹车阻断理由"
        );
        assert!(review.pause_recommended);
    }

    /// GL-07：被打回重跑的 phase，派发 intent 必须带上「上次为什么失败 + 证据 + 第几次重试」，
    /// 否则 agent 拿到的 intent 与首次一模一样，只会原样重做。
    #[test]
    fn dispatch_intent_carries_retry_reason_and_evidence() {
        // 直接复用 dispatch 构造 intent 的同款逻辑做断言：retry_count>0 才注入。
        let base = super::GoalPhaseDto {
            id: "impl".to_string(),
            goal_id: "g1".to_string(),
            title: "实现".to_string(),
            assigned_role: "implementer".to_string(),
            assigned_session_id: Some("goal-implementer".to_string()),
            assigned_session_display_name: None,
            assigned_session_available: true,
            status: "running".to_string(),
            depends_on: Vec::new(),
            skills_required: Vec::new(),
            output_artifacts: Vec::new(),
            verification: None,
            retry_count: 0,
            max_retries: 2,
            last_verdict: None,
            last_reason: None,
            last_evidence: None,
            route_hint: None,
            created_at: 1,
            updated_at: 1,
            requires_human_ack: false,
            human_ack: None,
        };
        // 首次派发：不注入重试上下文。
        assert_eq!(super::goal_phase_retry_intent_context(&base), "");

        // 被打回：注入原因/证据/重试计数。
        let bounced = super::GoalPhaseDto {
            retry_count: 1,
            last_verdict: Some("fail".to_string()),
            last_reason: Some("缺少 tests/foo.rs".to_string()),
            last_evidence: Some(serde_json::json!({ "missing_artifacts": ["tests/foo.rs"] })),
            ..base
        };
        let ctx = super::goal_phase_retry_intent_context(&bounced);
        assert!(ctx.contains("retry 1/2"), "应含重试计数: {ctx}");
        assert!(ctx.contains("缺少 tests/foo.rs"), "应含失败原因: {ctx}");
        assert!(ctx.contains("tests/foo.rs"), "应含证据: {ctx}");
        assert!(ctx.contains("fail"), "应含上次结论: {ctx}");
    }

    /// GL-08（codex #1）：预算耗尽导致的暂停不许直接 resume——否则 resume 就是绕过
    /// 全局天花板的后门（耗尽→暂停→resume→再跑→…无限）。
    #[test]
    fn resume_refuses_when_iteration_budget_exhausted() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("resume.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        // 预算耗尽(2/2)且已暂停。
        connection
            .execute_batch(
                "INSERT INTO goals VALUES \
                 ('g1','ws','room','目标','paused',2,2,0,NULL,'{}',NULL,10,20,NULL);",
            )
            .expect("seed exhausted");
        drop(connection);
        let err = super::resume_goal_sqlite(&db, "ws", "g1");
        assert!(err.is_err(), "预算耗尽时 resume 必须被拒绝");

        // 抬高 max_iterations 后可以恢复。
        let c = super::open_session_connection(&db).expect("open");
        c.execute("UPDATE goals SET max_iterations = 5 WHERE id='g1'", [])
            .expect("raise budget");
        drop(c);
        let ok = super::resume_goal_sqlite(&db, "ws", "g1").expect("抬高上限后应可 resume");
        assert_ne!(ok.goal.status, "paused");
    }

    /// GL-07（codex #6）：证据摘要按字段裁剪，不产出被硬截断的伪 JSON。
    #[test]
    fn evidence_digest_summarizes_without_broken_json() {
        let missing = super::goal_phase_evidence_digest(&serde_json::json!({
            "missing_artifacts": ["a.rs", "b.rs"],
            "text": "verifier 拒绝"
        }));
        assert!(missing.contains("missing artifacts: a.rs, b.rs"), "{missing}");
        assert!(missing.contains("report: verifier 拒绝"), "{missing}");
        // 不应是原始 JSON 串
        assert!(!missing.starts_with('{'), "不该直接吐 JSON: {missing}");

        // 超长命令输出：截断处有明确标记，且不残留半个 JSON。
        let long = "x".repeat(1000);
        let cmd = super::goal_phase_evidence_digest(&serde_json::json!({
            "command_failures": [long]
        }));
        assert!(cmd.contains("…[truncated]"), "截断需标注: {}", &cmd[..80.min(cmd.len())]);
        assert!(cmd.starts_with("command failures:"), "{}", &cmd[..40.min(cmd.len())]);

        // 未知形态兜底也标注截断，不假装是完整 JSON。
        let unknown = super::goal_phase_evidence_digest(&serde_json::json!({ "weird": long }));
        assert!(unknown.contains("…[truncated]"));
    }

    /// GL-13 场景：高风险阶段（如"上线到生产"）标 requires_human_ack。
    /// 依赖满足、会话就绪后 commander review 不放行，而是 awaiting_human_ack；
    /// 人工批准后可派发；人工拒绝则阶段 blocked、goal 暂停。
    #[test]
    fn human_ack_gate_blocks_dispatch_until_approved() {
        let _guard = config_test_guard();
        let temp = tempfile::tempdir().expect("tempdir");
        let (store, db_path) = gl09_store_with_roles(&temp, &["implementer"]);
        let goal = super::create_goal_sqlite(
            &db_path,
            "ws",
            "room-1",
            super::CreateGoalRequest {
                title: "上线发布".to_string(),
                chat_room_id: Some("room-1".to_string()),
                max_iterations: Some(10),
                background: Some(false),
                originating_user_msg_id: None,
                completion_condition: Some(serde_json::json!({ "type": "Manual" })),
            },
        )
        .expect("goal");
        // deploy 阶段标为需人工确认。
        super::set_goal_plan_sqlite(
            &db_path,
            "ws",
            &goal.id,
            super::GoalPlanRequest {
                phases: vec![super::GoalPlanPhaseRequest {
                    id: "deploy".to_string(),
                    title: "部署到生产".to_string(),
                    assigned_role: Some("implementer".to_string()),
                    depends_on: Vec::new(),
                    skills_required: Vec::new(),
                    output_artifacts: Vec::new(),
                    verification: None,
                    requires_human_ack: true,
                }],
            },
        )
        .expect("plan");

        let action_of = || -> String {
            super::refresh_goal_runtime_role_heartbeats(&db_path, "ws");
            super::review_goal_commander_sqlite(&db_path, "ws", &goal.id, &store.state.sessions)
                .expect("review")
                .phase_reviews
                .into_iter()
                .find(|p| p.phase_id == "deploy")
                .expect("phase")
                .action
        };

        // 未确认 → 不放行。
        assert_eq!(action_of(), "awaiting_human_ack", "高风险阶段派发前须人工确认");

        // 真实流程里是 dispatch 把阶段置成 awaiting 的（mark_goal_phases_awaiting_ack）。
        // ack 严格要求从 awaiting 转移，所以这里必须先走这一步。
        let enter_awaiting = || {
            let review = super::review_goal_commander_sqlite(
                &db_path,
                "ws",
                &goal.id,
                &store.state.sessions,
            )
            .expect("review");
            store
                .mark_goal_phases_awaiting_ack("ws", &goal.id, &review)
                .expect("mark awaiting");
        };
        enter_awaiting();

        // 拒绝 → 阶段 blocked、goal 暂停、记事件。
        let rejected = super::ack_goal_phase_sqlite(
            &db_path,
            "ws",
            &goal.id,
            "deploy",
            super::GoalPhaseAckRequest {
                approved: false,
                reason: Some("发布窗口未到".to_string()),
            },
        )
        .expect("reject");
        let phase = rejected
            .goal
            .phases
            .iter()
            .find(|p| p.id == "deploy")
            .expect("deploy");
        assert_eq!(phase.status, "blocked", "拒绝后阶段应 blocked");
        assert_eq!(phase.human_ack.as_deref(), Some("rejected"));
        assert_eq!(rejected.goal.status, "paused");
        assert!(rejected
            .goal
            .recent_events
            .iter()
            .any(|e| e.event_type == "goal-phase-ack-rejected"));
        // 已拒绝不可再确认（须重新规划）。
        assert!(super::ack_goal_phase_sqlite(
            &db_path,
            "ws",
            &goal.id,
            "deploy",
            super::GoalPhaseAckRequest { approved: true, reason: None },
        )
        .is_err());

        // 重新规划 → human_ack 重置，重新回到等待确认。
        super::set_goal_plan_sqlite(
            &db_path,
            "ws",
            &goal.id,
            super::GoalPlanRequest {
                phases: vec![super::GoalPlanPhaseRequest {
                    id: "deploy".to_string(),
                    title: "部署到生产".to_string(),
                    assigned_role: Some("implementer".to_string()),
                    depends_on: Vec::new(),
                    skills_required: Vec::new(),
                    output_artifacts: Vec::new(),
                    verification: None,
                    requires_human_ack: true,
                }],
            },
        )
        .expect("replan");
        assert_eq!(action_of(), "awaiting_human_ack", "重规划后须重新确认");
        enter_awaiting();

        // 批准 → 放行可派发，goal 恢复。
        let approved = super::ack_goal_phase_sqlite(
            &db_path,
            "ws",
            &goal.id,
            "deploy",
            super::GoalPhaseAckRequest { approved: true, reason: None },
        )
        .expect("approve");
        assert_ne!(approved.goal.status, "paused", "批准后 goal 应恢复");
        assert!(approved
            .goal
            .recent_events
            .iter()
            .any(|e| e.event_type == "goal-phase-ack-approved"));
        assert_eq!(action_of(), "ready_to_dispatch", "批准后应可派发");

        // 普通阶段（未标 requires_human_ack）不接受 ack。
        assert!(super::ack_goal_phase_sqlite(
            &db_path,
            "ws",
            &goal.id,
            "nonexistent",
            super::GoalPhaseAckRequest { approved: true, reason: None },
        )
        .is_err());
    }

    /// GL-13（codex 场景实测 #1/#2 回归锁）：确认只允许 `awaiting` → approved/rejected 的
    /// **单次**转移。未进入等待的阶段不能被凭空批准；批准/拒绝都是终态，不能互相覆盖
    /// （并发下条件 UPDATE 只让一个命中）；批准也不该解除因别的原因造成的暂停。
    #[test]
    fn ack_requires_awaiting_state_and_is_single_shot() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("ack-fsm.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        connection
            .execute_batch(
                "INSERT INTO goals VALUES \
                 ('g1','ws','room','目标','paused',10,1,0,NULL,'{}',NULL,10,20,NULL); \
                 INSERT INTO goal_phases \
                   (id,goal_id,title,assigned_role,status,depends_on_json,skills_json,\
                    output_artifacts_json,verification_json,created_at,updated_at,\
                    retry_count,max_retries,requires_human_ack,human_ack) \
                 VALUES \
                   ('deploy','g1','上线','implementer','pending','[]','[]','[]',NULL,10,10,0,2,1,NULL), \
                   ('other','g1','另一个','implementer','blocked','[]','[]','[]',NULL,20,20,3,2,0,NULL);",
            )
            .expect("seed");
        drop(connection);

        let ack = |approved: bool| {
            super::ack_goal_phase_sqlite(
                &db,
                "ws",
                "g1",
                "deploy",
                super::GoalPhaseAckRequest { approved, reason: None },
            )
        };

        // human_ack 还是 NULL（没进入等待）→ 不能凭空批准。
        assert!(ack(true).is_err(), "未进入等待的阶段不该能被批准");

        // 置为 awaiting 后可批准。
        let c = super::open_session_connection(&db).expect("open");
        c.execute(
            "UPDATE goal_phases SET human_ack='awaiting' WHERE id='deploy'",
            [],
        )
        .expect("await");
        drop(c);
        let approved = ack(true).expect("批准应成功");
        let deploy = approved
            .goal
            .phases
            .iter()
            .find(|p| p.id == "deploy")
            .expect("deploy");
        assert_eq!(deploy.human_ack.as_deref(), Some("approved"));
        // 还有一个 blocked 的 other 阶段 → goal 不该被这次批准放出来。
        assert_eq!(
            approved.goal.status, "paused",
            "还有其它阻塞时，批准不该解除暂停"
        );

        // 批准是终态：不能再被拒绝覆盖（并发场景的关键）。
        assert!(ack(false).is_err(), "已批准的阶段不该还能被拒绝");
    }

    /// GL-10：v14 迁移给 chat_handoffs 加 contract_json；结构化契约往返落库/读回，
    /// 旧记录（contract=None）向后兼容。
    #[test]
    fn chat_handoff_contract_roundtrips_and_defaults_none() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("handoff.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        // 迁移后 user_version=14，contract_json 列存在。
        let version: i64 = connection
            .query_row("PRAGMA user_version", [], |r| r.get(0))
            .expect("version");
        assert_eq!(version, 15);
        let cols: Vec<String> = connection
            .prepare("PRAGMA table_info(chat_handoffs)")
            .expect("pragma")
            .query_map([], |r| r.get::<_, String>(1))
            .expect("q")
            .filter_map(Result::ok)
            .collect();
        assert!(cols.contains(&"contract_json".to_string()));
        // chat_handoffs.chat_room_id 有外键 → 先建房间。
        connection
            .execute(
                "INSERT INTO chat_rooms(id, name, created_at, updated_at) VALUES ('room','R',1,1)",
                [],
            )
            .expect("seed room");
        drop(connection);

        let mk = |id: &str, contract: Option<serde_json::Value>| super::ChatHandoffRecord {
            id: id.to_string(),
            chat_room_id: "room".to_string(),
            from_agent_id: "goal-commander".to_string(),
            to_agent_id: "goal-implementer".to_string(),
            intent: "重跑".to_string(),
            intent_hash: "h".to_string(),
            attach: "none".to_string(),
            attach_message_ids: Vec::new(),
            originating_user_msg_id: "u".to_string(),
            depth: 0,
            status: "delivered".to_string(),
            rejected_reason: None,
            contract,
            created_at: 100,
            delivered_at: Some(100),
            completed_at: None,
        };
        // 带结构化契约的回退交接。
        super::insert_chat_handoff_sqlite(
            &db,
            &mk(
                "h-retry",
                Some(serde_json::json!({
                    "kind": "goal-phase-retry",
                    "phase_id": "impl",
                    "verdict": "fail",
                    "reason": "缺 tests",
                    "retry_count": 1,
                    "max_retries": 2
                })),
            ),
        )
        .expect("insert retry");
        // 普通交接（无契约）。
        super::insert_chat_handoff_sqlite(&db, &mk("h-plain", None)).expect("insert plain");

        let conn = super::open_session_connection(&db).expect("open");
        let all = super::query_all_chat_handoffs_from_connection(&conn).expect("read");
        let retry = all.iter().find(|h| h.id == "h-retry").expect("retry row");
        assert_eq!(retry.contract.as_ref().unwrap()["verdict"], "fail");
        assert_eq!(retry.contract.as_ref().unwrap()["retry_count"], 1);
        let plain = all.iter().find(|h| h.id == "h-plain").expect("plain row");
        assert!(plain.contract.is_none(), "普通交接 contract 应为 None");

        // codex #2：库里若存了非法 JSON（外部篡改/历史脏数据），读回应原样保留成字符串，
        // 不能静默丢成 None（否则 save() 全量重写会把它永久抹掉）。
        let c = super::open_session_connection(&db).expect("open");
        c.execute(
            "UPDATE chat_handoffs SET contract_json = '{not valid json' WHERE id = 'h-plain'",
            [],
        )
        .expect("corrupt");
        let reread = super::query_all_chat_handoffs_from_connection(&c).expect("reread");
        let corrupted = reread.iter().find(|h| h.id == "h-plain").expect("row");
        assert_eq!(
            corrupted.contract.as_ref().and_then(|v| v.as_str()),
            Some("{not valid json"),
            "非法 JSON 应原样保留成字符串，不丢失"
        );
    }

    /// GL-12：从指定 phase 断点续跑——目标 phase 及其传递下游重置为 pending 且清空路由状态，
    /// 上游已完成的 phase 原样保留，goal 置回 running。
    #[test]
    fn resume_from_phase_resets_target_and_downstream_only() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("resume-from.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        // 链：plan(completed) → impl(blocked,retry=3) → verify(pending, deps impl)。
        // 另有一条独立分支 docs(completed, 不依赖 impl)，不应被重置。
        connection
            .execute_batch(
                "INSERT INTO goals VALUES \
                 ('g1','ws','room','目标','paused',10,3,0,NULL,'{}',NULL,10,20,NULL); \
                 INSERT INTO goal_phases \
                   (id,goal_id,title,assigned_role,status,depends_on_json,skills_json,\
                    output_artifacts_json,verification_json,created_at,updated_at,retry_count,max_retries,last_verdict) \
                 VALUES \
                   ('plan','g1','规划','planner','completed','[]','[]','[]',NULL,10,10,0,2,'pass'), \
                   ('impl','g1','实现','implementer','blocked','[\"plan\"]','[]','[]',NULL,20,20,3,2,'fail'), \
                   ('verify','g1','验证','verifier','pending','[\"impl\"]','[]','[]',NULL,30,30,1,2,'fail'), \
                   ('docs','g1','文档','implementer','completed','[]','[]','[]',NULL,40,40,0,2,'pass');",
            )
            .expect("seed");
        drop(connection);

        let status = super::resume_goal_from_phase_sqlite(&db, "ws", "g1", "impl").expect("resume-from");
        let phase = |id: &str| status.goal.phases.iter().find(|p| p.id == id).cloned().expect(id);

        // 目标 impl + 下游 verify 重置为 pending、路由状态清空。
        let im = phase("impl");
        assert_eq!(im.status, "pending");
        assert_eq!(im.retry_count, 0);
        assert!(im.last_verdict.is_none());
        let ve = phase("verify");
        assert_eq!(ve.status, "pending", "下游 verify 应一并重置");
        assert_eq!(ve.retry_count, 0);
        assert!(ve.last_verdict.is_none());
        // 上游 plan 与独立分支 docs 保持 completed。
        assert_eq!(phase("plan").status, "completed", "上游不该被重置");
        assert_eq!(phase("docs").status, "completed", "不依赖目标的分支不该被重置");
        // goal 置回 running。
        assert_eq!(status.goal.status, "running");
        assert!(status
            .goal
            .recent_events
            .iter()
            .any(|e| e.event_type == "goal-resumed-from-phase"
                && e.payload["from_phase_id"] == "impl"));

        // codex #2：预算耗尽时 resume-from 与普通 resume 一致——拒绝，先抬高上限。
        let c = super::open_session_connection(&db).expect("open");
        c.execute("UPDATE goals SET current_iteration=10, max_iterations=10 WHERE id='g1'", [])
            .expect("exhaust");
        drop(c);
        assert!(
            super::resume_goal_from_phase_sqlite(&db, "ws", "g1", "impl").is_err(),
            "预算耗尽时 resume-from 应被拒绝"
        );
    }

    /// GL-09 辅助：搭一个带 commander + 指定角色会话的 store，供路由端到端测试复用。
    fn gl09_store_with_roles(
        temp: &tempfile::TempDir,
        roles: &[&str],
    ) -> (super::SessionStore, std::path::PathBuf) {
        let db_path = temp.path().join("sessions.sqlite3");
        let now = super::unix_timestamp_millis();
        let mut base = super::seed_session();
        base.id = "base".to_string();
        base.name = "commander".to_string();
        base.messages = Vec::new();
        let mut store = super::SessionStore {
            path: db_path.clone(),
            legacy_json_path: temp.path().join("sessions.json"),
            capacity: super::SessionStoreCapacity::default(),
            state: super::PersistedSessionState {
                sessions: vec![base],
                active_session_id: Some("base".to_string()),
                active_vision_session_id: None,
                chat_rooms: vec![super::PersistedChatRoom {
                    id: "room-1".to_string(),
                    name: "Room 1".to_string(),
                    created_at: now,
                    updated_at: now,
                    messages: Vec::new(),
                }],
                active_chat_room_id: Some("room-1".to_string()),
            },
        };
        store.save().expect("save");
        store
            .ensure_goal_role_sessions(roles.iter().map(|r| r.to_string()).collect())
            .expect("bootstrap roles");
        super::upsert_goal_role_config_sqlite(
            &db_path,
            "base",
            super::GoalRoleConfigUpdateRequest {
                role: Some("commander".to_string()),
                responsibility: Some("commander".to_string()),
                commander: Some(true),
                heartbeat_timeout_ms: Some(60_000),
                task_timeout_ms: Some(600_000),
            },
        )
        .expect("commander config");
        for role in roles {
            super::upsert_goal_role_config_sqlite(
                &db_path,
                &format!("goal-{role}"),
                super::GoalRoleConfigUpdateRequest {
                    role: Some((*role).to_string()),
                    responsibility: Some((*role).to_string()),
                    commander: Some(false),
                    heartbeat_timeout_ms: Some(60_000),
                    task_timeout_ms: Some(600_000),
                },
            )
            .unwrap_or_else(|_| panic!("{role} config"));
        }
        (store, db_path)
    }

    /// GL-09 路径①「pass 前进」：依赖阶段 completed 后，下游阶段变为 ready_to_dispatch；
    /// 依赖未满足时是 wait_dependency，不会越过依赖抢跑。
    #[test]
    fn routing_pass_advances_to_next_dependency_satisfied_phase() {
        let _guard = config_test_guard();
        let temp = tempfile::tempdir().expect("tempdir");
        let (mut store, db_path) = gl09_store_with_roles(&temp, &["implementer", "verifier"]);
        let goal = super::create_goal_sqlite(
            &db_path,
            "ws",
            "room-1",
            super::CreateGoalRequest {
                title: "pass 前进".to_string(),
                chat_room_id: Some("room-1".to_string()),
                max_iterations: Some(8),
                background: Some(false),
                originating_user_msg_id: None,
                completion_condition: Some(serde_json::json!({ "type": "Manual" })),
            },
        )
        .expect("goal");
        super::set_goal_plan_sqlite(
            &db_path,
            "ws",
            &goal.id,
            super::GoalPlanRequest {
                phases: vec![
                    super::GoalPlanPhaseRequest {
                        id: "impl".to_string(),
                        title: "实现".to_string(),
                        assigned_role: Some("implementer".to_string()),
                        depends_on: Vec::new(),
                        skills_required: Vec::new(),
                        output_artifacts: Vec::new(),
                        verification: None,
                        requires_human_ack: false,
                    },
                    super::GoalPlanPhaseRequest {
                        id: "verify".to_string(),
                        title: "验证".to_string(),
                        assigned_role: Some("verifier".to_string()),
                        depends_on: vec!["impl".to_string()],
                        skills_required: Vec::new(),
                        output_artifacts: Vec::new(),
                        verification: None,
                        requires_human_ack: false,
                    },
                ],
            },
        )
        .expect("plan");

        // 取 sessions 作参数（而不是闭包捕获 store），避免与下面的 &mut store 调用冲突。
        let action_of = |sessions: &[super::PersistedSession], phase_id: &str| -> String {
            // 刷新角色心跳，避免刚 bootstrap 的会话被判 offline（offline 判定排在依赖判定之前）。
            super::refresh_goal_runtime_role_heartbeats(&db_path, "ws");
            let review = super::review_goal_commander_sqlite(&db_path, "ws", &goal.id, sessions)
                .expect("review");
            review
                .phase_reviews
                .into_iter()
                .find(|p| p.phase_id == phase_id)
                .expect("phase review")
                .action
        };

        // impl 未完成时，verify 应等待依赖（不抢跑）。
        assert_eq!(action_of(&store.state.sessions, "verify"), "wait_dependency");
        assert_eq!(action_of(&store.state.sessions, "impl"), "ready_to_dispatch");

        // codex #1：走真实 pass 链路——impl 置 running，用无失败的模型答复经
        // record_goal_phase_model_result 完成（而不是直接改库造 completed），
        // 断言 impl completed + last_verdict=pass，再确认 verify 因依赖满足而前进。
        let connection = super::open_session_connection(&db_path).expect("open");
        super::update_goal_phase_status_connection(&connection, "ws", &goal.id, "impl", "running")
            .expect("mark running");
        drop(connection);
        let agent = store
            .state
            .sessions
            .iter()
            .find(|s| s.id == "goal-implementer")
            .expect("implementer session")
            .to_agent_session(false);
        let result = store
            .record_goal_phase_model_result(
                "ws",
                &goal.id,
                "impl",
                &agent,
                super::AgentModelResponse {
                    answer_text: "实现完成，产物已就绪。".to_string(),
                    reasoning_text: String::new(),
                    tool_requests: Vec::new(),
                    tool_write_executed: false,
                    model_tool_calls_executed: false,
                    turn_id: "t".to_string(),
                    used_real_model: false,
                    diagnostic_note: None,
                    context_footer: None,
                    context_usage: None,
                },
                Vec::new(),
                Vec::new(),
            )
            .expect("record pass");
        let impl_phase = result
            .status
            .goal
            .phases
            .iter()
            .find(|p| p.id == "impl")
            .expect("impl");
        assert_eq!(impl_phase.status, "completed", "无失败的执行应完成 phase");
        assert_eq!(impl_phase.last_verdict.as_deref(), Some("pass"), "完成即记 pass");
        assert_eq!(
            action_of(&store.state.sessions, "verify"),
            "ready_to_dispatch",
            "依赖 completed 后应前进"
        );
    }

    /// GL-09 路径④「implementer→planner」：implementer 报「无法完成」→ 阶段回 pending、
    /// goal 暂停、retry_count 递增；累计超上限后置 blocked。
    #[test]
    fn routing_implementer_blocked_bounces_to_planner_then_blocks() {
        let _guard = config_test_guard();
        let temp = tempfile::tempdir().expect("tempdir");
        let (mut store, db_path) = gl09_store_with_roles(&temp, &["implementer"]);
        let goal = super::create_goal_sqlite(
            &db_path,
            "ws",
            "room-1",
            super::CreateGoalRequest {
                title: "implementer 报阻".to_string(),
                chat_room_id: Some("room-1".to_string()),
                max_iterations: Some(20),
                background: Some(false),
                originating_user_msg_id: None,
                completion_condition: Some(serde_json::json!({ "type": "Manual" })),
            },
        )
        .expect("goal");
        super::set_goal_plan_sqlite(
            &db_path,
            "ws",
            &goal.id,
            super::GoalPlanRequest {
                phases: vec![super::GoalPlanPhaseRequest {
                    id: "impl".to_string(),
                    title: "实现".to_string(),
                    assigned_role: Some("implementer".to_string()),
                    depends_on: Vec::new(),
                    skills_required: Vec::new(),
                    output_artifacts: Vec::new(),
                    verification: None,
                    requires_human_ack: false,
                }],
            },
        )
        .expect("plan");
        let agent = store
            .state
            .sessions
            .iter()
            .find(|s| s.id == "goal-implementer")
            .expect("implementer session")
            .to_agent_session(false);

        let run_blocked = |store: &mut super::SessionStore| {
            let connection = super::open_session_connection(&db_path).expect("open");
            super::update_goal_phase_status_connection(&connection, "ws", &goal.id, "impl", "running")
                .expect("mark running");
            drop(connection);
            store
                .record_goal_phase_model_result(
                    "ws",
                    &goal.id,
                    "impl",
                    &agent,
                    super::AgentModelResponse {
                        answer_text: "BLOCKED: 依赖的外部接口不存在，无法完成此计划。".to_string(),
                        reasoning_text: String::new(),
                        tool_requests: Vec::new(),
                        tool_write_executed: false,
                        model_tool_calls_executed: false,
                        turn_id: "t".to_string(),
                        used_real_model: false,
                        diagnostic_note: None,
                        context_footer: None,
                        context_usage: None,
                    },
                    Vec::new(),
                    Vec::new(),
                )
                .expect("record blocked")
        };

        let impl_phase = |status: &super::GoalStatusResponse| {
            status.goal.phases.iter().find(|p| p.id == "impl").cloned().expect("impl")
        };
        // codex #3：连续三次真实报阻（每次非终态后模拟 resume），逐次断言，
        // 让 off-by-one（>= vs >）无处遁形，并验证 retry_count 经 save/重读不丢。
        // max_retries 默认 2：retry 1、2 保持 pending 重规划，retry 3 才 blocked。
        let resume_running = || {
            let c = super::open_session_connection(&db_path).expect("open");
            c.execute("UPDATE goals SET status='running' WHERE id=?1", super::params![&goal.id])
                .expect("resume goal");
        };

        let r1 = run_blocked(&mut store);
        let p1 = impl_phase(&r1.status);
        assert_eq!(p1.status, "pending", "报阻应回 pending 交 planner");
        assert_eq!(p1.retry_count, 1);
        assert_eq!(r1.status.goal.status, "paused");
        assert!(r1
            .status
            .goal
            .recent_events
            .iter()
            .any(|e| e.event_type == "goal-phase-blocked-needs-replan"));

        resume_running();
        let r2 = run_blocked(&mut store);
        let p2 = impl_phase(&r2.status);
        assert_eq!(p2.status, "pending", "retry 2/2 仍未超限，应保持 pending 而非 blocked");
        assert_eq!(p2.retry_count, 2);

        resume_running();
        let r3 = run_blocked(&mut store);
        let p3 = impl_phase(&r3.status);
        assert_eq!(p3.status, "blocked", "retry 3 > max 2 才 blocked");
        assert_eq!(p3.retry_count, 3);
        // codex #4：终态完整断言，堵住「phase blocked 但 goal 仍 running」这类回归。
        assert_eq!(r3.status.goal.status, "paused", "blocked 后 goal 应暂停");
        assert_eq!(p3.last_verdict.as_deref(), Some("fail"));
        assert!(p3.last_reason.is_some(), "应保留本次阻塞原因");
        assert!(r3.status.goal.recent_events.iter().any(|e| e.event_type == "goal-phase-blocked"
            && e.payload["phase_id"] == "impl"
            && e.payload["retry_count"].as_u64() == Some(3)
            && e.payload["max_retries"].as_u64() == Some(2)));
    }

    #[test]
    fn memory_edges_roundtrip_via_sqlite() {
        // E 关联图：迁移 v10 建表 → 覆盖式写边 → 一跳邻居按权重降序、剔除自身。
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("edges.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        connection
            .execute(
                "INSERT INTO sessions(id, name, provider, model, api_key_ref, created_at, updated_at) \
                 VALUES ('s1','S1','p','m','none',0,0)",
                [],
            )
            .expect("seed session");
        drop(connection);

        let edges = vec![
            ("bead-a".to_string(), "bead-b".to_string(), 0.7_f32),
            ("bead-a".to_string(), "bead-c".to_string(), 0.9_f32),
        ];
        assert_eq!(super::save_session_edges(&db, "s1", &edges), 2);

        let mut seed = std::collections::HashSet::new();
        seed.insert("bead-a".to_string());
        let neighbors = super::load_edge_neighbors(&db, "s1", &seed);
        let ids: Vec<String> = neighbors.iter().map(|(id, _)| id.clone()).collect();
        // 权重降序：c(0.9) 在 b(0.7) 前；自身 bead-a 不出现。
        assert_eq!(ids, vec!["bead-c".to_string(), "bead-b".to_string()]);
        assert!(!ids.contains(&"bead-a".to_string()));

        // 覆盖式写入：再次写空集应清空旧边。
        assert_eq!(super::save_session_edges(&db, "s1", &[]), 0);
        assert!(super::load_edge_neighbors(&db, "s1", &seed).is_empty());
    }

