    #[test]
    fn mark_beads_superseded_writes_and_is_idempotent() {
        // D 巩固：标记 superseded 写入 memory_meta；重复标记不产生重复行（幂等）。
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("consolidate.sqlite3");
        let connection = super::open_session_connection(&db).expect("open");
        super::initialize_session_schema(&connection).expect("schema");
        connection
            .execute(
                "INSERT INTO sessions(id, name, provider, model, api_key_ref, created_at, updated_at) \
                 VALUES ('s1','S1','p','m','none',0,0)",
                [],
            )
            .expect("seed session");
        drop(connection);

        super::mark_beads_superseded(&db, "s1", &["bead-x".to_string(), "bead-y".to_string()]);
        let connection = super::open_session_connection(&db).expect("reopen");
        let count: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM memory_meta WHERE session_id='s1' AND status='superseded'",
                [],
                |row| row.get(0),
            )
            .expect("count");
        assert_eq!(count, 2);

        // 幂等：再次标记 bead-x 不新增行。
        super::mark_beads_superseded(&db, "s1", &["bead-x".to_string()]);
        let count_again: i64 = connection
            .query_row(
                "SELECT COUNT(*) FROM memory_meta WHERE session_id='s1' AND status='superseded'",
                [],
                |row| row.get(0),
            )
            .expect("count again");
        assert_eq!(count_again, 2);
    }

    #[test]
    fn save_preserves_memory_side_tables_across_resave() {
        // 回归：save() 全量重写执行 `DELETE FROM sessions`，曾因 FK 级联抹掉记忆侧表
        // （memory_vectors/access/meta/edges），使 A/B/C/D/E 持久化每次 save 都丢失。
        // 修复后：会话仍在 → 侧表跨 save 存活；会话消失 → 孤儿行被清理。
        let tmp = tempfile::tempdir().expect("tempdir");
        let db = tmp.path().join("resave.sqlite3");
        let mk = |id: &str| -> super::PersistedSession {
            serde_json::from_value(serde_json::json!({
                "id": id, "name": id, "provider": "p", "model": "m",
                "api_key_ref": "", "created_at": 0, "updated_at": 0
            }))
            .expect("build session")
        };
        let cap = super::SessionStoreCapacity::default();
        // 首存：s1 + s2 均在。
        let state_both = super::PersistedSessionState {
            sessions: vec![mk("s1"), mk("s2")],
            ..Default::default()
        };
        super::save_session_state_to_sqlite(&db, &state_both, cap).expect("save1");

        // 直接写侧表：s1 行（应跨 save 存活）+ s2 行（s2 随后被移除 → 应被孤儿清理）。
        {
            let conn = super::open_session_connection(&db).expect("open");
            conn.execute(
                "INSERT INTO memory_meta(session_id,bead_id,entity_key,status,updated_at) \
                 VALUES ('s1','b1','user.pref','superseded',0)",
                [],
            )
            .expect("meta s1");
            conn.execute(
                "INSERT INTO memory_vectors(session_id,bead_id,model_id,dim,vec,created_at) \
                 VALUES ('s1','b1','bge-m3',1,X'00',0)",
                [],
            )
            .expect("vec s1");
            conn.execute(
                "INSERT INTO memory_meta(session_id,bead_id,entity_key,status,updated_at) \
                 VALUES ('s2','b2','k','active',0)",
                [],
            )
            .expect("meta s2");
        }

        // 再存：仅保留 s1（移除 s2）。修复前 `DELETE FROM sessions` 会级联清空 s1 的侧表行。
        let state_s1 = super::PersistedSessionState {
            sessions: vec![mk("s1")],
            ..Default::default()
        };
        super::save_session_state_to_sqlite(&db, &state_s1, cap).expect("save2");

        let conn = super::open_session_connection(&db).expect("reopen");
        let s1_meta: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM memory_meta WHERE session_id='s1'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        let s1_vec: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM memory_vectors WHERE session_id='s1'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        let s2_meta: i64 = conn
            .query_row(
                "SELECT COUNT(*) FROM memory_meta WHERE session_id='s2'",
                [],
                |r| r.get(0),
            )
            .unwrap();
        assert_eq!(s1_meta, 1, "存活会话的 memory_meta 应跨 save 保留");
        assert_eq!(s1_vec, 1, "存活会话的 memory_vectors 应跨 save 保留");
        assert_eq!(s2_meta, 0, "已移除会话的侧表行应被孤儿清理");
    }

    #[test]
    fn run_model_tool_dispatch_readonly_through_runtime() {
        // 路径 B：read_file "runtime_tool_execute "Ok "route=runtime-executed
        let _guard = config_test_guard();
        let tmp = tempfile::tempdir().expect("tempdir");
        let data_dir = tmp.path().join(super::DATA_DIR_NAME);
        std::fs::create_dir_all(&data_dir).expect("mkdir");
        let _session_db_env = scoped_session_db_env(&data_dir);
        let patched = super::WorkspaceConfig {
            workspace: super::ConfigWorkspace {
                default_dir: Some(tmp.path().display().to_string()),
                ..Default::default()
            },
            ..Default::default()
        };
        let prev_config = {
            let mut guard = super::workspace_config().lock().expect("lock");
            std::mem::replace(&mut *guard, patched)
        };
        let prev_workspace = {
            let mut guard = super::workspace_state()
                .lock()
                .expect("workspace state lock");
            std::mem::replace(&mut guard.current, tmp.path().to_path_buf())
        };

        use std::io::Write;
        let file_path = tmp.path().join("llm-read.txt");
        std::fs::File::create(&file_path)
            .expect("create")
            .write_all(b"hello-llm-runtime")
            .expect("write");

        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let resp = rt
            .block_on(super::run_model_tool_dispatch(
                "read_file",
                &serde_json::json!({ "path": file_path.to_string_lossy() }),
            ))
            .expect("read_file runtime path succeeds");
        assert_eq!(resp.route, "runtime-executed");
        assert_eq!(resp.status, "ok");
        let plan = resp.dispatch_plan.as_ref().expect("plan present");
        assert_eq!(plan.tool_id, "read_file");
        assert!(plan.execute_allowed);
        assert_eq!(plan.llm_tool_call.mode, "runtime");
        let model_tool_result = resp
            .tool_result_text
            .as_deref()
            .expect("model tool result text should be present");
        assert!(
            model_tool_result.contains("hello-llm-runtime"),
            "ToolResult 回灌给模型时必须包含真实 read_file 输出，actual={model_tool_result}"
        );
        assert!(model_tool_result.contains("permission_gate: allow-auto"));

        let _ = std::mem::replace(
            &mut *super::workspace_config().lock().expect("lock"),
            prev_config,
        );
        let _ = std::mem::replace(
            &mut super::workspace_state()
                .lock()
                .expect("workspace state lock")
                .current,
            prev_workspace,
        );
    }

    #[test]
    fn run_model_tool_dispatch_write_file_goes_to_dry_run_and_pending() {
        // 路径 B：write_file "runtime_tool_execute；默认安全模式下
        // Protected 路径仍会 DryRunOnly + pending 登记。
        let _guard = config_test_guard();
        let tmp = tempfile::tempdir().expect("tempdir");
        let data_dir = tmp.path().join(super::DATA_DIR_NAME);
        std::fs::create_dir_all(&data_dir).expect("mkdir");
        let _session_db_env = scoped_session_db_env(&data_dir);
        let patched = super::WorkspaceConfig {
            workspace: super::ConfigWorkspace {
                default_dir: Some(tmp.path().display().to_string()),
                ..Default::default()
            },
            tool: super::ConfigTool {
                dev_open_permissions: false,
                ..Default::default()
            },
            ..Default::default()
        };
        let prev_config = {
            let mut guard = super::workspace_config().lock().expect("lock");
            std::mem::replace(&mut *guard, patched)
        };
        let prev_workspace = {
            let mut guard = super::workspace_state()
                .lock()
                .expect("workspace state lock");
            std::mem::replace(&mut guard.current, tmp.path().to_path_buf())
        };

        // 目标路径"coolzhu.toml "Protected，RequireConfirm "DryRunOnly
        let target = tmp.path().join("coolzhu.toml");
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let resp = rt
            .block_on(super::run_model_tool_dispatch(
                "write_file",
                &serde_json::json!({
                    "path": target.to_string_lossy(),
                    "content": "x"
                }),
            ))
            .expect("write_file runtime path returns Ok(dispatch)");
        assert_eq!(resp.route, "runtime-dry-run");
        assert_eq!(resp.status, "dry-run-only");
        let plan = resp.dispatch_plan.as_ref().expect("plan present");
        assert!(!plan.execute_allowed);
        assert_eq!(plan.safety_gate, "require-confirm");

        let _ = std::mem::replace(
            &mut *super::workspace_config().lock().expect("lock"),
            prev_config,
        );
        let _ = std::mem::replace(
            &mut super::workspace_state()
                .lock()
                .expect("workspace state lock")
                .current,
            prev_workspace,
        );
    }

