    #[test]
    fn tool_event_bus_broadcasts_permission_required_on_enqueue() {
        // 订阅要先建立，否"send 时还没人接，就算"channel 也会被挤出。
        let mut rx = super::subscribe_tool_events();

        let call_id = "evt-req-unique-p".to_string();
        let invoke = super::ToolInvoke {
            call_id: call_id.clone(),
            tool_name: "bash".into(),
            input: serde_json::json!({"command": "ls"}),
            caller: super::ToolCaller::Llm,
            workspace_id: "ws-evt".into(),
            session_id: Some("ses-evt".into()),
            user_authorized: false,
            user_confirmed_twice: false,
        };
        let gate = runtime::PermissionGateReport {
            required: super::PermissionMode::DangerFullAccess,
            decision: super::PermissionDecision::RequireApproval,
            reason: "danger-inside".into(),
            protected_match: None,
            workspace_relative: true,
            affected_paths: vec![],
        };

        super::enqueue_pending_approval(&call_id, &invoke, &gate);

        // "channel 中与"call_id 匹配的事件；允许夹杂其它并发测试事件。
        let mut seen = false;
        for _ in 0..16 {
            match rx.try_recv() {
                Ok(super::ToolEvent::PermissionRequired(record)) if record.call_id == call_id => {
                    assert_eq!(record.tool_name, "bash");
                    assert_eq!(
                        record.permission.decision,
                        super::PermissionDecision::RequireApproval.as_str()
                    );
                    seen = true;
                    break;
                }
                Ok(_) => continue,
                Err(tokio::sync::broadcast::error::TryRecvError::Empty) => break,
                Err(tokio::sync::broadcast::error::TryRecvError::Lagged(_)) => continue,
                Err(tokio::sync::broadcast::error::TryRecvError::Closed) => break,
            }
        }
        assert!(seen, "应收到本 call_id PermissionRequired 事件");

        // 清理
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let _ = rt.block_on(super::api_tools_reject(Json(super::RejectRequest {
            call_id,
            reason: Some("cleanup".into()),
        })));
    }

