    #[test]
    fn pending_approval_roundtrip_approve_once_consumes_entry() {
        let call_id = "call-approve-once-unique-aaa".to_string();
        let invoke = super::ToolInvoke {
            call_id: call_id.clone(),
            tool_name: "bash".into(),
            input: serde_json::json!({"command": "ls"}),
            caller: super::ToolCaller::Llm,
            workspace_id: "ws-A".into(),
            session_id: Some("ses-1".into()),
            user_authorized: false,
            user_confirmed_twice: false,
        };
        let gate = runtime::PermissionGateReport {
            required: super::PermissionMode::DangerFullAccess,
            decision: super::PermissionDecision::RequireApproval,
            reason: "danger-inside-needs-first-approval".into(),
            protected_match: None,
            workspace_relative: true,
            affected_paths: vec!["/ws/...".into()],
        };
        super::enqueue_pending_approval(&call_id, &invoke, &gate);

        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let Json(list) = rt.block_on(super::api_tools_pending());
        let mine = list
            .pending
            .iter()
            .find(|r| r.call_id == call_id)
            .expect("call_id 应在 pending ");
        assert_eq!(mine.tool_name, "bash");
        assert!(mine.input_summary.starts_with("bash:"));

        let approve = super::ApproveRequest {
            call_id: call_id.clone(),
            scope: Some("once".into()),
            confirmed_twice: false,
        };
        let Json(resp) = rt
            .block_on(super::api_tools_approve(Json(approve)))
            .expect("approve ok");
        assert_eq!(resp.scope, "once");
        assert!(resp.ttl_secs.is_none(), "once scope must not set ttl");

        let Json(after) = rt.block_on(super::api_tools_pending());
        assert!(
            !after.pending.iter().any(|r| r.call_id == call_id),
            "call_id 应被 approve 消费"
        );
    }

