    #[test]
    fn pending_approval_reject_removes_entry_and_does_not_grant() {
        let call_id = "call-reject-unique-ccc".to_string();
        let invoke = super::ToolInvoke {
            call_id: call_id.clone(),
            tool_name: "write_file".into(),
            input: serde_json::json!({"path": "a", "content": "b"}),
            caller: super::ToolCaller::Llm,
            workspace_id: "ws-C-unique".into(),
            session_id: Some("ses-r-unique".into()),
            user_authorized: false,
            user_confirmed_twice: false,
        };
        let gate = runtime::PermissionGateReport {
            required: super::PermissionMode::WorkspaceWrite,
            decision: super::PermissionDecision::RequireApproval,
            reason: "workspace-write-outside".into(),
            protected_match: None,
            workspace_relative: false,
            affected_paths: vec!["a".into()],
        };
        super::enqueue_pending_approval(&call_id, &invoke, &gate);

        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let req = super::RejectRequest {
            call_id: call_id.clone(),
            reason: Some("user-denied".into()),
        };
        let Json(resp) = rt
            .block_on(super::api_tools_reject(Json(req)))
            .expect("reject ok");
        assert_eq!(resp.call_id, call_id);
        assert_eq!(resp.reason.as_deref(), Some("user-denied"));

        let Json(after) = rt.block_on(super::api_tools_pending());
        assert!(
            !after.pending.iter().any(|r| r.call_id == call_id),
            "call_id 应被 reject 消费"
        );
        assert!(
            !super::session_grant_view_for("ws-C-unique", Some("ses-r-unique"), "write_file")
                .session_authorized,
            "reject 不应建立 session grant"
        );
    }

