    #[test]
    fn web_frontend_settings_keeps_goal_roles_in_task_authorization_window() {
        let settings_start = WEB_INDEX_HTML
            .find("class=\"workbench-window settings-workbench-window\"")
            .expect("settings window article exists");
        let tasks_start = WEB_INDEX_HTML
            .find("class=\"workbench-window tasks-workbench-window\"")
            .expect("task authorization window article exists");
        let settings_html = &WEB_INDEX_HTML[settings_start..tasks_start];
        let tasks_html = &WEB_INDEX_HTML[tasks_start..];

        assert!(
            !settings_html.contains("data-role=\"goal-role-consult\""),
            "Goal role assignment belongs in task authorization, not Settings"
        );
        assert!(
            !settings_html.contains("data-role=\"goal-role-config\""),
            "Goal role runtime config belongs in task authorization, not Settings"
        );
        assert!(tasks_html.contains("data-role=\"goal-role-consult\""));
        assert!(tasks_html.contains("data-role=\"goal-role-config\""));
        assert!(tasks_html.contains("data-action=\"goal-role-assign\""));
        assert!(tasks_html.contains("data-action=\"goal-role-bootstrap\""));
        assert!(tasks_html.contains("data-action=\"goal-role-heartbeat\""));
        assert!(
            tasks_html.find("data-role=\"task-approvals-section\"")
                < tasks_html.find("data-role=\"goal-role-consult\""),
            "Goal role card should sit with pending authorization context"
        );
    }

