    #[test]
    fn web_frontend_round3_authorization_window_matches_approval_config_selfcheck_design_reference()
    {
        assert!(!WEB_INDEX_HTML.contains("data-round3-layout=\"authorization-design-grid-v2\""));
        assert!(!WEB_INDEX_HTML
            .contains("data-round3-legacy-layout=\"authorization-approval-config-selfcheck\""));
        assert!(
            !WEB_INDEX_HTML.contains("data-round3-card=\"approval-pending\""),
            "authorization window must reclaim the obsolete pending-approval card space"
        );
        assert!(
            !WEB_INDEX_HTML.contains("aria-label=\"待审批和计划任务\""),
            "authorization window must not expose obsolete pending-approval wording to UI automation"
        );
        assert!(!WEB_INDEX_HTML.contains("data-round3-card=\"goal-assignment\""));
        assert!(!WEB_INDEX_HTML.contains("data-round3-card=\"authorization-config\""));
        assert!(!WEB_INDEX_HTML.contains("data-round3-card=\"module-selfcheck\""));
        assert!(WEB_INDEX_HTML.contains("class=\"task-permission-layout\""));
        assert!(WEB_INDEX_HTML.contains("data-role=\"goal-role-consult\""));
        // Phase 2 C2/A1：授权配置列已迁出任务窗口，改挂到聊天室左栏「会话授权」折叠组；
        // 任务窗口重排为两列（Goal 与计划 / 诊断）；dock 标签由「任务授权」改名「任务中心」。
        assert!(!WEB_INDEX_HTML.contains("class=\"task-permission-column task-config-column\""));
        assert!(WEB_INDEX_HTML.contains("class=\"chat-sidebar-group chat-session-auth\""));
        let chat_left_rail = WEB_INDEX_HTML
            .find("<aside class=\"chat-left-rail\"")
            .expect("chat left rail exists");
        let session_auth = WEB_INDEX_HTML
            .find("<details class=\"chat-sidebar-group chat-session-auth\"")
            .expect("session auth details exists");
        let task_window = WEB_INDEX_HTML
            .find("<article class=\"workbench-window tasks-workbench-window\"")
            .expect("task window exists");
        let relay_config = WEB_INDEX_HTML
            .find("class=\"task-schedule-relay-config\"")
            .expect("schedule relay config exists");
        assert!(
            chat_left_rail < session_auth && session_auth < task_window,
            "session auth must live inside the chat left rail, before the task window"
        );
        assert!(
            session_auth < relay_config,
            "session auth must not be embedded in the scheduled-task relay controls"
        );
        assert!(WEB_INDEX_HTML.contains(">任务中心</span>"));
        assert!(WEB_INDEX_HTML.contains("class=\"task-permission-column module-selfcheck\""));
        assert!(WEB_INDEX_HTML.contains("task-window-schedules-always-open"));
        assert!(
            !WEB_INDEX_HTML.contains("<details class=\"task-window-fold\">"),
            "scheduled tasks must remain visible instead of folding"
        );
        assert!(WEB_STYLES_CSS.contains("ui-feedback-round3-authorization-three-column-design"));
        assert!(WEB_STYLES_CSS.contains("body.ui-3d .task-permission-layout"));
        // 授权列迁出后任务窗口由三列改为两列布局。
        assert!(WEB_STYLES_CSS.contains(
            "grid-template-columns: minmax(320px, 1fr) minmax(300px, 1fr);"
        ));
        assert!(WEB_STYLES_CSS.contains("body.ui-3d .goal-role-assignment-grid label::before"));
        assert!(WEB_STYLES_CSS.contains("body.ui-3d .module-selfcheck .logs-window-checks"));
    }

