    #[test]
    fn web_frontend_project_tree_preserves_expansion_when_opening_file() {
        assert!(WEB_APP_JS.contains("const expandedProjectPaths = new Set()"));
        assert!(WEB_APP_JS.contains("function syncProjectTreeSelection"));
        assert!(WEB_APP_JS.contains("expandedProjectPaths.clear()"));
        assert!(WEB_APP_JS.contains("expandedProjectPaths.add(path)"));
        assert!(WEB_APP_JS.contains("expandedProjectPaths.delete(path)"));
        assert!(WEB_APP_JS.contains("expandedProjectPaths.has(entry.relative_path"));

        let open_file_start = WEB_APP_JS
            .find("async function openProjectFile")
            .expect("openProjectFile function exists");
        let open_file_end = WEB_APP_JS[open_file_start..]
            .find("\nfunction toggleIdeViewDiffMode")
            .map(|offset| open_file_start + offset)
            .expect("openProjectFile function boundary exists");
        let open_file = &WEB_APP_JS[open_file_start..open_file_end];
        assert!(open_file.contains("syncProjectTreeSelection()"));
        assert!(
            open_file.contains("const previousPath = selectedProjectPath"),
            "openProjectFile must remember the previously selected path before optimistic selection"
        );
        assert!(
            open_file.contains("selectedProjectPath = previousPath"),
            "openProjectFile catch path must roll back stale active selection on preview load failure"
        );
        let rollback_start = open_file
            .find("selectedProjectPath = previousPath")
            .expect("openProjectFile rollback exists");
        assert!(
            open_file[rollback_start..].contains("syncProjectTreeSelection()"),
            "openProjectFile rollback must resync the project tree selection"
        );
        assert!(
            !open_file.contains("renderProjectApiTree"),
            "opening a file must not rebuild and collapse the project tree"
        );

        let toggle_start = WEB_APP_JS
            .find("function toggleProjectTreeNode")
            .expect("toggleProjectTreeNode function exists");
        let toggle_end = WEB_APP_JS[toggle_start..]
            .find("\nfunction syncProjectTreeSelection")
            .map(|offset| toggle_start + offset)
            .expect("toggleProjectTreeNode function boundary exists");
        let toggle_node = &WEB_APP_JS[toggle_start..toggle_end];
        let add_start = toggle_node
            .find("expandedProjectPaths.add(path)")
            .expect("expanded path add remains in toggleProjectTreeNode");
        let delete_start = toggle_node
            .find("expandedProjectPaths.delete(path)")
            .expect("expanded path delete remains in toggleProjectTreeNode");
        assert!(
            toggle_node[..add_start].rfind("if (path)").is_some(),
            "expandedProjectPaths.add(path) must be guarded so the root path is not persisted"
        );
        assert!(
            toggle_node[..delete_start].rfind("if (path)").is_some(),
            "expandedProjectPaths.delete(path) must be guarded so the root path is not persisted"
        );
    }

