    #[test]
    fn starship_bridge_animates_hologram_earth_and_window_starfield_safely() {
        assert!(
            !WEB_INDEX_HTML.contains("bridge-hologram-earth"),
            "the folded bridge strip is no longer rendered below the dock"
        );
        assert!(
            !WEB_INDEX_HTML.contains("bridge-starfield-layer"),
            "the folded bridge strip is no longer rendered below the dock"
        );
        assert!(
            WEB_APP_JS.contains("THREE.Points")
                && WEB_APP_JS.contains("seedBridgeStar")
                && WEB_APP_JS.contains("ResizeObserver")
                && WEB_APP_JS.contains("starfield-flight-texture.png"),
            "forward-flight starfield should use the local Three.js/WebGL layer and generated texture"
        );
        assert!(
            WEB_APP_JS.contains("THREE.SphereGeometry")
                && WEB_APP_JS.contains("hologram-earth-texture.png"),
            "holographic earth should be a separate rotating WebGL sphere layer"
        );
        assert!(
            WEB_STYLES_CSS.contains("animation: bridgeEarthRotate 36s linear infinite"),
            "holographic earth rotation should be slow, not a fast spinner"
        );
        assert!(
            WEB_STYLES_CSS.contains("@keyframes bridgeEarthRotate"),
            "earth rotation keyframes should be explicit and testable"
        );
        assert!(
            WEB_STYLES_CSS.contains("animation: bridgeStarfieldDrift 96s linear infinite"),
            "window starfield should drift slowly"
        );
        assert!(
            WEB_STYLES_CSS.contains("@keyframes bridgeStarfieldDrift"),
            "starfield parallax keyframes should be explicit and testable"
        );
        assert!(
            WEB_STYLES_CSS.contains("prefers-reduced-motion: reduce")
                && WEB_STYLES_CSS.contains("bridge-hologram-earth"),
            "bridge animations must have reduced-motion fallback"
        );
    }

