    #[test]
    fn starship_crew_are_anchored_to_existing_bridge_seats_without_fake_platforms() {
        let scene = super::build_office_scene_response();
        let expected_seat_anchors = [
            ("commander", 24, 84),
            ("pilot", 37, 63),
            ("operations", 30, 68),
            ("envoy", 70, 68),
            ("memory", 63, 63),
            ("security", 75, 84),
        ];
        for (id, expected_x, expected_y) in expected_seat_anchors {
            let crew = scene
                .robots
                .iter()
                .find(|robot| robot.id == id)
                .expect("expected bridge crew member");
            assert_eq!(
                crew.x, expected_x,
                "{id} should align to a bridge seat x anchor"
            );
            assert_eq!(
                crew.y, expected_y,
                "{id} should align to a bridge seat y anchor"
            );
        }
        assert!(
            !WEB_APP_JS.contains("crew-seat"),
            "sitting crew sprites should use the baked bridge chairs, not an extra fake platform"
        );
        assert!(
            !WEB_STYLES_CSS.contains(".crew-seat"),
            "sitting crew sprites should not draw an extra oval platform over the bridge seats"
        );
        assert!(
            WEB_APP_JS.contains("node.dataset.lane = robot?.lane"),
            "crew depth should be exposed so CSS can size front and rear seats differently"
        );
        assert!(
            WEB_STYLES_CSS.contains("[data-lane=\"front\"]"),
            "front bridge seats should have their own scale so seated crew do not look glued to the console"
        );
        assert!(
            WEB_STYLES_CSS.contains("body.ui-3d .starship-bridge .office-scene-shade {\n  z-index: 1;"),
            "starship bridge shade should stay behind crew and should not obscure the baked bridge seats"
        );
        assert!(
            WEB_STYLES_CSS.contains("repeating-linear-gradient(0deg, rgba(126, 220, 255, 0.045)"),
            "starship bridge shade should use a light scanline overlay instead of a dark office vignette"
        );
    }

