    #[test]
    fn build_relay_prompt_includes_prior_replies_and_position() {
        // 接力提示必须把前序会话的回复按顺序带给后一个会话（报数 1/2/3 的基础）。
        let acc = vec![
            ("test3".to_string(), 1usize, "1".to_string()),
            ("test5".to_string(), 2usize, "2".to_string()),
        ];
        let p = super::build_relay_prompt("报数接龙", &acc, 3, 3);
        assert!(p.contains("原始消息"));
        assert!(p.contains("第1位 test3 回复：1"));
        assert!(p.contains("第2位 test5 回复：2"));
        assert!(p.contains("第 3 位"));
        // 首位无接力上文块。
        let first = super::build_relay_prompt("报数接龙", &[], 1, 3);
        assert!(!first.contains("接力上文"));
    }

