    #[test]
    fn web_frontend_overview_card_can_toggle_showui_service() {
        // Phase 7 T1：ShowUI 服务开关从 Agent 总览卡头部迁到「视觉实验」窗口 vision-command-rail 顶部；
        // 总览头部原位置改放当前工作区名展示（点击复制路径）。
        let header_start = WEB_INDEX_HTML
            .find("<header class=\"compact-card-head\">")
            .expect("overview header exists");
        let header_end = WEB_INDEX_HTML[header_start..]
            .find("</header>")
            .map(|offset| header_start + offset)
            .expect("overview header closes");
        let overview_header = &WEB_INDEX_HTML[header_start..header_end];
        // 总览头部不再承载 ShowUI 开关，改放工作区名按钮
        assert!(!overview_header.contains("data-role=\"showui-service-control\""));
        assert!(overview_header.contains("data-role=\"overview-workspace-name\""));
        assert!(overview_header.contains("data-role=\"overview-workspace-label\""));
        // ShowUI 开关现位于视觉实验窗口操作列（vision-command-rail）顶部
        let vision_rail = WEB_INDEX_HTML
            .find("class=\"vision-command-rail\"")
            .expect("vision command rail exists");
        let showui_control = WEB_INDEX_HTML
            .find("data-role=\"showui-service-control\"")
            .expect("showui service control exists");
        assert!(vision_rail < showui_control);
        assert!(WEB_INDEX_HTML.contains("vision-showui-service-control"));
        assert!(WEB_INDEX_HTML.contains("data-role=\"showui-service-toggle\""));
        assert!(WEB_INDEX_HTML.contains("data-action=\"showui-service-toggle\""));
        assert!(WEB_INDEX_HTML.contains("showui.serviceStatus"));
        assert!(WEB_APP_JS.contains("/api/showui/service"));
        assert!(WEB_APP_JS.contains("function refreshShowUiServiceStatus"));
        assert!(WEB_APP_JS.contains("function toggleShowUiService"));
        assert!(WEB_APP_JS.contains("const showUiServiceActive ="));
        assert!(WEB_APP_JS.contains("const nextEnabled = !showUiServiceStatus.running"));
        assert!(
            WEB_APP_JS.contains("button.dataset.label = showUiServiceActive ? \"停止\" : \"启动\"")
        );
        assert!(WEB_APP_JS.contains("ShowUI stopped"));
        // 工作区名展示：复用 /api/system/info 的 workspace，点击复制完整路径
        assert!(WEB_APP_JS.contains("function setOverviewWorkspaceName"));
        assert!(WEB_APP_JS.contains("function copyOverviewWorkspacePath"));
        assert!(WEB_STYLES_CSS.contains(".vision-showui-service-control"));
        assert!(WEB_STYLES_CSS.contains(".overview-workspace-name"));
        assert!(WEB_STYLES_CSS.contains(".showui-service-toggle"));
        assert!(WEB_MAIN_RS.contains("/api/showui/service"));
        assert!(WEB_MAIN_RS.contains("ShowUiServiceRequest"));
        assert!(WEB_MAIN_RS.contains("start_showui_service"));
        assert!(WEB_MAIN_RS.contains("stop_showui_service"));
        assert!(WEB_MAIN_RS.contains("terminate_showui_service_process"));
        assert!(WEB_MAIN_RS.contains("terminate_showui_service_process_with_messages"));
        assert!(WEB_MAIN_RS.contains("ShowUI service stopped; web shell kept open."));
        assert!(WEB_MAIN_RS.contains("spawn_showui_exit_monitor"));
        assert!(WEB_MAIN_RS.contains("mark_showui_service_process_exited"));
        let mark_start = WEB_MAIN_RS
            .find("fn mark_showui_service_process_exited")
            .expect("showui exit marker exists");
        let mark_end = WEB_MAIN_RS[mark_start..]
            .find("fn showui_service_status_with_message")
            .map(|offset| mark_start + offset)
            .expect("showui status follows marker");
        let mark_body = &WEB_MAIN_RS[mark_start..mark_end];
        assert!(!mark_body.contains("SHOWUI_SERVICE_ENABLED.store(false"));
        assert!(WEB_MAIN_RS.contains("Web Console stays running"));
        assert!(WEB_MAIN_RS.contains("process_exists"));
        assert!(WEB_MAIN_RS.contains("COOLZHU_WEB_CONSOLE_PID"));
        assert!(WEB_MAIN_RS.contains("--web-console-pid"));
        assert!(WEB_MAIN_RS.contains(".stdin(Stdio::null())"));
        assert!(WEB_MAIN_RS.contains(".stdout(Stdio::null())"));
        assert!(WEB_MAIN_RS.contains(".stderr(Stdio::null())"));
        let forced_exit = ["std::process", "::exit(0)"].concat();
        assert!(!WEB_MAIN_RS.contains(&forced_exit)); // 优雅退出（信号 + with_graceful_shutdown），不用硬退出
                                                      // 桌宠退出联动 web-console（可配置 pet_exit_closes_console，默认关）：新设计
        assert!(WEB_MAIN_RS.contains("pet_exit_closes_console"));
        assert!(WEB_MAIN_RS.contains("web_console_shutdown_signal"));
        assert!(WEB_MAIN_RS.contains("with_graceful_shutdown"));
    }

