    #[tokio::test]
    async fn vision_realtime_frame_increments_processed_frame_count_for_injected_detections() {
        let _guard = realtime_vision_test_guard().await;
        if let Ok(mut state) = super::vision_realtime_state().lock() {
            *state = super::VisionRealtimeElementState::default();
            state.loop_requested = true;
            state.last_error = Some("waiting for UI-DETR service".to_string());
        }

        let payload = serde_json::json!({
            "detections": [
                { "bbox": [0.1, 0.2, 0.3, 0.4], "label": "button", "text": "Start", "score": 0.91 }
            ]
        })
        .to_string();

        for index in 0..2 {
            let axum::Json(response) =
                super::api_vision_realtime_frame(axum::Json(super::VisionRealtimeFrameRequest {
                    raw_response: Some(payload.clone()),
                    source: Some(format!("playwright-frame-{index}")),
                    min_confidence: Some(0.35),
                    max_elements: Some(8),
                }))
                .await;
            assert_eq!(response.status, "parsed");
            assert_eq!(response.accepted, 1);
        }

        let state = super::vision_realtime_state()
            .lock()
            .map(|state| state.clone())
            .unwrap_or_default();
        assert_eq!(state.frames_processed, 2);
        assert_eq!(state.elements.len(), 1);
        assert_eq!(state.elements[0].label.as_deref(), Some("button"));
        assert!(state.last_error.is_none());
        assert!(!state.loop_requested);
        assert!(!state.loop_running);
    }

    #[tokio::test]
    async fn vision_realtime_external_frame_aborts_stale_polling_error_writer() {
        let _guard = realtime_vision_test_guard().await;
        if let Ok(mut state) = super::vision_realtime_state().lock() {
            *state = super::VisionRealtimeElementState::default();
            state.loop_requested = true;
            state.loop_running = true;
            state.last_error = Some("waiting for UI-DETR service".to_string());
        }
        if let Ok(mut session) = super::realtime_session_state().lock() {
            *session = super::RealtimeSessionState {
                running: true,
                start_vision: true,
                vision_state: "error".to_string(),
                ..Default::default()
            };
        }
        if let Ok(mut handle) = super::vision_realtime_loop_handle().lock() {
            if let Some(task) = handle.take() {
                task.abort();
            }
            *handle = Some(tokio::spawn(async {
                tokio::time::sleep(std::time::Duration::from_millis(80)).await;
                if let Ok(mut state) = super::vision_realtime_state().lock() {
                    state.last_error =
                        Some("stale polling loop wrote UI-DETR backend error".to_string());
                    state.loop_requested = false;
                    state.loop_running = false;
                }
            }));
        }

        let payload = serde_json::json!({
            "detections": [
                { "bbox": [0.1, 0.2, 0.3, 0.4], "label": "button", "text": "Start", "score": 0.91 }
            ]
        })
        .to_string();
        let axum::Json(response) =
            super::api_vision_realtime_frame(axum::Json(super::VisionRealtimeFrameRequest {
                raw_response: Some(payload),
                source: Some("external-frame-feed".to_string()),
                min_confidence: Some(0.35),
                max_elements: Some(8),
            }))
            .await;
        assert_eq!(response.status, "parsed");
        assert_eq!(response.accepted, 1);

        tokio::time::sleep(std::time::Duration::from_millis(140)).await;
        let status = super::realtime_session_status_response().await;
        assert_ne!(status.vision_state, "error");
        assert_eq!(status.vision_frames_processed, 1);
        assert_eq!(status.vision_element_count, 1);
    }

