    #[tokio::test]
    async fn realtime_session_start_records_reported_capabilities_but_requires_health_confirmation()
    {
        let _guard = realtime_audio_test_guard().await;
        let now = super::uuid_timestamp();
        if let Ok(mut cache) = super::audio_health_cache().lock() {
            *cache = Some(super::AudioHealthSnapshot {
                stt_available: true,
                tts_available: true,
                tts_backend: "piper".to_string(),
                index_tts_base_url: None,
                index_tts_available: false,
                error: None,
                checked_at_ms: now,
            });
        }
        if let Ok(mut audio) = super::audio_realtime_state().lock() {
            *audio = super::AudioRealtimeState::default();
        }
        if let Ok(mut realtime) = super::realtime_session_state().lock() {
            *realtime = super::RealtimeSessionState::default();
        }

        let request: super::RealtimeSessionControlRequest = serde_json::from_value(json!({
            "start_vision": false,
            "start_audio": true,
            "requested_mode": "full_streaming",
            "auto_send_transcript": true,
            "auto_tts_reply": true,
            "stt_transport": "provider_native_streaming_asr",
            "aec_mode": "far_end_reference_aec",
            "provider_adapter": "realtime_provider_adapter",
            "tts_transport": "chunked_tts_stream"
        }))
        .expect("valid realtime request");
        let axum::Json(response) = super::api_realtime_session_start(axum::Json(request)).await;

        assert_eq!(response.requested_mode, super::REALTIME_MODE_FULL_STREAMING);
        assert_eq!(
            response.active_mode,
            super::REALTIME_MODE_HALF_DUPLEX_GUARDED
        );
        assert!(response.mode_downgrade_reason.is_some());
        assert!(!response.streaming_risk.full_streaming_ready);
        assert_eq!(
            response.streaming_risk.stt_transport,
            "provider_native_streaming_asr"
        );
        assert_eq!(response.streaming_risk.aec_mode, "far_end_reference_aec");
        assert_eq!(
            response.streaming_risk.provider_adapter,
            "realtime_provider_adapter"
        );
        assert!(response
            .streaming_risk
            .readiness_gates
            .iter()
            .all(|gate| !gate.ready));

        let _ = super::api_realtime_session_stop().await;
    }

