    #[tokio::test]
    async fn audio_tts_chunk_bridge_emits_event_and_marks_streaming_tts_ready() {
        use base64::Engine;

        let _guard = realtime_audio_test_guard().await;
        let now = super::uuid_timestamp();
        if let Ok(mut cache) = super::audio_health_cache().lock() {
            *cache = Some(super::AudioHealthSnapshot {
                stt_available: true,
                tts_available: true,
                tts_backend: "streaming-tts-test".to_string(),
                index_tts_base_url: None,
                index_tts_available: false,
                error: None,
                checked_at_ms: now,
            });
        }
        if let Ok(mut audio) = super::audio_realtime_state().lock() {
            *audio = super::AudioRealtimeState::default();
        }
        if let Ok(mut realtime) = super::realtime_session_state().lock() {
            *realtime = super::RealtimeSessionState::default();
            realtime.running = true;
            realtime.session_id = Some("rt-tts-chunk-bridge".to_string());
            realtime.tts_transport = super::REALTIME_TTS_CHUNKED_STREAM.to_string();
        }
        let mut receiver = super::realtime_session_event_bus().subscribe();

        let encoded = base64::engine::general_purpose::STANDARD.encode(b"coolzhu-tts-audio-chunk");
        let axum::Json(response) = super::api_audio_tts_chunk(axum::Json(super::TtsChunkRequest {
            session_id: Some("rt-tts-chunk-bridge".to_string()),
            source: Some("streaming_tts_test".to_string()),
            backend: Some("streaming-tts-test".to_string()),
            voice: None,
            mime_type: Some("audio/wav".to_string()),
            audio_base64: Some(encoded),
            audio_url: None,
            index: Some(1),
            total: Some(1),
            duration_ms: Some(42),
            final_chunk: Some(true),
        }))
        .await
        .expect("tts chunk bridge accepts a real audio payload");

        assert!(response.ok);
        assert!(response.audio_payload_received);
        assert!(response.bytes > 0);
        assert!(response
            .audio_url
            .as_deref()
            .unwrap_or_default()
            .starts_with("/api/audio/tts/files/"));

        let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(1);
        let event = loop {
            let event = tokio::time::timeout_at(deadline, receiver.recv())
                .await
                .expect("tts chunk event")
                .expect("valid realtime session event");
            if event.kind == "tts_chunk"
                && event.session_id.as_deref() == Some("rt-tts-chunk-bridge")
            {
                break event;
            }
        };
        assert_eq!(event.kind, "tts_chunk");
        assert_eq!(event.session_id.as_deref(), Some("rt-tts-chunk-bridge"));
        assert_eq!(event.payload["chunk_bytes"], json!(response.bytes));
        assert!(event.payload["audio_url"]
            .as_str()
            .unwrap_or_default()
            .starts_with("/api/audio/tts/files/"));

        let axum::Json(status) = super::api_realtime_session_status().await;
        assert!(status
            .streaming_risk
            .readiness_gates
            .iter()
            .any(|gate| gate.id == "streaming_tts_output" && gate.ready));
    }

    #[tokio::test]
    async fn audio_tts_stream_adapter_forwards_upstream_chunks_to_tts_chunk_events() {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};

        let _guard = realtime_audio_test_guard().await;
        let now = super::uuid_timestamp();
        if let Ok(mut cache) = super::audio_health_cache().lock() {
            *cache = Some(super::AudioHealthSnapshot {
                stt_available: true,
                tts_available: true,
                tts_backend: "streaming-tts-test".to_string(),
                index_tts_base_url: None,
                index_tts_available: false,
                error: None,
                checked_at_ms: now,
            });
        }
        if let Ok(mut audio) = super::audio_realtime_state().lock() {
            *audio = super::AudioRealtimeState::default();
        }
        if let Ok(mut realtime) = super::realtime_session_state().lock() {
            *realtime = super::RealtimeSessionState::default();
            realtime.running = true;
            realtime.session_id = Some("rt-tts-stream-adapter".to_string());
            realtime.tts_transport = super::REALTIME_TTS_CHUNKED_STREAM.to_string();
        }

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind test streaming tts upstream");
        let upstream_addr = listener
            .local_addr()
            .expect("test streaming tts upstream address");
        tokio::spawn(async move {
            let (mut socket, _) = listener.accept().await.expect("accept tts request");
            let mut buffer = [0_u8; 4096];
            let _ = socket.read(&mut buffer).await.expect("read tts request");
            let chunks: [&[u8]; 2] = [b"RIFFstreaming-tts-part-1", b"streaming-tts-part-2"];
            socket
                .write_all(
                    b"HTTP/1.1 200 OK\r\nContent-Type: audio/wav\r\nTransfer-Encoding: chunked\r\n\r\n",
                )
                .await
                .expect("write tts response headers");
            for chunk in chunks {
                socket
                    .write_all(format!("{:x}\r\n", chunk.len()).as_bytes())
                    .await
                    .expect("write tts chunk length");
                socket.write_all(chunk).await.expect("write tts chunk body");
                socket
                    .write_all(b"\r\n")
                    .await
                    .expect("write tts chunk newline");
            }
            socket
                .write_all(b"0\r\n\r\n")
                .await
                .expect("write final tts chunk");
        });

        let mut receiver = super::realtime_session_event_bus().subscribe();
        let axum::Json(response) =
            super::api_audio_tts_stream(axum::Json(super::TtsStreamRequest {
                text: "你好，酷猪".to_string(),
                session_id: Some("rt-tts-stream-adapter".to_string()),
                source: Some("streaming_tts_adapter_test".to_string()),
                backend: Some("http-stream-test".to_string()),
                voice: Some("test-voice".to_string()),
                mime_type: Some("audio/wav".to_string()),
                upstream_url: Some(format!("http://{upstream_addr}/stream")),
                turn_id: Some("turn-correlation-test".to_string()),
                generation_id: Some(7),
                segment_index: Some(3),
            }))
            .await
            .expect("streaming tts adapter accepts a real HTTP byte stream");

        assert!(response.ok);
        assert_eq!(
            response.session_id.as_deref(),
            Some("rt-tts-stream-adapter")
        );
        assert_eq!(response.chunk_count, 2);
        assert_eq!(response.turn_id.as_deref(), Some("turn-correlation-test"));
        assert_eq!(response.generation_id, Some(7));
        assert_eq!(response.segment_index, Some(3));
        assert!(response.bytes > 0);
        assert_eq!(response.audio_urls.len(), 2);
        assert!(response
            .audio_urls
            .iter()
            .all(|url| url.starts_with("/api/audio/tts/files/")));

        let mut chunk_events = Vec::new();
        let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(1);
        while chunk_events.len() < 2 {
            let event = tokio::time::timeout_at(deadline, receiver.recv())
                .await
                .expect("tts stream chunk event")
                .expect("valid tts stream event");
            if event.kind == "tts_chunk"
                && event.session_id.as_deref() == Some("rt-tts-stream-adapter")
            {
                chunk_events.push(event);
            }
        }
        let first = &chunk_events[0];
        let second = &chunk_events[1];
        assert_eq!(first.kind, "tts_chunk");
        assert_eq!(second.kind, "tts_chunk");
        assert_eq!(first.payload["final_chunk"], json!(false));
        assert_eq!(second.payload["final_chunk"], json!(true));
        assert_eq!(second.payload["chunk_count"], json!(2));
        assert_eq!(first.payload["turn_id"], json!("turn-correlation-test"));
        assert_eq!(first.payload["generation_id"], json!(7));
        assert_eq!(first.payload["segment_index"], json!(3));

        let raw_realtime = super::realtime_session_state()
            .lock()
            .map(|state| state.clone())
            .unwrap_or_default();
        assert!(raw_realtime.streaming_tts_ready);

        let axum::Json(status) = super::api_realtime_session_status().await;
        assert!(status
            .streaming_risk
            .readiness_gates
            .iter()
            .any(|gate| gate.id == "streaming_tts_output" && gate.ready));
    }

