    async fn realtime_audio_test_guard() -> tokio::sync::MutexGuard<'static, ()> {
        static LOCK: std::sync::OnceLock<tokio::sync::Mutex<()>> = std::sync::OnceLock::new();
        LOCK.get_or_init(|| tokio::sync::Mutex::new(()))
            .lock()
            .await
    }

    async fn realtime_vision_test_guard() -> tokio::sync::MutexGuard<'static, ()> {
        // Vision and audio realtime tests mutate the same unified session singleton and event bus.
        // Serialize both families through one guard so parallel test execution cannot reassign the
        // active session between an emitted chunk and its readiness assertion.
        realtime_audio_test_guard().await
    }

