    #[tokio::test]
    async fn audio_realtime_segment_persists_uploaded_audio_payload() {
        use base64::Engine;

        let _guard = realtime_audio_test_guard().await;
        if let Ok(mut state) = super::audio_realtime_state().lock() {
            *state = super::AudioRealtimeState::default();
            state.running = true;
            state.session_id = Some("audio-rt-payload".to_string());
            state.active_stt_transport = "segmented_mediarecorder".to_string();
        }
        if let Ok(mut realtime) = super::realtime_session_state().lock() {
            *realtime = super::RealtimeSessionState::default();
            realtime.running = true;
            realtime.session_id = Some("rt-payload".to_string());
        }

        let payload = b"coolzhu-audio-webm-chunk";
        let encoded = base64::engine::general_purpose::STANDARD.encode(payload);
        let axum::Json(response) =
            super::api_audio_realtime_segment(axum::Json(super::AudioRealtimeSegmentRequest {
                session_id: Some("audio-rt-payload".to_string()),
                bytes: Some(999),
                duration_ms: Some(250),
                mime_type: Some("audio/webm;codecs=opus".to_string()),
                final_segment: Some(false),
                audio_base64: Some(encoded),
            }))
            .await;

        assert!(response.running);
        assert_eq!(response.audio_segments_received, 1);
        assert_eq!(response.audio_bytes_received, payload.len() as u64);
        assert!(response.audio_payload_received);
        assert_eq!(response.audio_payload_bytes, payload.len() as u64);
        let path = response
            .last_audio_chunk_path
            .as_deref()
            .expect("audio chunk path should be recorded");
        let saved = std::fs::read(path).expect("audio chunk should be written");
        assert_eq!(saved, payload);

        let realtime = super::realtime_session_state()
            .lock()
            .map(|state| state.clone())
            .unwrap_or_default();
        assert_eq!(realtime.audio_bytes_received, payload.len() as u64);
        assert_eq!(realtime.last_audio_chunk_path.as_deref(), Some(path));
    }

