    #[test]
    fn session_store_scrubs_stale_goal_temporary_memory() {
        let temp = tempfile::tempdir().expect("tempdir");
        let db_path = temp.path().join("sessions.sqlite3");
        let goal = super::create_goal_sqlite(
            &db_path,
            "workspace-memory-scrub",
            "room-memory-scrub",
            super::CreateGoalRequest {
                title: "Temporary Goal".to_string(),
                chat_room_id: Some("room-memory-scrub".to_string()),
                max_iterations: Some(1),
                background: Some(false),
                originating_user_msg_id: None,
                completion_condition: Some(serde_json::json!({"type":"UserConfirm"})),
            },
        )
        .expect("goal");
        let connection = super::open_session_connection(&db_path).expect("open db");
        connection
            .execute(
                "UPDATE goals SET status='completed' WHERE id=?1",
                rusqlite::params![goal.id],
            )
            .expect("mark completed");
        let now = super::unix_timestamp_millis();
        let mut session = super::seed_session();
        session.id = "agent-memory-scrub".to_string();
        session.memory_beads = vec![
            super::MemoryBeadDto {
                id: "goal-skill".to_string(),
                kind: "goal-task-skill".to_string(),
                layer: "L1".to_string(),
                summary: "Task-scoped goal role skill overlay. Assigned role: verifier."
                    .to_string(),
                source: super::goal_task_skill_memory_source(&goal.id),
                pinned: false,
                confidence: 0.9,
                created_at: now,
                ..MemoryBeadDto::default()
            },
            super::MemoryBeadDto {
                id: "goal-auto".to_string(),
                kind: "decision".to_string(),
                layer: "L2".to_string(),
                summary: "Goal phase reasoning. Assigned role: verifier. goal-artifacts/demo.html"
                    .to_string(),
                source: "chat-room:auto-extract".to_string(),
                pinned: false,
                confidence: 0.7,
                created_at: now,
                ..MemoryBeadDto::default()
            },
            super::MemoryBeadDto {
                id: "keep".to_string(),
                kind: "experience".to_string(),
                layer: "L3".to_string(),
                summary: "Useful successful troubleshooting experience.".to_string(),
                source: "manual".to_string(),
                pinned: false,
                confidence: 0.8,
                created_at: now,
                ..MemoryBeadDto::default()
            },
        ];
        let mut store = super::SessionStore {
            path: db_path,
            legacy_json_path: temp.path().join("sessions.json"),
            capacity: super::SessionStoreCapacity::default(),
            state: super::PersistedSessionState {
                sessions: vec![session],
                active_session_id: Some("agent-memory-scrub".to_string()),
                active_vision_session_id: None,
                chat_rooms: Vec::new(),
                active_chat_room_id: None,
            },
        };

        assert_eq!(store.scrub_temporary_goal_memories_from_state(), 2);
        assert_eq!(store.state.sessions[0].memory_beads.len(), 1);
        assert_eq!(store.state.sessions[0].memory_beads[0].id, "keep");
    }

