    #[test]
    fn context_lifecycle_snapshot_prefers_remote_tokens_and_uses_policy_thresholds() {
        let mut session = super::seed_session();
        session.model = "glm-5.1".to_string();
        let agent = session.to_agent_session(false);
        let assembly = super::ContextAssembly {
            system_prompt: String::new(),
            messages: Vec::new(),
            memory_beads: Vec::new(),
            history_message_count: 0,
            token_budget: super::ContextTokenBudget {
                system: 100,
                memory: 200,
                history: 300,
                user: 400,
                total: 1_000,
                budget: 5_000,
            },
            truncated: false,
        };
        // 2026-05-31 容量更正：glm-5.1 上下文 200K；input 提到 170K(=85%) 以保持"超阈值触发"测试本意。
        let remote_usage = api::Usage {
            input_tokens: 170_000,
            cache_creation_input_tokens: 0,
            cache_read_input_tokens: 0,
            output_tokens: 512,
        };
        let policy = super::ContextLifecyclePolicy {
            warning_percent: 70,
            auto_compact_percent: 80,
            ..super::ContextLifecyclePolicy::default()
        };

        let snapshot = super::context_usage_snapshot_for_assembly_with_usage(
            &agent,
            &assembly,
            Some(&remote_usage),
            policy,
        );

        assert_eq!(snapshot.used_tokens, 170_000);
        assert_eq!(snapshot.context_tokens, 200_000);
        assert_eq!(snapshot.source, super::ContextUsageSource::Remote);
        assert!(snapshot.warning_reached);
        assert!(snapshot.auto_compact_reached);
    }

