    #[test]
    fn clawbot_send_request_requires_room_and_copies_bound_route() {
        let envelope = crate::clawbot_channel::ClawbotInboundEnvelope::weixin_user(
            crate::clawbot_channel::ClawbotInboundMessage {
                account_id: "wx-main".to_string(),
                peer_id: "peer-1".to_string(),
                conversation_id: None,
                peer_name: Some("测试联系人".to_string()),
                sender_id: None,
                sender_name: None,
                is_group: false,
                group_event: None,
                mentioned_bot: false,
                mentions: vec![],
                raw_payload_summary: None,
                context_token: Some("ctx-1".to_string()),
                external_msg_id: "msg-1".to_string(),
                kind: crate::clawbot_channel::ClawbotMessageKind::Text,
                text: Some("继续任务".to_string()),
                media_refs: vec![],
                received_at_ms: 1,
            },
        );
        let mut preview = crate::clawbot_channel::ClawbotInboundPreview {
            action: crate::clawbot_channel::ClawbotDispatchAction::DispatchToCoolzhu,
            command: None,
            account_id: "wx-main".to_string(),
            peer_id: "peer-1".to_string(),
            peer_name: Some("测试联系人".to_string()),
            chat_room_id: Some("room-full-access".to_string()),
            session_id: Some("session-glm".to_string()),
            target_agent_ids: vec!["agent-a".to_string()],
            workspace_id: Some("default".to_string()),
            context_token: Some("ctx-1".to_string()),
            external_msg_id: "msg-1".to_string(),
            reason: None,
        };

        let request = super::clawbot_send_request(&envelope, &preview).expect("bound request");
        assert_eq!(request.chat_room_id.as_deref(), Some("room-full-access"));
        assert_eq!(request.session_id.as_deref(), Some("session-glm"));
        assert_eq!(request.target_agent_ids, vec!["agent-a"]);
        assert_eq!(request.text, "继续任务");

        preview.chat_room_id = None;
        assert!(super::clawbot_send_request(&envelope, &preview).is_err());
    }

    #[test]
    fn clawbot_group_dispatch_gate_uses_sender_grant_and_command_capability() {
        let mut message = crate::clawbot_channel::ClawbotInboundMessage {
            account_id: "wx-main".to_string(),
            peer_id: "group-1".to_string(),
            conversation_id: Some("group-1".to_string()),
            peer_name: Some("测试群".to_string()),
            sender_id: Some("member-1".to_string()),
            sender_name: Some("测试成员".to_string()),
            is_group: true,
            group_event: None,
            mentioned_bot: true,
            mentions: vec!["wx-main".to_string()],
            raw_payload_summary: Some("keys=conversation_id,sender_id".to_string()),
            context_token: Some("ctx-1".to_string()),
            external_msg_id: "msg-group-1".to_string(),
            kind: crate::clawbot_channel::ClawbotMessageKind::Text,
            text: Some("@机器人 你好".to_string()),
            media_refs: vec![],
            received_at_ms: 1,
        };
        let mut preview = crate::clawbot_channel::ClawbotInboundPreview {
            action: crate::clawbot_channel::ClawbotDispatchAction::DispatchToCoolzhu,
            command: None,
            account_id: "wx-main".to_string(),
            peer_id: "group-1".to_string(),
            peer_name: Some("测试群".to_string()),
            chat_room_id: Some("main-room".to_string()),
            session_id: Some("session-glm".to_string()),
            target_agent_ids: vec![],
            workspace_id: Some("default".to_string()),
            context_token: Some("ctx-1".to_string()),
            external_msg_id: "msg-group-1".to_string(),
            reason: None,
        };

        assert!(matches!(
            super::clawbot_authorization_decision(
                &message,
                &preview,
                true,
                false,
                true,
                None,
                Some("full-access")
            ),
            crate::wechat_authorization::WechatAuthorizationDecision::Deny {
                code: "member_not_allowlisted",
                ..
            }
        ));

        assert_eq!(
            super::clawbot_authorization_decision(
                &message,
                &preview,
                true,
                true,
                true,
                None,
                Some("full-access")
            ),
            crate::wechat_authorization::WechatAuthorizationDecision::Allow {
                requires_approval: false
            }
        );

        let grant = crate::wechat_authorization::WechatMemberGrant::from_preset(
            "wx-main",
            "group-1",
            "member-1",
            None,
            crate::wechat_authorization::WechatMemberPreset::ChatMember,
            1,
        );
        assert_eq!(
            super::clawbot_authorization_decision(
                &message,
                &preview,
                true,
                false,
                true,
                Some(&grant),
                Some("full-access")
            ),
            crate::wechat_authorization::WechatAuthorizationDecision::Allow {
                requires_approval: false
            }
        );

        message.text = Some("/file get report.md".to_string());
        preview.action = crate::clawbot_channel::ClawbotDispatchAction::ApplyCommand;
        preview.command = crate::clawbot_channel::parse_clawbot_command("/file get report.md");
        assert!(matches!(
            super::clawbot_authorization_decision(
                &message,
                &preview,
                true,
                false,
                true,
                Some(&grant),
                Some("full-access")
            ),
            crate::wechat_authorization::WechatAuthorizationDecision::Deny {
                code: "capability_denied",
                ..
            }
        ));

        let operator = crate::wechat_authorization::WechatMemberGrant::from_preset(
            "wx-main",
            "group-1",
            "member-1",
            None,
            crate::wechat_authorization::WechatMemberPreset::Operator,
            1,
        );
        message.text = Some("/continue 1".to_string());
        preview.command = crate::clawbot_channel::parse_clawbot_command("/continue 1");
        assert!(matches!(
            super::clawbot_authorization_decision(
                &message,
                &preview,
                true,
                false,
                true,
                Some(&operator),
                Some("full-access")
            ),
            crate::wechat_authorization::WechatAuthorizationDecision::Deny {
                code: "capability_denied",
                ..
            }
        ));

        message.text = Some("/file put incoming/report.docx".to_string());
        preview.command =
            crate::clawbot_channel::parse_clawbot_command("/file put incoming/report.docx");
        assert!(matches!(
            super::clawbot_authorization_decision(
                &message,
                &preview,
                true,
                false,
                true,
                Some(&operator),
                Some("read-only")
            ),
            crate::wechat_authorization::WechatAuthorizationDecision::Deny {
                code: "room_permission_denied",
                ..
            }
        ));
    }

