    #[tokio::test]
    async fn clawbot_task_commands_list_and_resolve_goal_snapshot() {
        let _guard = config_test_guard();
        let temp = tempfile::tempdir().expect("temp goal db");
        let _session_db_env = scoped_session_db_env(temp.path());
        let db_path = super::default_session_sqlite_path();
        let workspace_id = "ws-wechat-task-test";
        let room_id = "room-wechat-task";
        let goal = super::create_goal_sqlite(
            &db_path,
            workspace_id,
            room_id,
            super::CreateGoalRequest {
                title: "微信任务验收".to_string(),
                chat_room_id: Some(room_id.to_string()),
                max_iterations: Some(3),
                background: Some(false),
                originating_user_msg_id: Some("wx-msg-1".to_string()),
                completion_condition: None,
            },
        )
        .expect("create goal");

        let binding = crate::clawbot_channel::ClawbotConversationBinding {
            account_id: "wx-main".to_string(),
            peer_id: "peer-task".to_string(),
            peer_name: Some("微信任务测试".to_string()),
            chat_room_id: Some(room_id.to_string()),
            default_session_id: Some("agent-task".to_string()),
            target_agent_ids: vec![],
            workspace_id: workspace_id.to_string(),
            last_context_token: None,
            allowlisted: true,
            enabled: true,
        };
        let previous_channel_state = std::mem::replace(
            &mut *super::clawbot_channel_state()
                .lock()
                .expect("clawbot channel state"),
            crate::clawbot_channel::ClawbotChannelState::default().with_binding(binding),
        );

        let message = crate::clawbot_channel::ClawbotInboundMessage {
            account_id: "wx-main".to_string(),
            peer_id: "peer-task".to_string(),
            conversation_id: None,
            peer_name: Some("微信任务测试".to_string()),
            sender_id: None,
            sender_name: None,
            is_group: false,
            group_event: None,
            mentioned_bot: false,
            mentions: vec![],
            raw_payload_summary: None,
            context_token: None,
            external_msg_id: "wx-msg-1".to_string(),
            kind: crate::clawbot_channel::ClawbotMessageKind::Text,
            text: Some("/tasks".to_string()),
            media_refs: vec![],
            received_at_ms: 1,
        };

        let list = super::execute_clawbot_command_runtime(
            &message,
            &crate::clawbot_channel::ClawbotCommand::ListTasks,
            Some("full-access"),
        )
        .await
        .expect("/tasks should be available");
        assert!(list.message.contains("微信任务验收"));
        assert!(list.message.contains(&goal.id));
        assert!(list.message.contains("1."));

        let detail = super::execute_clawbot_command_runtime(
            &message,
            &crate::clawbot_channel::ClawbotCommand::Registered {
                command_id: "task".to_string(),
                arguments: "1".to_string(),
            },
            Some("full-access"),
        )
        .await
        .expect("/task 1 should resolve latest task snapshot");
        assert!(detail.message.contains("微信任务验收"));
        assert!(detail.message.contains(&goal.id));
        assert!(detail.message.contains("状态"));

        let _ = std::mem::replace(
            &mut *super::clawbot_channel_state()
                .lock()
                .expect("clawbot channel state"),
            previous_channel_state,
        );
    }

