    #[tokio::test]
    async fn clawbot_new_selects_existing_session_without_creating_one() {
        let _config_guard = config_test_guard();
        let temp = tempfile::tempdir().expect("temp workspace");
        let _workspace_guard = WorkspaceScopeTestGuard::install(temp.path());
        let mut base = super::seed_session();
        base.id = "session-bailian".to_string();
        base.name = "GLM5.2 百炼".to_string();
        base.provider = "bailian".to_string();
        base.model = "glm-5.2".to_string();
        let mut selected = base.clone();
        selected.id = "session-openai".to_string();
        selected.name = "GLM5.2 OpenAI".to_string();
        selected.provider = "openai-compatible".to_string();
        let _store_guard = SessionStoreTestGuard::install(super::PersistedSessionState {
            sessions: vec![base, selected],
            active_session_id: Some("session-bailian".to_string()),
            active_vision_session_id: None,
            chat_rooms: Vec::new(),
            active_chat_room_id: None,
        });
        let binding = crate::clawbot_channel::ClawbotConversationBinding {
            account_id: "wx-main".to_string(),
            peer_id: "peer-new".to_string(),
            peer_name: Some("新会话测试".to_string()),
            chat_room_id: Some("room-new".to_string()),
            default_session_id: Some("session-bailian".to_string()),
            target_agent_ids: vec![],
            workspace_id: "ws-new".to_string(),
            last_context_token: None,
            allowlisted: true,
            enabled: true,
        };
        let previous_channel_state = std::mem::replace(
            &mut *super::clawbot_channel_state()
                .lock()
                .expect("channel state"),
            crate::clawbot_channel::ClawbotChannelState::default().with_binding(binding),
        );
        let message = wechat_runtime_test_message("peer-new", "/new session-openai");

        let result = super::execute_clawbot_command_runtime(
            &message,
            &crate::clawbot_channel::ClawbotCommand::Registered {
                command_id: "new".to_string(),
                arguments: "session-openai".to_string(),
            },
            Some("full-access"),
        )
        .await
        .expect("/new should select an existing model session");

        let store = super::session_store().lock().expect("session store");
        assert_eq!(store.state.sessions.len(), 2);
        assert!(store
            .state
            .sessions
            .iter()
            .any(|session| session.id == "session-openai"));
        assert!(result.message.contains("未创建新会话"));
        drop(store);
        let bound = super::clawbot_channel_state()
            .lock()
            .expect("channel state")
            .binding("wx-main", "peer-new")
            .cloned()
            .expect("updated binding");
        assert_eq!(bound.default_session_id.as_deref(), Some("session-openai"));

        let model_error = super::execute_clawbot_command_runtime(
            &message,
            &crate::clawbot_channel::ClawbotCommand::Registered {
                command_id: "new".to_string(),
                arguments: "glm-5.2".to_string(),
            },
            Some("full-access"),
        )
        .await
        .expect_err("同名模型不能替代具体会话标识");
        assert_eq!(model_error.code, "session_not_found");
        assert!(model_error.message.contains("模型名不能作为会话标识"));
        assert_eq!(
            super::session_store()
                .lock()
                .expect("session store")
                .state
                .sessions
                .len(),
            2,
            "拒绝模型名后也不能创建会话"
        );

        let _ = std::mem::replace(
            &mut *super::clawbot_channel_state()
                .lock()
                .expect("channel state"),
            previous_channel_state,
        );
    }

    #[tokio::test]
    async fn clawbot_continue_and_stop_control_goal_in_bound_room() {
        let _config_guard = config_test_guard();
        let temp = tempfile::tempdir().expect("temp goal db");
        let _workspace_guard = WorkspaceScopeTestGuard::install(temp.path());
        let _session_db_env = scoped_session_db_env(temp.path());
        let workspace_id = "ws-control";
        let room_id = "room-control";
        let db_path = super::default_session_sqlite_path();
        let goal = super::create_goal_sqlite(
            &db_path,
            workspace_id,
            room_id,
            super::CreateGoalRequest {
                title: "微信控制任务".to_string(),
                chat_room_id: Some(room_id.to_string()),
                max_iterations: Some(3),
                background: Some(false),
                originating_user_msg_id: Some("msg-control".to_string()),
                completion_condition: None,
            },
        )
        .expect("create goal");
        super::pause_goal_sqlite(&db_path, workspace_id, &goal.id).expect("pause goal");
        let binding = crate::clawbot_channel::ClawbotConversationBinding {
            account_id: "wx-main".to_string(),
            peer_id: "peer-control".to_string(),
            peer_name: Some("任务控制测试".to_string()),
            chat_room_id: Some(room_id.to_string()),
            default_session_id: None,
            target_agent_ids: vec![],
            workspace_id: workspace_id.to_string(),
            last_context_token: None,
            allowlisted: true,
            enabled: true,
        };
        let previous_channel_state = std::mem::replace(
            &mut *super::clawbot_channel_state()
                .lock()
                .expect("channel state"),
            crate::clawbot_channel::ClawbotChannelState::default().with_binding(binding),
        );
        let message =
            wechat_runtime_test_message("peer-control", &format!("/continue {}", goal.id));

        let resumed = super::execute_clawbot_command_runtime(
            &message,
            &crate::clawbot_channel::ClawbotCommand::ContinueTask {
                task_id: goal.id.clone(),
            },
            Some("full-access"),
        )
        .await
        .expect("/continue should resume the bound goal");
        assert!(resumed.message.contains("已继续任务"));
        assert!(resumed.message.contains("运行循环：已启动"));
        assert_ne!(
            super::get_goal_sqlite(&db_path, workspace_id, &goal.id)
                .expect("resumed goal")
                .status,
            "paused"
        );

        let stopped = super::execute_clawbot_command_runtime(
            &wechat_runtime_test_message("peer-control", "/stop"),
            &crate::clawbot_channel::ClawbotCommand::Registered {
                command_id: "stop".to_string(),
                arguments: String::new(),
            },
            Some("full-access"),
        )
        .await
        .expect("/stop should pause the latest active goal");
        assert!(stopped.message.contains("已停止任务"));
        assert_eq!(
            super::get_goal_sqlite(&db_path, workspace_id, &goal.id)
                .expect("stopped goal")
                .status,
            "paused"
        );

        let _ = std::mem::replace(
            &mut *super::clawbot_channel_state()
                .lock()
                .expect("channel state"),
            previous_channel_state,
        );
    }

